local _, ns = ...
local E = ns.DB.entries
E["npc:feero-ironhand"] = {t="npc",n="Feero Ironhand",z="ashenvale",s="Feero Ironhand is a human fighter stationed at Maestra's Post in the western reaches of Ashenvale. Standing guard along the border between Darkshore and the forest, he works closely with Delgren the Purifier to combat the shadowy Cult of the Dark Strand.",h="Feero Ironhand is a human fighter stationed at Maestra's Post in the western reaches of Ashenvale.",sec={{t="A Bulwark at Maestra's Post",b="Located along the road leading south from Darkshore into Ashenvale, Maestra's Post serves as a critical watchpoint for travelers and Alliance defenders alike. Feero Ironhand operates out of this outpost, maintaining communications and trade lines with Auberdine while keeping a vigilant watch over the surrounding woods. Together with Delgren the Purifier, Feero focuses his efforts against the malevolent Cult of the Dark Strand, ensuring the cultists and forest predators do not sever the path between Darnassus's supply lines and the front lines of Ashenvale.",sp=0}},faq={{q="Who is Feero Ironhand?",a="Feero Ironhand is an Alliance human warrior stationed at Maestra's Post in western Ashenvale. He assists travelers passing between Darkshore and Ashenvale and coordinates logistics back to Auberdine.",al={"feero ironhand","who is feero","feero npc"}},{q="What is Feero's purpose at Maestra's Post?",a="Feero helps hold the outpost against local threats, supporting Delgren the Purifier in opposing the Cult of the Dark Strand while keeping vital courier and supply routes running into Darkshore.",al={"why is feero here","feero role","maestras post human"}},{q="What is the Cult of the Dark Strand?",a="The Cult of the Dark Strand is a sinister cabal operating out of northern Ashenvale, dabbling in dark magic and foul rituals. Alliance forces at Maestra's Post actively work to disrupt and dismantle their operations.",al={"dark strand cult","cult of dark strand","dark strand"}},{q="Does Feero have connections to the Argent Dawn?",a="Feero works in close concert with Delgren the Purifier, a dedicated holy warrior combatting dark forces in the forest, maintaining strong ties to the vigilant defenders fighting against evil throughout Kalimdor.",al={"feero argent dawn","is feero argent dawn"}}},ang={["faction:Alliance"]="Feero provides an important foothold for Alliance wayfarers traveling down from Darkshore into the dangerous, contested wilderness of Ashenvale.",["race:Human"]="Seeing a fellow human standing guard in the ancient elven woods of Ashenvale is a welcome sign of the Alliance's far-reaching cooperation."},kw={"ashenvale","auberdine","cult of the dark strand","delgren the purifier","feero ironhand","maestra's post"},rel={"subzone:maestra-s-post","npc:delgren-the-purifier","subzone:auberdine","zone:ashenvale","quest:976","topic:argent-dawn","zone:darnassus"},src={"Feero Ironhand"}}
E["npc:gurda-ragescar"] = {t="npc",n="Gurda Ragescar",z="ashenvale",s="Gurda Ragescar was an orc stationed at a small Horde outpost southwest of Splintertree Post in Ashenvale. Alongside Feran Strongwind, she fell defending their camp against local perils in the shadowed forest.",h="Gurda Ragescar was an orc stationed at a small Horde outpost southwest of Splintertree Post in Ashenvale.",sec={{t="A Slain Outpost",b="Resting just southwest of the fortified walls of Splintertree Post, Gurda Ragescar maintained a modest Horde camp under the dense canopy of Ashenvale. Deep within territory contested by night elven defenders and wild beasts, maintaining such isolated positions is perilous work. Gurda, along with Feran Strongwind and their detachment of guards, was ultimately overrun and killed at their post, leaving only the remnants of their final stand for passing allies to discover.",sp=0},{t="The Fallen Scouts",b="Travelers wandering near the trail may come across the tragic scene of Gurda's defeat. Even in death, the possessions and tasks carried by her encampment offer clues to Horde endeavors across the woods, including missing documents and orders disrupted by the ambush.",sp=0}},faq={{q="Who is Gurda Ragescar?",a="Gurda Ragescar is an orc scout and quest giver positioned at a small camp just southwest of Splintertree Post in Ashenvale, who met a violent end alongside her outpost companions.",al={"who is gurda","gurda ragescar lore"}},{q="Where can Gurda Ragescar be found?",a="Her body lies at an overrun camp southwest of Splintertree Post, off the roadway cutting through central Ashenvale.",al={"gurda location","where is gurda ragescar"}},{q="Who was killed alongside her?",a="She perished beside Feran Strongwind and their retinue of guards during an attack on their small encampment.",al={"who died with gurda","feran strongwind"}},{q="What quest involves Gurda Ragescar?",a="Gurda is tied to the quest The Lost Pages, involving the recovery of scattered documents in the Ashenvale wilderness.",al={"gurda quests","the lost pages"}}},ang={["faction:Horde"]="The fallen camp serves as a somber reminder of the high price the Horde pays to secure a foothold within the sacred forests of Ashenvale."},kw={"ashenvale","feran strongwind","gurda","orc","ragescar","splintertree","the lost pages"},rel={"subzone:splintertree-post","quest:6504","zone:ashenvale"},src={"Gurda Ragescar"}}
E["npc:illiyana"] = {t="npc",n="Illiyana",z="ashenvale",s="Illiyana is an ancient dryad stationed in eastern Ashenvale, dedicated to protecting the woodland from ancient corruption. Wandering near Forest Song, she rallies champions of the Alliance to push back against the vicious satyrs that plague the ancient groves. Her vigilance represents the enduring bond between the daughters of Cenarius and the night elven wilderness.",h="Illiyana is an ancient dryad stationed in eastern Ashenvale, dedicated to protecting the woodland from...",sec={{t="Daughter of the Forest",b="Like all dryads, Illiyana is one of the daughters of the demigod Cenarius. Peaceful yet fiercely protective of wild lands, she patrols the woods of eastern Ashenvale. As dark forces stir and the woodlands suffer under creeping corruption, Illiyana keeps watch over sacred relics and groves, acting as a steward for nature's primal sanctity.",sp=0},{t="The Threat of the Satyr",b="Illiyana's primary concern in the region is the lingering blight of the satyrs. These twisted, demonic creatures continuously seek to corrupt the glades and endanger her dryad sisters. Illiyana frequently enlists passing travelers to strike down these vile abominations and recover lost artifacts, including the Branch of Cenarius, to ensure the woods remain sheltered from demonic taint.",sp=0}},faq={{q="Who is Illiyana?",a="Illiyana is a dryad found roaming eastern Ashenvale near Forest Song. As a daughter of Cenarius, she dedicates her existence to watching over the wildlands and protecting her sisters from demonic forces.",al={"who is this dryad","illiyana ashenvale","what is illiyana"}},{q="Why does Illiyana keep walking while I talk to her?",a="Illiyana maintains an active patrol route through the woodland. Unlike stationary quest givers, she continues her watchful pacing through the grove even when engaging in conversation with travelers.",al={"illiyana moving","why does she walk away","illiyana quest walking"}},{q="What tasks does Illiyana offer?",a="She calls upon adventurers to hunt down vile satyrs that menace the region and to recover sacred relics like the Branch of Cenarius to safeguard her fellow dryads.",al={"illiyana quests","forest song quests"}},{q="Where is Illiyana located?",a="She patrols near the outpost of Forest Song in eastern Ashenvale, keeping watch along the paths and nearby groves.",al={"illiyana location","where to find illiyana","forest song dryad location"}},{q="Why are the dryads in danger from satyrs?",a="Satyrs are ancient night elves warped by demonic corruption who delight in defiling nature and subjugating Cenarius's children. Dryads represent the pure, untainted beauty of the forest, making them prime targets for satyr malice.",al={"why do satyrs hate dryads","dryads and satyr lore"}},{q="Does Illiyana help the Horde?",a="No. Illiyana is allied with the Night Elves and the broader Alliance. Horde members venturing into her glade will find her and her allies hostile.",al={"is illiyana hostile to horde","can horde talk to illiyana"}}},ang={["race:NightElf"]="For the Kaldorei, dryads like Illiyana are sacred kin of Cenarius, revered protectors whose call to arms against demonic satyrs is answered without hesitation.",["class:Druid"]="Druids hold dryads in high regard as embodiments of the wild, and helping Illiyana preserve the sanctified glades aligns directly with the Cenarion duty to heal the land.",["faction:Alliance"]="Illiyana represents a vital woodland ally in eastern Ashenvale, offering shelter and guidance to Alliance forces securing the wilderness against encroaching evils."},kw={"ashenvale","branch of cenarius","cenarius","dryad","forest song","illiyana","satyr","shrine of aessina"},rel={"subzone:forest-song","zone:ashenvale","topic:satyr","topic:cenarius","quest:1031","quest:1032","quest:1021","npc:shael-dryn"},src={"Illiyana"}}
E["npc:illiyana-moonblaze"] = {t="npc",n="Illiyana Moonblaze",z="ashenvale",s="Illiyana Moonblaze is an unconventional night elf scout and quartermaster stationed at Silverwing Grove in Ashenvale. Operating alongside the Silverwing Sentinels, she supplies Alliance champions waging war against the Warsong Outriders. Despite her formal officer standing, her sharp instincts and roguish demeanor set her apart from traditional kaldorei military ranks.",h="Illiyana Moonblaze is an unconventional night elf scout and quartermaster stationed at Silverwing Grove in...",sec={{t="A Scout Outside the Ranks",b="Illiyana Moonblaze serves as the primary supply officer for the Silverwing Sentinels nestled in Silverwing Grove. Yet, one look reveals she is far from an ordinary sentinel. Wielding twin blades and donning dark corsetry, she carries the swagger of a rogue or a buccaneer rather than the disciplined poise of Elune's faithful warriors. Traditional sentinel hierarchy has historically viewed those of her trade with wariness, likening them almost to lawless rogues. Nevertheless, her unmatched cunning and talent for tracking make her invaluable in the contested woodlands.",sp=0},{t="Supplies for the Front Lines",b="Beyond her unconventional scouting duties, Illiyana equips Alliance volunteers preparing to clash with the Warsong clan in Warsong Gulch. As champions earn favor with the Silverwing Sentinels, she rewards their service with custom rations, specialized draugths, and masterwork armaments designed specifically for woodland skirmishes. She also maintains weapons and armor for weary fighters returning from the frontline, keeping the Sentinels' war effort supplied and functional.",sp=0}},faq={{q="Where can I find Illiyana Moonblaze?",a="She is located at Silverwing Grove in southeastern Ashenvale, near the staging grounds and portal leading into Warsong Gulch.",al={"illiyana moonblaze location","where is illiyana","silverwing quartermaster location"}},{q="Is Illiyana Moonblaze a member of the Sentinels?",a="Technically, she holds officer standing to coordinate logistics, but she is not a traditional Sentinel. Her background aligns with kaldorei scouts and rogues—a calling that conventional Sentinel society historically treated with suspicion.",al={"is illiyana a sentinel","illiyana rank","illiyana faction"}},{q="What does Illiyana offer to Alliance champions?",a="She acts as the Silverwing Sentinels' quartermaster, offering care packages, battlefield armaments, rings, tabards, and consumables tailored for the struggle in Warsong Gulch to those who gain reputation with the faction.",al={"what does illiyana sell","warsong gulch rewards ashenvale","illiyana vendor"}},{q="Why does she look and act like a rogue?",a="Her skills rely on stealth, cunning, and lethal tracking rather than priestly devotion or martial sentinel discipline. While night elf society often viewed such roguish paths as dishonorable or akin to piracy, her practical wilderness survival skills prove vital in desperate times.",al={"illiyana rogue lore","why is she dressed like a pirate","illiyana pirate"}},{q="Does she provide equipment repairs?",a="Yes, alongside supplying specialized military gear, she offers standard weapon and armor repair services to Alliance defenders resting at the grove.",al={"can illiyana repair","silverwing repair vendor","repair in silverwing grove"}},{q="What care packages does she hand out?",a="She assists Alliance fighters through logistical quests involving Sentinel Basic, Standard, and Advanced Care Packages, supplying frontline defenders with essential battlefield provisions.",al={"sentinel care package","illiyana quests","warsong gulch packages"}}},ang={["class:Rogue"]="Illiyana represents a rare sight among the kaldorei: a seasoned shadow-walker and tracker working openly alongside regular military forces despite traditional societal disdain.",["faction:Alliance"]="For Alliance fighters marching south into the contested border of Warsong Gulch, Illiyana is the primary quartermaster supplying weapons, armor, and rations.",["race:NightElf"]="Her roguish presence offers a stark contrast to typical Priestesses and Sentinels, showing how kaldorei scouts adapt independent methods to safeguard Ashenvale."},kw={"ashenvale","care package","illiyana moonblaze","rogue","sentinel","silverwing grove","warsong gulch"},rel={"subzone:silverwing-grove","subzone:silverwing-outpost","zone:ashenvale","topic:sentinels","quest:7863","quest:7864","quest:7865","topic:night-elf"},src={"Illiyana Moonblaze"}}
E["npc:karang-amakkar"] = {t="npc",n="Karang Amakkar",z="ashenvale",s="Karang Amakkar is an orc scout stationed at Zoram'gar Outpost along the rocky coast of Ashenvale. Operating on the fringe of Horde territory, he focuses on curbing the violent furbolg tribes that threaten the outpost's supply lines and borders. Adventurers travelling through the outpost rely on his local intelligence to navigate the perilous tensions of the forest.",h="Karang Amakkar is an orc scout stationed at Zoram'gar Outpost along the rocky coast of Ashenvale.",sec={{t="On the Coast of Ashenvale",b="Perched at Zoram'gar Outpost on the Zoram Strand, Karang Amakkar serves the Horde at one of its most vulnerable border outposts. The encampment faces constant pressure from the sea, the night elves, and wild beasts inland. Karang keeps a close eye on the hostile native populations that surround the road eastward, ensuring that Horde couriers and scouting parties do not get ambushed by territorial indigenous tribes.",sp=0},{t="Dealing with the Furbolgs",b="Karang focuses much of his attention on the furbolg populations native to the ancient woods, notably the Thistlefur and Foulweald tribes. With corruption and primal hostility driving these bear-folk into frenzies, Karang tasks capable warriors with culling their leaders and clearing out dens before the tribes can muster organized assaults against Zoram'gar.",sp=0}},faq={{q="Who is Karang Amakkar?",a="Karang Amakkar is an orc questgiver stationed at Zoram'gar Outpost along the coast of Ashenvale. He works on behalf of the Horde to manage regional threats, especially hostile furbolg clans.",al={"karang","who is karang","karang amakkar lore"}},{q="Where can I find Karang Amakkar?",a="He is located in Zoram'gar Outpost, on the northwestern shoreline of Ashenvale along the Zoram Strand.",al={"karang location","where is karang amakkar","karang amakkar spot"}},{q="What tasks does Karang Amakkar offer?",a="Karang tasks Horde adventurers with confronting aggressive furbolg tribes nearby, directing strikes against the Thistlefur clan and the leader of the Foulweald.",al={"karang quests","karang tasks","what does karang want"}},{q="Why is Karang worried about the furbolgs?",a="The furbolgs in Ashenvale have grown increasingly savage and corrupt, attacking travelers and threatening to cut off Zoram'gar Outpost from the rest of the Horde's strongholds in the region.",al={"why kill furbolgs","furbolg threat ashenvale","thistlefur threat"}},{q="Is Karang Amakkar related to Initiate Amakkar?",a="While they share a clan name or family surname, any exact familial relationship between Karang and Initiate Amakkar remains unconfirmed.",al={"amakkar family","initiate amakkar relative","karang family"}},{q="Does Karang fight the night elves directly?",a="Karang's duties in Zoram'gar primarily focus on territorial defense and dealing with wild threats like the Thistlefur furbolgs, leaving overt military maneuvers against the night elves to other Horde commanders.",al={"karang vs night elves","karang alliance"}}},ang={["faction:Horde"]="Karang Amakkar provides vital aid to Horde travelers braving the western reaches of Ashenvale, offering work to push back hostile creatures surrounding Zoram'gar Outpost.",["race:Orc"]="Stationed on a remote outpost far from Durotar, Karang embodies the gritty determination of orcish sentries holding dangerous frontier borders."},kw={"ashenvale","foulweald","furbolg","karang amakkar","thistlefur","zoram strand","zoram'gar outpost"},rel={"subzone:zoram-gar-outpost","zone:ashenvale","quest:216","quest:6621"},src={"Karang Amakkar"}}
E["npc:kil-hala"] = {t="npc",n="Kil'hala",z="ashenvale",s="Kil'hala is a jungle troll tailoring trainer stationed at the Crossroads in the Barrens. Skilled in working with both everyday cloth and exotic woven materials, he instructs Horde crafters looking to refine their needlework. Beyond common thread, he directs ambitious tailors north into Ashenvale to procure rare reagents like nether-lace.",h="Kil'hala is a jungle troll tailoring trainer stationed at the Crossroads in the Barrens.",sec={{t="Tailor of the Barrens",b="Positioned at the bustling hub of the Crossroads, Kil'hala offers his tailoring expertise to passing travelers and Horde recruits. While much of his craft involves common spun bolts and garments fit for dry plains life, his knowledge extends into rare magical textiles. To craft truly remarkable robes, Kil'hala challenges weavers to venture into the untamed canopies of Ashenvale, where ethereal materials like nether-lace can be harvested from magical dryads.",sp=0}},faq={{q="Who is Kil'hala?",a="Kil'hala is a Darkspear troll and a tailoring trainer located at the Crossroads in the Barrens. He assists Horde tradesfolk in learning the basics of weaving cloth and garment construction.",al={"kilhala identity","who is kilhala","crossroads tailor"}},{q="Where can I find Kil'hala?",a="He is located in the Barrens within the central settlement of the Crossroads, situated alongside other Horde trade trainers.",al={"kilhala location","where is kilhala","kilhala spot"}},{q="What tasks does Kil'hala give to tailors?",a="He directs weavers seeking advanced cloth crafting to venture into Ashenvale to hunt dryads known as the Laughing Sisters. Kil'hala uses their ethereal locks to create a unique Nether-lace Garment.",al={"kilhala quests","laughing sisters quest","nether lace garment"}}},ang={["profession:Tailoring"]="Kil'hala is an essential stop for journeyman Horde tailors traversing Kalimdor, teaching craft techniques and offering quests to weave exotic magical robes.",["faction:Horde"]="Providing textile goods and tradecraft training in the Crossroads, Kil'hala helps equip the warband and travelers carving a foothold in the Barrens."},kw={"barrens","crossroads","kil'hala","kilhala","laughing sisters","nether-lace","tailoring","trainer"},rel={"subzone:crossroads","quest:1945","quest:1946","zone:ashenvale","topic:troll"},src={"Kil'hala"}}
E["npc:krolg"] = {t="npc",n="Krolg",z="ashenvale",s="Krolg is an uncorrupted furbolg living in an isolated hut south of Mystral Lake in Ashenvale. Formerly a member of the Foulweald tribe, he has broken away from his kin who fell to demonic madness and will only speak with those who appear to him in furbolg form.",h="Krolg is an uncorrupted furbolg living in an isolated hut south of Mystral Lake in Ashenvale.",sec={{t="A Mind Unbroken",b="While most of the Foulweald furbolgs in Ashenvale have succumbed to the demonic taint left behind by the Burning Legion, Krolg remains lucid and untouched by madness. Residing in a secluded shelter south of Mystral Lake, he keeps a cautious vigil over the forest. Having witnessed the tragic descent of his brethren into senseless violence, he refuses to interact with outsiders at face value, speaking only with beings that appear as kin.",sp=0},{t="Dartol's Legacy",b="Through the magical enchantment of Dartol's Rod of Transformation, Alliance travelers are able to cloak themselves in the guise of a furbolg. Upon seeing what appears to be a friendly kindred spirit, Krolg opens up and reveals crucial insights into cleansing the land. He assists in completing Dartol's ancient rod and directs heroes against Chief Murgut, the self-proclaimed King of the Foulweald whose corrupt leadership threatens the region.",sp=1}},faq={{q="Why won't Krolg talk to me?",a="Krolg is deeply suspicious of outsiders and terrified of the violent chaos consuming the forest. He will completely ignore you unless you are under the furbolg transformation granted by Dartol's Rod of Transformation during the Raene's Cleansing questline.",al={"krolg wont speak","cant talk to krolg","why is krolg silent"}},{q="Where can Krolg be found?",a="He lives in a small shelter known as Krolg's Hut, situated just south of Mystral Lake in south-central Ashenvale.",al={"krolg location","where is krolg","krolg hut"}},{q="What tribe does Krolg belong to?",a="Krolg was originally part of the Foulweald tribe. Unlike the rest of his kin, who fell to corruption and demonic frenzy, he maintained his sanity and severed ties with them.",al={"krolg tribe","is krolg foulweald"}},{q="Is Krolg hostile to players?",a="No, Krolg is non-hostile to Alliance travelers. However, he remains entirely silent and unwilling to offer quests until approached in furbolg form.",al={"does krolg attack","is krolg an enemy"}},{q="Why does Krolg want Chief Murgut dead?",a="Chief Murgut leads the corrupted Foulweald tribe as their self-proclaimed king. To protect what remains of the woodland and stop the spread of feral corruption, Krolg tasks transformed adventurers with slaying the chief.",al={"king of the foulweald quest","why kill murgut"},sp=1},{q="Who was Dartol, whose rod Krolg helps restore?",a="Dartol was a night elf who created a magical rod capable of cleansing demonic corruption and granting furbolg form. Krolg helps players assemble the final pieces required to awaken its true power.",al={"who is dartol","dartols rod backstory"}}},ang={["race:NightElf"]="For the night elves of Astranaar, Krolg represents a bittersweet reminder of their ancient furbolg allies before demonic corruption shattered the tribes.",["class:Druid"]="Druids seeking to restore balance to Ashenvale find an invaluable, lucid voice in Krolg amidst a landscape overrun by tainted wildlife.",["faction:Alliance"]="Alliance scouts assisting Raene Wolfrunner rely on Krolg to dismantle the leadership of the hostile Foulweald furbolgs."},kw={"ashenvale furbolg","chief murgut","dartol's rod","foulweald","krolg","krolg's hut","mystral lake","raene's cleansing"},rel={"quest:991","quest:6621","npc:raene-wolfrunner","subzone:mystral-lake","zone:ashenvale","topic:furbolg","topic:alliance"},src={"Krolg"}}
E["npc:kuray-bin"] = {t="npc",n="Kuray'bin",z="ashenvale",s="Kuray'bin is a Darkspear jungle troll scout stationed at a guard post outside Splintertree Post in Ashenvale. He watches the surrounding forest trails for night elf scouts sneaking close to the Horde encampment.",h="Kuray'bin is a Darkspear jungle troll scout stationed at a guard post outside Splintertree Post in Ashenvale.",sec={{t="Eyes on the Forest Edge",b="Positioned just outside Splintertree Post, Kuray'bin keeps watch against Alliance infiltration in the deep woods of Ashenvale. The Silverwing Sentinels constantly patrol the surrounding canopy, sending agile outrunners across the border to gather intelligence on Horde lumber operations and defenses. Knowing that unmonitored scouts quickly become ambushing forces, Kuray'bin directs capable Horde fighters to hunt down the outrunners before they can report back to Silverwing Refuge.",sp=0}},faq={{q="Who is Kuray'bin?",a="Kuray'bin is a Darkspear troll watchman stationed outside Splintertree Post in Ashenvale. He tasks Horde adventurers with culling hostile night elf scouts lurking in the surrounding woodland.",al={"kuraybin","who is kuraybin","splintertree troll scout"}},{q="Where can I find Kuray'bin?",a="He is located just outside the stockade gates of Splintertree Post, guarding the road approaches in central-eastern Ashenvale.",al={"kuraybin location","where is kuraybin"}},{q="Why does Kuray'bin want the Silverwing Outrunners dead?",a="The outrunners are Silverwing Sentinels infiltrating close to Splintertree Post. Kuray'bin wants them eliminated before they gather tactical intelligence on the Horde's positions or coordinate surprise assaults.",al={"why kill outrunners","ashenvale outrunners quest lore"}},{q="Does Kuray'bin offer any other tasks?",a="No. His single duty at the outpost perimeter is overseeing counter-scouting against the elusive night elf outrunners.",al={"kuraybin quests","kuray bin task"}}},ang={["faction:Horde"]="Kuray'bin represents the frontline vigilance necessary to keep Splintertree Post from being surrounded and overrun by night elf guerillas.",["race:Troll"]="Like many Darkspear scouts serving the Horde, Kuray'bin uses his jungle tracking instincts to detect night elf infiltrators where others see only trees."},kw={"ashenvale outrunners","darkspear","kuray'bin","kuraybin","silverwing sentinels","splintertree post"},rel={"subzone:splintertree-post","quest:6503","zone:ashenvale","topic:sentinels","topic:horde","topic:troll","topic:alliance"},src={"Kuray'bin"}}
E["npc:marukai"] = {t="npc",n="Marukai",z="ashenvale",s="Marukai is a Darkspear jungle troll stationed at Zoram'gar Outpost along the foggy coast of northwest Ashenvale. Dedicated to holding this remote beachhead for the Horde, she coordinates efforts to cull the encroaching Wrathtail naga who threaten the outpost.",h="Marukai is a Darkspear jungle troll stationed at Zoram'gar Outpost along the foggy coast of northwest...",sec={{t="Holding the Strand",b="Zoram'gar Outpost sits isolated on the northern edge of the Zoram Strand, surrounded by ancient ruins, hostile night elf territory, and the restless sea. As the Wrathtail naga emerge in force from the waters and ancient elven ruins to claim the shoreline, Marukai works to keep the encampment from being overwhelmed. She directs Horde champions to push the serpent-folk back into the tide and collect their heads, ensuring the outpost remains a viable coastal stronghold.",sp=0}},faq={{q="Who is Marukai?",a="Marukai is a jungle troll questgiver defending Zoram'gar Outpost, the Horde's isolated coastal encampment on the northwestern shores of Ashenvale.",al={"marukai lore","who is marukai","marukai npc"}},{q="Why is Marukai fighting the naga?",a="The Wrathtail naga have infested the nearby Zoram Strand and surrounding ruins. To secure the outpost's borders and ensure Horde survival on the coast, Marukai hires adventurers to thin their numbers by hunting them down directly.",al={"why kill naga","marukai naga quest","zoram strand naga"}},{q="Where is Marukai located?",a="She can be found standing alongside her kin at Zoram'gar Outpost, situated at the mouth of the Zoram Strand in northwestern Ashenvale, just south of the submerged ruins of Blackfathom Deeps.",al={"where is marukai","marukai location","find marukai"}}},ang={["faction:Horde"]="Marukai anchors one of the Horde's most precarious coastal camps in night elf territory, relying on allied champions to prevent the local naga from overrunning their position.",["race:Troll"]="Far from the warm echoes of Sen'jin Village, Marukai represents the resilience of the Darkspear tribe as they carve out fortified footholds for the Horde across Kalimdor."},kw={"ashenvale","darkspear","jungle troll","marukai","naga","wrathtail","zoram strand","zoram'gar outpost"},rel={"subzone:zoram-gar-outpost","subzone:zoram-strand","quest:6442","npc:mitsuwa","topic:naga","zone:ashenvale","topic:horde","topic:troll"},src={"Marukai"}}
E["npc:mastok-wrilehiss"] = {t="npc",n="Mastok Wrilehiss",z="ashenvale",s="Mastok Wrilehiss is an orc officer stationed at Splintertree Post in eastern Ashenvale. Serving as a crucial defensive coordinator for the Horde in the contested forest, he directs scouts and warriors to secure nearby borders and handle corrupting elemental threats. His presence is vital for maintaining the precarious foothold the Horde holds amidst constant night elf hostility.",h="Mastok Wrilehiss is an orc officer stationed at Splintertree Post in eastern Ashenvale.",sec={{t="A Bulwark in the Ancient Woods",b="Splintertree Post stands deep in the shadow of Ashenvale's towering canopy, completely surrounded by hostile night elven territory. Mastok Wrilehiss serves as one of the post's core defenders, monitoring supply routes and forest activity. The position is perilous; any sign of weakness invites swift strikes from the Sentinels who view the settlement as a despoiling intrusion.",sp=0},{t="Coordinating the Front",b="From his vantage within the stockade, Mastok actively tasks passing adventurers with critical strategic duties. He keeps watchful eyes on the borders leading into neighboring territories like the Stonetalon Mountains and dispatches scouts to consult shamans such as Je'neu Sancrea of the Earthen Ring at Zoram'gar Strand. His duties bridge military defense with monitoring the strange, corrupting forces afflicting the local elementals.",sp=0}},faq={{q="Who is Mastok Wrilehiss?",a="Mastok Wrilehiss is an elite orc stationed at Splintertree Post in Ashenvale. He acts as an officer and quest giver tasked with holding the outpost against night elf incursions and investigating nearby regional threats.",al={"who is mastok","mastok wrilehiss role","who is this orc"}},{q="Where can Mastok Wrilehiss be found?",a="He is located inside Splintertree Post, an fortified Horde outpost situated in east-central Ashenvale along the main forest road.",al={"mastok location","where is mastok wrilehiss","mastok map"}},{q="What tasks does Mastok assign to adventurers?",a="Mastok tasks Horde adventurers with strategic duties including investigating corrupt elemental threats in the forest, securing passes toward Stonetalon, and directing emissaries to Je'neu Sancrea of the Earthen Ring.",al={"mastok quests","quests from mastok"}},{q="Why is Splintertree Post under constant pressure?",a="The outpost serves as a central Horde logging hub and stronghold within Ashenvale. The native night elves view the presence of the orcs and their timber harvesting as a severe desecration of sacred lands, resulting in unending skirmishes.",al={"why are night elves attacking splintertree","splintertree post conflict"}},{q="Why does Mastok send travelers to Je'neu Sancrea?",a="The Earthen Ring shamans, including Je'neu at Zoram'gar Strand, study and heal the elemental instability wracking Ashenvale. Mastok connects frontline fighters with their spiritual expertise to handle tainted water elementals and strange disturbances.",al={"why contact earthen ring","mastok and jeneu"}},{q="Is Mastok Wrilehiss hostile to Alliance players?",a="Yes. Mastok is a dedicated member of the Horde and an elite defender of Splintertree Post, meaning he will attack Alliance players on sight if they approach the encampment.",al={"can alliance talk to mastok","is mastok killable"}}},ang={["faction:Horde"]="For Horde champions fighting to maintain a frontier foothold in Ashenvale, Mastok is a key commander who can direct you toward crucial tasks across the region.",["faction:Alliance"]="Mastok Wrilehiss represents the entrenched orcish military presence within Ashenvale, defending the fortified settlement of Splintertree against night elf sentinels.",["class:Shaman"]="Mastok's concern over corrupted elementals within the forest often directs adventurers to seek guidance from the Earthen Ring at Zoram'gar Strand."},kw={"ashenvale","earthen ring","mastok","orc","splintertree","stonetalon","wrilehiss"},rel={"subzone:splintertree-post","zone:ashenvale","quest:824","quest:1918","quest:25","topic:alliance"},src={"Mastok Wrilehiss"}}
E["npc:mitsuwa"] = {t="npc",n="Mitsuwa",z="ashenvale",s="Mitsuwa is a Darkspear troll stationed at Zoram'gar Outpost along the misty coast of Ashenvale. Deeply troubled by the ambush of his traveling kin, he enlists Horde champions to avenge the fallen and reclaim stolen spiritual talismans.",h="Mitsuwa is a Darkspear troll stationed at Zoram'gar Outpost along the misty coast of Ashenvale.",sec={{t="Avenging the Fallen Kin",b="Situated at the remote Zoram'gar Outpost on the strand of the Zoram Strand, Mitsuwa serves the Horde alongside his companion Marukai. When a group of traveling trolls bound for the encampment was ambushed and slaughtered by the aggressive Thistlefur furbolgs of northern Ashenvale, Mitsuwa took the loss as a grievous offense. Driven by duty and anger, he directs able-bodied warriors toward the Thistlefur dens to reclaim the stolen troll charms, ensuring the spirits of his kin are honored and their sacred possessions recovered from the beasts.",sp=0}},faq={{q="Who is Mitsuwa?",a="Mitsuwa is a Darkspear jungle troll residing at Zoram'gar Outpost in northwestern Ashenvale. He watches over the frontier post alongside his companion Marukai and coordinates retribution against hostile regional threats.",al={"mitsuwa","who is mitsuwa","mitsuwa lore"}},{q="What happened to the trolls traveling to Zoram'gar?",a="A group of trolls journeying across Ashenvale to reinforce or visit Zoram'gar Outpost was ambushed and slaughtered by the native Thistlefur furbolgs, who stripped the fallen travelers of their personal possessions.",al={"dead trolls ashenvale","thistlefur attack trolls"}},{q="Why are the troll charms so important to Mitsuwa?",a="The charms carry spiritual and cultural significance for the Darkspear tribe. Leaving sacred relics in the hands of the Thistlefur furbolgs after a brutal massacre is a profound dishonor to the spirits of the slain.",al={"why troll charms","troll charm quest reason"}},{q="Where are the charms located?",a="The charms were carried off by the Thistlefur furbolgs to their village and foul den, located in northern Ashenvale east of the Zoram Strand.",al={"where are troll charms","thistlefur village location"}}},ang={["race:Troll"]="Mitsuwa's call to arms strikes a deeply personal chord for Darkspear adventurers, as recovering sacred ancestral charms from crude furbolg marauders restores peace to their murdered brothers and sisters.",["faction:Horde"]="Zoram'gar Outpost is an isolated and besieged garrison; aiding Mitsuwa strengthens the Horde's perilous presence against wild beasts and Alliance scouts on the western reaches of Kalimdor."},kw={"ashenvale","darkspear","furbolg","marukai","mitsuwa","thistlefur","troll","troll charm","zoram'gar"},rel={"quest:6462","subzone:zoram-gar-outpost","npc:marukai","topic:furbolg","topic:troll","topic:horde","zone:ashenvale"},src={"Mitsuwa"}}
E["npc:orendil-broadleaf"] = {t="npc",n="Orendil Broadleaf",z="ashenvale",s="Orendil Broadleaf is a skilled night elf herbalist and healer stationed at Maestra's Post in western Ashenvale. Known for his deep knowledge of forest flora, he treats wounded defenders and concocts vital remedies to save young lives across the troubled woodlands.",h="Orendil Broadleaf is a skilled night elf herbalist and healer stationed at Maestra's Post in western...",sec={{t="Healer of the Forest Border",b="Positioned at Maestra's Post along the western threshold of Ashenvale, Orendil Broadleaf provides essential medical care to the Sentinels who defend the borderlands. Recognized for his masterful knowledge of local herbs and restorative craft, Orendil directs his apprentices and relies on passing travelers to gather rare natural reagents. Even as tension and conflict encroach upon the sacred grove, his tireless focus remains on safeguarding his kin and soothing the ailments of the forest's defenders.",sp=0},{t="A Race Against Sickness",b="Beyond caring for the wounded sentinels, Orendil plays a central part in the desperate effort to cure Relara Whitemoon, an afflicted child in Astranaar. Through careful study of forest botanicals—including Bathran's hair—he devises potent elixirs capable of holding back deadly sickness, demonstrating how herbal mastery remains a crucial shield against the perils haunting Ashenvale.",sp=1}},faq={{q="Who is Orendil Broadleaf?",a="Orendil Broadleaf is a night elf herbalist and healer residing at Maestra's Post in western Ashenvale. He oversees healing efforts for local defenders and trains apprentices in the natural arts.",al={"orendil broadleaf","who is orendil","orendil ashenvale"}},{q="Where can Orendil Broadleaf be found?",a="He is located at Maestra's Post, a night elf outpost situated along the main path in western Ashenvale, near the border with Darkshore.",al={"orendil broadleaf location","find orendil","where is orendil"}},{q="What is Orendil trying to cure?",a="Orendil formulates a curative draught to save Relara Whitemoon, an ailing night elf child residing in Astranaar, using rare herbs gathered from the wild reaches of Ashenvale.",al={"orendil cure","who is orendil curing","relara whitemoon cure"}},{q="What is Orendil's Retreat?",a="Orendil's Retreat is an encampment named in his honor where his apprentices carry out herbal research and aid in protecting the surrounding forest.",al={"orendils retreat","orendil retreat","where apprentices study"}}},ang={["profession:Herbalism"]="Orendil demonstrates the life-saving importance of regional botanicals, relying on rare plants like Bathran's hair to brew potent antidotes in the field.",["race:NightElf"]="For night elves defending Ashenvale, Orendil is an essential guardian of life whose gentle remedies keep frontier defenders and vulnerable children alive."},kw={"ashenvale","astranaar","bathran's hair","maestra's post","orendil broadleaf","orendil's cure","relara whitemoon"},rel={"subzone:maestra-s-post","quest:1020","quest:1010","subzone:astranaar","npc:raene-wolfrunner","zone:ashenvale","topic:sentinels","topic:night-elf"},src={"Orendil Broadleaf"}}
E["npc:pelturas-whitemoon"] = {t="npc",n="Pelturas Whitemoon",z="ashenvale",s="Pelturas Whitemoon is a night elf father dwelling in Astranaar whose young daughter, Relara, has been struck by a terrible, corrupting illness. Desperate to save her, he works closely with local herbalist Orendil Broadleaf and traveling Alliance champions to gather sacred remedies from the surrounding wilds. His quest to heal Relara takes adventurers into some of Ashenvale's oldest sacred groves and ruins.",h="Pelturas Whitemoon is a night elf father dwelling in Astranaar whose young daughter, Relara, has been struck...",sec={{t="A Father's Plight in Astranaar",b="Residing in the serene boughs of Astranaar, Pelturas Whitemoon lives the quiet life typical of forest-dwelling Kaldorei, often venturing out with his young daughter Relara to collect shimmering moonstones around Fallen Sky Lake. However, when Relara falls critically ill with a mysterious affliction, his quiet world collapses into frantic desperation. Astranaar is besieged on many fronts, but for Pelturas, nothing in the great forest matters more than saving his child.",sp=0},{t="Ancient Cures and Corrupted Groves",b="Normal herbal remedies fail to break Relara's condition, prompting Pelturas to turn to the herbalist Orendil Broadleaf. Treating the affliction requires rare and sacred reagents tied to the land and the Moon Goddess, including an Elune's Tear and shimmering stardust from ancient Kaldorei ruins to cool her burning fever. Each step only narrowly keeps death at bay, highlighting how deeply the corruption spreading through Ashenvale's soil and waters has begun to touch its people.",sp=1},{t="Fallen Sky Lake",b="To fully restore Relara's vitality, Pelturas seeks a moonstone from the Shadethicket Oracle at Fallen Sky Lake. The lake, once a tranquil spot where father and daughter peacefully gathered stones together, has grown perilous due to the violent emergence of corrupted bog beasts. By crushing the recovered moonstone into a restorative tea, Pelturas finally breaks the lingering weakness, restoring Relara to health.",sp=1}},faq={{q="Who is Pelturas Whitemoon?",a="Pelturas Whitemoon is a night elf resident of Astranaar in central Ashenvale. He is best known for seeking the aid of passing Alliance travelers to gather sacred ingredients to cure his seriously ill daughter, Relara.",al={"pelturas","who is pelturas whitemoon","pelturas astranaar"}},{q="What is wrong with his daughter, Relara?",a="Relara suffers from a sudden, virulent disease that causes a severe fever and deep weakness. The sickness appears tied to the unnatural corruption spreading through Ashenvale's wilds, resisting mundane medicine and requiring sacred reagents to cleanse.",al={"relara illness","why is relara sick","relara disease"}},{q="Who helps Pelturas treat the sickness?",a="Pelturas seeks council from Orendil Broadleaf, a knowledgeable local night elf who prescribes traditional Kaldorei remedies, including cleansing stones and herbal poultices.",al={"pelturas herbalist","who helps relara","orendil broadleaf pelturas"}},{q="What reagents are needed to cure Relara?",a="Saving Relara requires a progression of treatments: an initial herbal draught from Orendil, a purifying Elune's Tear, powdered stardust from ancient ruins to break her burning fever, and a moonstone from Fallen Sky Lake brewed into tea to restore her vigor.",al={"cure reagents pelturas","relara cure ingredients","what cures relara"}},{q="Why is Fallen Sky Lake significant to Pelturas?",a="Fallen Sky Lake was a place where Pelturas and Relara used to spend time together gathering moonstones. The lake has recently been overtaken by hostile Shadethicket bog beasts, forcing Pelturas to ask adventurers to retrieve the moonstone needed for his daughter's recovery.",al={"fallen sky lake pelturas","moonstone fallen sky lake"}},{q="Is Pelturas a member of the Cenarion Circle or the Sentinels?",a="No. Pelturas is a civilian town resident of Astranaar, representing the everyday Kaldorei families who live within Ashenvale and suffer from the forest's encroaching dangers.",al={"is pelturas a sentinel","pelturas faction role"}}},ang={["race:NightElf"]="Pelturas's struggle reflects the vulnerability of everyday Kaldorei families as ancient glades fall prey to corruption and regional conflict.",["faction:Alliance"]="Helping Pelturas save his daughter reinforces the Alliance's commitment to defending and aiding the Kaldorei settlements in Kalimdor.",["class:Priest"]="The cleansing rites and holy reagents consecrated to Elune showcase the healing power and sacred reverence that the Sisterhood of Elune brings to night elf culture.",["profession:Herbalism"]="The sequence of natural draughts, poultices, and botanical tinctures needed for Relara highlights the deep connection between Kaldorei medicine and herbal lore."},kw={"ashenvale","astranaar","elune's tear","fallen sky lake","moonstone","orendil broadleaf","pelturas","relara","ruins of stardust","whitemoon"},rel={"subzone:astranaar","zone:ashenvale","npc:orendil-broadleaf","quest:1020","quest:1033","quest:1034","quest:1035","topic:elune"},src={"Pelturas Whitemoon"}}
E["npc:pixel"] = {t="npc",n="Pixel",z="ashenvale",s="Pixel is an enterprising goblin courier operating out of Splintertree Post in Ashenvale. Making her living delivering heavy goods across dangerous territories, she handles shipments like Warsong saw blades for the local Horde forces—though she never lets any cargo go without proper compensation.",h="Pixel is an enterprising goblin courier operating out of Splintertree Post in Ashenvale.",sec={{t="Business in the Deep Woods",b="While Splintertree Post serves as a fortified bastion for the Horde amidst the hostile canopies of Ashenvale, Pixel remains firmly focused on profit. As an independent courier willing to haul freight into active war zones, she provides essential logistics for the Warsong Clan's logging efforts. However, true to goblin custom, contracts and coin dictate her cooperation. She holds fast to her deliveries until the client produces payment, often demanding practical bounties like satyr horns from passing adventurers before relinquishing valuable lumbering supplies.",sp=0}},faq={{q="Who is Pixel?",a="Pixel is a freelance goblin courier stationed at Splintertree Post in eastern Ashenvale. She makes her trade hauling cargo through perilous lands, currently managing a shipment of saw blades vital to the local Warsong logging campaign.",al={"who is this goblin","pixel lore","splintertree goblin"}},{q="Why won't Pixel hand over the saw blades immediately?",a="Like any savvy goblin, Pixel operates strictly on business principles. Despite the Horde's urgency in Ashenvale, she refuses to release her cargo of saw blades without proper compensation or trade goods to cover her fee.",al={"why does pixel want payment","warsong saw blades delivery","saw blades quest"}},{q="Why does she want satyr horns?",a="Pixel accepts valuable trophies from the local forests, such as satyr horns, as currency or collateral. Satyrs are plentiful and hostile in Ashenvale, making their horns a recognizable and lucrative prize for a merchant willing to trade.",al={"why satyr horns","pixel satyrs","satyr quest splintertree"}},{q="Is Pixel officially a member of the Horde?",a="Pixel works closely with the Horde at Splintertree Post due to lucrative contracts with the Warsong lumber operations, but her primary loyalty lies with trade, profit, and fulfilling her delivery agreements.",al={"is pixel horde","pixel faction","is pixel neutral"}}},ang={["faction:Horde"]="For Horde champions fighting to establish a foothold in Ashenvale, Pixel provides the industrial hardware the Warsong Clan desperately needs to keep their logging machinery running."},kw={"ashenvale","courier","goblin","pixel","satyr horns","splintertree post","warsong saw blades"},rel={"subzone:splintertree-post","zone:ashenvale","quest:6581","quest:6441","topic:goblin","topic:satyr"},src={"Pixel"}}
E["npc:raene-wolfrunner"] = {t="npc",n="Raene Wolfrunner",z="ashenvale",s="Raene Wolfrunner is an accomplished Sentinel officer and hunter stationed at the heart of Astranaar in Ashenvale. Accompanied by her loyal wolf and saber cat companions, she coordinates defense efforts across the forest against encroaching Horde forces and corrupted furbolg tribes. She serves as a vital anchor for Alliance champions striving to protect the sacred wilderness.",h="Raene Wolfrunner is an accomplished Sentinel officer and hunter stationed at the heart of Astranaar in...",sec={{t="Defender of Astranaar",b="Raene Wolfrunner stands watchful in Astranaar alongside her trusty saber cat Korra and wolf Dagri. As an officer among the Sentinels, she oversees patrols throughout Ashenvale and coordinates intelligence reaching beyond its borders, dispatching scouts like Kaela Shadowspear into neighboring regions such as the Stonetalon Mountains. Raene's devotion to the ancient woods is absolute; she has declared she would sooner face the Horde's lumbering forces alone than watch them hack and burn through the sacred timber unhindered.",sp=0},{t="Stemming the Forest's Corruption",b="Beyond the tensions with the Horde, Raene is deeply invested in addressing the dark taint sickening Ashenvale's native denizens. She directs campaigns against hostile furbolg tribes, including aggressive strikes against the Foulweald camps harassing travelers and targeted culls against rising Thistlefur leadership. Her subordinate scouts keep close watch over changing furbolg behavior, relying on Raene's steady command to protect local settlements and passing wayfarers from coordinated ambushes.",sp=0},{t="Dartol's Rod",b="Raene's most personal crusade involves Dartol's Rod, an ancient relic tied to furbolg purification. Her longtime friend Teronis was slain while searching for the rod's missing gemstone, prompting Raene to order his body recovered and pledge to see his research fulfilled. Working in tandem with the dryad Shael'dryn, she helps champions assemble the relic, ultimately enabling an adventurer to assume furbolg guise, confer with chieftain Krolg, and defeat the tainted leader Ran Bloodtooth to purge the regional threat.",sp=1}},faq={{q="Where can Raene Wolfrunner be found?",a="Raene is stationed in Astranaar, the central night elf town of Ashenvale. She stands ready outdoors, flanked by her two animal companions.",al={"raene wolfrunner location","where is raene","raene astranaar spot"}},{q="Who are the animals standing next to Raene?",a="They are her trained hunting companions: a saber cat named Korra and a wolf named Dagri, who remain by her side in Astranaar.",al={"raene wolfrunner pets","raene wolf and cat","raene companions"}},{q="What is Raene's role within the Sentinels?",a="She acts as a ranking Sentinel officer in central Ashenvale, issuing orders to scouts, managing outposts, and coordinating tactical operations against local threats.",al={"raene rank","is raene an officer","raene sentinel role"}},{q="What happened to Raene's friend Teronis?",a="Teronis was aiding the Sentinels by seeking a gemstone needed for Dartol's Rod. He was slain in the field, leading Raene to recover his remains and complete his mission.",al={"who is teronis","raene friend teronis","teronis death"},sp=1},{q="Why is Raene focusing so heavily on the furbolgs?",a="Corrupted tribes like the Foulweald and Thistlefur have grown increasingly aggressive, ambushing travelers on forest roads and threatening the stability of Astranaar.",al={"raene furbolg quest","why fight thistlefur","foulweald ashenvale problem"}},{q="What is the purpose of Dartol's Rod in her questline?",a="The reconstructed rod allows an adventurer to temporarily adopt the form of a furbolg, opening communication with Krolg to target and vanquish the corrupt chieftain Ran Bloodtooth.",al={"dartols rod purpose","what does dartols rod do","raenes cleansing rod"},sp=1}},ang={["faction:Alliance"]="For Alliance travelers arriving from Darkshore, Raene is the principal officer coordinating the military and ecological defense of Ashenvale.",["race:NightElf"]="Raene embodies the Sentinel dedication to Elune and Kalimdor's wilderness, refusing to allow the woodland sanctuaries of Ashenvale to be despoiled.",["class:Hunter"]="As a seasoned hunter who commands both a wolf and a saber cat, Raene represents the wilderness mastery and kinship with beasts prized by her class."},kw={"ashenvale","astranaar","dagri","dartol","korra","raene","sentinels","teronis","thistlefur","wolfrunner"},rel={"subzone:astranaar","quest:991","zone:ashenvale","npc:shael-dryn","npc:krolg","npc:kaela-shadowspear","quest:1025","quest:1054"},src={"Raene Wolfrunner"}}
E["npc:ruul-snowhoof"] = {t="npc",n="Ruul Snowhoof",z="ashenvale",s="Ruul Snowhoof is a tauren druid held captive inside Thistlefur Hold in northern Ashenvale. Trapped in his bear form within a crude cage, he relies on Horde adventurers to break him out and guide him to safety.",h="Ruul Snowhoof is a tauren druid held captive inside Thistlefur Hold in northern Ashenvale.",sec={{t="A Bear in a Cage",b="Ruul Snowhoof ventured into northern Ashenvale only to fall into the clutches of the corrupt Thistlefur furbolgs. When captured, he assumed the shape of a mighty bear—a guise his captors entirely mistook for an actual wild beast. Instead of slaying him outright, the furbolgs locked him inside a wooden cage deep within Thistlefur Hold, leaving him to slowly starve. Weakened and unable to safely drop his form or fight his way out alone, Ruul waits for allies of the Horde to spring his lock, fight off his jailers, and clear a path through the den so he can return to his sister, Yama Snowhoof, at Splintertree Post.",sp=0}},faq={{q="Why is Ruul Snowhoof a bear in a cage?",a="Ruul is a tauren druid who took on Bear Form when confronted by the Thistlefur furbolgs. His captors mistook him for a genuine wild beast rather than a shapeshifted druid and locked him away in a cage deep inside their hold.",al={"why is ruul a bear","ruul snowhoof bear form","why is he caged"}},{q="Why don't the furbolgs just kill Ruul?",a="The corrupted Thistlefur furbolgs chose to keep Ruul captive in his beast form and are, for reasons of their own cruelty or malice, slowly starving him in his cage rather than slaying him immediately.",al={"why starving ruul","what do furbolgs want with ruul"}},{q="Where does Ruul go after escaping Thistlefur Hold?",a="Once escorted past the furbolg patrols to the safety outside Thistlefur Hold, Ruul directs his saviors to report his survival to his sister, Yama Snowhoof, who is stationed at Splintertree Post.",al={"where does ruul go","ruul snowhoof destination"}},{q="Can Alliance players interact with Ruul Snowhoof?",a="No. Ruul Snowhoof is loyal to the Horde and will only offer his escape quest and assistance to Horde adventurers who discover his cage.",al={"is ruul horde only","alliance ruul snowhoof"}}},ang={["class:Druid"]="Finding a brother of the Cenarion path caged in beast form by corrupted furbolgs underscores the creeping taint affecting Ashenvale's wildlife and primitive tribes.",["race:Tauren"]="Ruul belongs to the respected Snowhoof family; rescuing him ensures one of your own blood returns alive to his sister Yama at Splintertree Post."},kw={"bear form","freedom to ruul","ruul snowhoof","splintertree post","thistlefur furbolgs","thistlefur hold","yama snowhoof"},rel={"quest:6482","subzone:thistlefur-hold","subzone:splintertree-post","zone:ashenvale","topic:druid","topic:furbolg","topic:tauren","topic:horde"},src={"Ruul Snowhoof"}}
E["npc:senani-thunderheart"] = {t="npc",n="Senani Thunderheart",z="ashenvale",s="Senani Thunderheart is a tauren huntress stationed at Silverwind Refuge on the shores of Mystral Lake in Ashenvale. Serving the Horde, she tests the mettle of passing travelers by challenging them to pursue the fierce wild predators that roam the ancient forest. Through her trials, hunters prove their skill while thinning the deadly beasts prowling near Horde territory.",h="Senani Thunderheart is a tauren huntress stationed at Silverwind Refuge on the shores of Mystral Lake in...",sec={{t="The Master of the Hunt",b="Found keeping camp at Silverwind Refuge, Senani Thunderheart represents the hunting traditions of the tauren amid the shadowed groves of Ashenvale. Far from the open plains of Mulgore, she directs Horde adventurers to test their tracking and combat prowess against the forest's apex beasts. She views the hunt as both an honorable challenge and a necessary ritual to survive in an untamed, contested land.",sp=0},{t="The Beasts of Ashenvale",b="Senani oversees the traditional hunting trials of Ashenvale, directing hunters toward three notorious predators: the bear Ursangous, the cat Shadumbra, and the hippogryph Sharptalon. Claiming their tokens—a paw, a head, and a claw—is a rite of passage that demonstrates a hunter's respect for the land and dominion over its fiercest denizens. In addition to these predatory challenges, she also watches the growing threat of corrupted wildlife and hostile furbolgs encroaching on the region.",sp=0}},faq={{q="Who is Senani Thunderheart?",a="Senani Thunderheart is a tauren huntress and quest giver located at Silverwind Refuge in Ashenvale. She serves the Horde by directing adventurers to hunt the most dangerous wildlife prowling the forest.",al={"who is senani","senani thunderheart lore","silverwind refuge questgiver"}},{q="Where can I find Senani Thunderheart?",a="Senani is stationed at Silverwind Refuge, an encampment on the southeastern bank of Mystral Lake in south-central Ashenvale, just off the main road.",al={"senani location","where is senani","where is silverwind refuge"}},{q="What is the Ashenvale Hunt?",a="The Ashenvale Hunt is a series of hunting challenges issued by Senani. Hunters are tasked with tracking down and slaying three legendary forest predators: Ursangous the bear, Shadumbra the nightsaber, and Sharptalon the hippogryph.",al={"the ashenvale hunt","what does senani want","hunting quests ashenvale"}},{q="Which trophies does Senani require for the hunt?",a="She asks hunters to return with Ursangous's Paw, Shadumbra's Head, and Sharptalon's Claw to prove that all three formidable beasts have been bested.",al={"hunt trophies","ashenvale hunt items","what does senani need"}},{q="Does Senani have any connection to the furbolgs in the area?",a="Yes, Senani tracks threats to the refuge and the nearby roads, offering tasks like confronting the Foulweald furbolg tribe and their leader to prevent them from overrunning the area.",al={"foulweald quest","king of the foulweald","senani furbolg"}},{q="Is Senani affiliated with the Cenarion Circle?",a="No, Senani is aligned directly with the Horde and the tauren tribes, approaching the woods from the perspective of a traditional hunter rather than a Cenarion druidic guardian.",al={"is senani a druid","senani cenarion circle"}}},ang={["race:Tauren"]="For tauren travelers, meeting Senani brings a reminder of the Earth Mother's trials, honoring the ancient balance between hunter and quarry even far from Mulgore.",["class:Hunter"]="Senani embodies the classic hunter's spirit, testing your tracking skills against Ashenvale's elusive beasts: Ursangous, Shadumbra, and Sharptalon.",["faction:Horde"]="Silverwind Refuge serves as a useful waystation in central Ashenvale, where Senani helps Horde scouts prove their worth and secure the wilderness."},kw={"ashenvale","ashenvale hunt","mystral lake","senani","shadumbra","sharptalon","silverwind refuge","thunderheart","ursangous"},rel={"subzone:silverwind-refuge","zone:ashenvale","quest:235","quest:247","quest:23","quest:24","quest:2","quest:6621"},src={"Senani Thunderheart"}}
E["npc:sentinel-farsong"] = {t="npc",n="Sentinel Farsong",z="ashenvale",s="Sentinel Farsong is a night elf sentinel stationed at Silverwing Grove in Ashenvale. Serving as a crucial liaison for the Silverwing Sentinels, she coordinates intelligence and combat efforts against the encroaching Warsong Outriders in Warsong Gulch.",h="Sentinel Farsong is a night elf sentinel stationed at Silverwing Grove in Ashenvale.",sec={{t="Guardian of Silverwing Grove",b="Standing vigil within Silverwing Grove, Sentinel Farsong is deeply involved in the defense of Ashenvale's southern border. With the Warsong clan continuously harvesting lumber and pushing deeper into ancestral night elf territories, she mobilizes Alliance champions to strike at Warsong Outriders and ensures field reports reach Silverwing command. Her duties center on rallying volunteers to check the Horde's territorial expansion and preserve the sacred woods.",sp=0}},faq={{q="Who is Sentinel Farsong?",a="Sentinel Farsong is a night elf sentinel affiliated with the Silverwing Sentinels in Ashenvale. Stationed at Silverwing Grove near the entrance to Warsong Gulch, she recruits Alliance adventurers and collects critical battle intelligence.",al={"farsong","sentinel farsong lore","who is farsong"}},{q="Where can she be found?",a="She is located at Silverwing Grove in southeastern Ashenvale, the staging ground for the Alliance's ongoing military efforts in Warsong Gulch.",al={"sentinel farsong location","where is farsong","farsong ashenvale map"}},{q="Why is she fighting the Warsong Outriders?",a="The Warsong Outriders are harvesting timber and desecrating the sacred forests of Ashenvale. Farsong coordinates defense efforts to halt their operations and reclaim territory claimed by the Horde.",al={"why fight warsong outriders","farsong motivation","ashenvale conflict"}}},ang={["faction:Alliance"]="Sentinel Farsong represents the Alliance's frontline mobilization in Ashenvale, directing volunteers directly into the struggle against the Warsong Clan.",["race:NightElf"]="As a protector of Elune's sacred woods, Farsong embodies the kaldorei commitment to driving out any who defile the ancient groves."},kw={"ashenvale","sentinel farsong","silverwing grove","silverwing sentinels","warsong gulch","warsong outriders"},rel={"subzone:silverwing-grove","quest:9521","npc:warsong-outrider","zone:ashenvale","topic:night-elf","topic:alliance"},src={"Sentinel Farsong"}}
E["npc:sentinel-luciel-starwhisper"] = {t="npc",n="Sentinel Luciel Starwhisper",z="ashenvale",s="Sentinel Luciel Starwhisper is a night elf scout stationed deep inside enemy territory near the Warsong Lumber Camp in Ashenvale. Operating covertly right at the edge of the Horde's logging operations, she works tirelessly to disrupt the Warsong clan's destruction of the sacred ancient forest.",h="Sentinel Luciel Starwhisper is a night elf scout stationed deep inside enemy territory near the Warsong...",sec={{t="Eyes on the Lumber Camp",b="While most Sentinels hold defensive perimeters at Silverwind Refuge or Astranaar, Luciel Starwhisper conducts forward reconnaissance directly adjacent to the Warsong Lumber Camp. The encroaching orcs have heavily deforested southern Ashenvale, utilizing iron shredders and explosive devices to fell ancient trees. Luciel observes these devastating operations from the brush, directing capable Alliance scouts and adventurers to dismantle Horde machinery, defuse ordnance, and eliminate the engineers driving the deforestation.",sp=0}},faq={{q="Who is Sentinel Luciel Starwhisper?",a="Luciel Starwhisper is a night elf Sentinel operating as a field scout near the Warsong Lumber Camp in southern Ashenvale. She monitors Horde logging operations and recruits Alliance allies to actively sabotage Warsong machinery and explosives.",al={"who is luciel","luciel starwhisper lore","luciel starwhisper role"}},{q="Why is she stationed so close to the Warsong Lumber Camp?",a="Her post provides critical forward observation on the Warsong clan's harvest operations. From her vantage point, she can spot incoming machinery and supply stockpiles, coordinating strikes before the orcs clear deeper into Ashenvale's sacred groves.",al={"why is she near warsong","luciel location","why is luciel here"}},{q="Is she related to anyone else in Kalimdor?",a="She shares her surname with Jenai Starwhisper, an astronomer of Darnassus, suggesting she belongs to the Starwhisper lineage, though she chose the path of the martial Sentinels rather than peaceful study.",al={"jenai starwhisper relative","starwhisper family","luciel starwhisper relatives"}}},ang={["race:NightElf"]="For the kaldorei, Luciel stands on the front line of an existential battle to preserve the sacred boughs of Ashenvale from the axes of the Warsong Outriders.",["faction:Alliance"]="Alliance operatives moving through contested territory can assist Luciel to blunt the Horde's industrial supply lines in central Kalimdor."},kw={"ashenvale","luciel","lumber camp","scout","sentinel","shredders","starwhisper","warsong"},rel={"subzone:warsong-lumber-camp","zone:ashenvale","topic:night-elf","quest:9518"},src={"Sentinel Luciel Starwhisper"}}
E["npc:sentinel-melyria-frostshadow"] = {t="npc",n="Sentinel Melyria Frostshadow",z="ashenvale",s="Sentinel Melyria Frostshadow is a night elf sentinel stationed at Raynewood Tower in central Ashenvale. Standing guard along the contested forest roads, she directs Alliance adventurers to recover fallen comrades and investigate eerie disturbances taking root in the wild wood.",h="Sentinel Melyria Frostshadow is a night elf sentinel stationed at Raynewood Tower in central Ashenvale.",sec={{t="The Vigil at Raynewood",b="Raynewood Tower serves as a crucial night elf defensive post in the eastern reaches of Ashenvale, watching over the path between the Silverwing Outpost and Splintertree Post. Sentinel Melyria Frostshadow stands watch here, contending with the ongoing friction against Horde invaders and the local satyr and wildkin threats. From this vantage point, she coordinates local defensive efforts, tracking down fallen sentinels and keeping military lines of communication intact.",sp=0},{t="Echoes of Velinde Starsong",b="Beyond routine skirmishes, Frostshadow is deeply troubled by unsettling mysteries that have crept into the woodland. She is one of the few sentinels willing to speak of the Howling Vale, an eerie den of ferocious lupine beasts nestled in the woods. Her investigations touch upon the lingering riddle of Sentinel Velinde Starsong, an honored night elf commander who mysteriously vanished after wielding an enigmatic, summoning artifact in the shadowed glades.",sp=1}},faq={{q="Who is Sentinel Melyria Frostshadow?",a="She is a night elf sentinel officer stationed at Raynewood Tower in Ashenvale. She organizes local patrols, aids in recovering fallen night elf troops, and investigates strange supernatural happenings across the forest.",al={"who is melyria","melyria frostshadow info","raynewood sentinel"}},{q="Where can I find Sentinel Melyria Frostshadow?",a="She is stationed at Raynewood Tower, located along the main road in central-eastern Ashenvale, east of Astranaar and west of Splintertree Post.",al={"melyria location","where is melyria frostshadow","find melyria"}},{q="What is Raynewood Tower?",a="Raynewood Tower is an Alliance outpost and watchtower in Ashenvale. It safeguards the highway through the forest against hostile wildlife, satyrs, and Horde military forces venturing from nearby bases.",al={"raynewood tower lore","what is raynewood"}},{q="What is the connection between Melyria and Velinde Starsong?",a="Melyria directs adventurers to investigate the Howling Vale, a grove plagued by strange wolf-like horrors, in hopes of unraveling what truly became of Sentinel Velinde Starsong after she disappeared under mysterious circumstances.",al={"velinde starsong quest","howling vale mystery"}}},ang={["faction:Alliance"]="Melyria provides critical operational support in central Ashenvale, anchoring Alliance resistance and uncovering dangerous mysteries behind enemy lines.",["race:NightElf"]="As a sister of the Sentinels, Frostshadow honors fallen defenders and seeks truth regarding the fate of Velinde Starsong, one of the sisterhood's missing leaders."},kw={"ashenvale","frostshadow","melyria","raynewood","sentinel","starsong","velinde"},rel={"quest:1037","quest:1022","subzone:howling-vale","zone:ashenvale","topic:night-elf","quest:9521"},src={"Sentinel Melyria Frostshadow"}}
E["npc:sentinel-selarin"] = {t="npc",n="Sentinel Selarin",z="ashenvale",s="Sentinel Selarin is a night elf scout dispatched to the coastal settlement of Auberdine. Acting as an emissary for the defenders of Ashenvale, she seeks reinforcements to help stem the rising perils threatening the ancient forest.",h="Sentinel Selarin is a night elf scout dispatched to the coastal settlement of Auberdine.",sec={{t="A Plea for Reinforcements",b="As tensions and dark threats mount across Ashenvale, the garrison there has found its resources stretched to the breaking point. Under the direction of Raene Wolfrunner, Sentinel Selarin traveled north along the forest road into Darkshore. Her mission was straightforward: seek out Terenthis in Auberdine and request assistance from the sentinels and scouts stationed on the coast.",sp=0},{t="Rallying the Wayfarers",b="Upon arriving in Auberdine, Selarin found Terenthis thoroughly consumed by local duties and unable to personally answer the call. Rather than returning empty-handed, Selarin resolved to remain in town and enlist capable travelers passing through Darkshore. She directs proven adventurers south toward Astranaar, urging them to lend their blades and spells to Raene Wolfrunner's beleaguered forces.",sp=0}},faq={{q="Who is Sentinel Selarin?",a="Sentinel Selarin is a night elf warrior of the Sentinels. She serves as a courier and liaison, dispatched from Ashenvale to solicit aid from the settlement of Auberdine in Darkshore.",al={"selarin lore","who is selarin","sentinel selarin"}},{q="Why did Selarin come to Auberdine?",a="She was ordered by Raene Wolfrunner to locate Terenthis in Auberdine and secure reinforcements to combat the growing dangers threatening the Ashenvale wilderness.",al={"why is selarin in darkshore","selarin mission","what is selarin doing"}},{q="Why didn't Terenthis go to Ashenvale with her?",a="Terenthis was tied up managing critical affairs and investigating threats within Darkshore itself. Consequently, Selarin decided to recruit independent Alliance travelers to journey south instead.",al={"why doesn't terenthis help","terenthis and selarin","terenthis busy"}},{q="Where does she send adventurers?",a="She directs adventurers southward across the border into Ashenvale to report directly to Raene Wolfrunner at Astranaar.",al={"where does selarin send me","selarin quest destination","after selarin"}}},ang={["faction:Alliance"]="Selarin serves as an important bridge for Alliance champions journeying south from Darkshore into the contested wilderness of Ashenvale.",["race:NightElf"]="As a member of the Sentinels, Selarin embodies the vigilance and unity required to defend the ancestral borders of the kaldorei."},kw={"ashenvale","auberdine","darkshore","raene wolfrunner","selarin","sentinel selarin","sentinels","terenthis"},rel={"npc:terenthis","npc:raene-wolfrunner","subzone:auberdine","zone:darkshore","zone:ashenvale","quest:990","topic:sentinels","topic:night-elf"},src={"Sentinel Selarin"}}
E["npc:sentinel-velene-starstrike"] = {t="npc",n="Sentinel Velene Starstrike",z="ashenvale",s="Sentinel Velene Starstrike is a night elf guardian stationed at Silverwind Refuge in central Ashenvale. Tasked with protecting the sanctuary and the surrounding waters, she confronts encroaching unnatural threats such as rogue elementals and foul sorcerers. Her vigilance helps safeguard the ancient woodland from corrupting magical interference.",h="Sentinel Velene Starstrike is a night elf guardian stationed at Silverwind Refuge in central Ashenvale.",sec={{t="Guardian of Silverwind",b="Stationed beside the clear waters of Mystral Lake, Sentinel Velene Starstrike maintains a watchful vigil from Silverwind Refuge. Like many night elf sentinels scattered throughout Ashenvale, her primary duty is preserving the balance of the forest and repelling threats to elven sanctuaries. The serene grove serves as a vital rest stop for travelers traversing the central woods, making her presence essential to the area's ongoing safety.",sp=0},{t="Disturbances at Mystral Lake",b="The peace around Silverwind Refuge is fragile. Velene keeps close watch over Mystral Lake, where erratic elemental spirits and reckless mage summoners disrupt the natural rhythm of the wilderness. Through her direction, champions are dispatched to suppress rogue water elementals and put an end to the careless practitioners disturbing the spirits of the land.",sp=0}},faq={{q="Where is Sentinel Velene Starstrike located?",a="Sentinel Velene Starstrike is stationed at Silverwind Refuge, an Alliance outpost situated in central Ashenvale near the southeastern shore of Mystral Lake.",al={"velene starstrike location","where is velene","silverwind refuge quest giver"}},{q="What tasks does Sentinel Velene assign?",a="Velene asks adventurers to deal with the disturbed spirits and practitioners around Mystral Lake, sending them to collect bracers from restless elementals and neutralize the rogue summoners agitating the waters.",al={"velene starstrike quests","what quests does velene give"}},{q="What is the threat at Mystral Lake?",a="The waters of Mystral Lake have been troubled by aggressive water elementals, stirred into turmoil and exploited by mortal mage summoners who practice their craft without regard for the forest's delicate harmony.",al={"mystral lake problem","why are elementals at mystral lake"}},{q="Is Velene related to anyone else in Kalimdor?",a="She shares the Starstrike surname with Layo Starstrike, a night elf stationed far to the south in the harsh wastes of Silithus, suggesting they belong to the same lineage or house.",al={"starstrike family","layo starstrike relative"}},{q="What is Silverwind Refuge?",a="Silverwind Refuge is a serene night elf retreat nestled along the shores of Mystral Lake in Ashenvale. It serves as a peaceful haven and tactical outpost for Sentinels and allied travelers navigating the wild interior of the forest.",al={"what is silverwind refuge","silverwind refuge lore"}},{q="Why do the Sentinels care about elemental activity?",a="Night elves view the wilderness as a sacred, living ecosystem. Violent or corrupted elementals disrupt native wildlife and corrupt the natural waterways, forcing the Sentinels to intervene and restore equilibrium.",al={"why do night elves fight elementals","sentinels and elementals"}}},ang={["race:NightElf"]="Sentinel Velene embodies the tireless commitment of the Sentinels, standing as a bulwark against magical recklessness to preserve Ashenvale's natural harmony.",["faction:Alliance"]="Silverwind Refuge offers safety along a dangerous road, with Sentinel Velene coordinating local efforts to keep central Ashenvale secure.",["class:Mage"]="Velene holds little patience for irresponsible spellcasters whose reckless conjurations agitate local elementals and pollute natural waters."},kw={"ashenvale","elemental bracers","mage summoner","mystral lake","sentinel","silverwind refuge","starstrike","velene"},rel={"subzone:silverwind-refuge","subzone:mystral-lake","zone:ashenvale","quest:1016","quest:1017","topic:night-elf","zone:silithus"},src={"Sentinel Velene Starstrike"}}
E["npc:shael-dryn"] = {t="npc",n="Shael'dryn",z="ashenvale",s="Shael'dryn is an inquisitive dryad residing at Raynewood Retreat in eastern Ashenvale. Known for her lighthearted wit and fondness for wordplay, she serves as a vital contact for night elf scouts investigating forest corruption. She plays a pivotal role in aiding Astranaar's sentinels with cleansing relics to combat demonic and foul influences spreading across the wilderness.",h="Shael'dryn is an inquisitive dryad residing at Raynewood Retreat in eastern Ashenvale.",sec={{t="A Jester of the Woods",b="Daughter of Cenarius like all dryads, Shael'dryn approaches the perils of the wild with an unexpectedly playful spirit. Companions and travelers know her as a lover of puns and spoken jests, often using lighthearted humor to cut through the brooding tension of the tainted woodland. Yet behind her teasing demeanor lies deep devotion to the well-being of Ashenvale and its ancient spirits.",sp=0},{t="Guardian of Raynewood",b="Stationed around Raynewood Retreat, Shael'dryn keeps watch alongside the night elf sentinels guarding the eastern approaches of the forest. When corruption surfaces among the local wildlife or tainted relics threaten the land's harmony, her deep natural understanding allows her to guide adventurers through the steps required to restore spiritual balance.",sp=0},{t="Purification of the Woods",b="Shael'dryn works closely in coordination with Raene Wolfrunner in Astranaar. When sentinels recover tainted artifacts such as corrupted glowing gems and the lost Rod of Tethis, Shael'dryn knows the obscure rituals, moonwell waters, and natural tokens needed to purify them, transforming dark curiosities into potent cleansing tools for the Alliance.",sp=1}},faq={{q="Who is Shael'dryn?",a="Shael'dryn is a dryad found at Raynewood Retreat in Ashenvale. She aids Alliance adventurers with woodland lore and natural magic, all while indulging her penchant for puns and jokes.",al={"who is she","shael dryn lore","shaeldryn identity"}},{q="Where can I find Shael'dryn?",a="She can be found at Raynewood Retreat, an Alliance-aligned outpost situated in the eastern reaches of Ashenvale along the road toward Azshara.",al={"shaeldryn location","where is shael'dryn","raynewood dryad"}},{q="What is Shael'dryn's connection to Raene Wolfrunner?",a="Raene Wolfrunner directs adventurers to Shael'dryn because the dryad possesses the spiritual knowledge necessary to investigate and cleanse corrupted gems and relics recovered throughout the forest.",al={"raene and shaeldryn","raenes cleansing dryad","why send me to shaeldryn"}},{q="What is unique about Shael'dryn's appearance?",a="Shael'dryn and her fellow dryad Illiyana share an uncommon coloration that sets their models apart from most other dryads encountered across Kalimdor.",al={"dryad model","unique skin","shaeldryn color"}},{q="What kind of personality does she have?",a="Unlike the stern and somber tone common among many Kaldorei defenders, Shael'dryn is recognized by her peers as a lover of humor and clever wordplay, maintaining a jovial outlook despite the forest's plight.",al={"shaeldryn personality","does she joke","shaeldryn jokes"}},{q="Is Shael'dryn friendly to the Horde?",a="No. Positioned at the Alliance outpost of Raynewood Retreat and closely allied with the Astranaar Sentinels, Shael'dryn is hostile toward members of the Horde.",al={"can horde talk to shaeldryn","horde rep","is shaeldryn alliance only"}}},ang={["race:NightElf"]="For the Kaldorei, Shael'dryn is a welcome sister of the forest whose natural ties to Cenarius make her indispensable for cleansing tainted woodland relics.",["class:Druid"]="Druids will appreciate her natural connection to the spirits of Kalimdor and her insight into restoring flora and fauna warped by dark powers.",["faction:Alliance"]="Raynewood Retreat serves as an important sanctuary in eastern Ashenvale, where Shael'dryn assists Alliance forces resisting corruption and hostile encroachment."},kw={"ashenvale","cenarius","cleansing","dryad","illiyana","raene","raynewood","shael'dryn","shaeldryn"},rel={"npc:illiyana","quest:991","zone:ashenvale"},src={"Shael'dryn"}}
E["npc:shindrell-swiftfire"] = {t="npc",n="Shindrell Swiftfire",z="ashenvale",s="Shindrell Swiftfire is a night elf sentinel and scout stationed in Astranaar, the heart of night elf operations in Ashenvale. Keenly aware of shifting perils along Kalimdor's western reaches, she directs capable Alliance adventurers toward gathering threats on the coastline and nearby mountain passes. Her duties make her an essential hub for coordinating local defense against emerging oceanic and wild menaces.",h="Shindrell Swiftfire is a night elf sentinel and scout stationed in Astranaar, the heart of night elf...",sec={{t="A Watchful Eye in Astranaar",b="From Astranaar's winding walkways, Shindrell Swiftfire serves as an alert observer of Ashenvale's broader frontiers. While the forest's Sentinels are constantly pressured by the Horde's logging incursions from the east and south, Shindrell keeps her eyes fixed on dangers that lie beyond the immediate woodland front. She acts as a vital liaison for travelers arriving from Darkshore or heading out toward the jagged ridges of Stonetalon, ensuring no sudden menace strikes Astranaar undefended from the flank.",sp=0},{t="The Menace on the Coast",b="Among Shindrell's primary concerns is the troubled Zoram Strand on Ashenvale's northwestern shore. The sudden emergence of hostile naga crawling from the ocean depths poses a grave mystery and direct threat to the Kaldorei settlements. By dispatching seasoned fighters to investigate the shoreline and coordinate with scouts closer to the scene, Shindrell works to contain the serpentine invaders before they secure a permanent foothold on ancient night elf lands.",sp=0}},faq={{q="Where can I find Shindrell Swiftfire?",a="Shindrell Swiftfire is stationed in Astranaar, the central night elf town in Ashenvale. She can be found among the settlement's wooden walkways coordinating scouting operations and receiving travelers.",al={"shindrell swiftfire location","where is shindrell","find shindrell swiftfire"}},{q="What is Shindrell's role in Astranaar?",a="She acts as a scout coordinator and quest giver for the Alliance, directing adventurers toward outward threats that menace Ashenvale, such as the naga on the western coast and wild beasts in the nearby mountain ranges.",al={"what does shindrell do","who is shindrell swiftfire","shindrell purpose"}},{q="Why does she send scouts to the Zoram Strand?",a="Hostile naga have surged onto the western shores of Ashenvale, claiming ruins and menacing night elf borders. Shindrell directs adventurers to scout the beaches and assist field sentinels in curbing the serpentine threat.",al={"why zoram strand","shindrell naga quest","the zoram strand mission"}},{q="What connects Shindrell to Stonetalon Mountains?",a="With Ashenvale under threat from all sides, securing the high passes is vital. Shindrell dispatches scouts to deal with aggressive Pridewing wyverns and to maintain contact with Kaldorei scouts watching the Stonetalon boundary.",al={"stonetalon quests","pridewings quest","why stonetalon"}},{q="Does Shindrell have ties to Blackfathom Deeps?",a="Her focus on the Zoram Strand leads directly into the shadow of Blackfathom Deeps. By investigating the naga along the coast, adventurers sent by Shindrell uncover the darker aquatic menace festering beneath the waves.",al={"shindrell blackfathom","blackfathom deeps connection","shindrell bfd"}},{q="Who is Kayneth Stillwind, and why does Shindrell mention him?",a="Kayneth Stillwind is an allied scout stationed in the wilderness. Shindrell directs adventurers to locate him so that vital intelligence and reinforcements can be shared across distant posts in the region.",al={"who is kayneth","kayneth stillwind quest","kayneth connection"}}},ang={["race:NightElf"]="For night elves, Shindrell represents the vigilant Sentinels guarding Ashenvale's fringes against ancient foes like the naga while the bulk of their forces face the Horde.",["faction:Alliance"]="Shindrell serves as an operational bridge in Astranaar, guiding fresh Alliance arrivals deeper into the contentious and dangerous terrain of central Kalimdor.",["class:Hunter"]="Her tasks involving tracking pridewings and assessing untamed coastlines resonate with scouts and rangers adept at surviving the wilderness."},kw={"ashenvale","astranaar","naga","pridewings","sentinel","shindrell","stonetalon","swiftfire","zoram strand"},rel={"subzone:astranaar","zone:ashenvale","subzone:zoram-strand","quest:1008","quest:1134","quest:4581","topic:naga","topic:night-elf"},src={"Shindrell Swiftfire"}}
E["npc:talen"] = {t="npc",n="Talen",z="ashenvale",s="Talen is a night elf amateur archaeologist encamped near the Zoram Strand in northwestern Ashenvale. Despite the constant danger posed by nearby naga and Horde outposts, he is dedicated to recovering ancient kaldorei relics buried along the coast.",h="Talen is a night elf amateur archaeologist encamped near the Zoram Strand in northwestern Ashenvale.",sec={{t="Scholar on the Coast",b="Perched at Blackfathom Camp on the edge of the Zoram Strand, Talen spends his days pursuing historical curiosities rather than waging war. While the wilderness of Ashenvale is fraught with territorial skirmishes and hostile shoreline denizens, Talen remains focused on gathering long-lost treasures from the ruins submerged beneath the waves and sands. He relies heavily on passing adventurers to braving the savage Wrathscale naga and retrieve elusive artifacts—including pristine statuettes and the talismans of dangerous sea-dwelling matriarchs like Ruuzel.",sp=0}},faq={{q="Who is Talen?",a="Talen is a night elf scholar and amateur archaeologist residing at Blackfathom Camp in Ashenvale. Rather than serving as a sentinel or soldier, he studies the ancient relics buried along the seashore.",al={"who is this night elf","talen ashenvale","talen zoram strand"}},{q="Why is Talen camping near the Zoram Strand?",a="He is investigating the sunken ruins and shores of the Zoram Strand to recover ancient kaldorei artifacts. Because the beach is crawling with violent naga and lies close to the Horde outpost of Zoram'gar, he stays at a small campsite tucked away from the main shoreline.",al={"why is talen here","talen purpose","blackfathom camp purpose"}},{q="What artifacts does Talen want?",a="Talen enlists travelers to search the coastline for ancient statuettes washed ashore and tasks them with hunting down the powerful naga Ruuzel on a nearby offshore isle to retrieve a unique scrying ring.",al={"talen quests","what does talen need","ruuzel quest"}},{q="Is Talen hostile to the Horde?",a="While Talen is allied with the night elves, he is primarily a scholar and does not aggressively attack Horde travelers unless provoked or attacked first.",al={"does talen attack horde","horde friendly talen"}}},ang={["race:NightElf"]="For the kaldorei, the Zoram Strand is a tragic reminder of the Sundering; Talen represents a desire to preserve and recover the heritage lost when ancient coastal estates slid into the Great Sea.",["faction:Alliance"]="Talen provides Alliance travelers with a valuable field contact in the contested northern reaches of Ashenvale, not far from Maestra's Post."},kw={"ancient statuette","archaeologist","ashenvale","blackfathom camp","ruuzel","talen","zoram strand"},rel={"subzone:blackfathom-camp","subzone:zoram-strand","quest:1007","quest:1009","zone:ashenvale","subzone:zoram-gar-outpost","subzone:maestra-s-post","topic:night-elf"},src={"Talen"}}
E["npc:teronis-corpse"] = {t="npc",n="Teronis' Corpse",z="ashenvale",s="Teronis' Corpse lies on a secluded island within Lake Falathim in western Ashenvale. Before his untimely demise, this night elf scout was dispatched from Astranaar on a crucial mission to recover Dartol's Rod to aid in cleansing the forest.",h="Teronis' Corpse lies on a secluded island within Lake Falathim in western Ashenvale.",sec={{t="A Scout's Grim Fate",b="Sent forth by Raene Wolfrunner from the settlement of Astranaar, Teronis was tasked with recovering the lost rod of Dartol, an ancient night elf relic capable of purifying corrupted woodland magic. His search brought him deep into the waters of Lake Falathim, but the journey turned fatal when hostile murlocs swarmed the island. Teronis fell in battle, leaving his journal behind and the rod's radiant gemstone plundered by the lake's aggressive amphibians.",sp=0}},faq={{q="Who was Teronis?",a="Teronis was a night elf scout sent out from Astranaar by Sentinel Raene Wolfrunner. He was tasked with retrieving Dartol's Rod, an old artifact needed to cleanse demonic corruption seeped into Ashenvale's soil and waters.",al={"who is teronis","teronis lore","identity of teronis"}},{q="How did Teronis die?",a="Teronis was ambushed and slain by the aggressive murlocs that infest the shores and waters of Lake Falathim while attempting to secure the rod's components.",al={"who killed teronis","teronis cause of death","how did he die"}},{q="Where is his lost gemstone?",a="After Teronis was killed, the glowing gemstone that crowned Dartol's Rod was scavenged by the local murlocs dwelling around Lake Falathim.",al={"where is the gem","lost gem","teronis gem"}},{q="Why is recovering his mission so important to Astranaar?",a="Ashenvale's wildlife and woodland pools are increasingly suffering from vile demonic and fel taint. Dartol's Rod holds innate cleansing magic that the Sentinels hope will reverse or hold back this persistent rot.",al={"why help raene","dartol rod purpose"}}},ang={["race:NightElf"]="Finding Teronis fallen in the wilds is a sobering reminder of how dangerous Ashenvale has become even to seasoned Sentinels and scouts.",["faction:Alliance"]="Honoring the sacrifice of Astranaar's scouts means carrying on their unfinished work to purge the land of looming corruption."},kw={"ashenvale","astranaar","dartol's rod","lake falathim","murloc","raene wolfrunner","teronis","teronis' corpse"},rel={"quest:991","subzone:lake-falathim","zone:ashenvale","topic:murloc","topic:night-elf"},src={"Teronis' Corpse"}}
E["npc:therylune"] = {t="npc",n="Therylune",z="ashenvale",s="Therylune is a dryad found held captive at the Master's Glaive in southern Darkshore. Entrapped by the insidious Twilight's Hammer cultists who have occupied the ancient site, she relies on bold travelers to help her break free and escape their clutches.",h="Therylune is a dryad found held captive at the Master's Glaive in southern Darkshore.",sec={{t="Captive of the Cult",b="Dryads are guardians of nature and daughters of Cenarius, normally roaming the tranquil woodlands of northern Kalimdor. However, Therylune ventured too close to the ominous excavation at the Master's Glaive in southern Darkshore, where Twilight's Hammer cultists have gathered. Ambushed and trapped by the dark cult, she is unable to fight her way out alone through the swarms of cultists and requires an escort to flee to safety.",sp=0}},faq={{q="Who is Therylune?",a="Therylune is a dryad, one of the woodland daughters of the demigod Cenarius. She has been captured by Twilight's Hammer cultists operating at the Master's Glaive in southern Darkshore.",al={"who is therylune","therylune lore","what is therylune"}},{q="Why is Therylune trapped at the Master's Glaive?",a="Therylune was ambushed and pinned down by the Twilight's Hammer cultists who have established a dark camp around the giant petrified remains at the Master's Glaive.",al={"why is she captured","how did therylune get caught","masters glaive cultists"}},{q="Does Therylune have any family?",a="Yes, Therylune is the sister of Therysil, another dryad who dwells in the woodlands of northern Kalimdor.",al={"therylune sister","therysil therylune","therylune family"}},{q="What happens once you help her escape?",a="When adventurers clear a path through the hostile cultists, Therylune successfully flees the Master's Glaive and returns to the safety of the surrounding wilds.",al={"therylunes escape","quest 945","what does therylune do"},sp=1}},ang={["class:Druid"]="As stewards of nature aligned with Cenarius and his kin, druids feel a direct kinship and urgent duty to rescue a dryad captured by malevolent cultists.",["race:NightElf"]="Night elves share sacred ancient ties with the daughters of Cenarius, making Therylune's captivity at the hands of the Twilight's Hammer an affront to Kalimdor's balance."},kw={"cenarius","darkshore","dryad","escort","master's glaive","therylune","therysil","twilight's hammer"},rel={"quest:945","subzone:master-s-glaive","zone:darkshore","topic:twilight-s-hammer","npc:therysil","quest:944"},src={"Therylune"}}
E["npc:therysil"] = {t="npc",n="Therysil",z="ashenvale",s="Therysil is a dryad dwelling at the Shrine of Aessina in central Ashenvale. Deeply devoted to the preservation of nature, she waits anxiously for word of her sister, Therylune, who fell into the hands of sinister cultists.",h="Therysil is a dryad dwelling at the Shrine of Aessina in central Ashenvale.",sec={{t="A Guardian's Vigil",b="Therysil makes her home near the tranquil waters of the Shrine of Aessina, a sacred glade within the ancient woods of Ashenvale. Like all dryads, the daughters of Cenarius, she is bound to the defense of the wild and the spirits dwelling within it. Yet her focus has been torn from quiet stewardship to gnawing worry. Her sister, Therylune, was captured nearby by the deranged Twilight's Hammer cult, leaving Therysil desperate for any wandering ally willing to aid in her sister's rescue.",sp=0}},faq={{q="Who is Therysil?",a="Therysil is a dryad found residing at the Shrine of Aessina in Ashenvale. She is a daughter of Cenarius and the sister of Therylune.",al={"who is therysil","therysil lore","dryad at aessina"}},{q="What is Therysil's concern?",a="Her sister, Therylune, was ambushed and taken captive by the Twilight's Hammer cultists lurking in Ashenvale. Therysil waits at the shrine hoping an adventurer can guide her sister safely home.",al={"what is therysil doing","why is therysil worried","therysil quest"}},{q="Who is Therylune?",a="Therylune is Therysil's sister, another dryad of Ashenvale. She was captured by the Twilight's Hammer and requires an escort to escape their clutches and reunite with Therysil.",al={"therylune","therysil sister","who is therylune"}},{q="Where can Therysil be found?",a="Therysil stands at the Shrine of Aessina, a sacred natural haven nestled along the roadway in central Ashenvale.",al={"therysil location","where is therysil","shrine of aessina dryad"}}},ang={["class:Druid"]="As a daughter of Cenarius, Therysil represents the deep bond between the Cenarion circle and the natural spirits of Ashenvale, making her plight especially urgent to visiting druids.",["race:NightElf"]="The dryads have long been staunch allies of the kaldorei in safeguarding Ashenvale's sacred groves, such as the Shrine of Aessina."},kw={"ashenvale","cenarius","dryad","shrine of aessina","therylune","therysil","twilight's hammer"},rel={"npc:therylune","quest:945","subzone:shrine-of-aessina","zone:ashenvale","topic:twilight-s-hammer"},src={"Therysil"}}
E["npc:thyn-tel-bladeweaver"] = {t="npc",n="Thyn'tel Bladeweaver",z="ashenvale",s="Thyn'tel Bladeweaver is a night elf sentinel stationed at the Warrior's Terrace in Darnassus. She is deeply troubled by the disappearance of Priestess Velinde Starsong and dispatches trusted Alliance adventurers to track down clues regarding her whereabouts. Through her inquiries, she seeks to piece together the unraveling mystery behind the Scythe of Elune.",h="Thyn'tel Bladeweaver is a night elf sentinel stationed at the Warrior's Terrace in Darnassus.",sec={{t="A Sentinel's Inquest",b="Standing watch over Darnassus from the Warrior's Terrace, Thyn'tel Bladeweaver represents the vigilant military arm of the kaldorei. When Priestess Velinde Starsong mysteriously vanished without leaving word, Thyn'tel refused to let the trail go cold. Sensing that grave forces were involved, she takes it upon herself to commission adventurers willing to dig into the Sentinel's personal belongings and uncover where her journey led.",sp=0},{t="Tracing Velinde's Steps",b="Thyn'tel directs investigators to inspect Velinde's remaining effects left behind in the capital. The clues uncovered reveal a journal describing Velinde's communion with Elune and the terrifying worgen beasts summoned through the Scythe of Elune. Guided by Thyn'tel, travelers follow the trail southward through the port of Ratchet into the Barrens, attempting to find where the desperate priestess sailed before she vanished entirely.",sp=1}},faq={{q="Who is Thyn'tel Bladeweaver?",a="Thyn'tel Bladeweaver is a night elf sentinel located on the Warrior's Terrace in Darnassus. She serves as a quest giver initiating the investigation into the disappearance of Priestess Velinde Starsong.",al={"thyntel bladeweaver","who is thyntel","thyn'tel info"}},{q="Where can I find Thyn'tel Bladeweaver?",a="She can be found standing in Darnassus, specifically stationed on the Warrior's Terrace among the kaldorei warriors and sentinels.",al={"thyn'tel location","where is thyn'tel bladeweaver","thyntel map"}},{q="What quests does Thyn'tel Bladeweaver offer?",a="She is the primary contact for the quest chain investigating Velinde Starsong, providing quests such as 'Velinde's Effects', 'The Barrens Port', and concluding with 'Answered Questions'.",al={"thyntel quests","what quest does she give"}},{q="Why is she interested in Velinde Starsong?",a="Velinde Starsong was a respected Sentinel priestess who disappeared abruptly after wielding the Scythe of Elune in Ashenvale. Thyn'tel seeks to discover her fate and uncover the dark mystery surrounding her departure.",al={"why investigate velinde","what happened to velinde"}},{q="Where does her quest chain lead?",a="After examining Velinde's effects in Darnassus, Thyn'tel directs investigators south across the sea to Ratchet in the Barrens to track down shipping records of Velinde's voyage.",al={"velinde quest path","where does the quest go"}},{q="Is Thyn'tel Bladeweaver an Alliance-only contact?",a="Yes. Stationed within the night elf capital of Darnassus, Thyn'tel Bladeweaver offers quests exclusively to members of the Alliance.",al={"can horde talk to thyntel","is she alliance"}}},ang={["race:NightElf"]="For night elves, Thyn'tel's assignment strikes close to home, uncovering the hidden tragedy of a revered priestess who fell victim to forces beyond her control.",["faction:Alliance"]="Alliance heroes who visit the Warrior's Terrace are entrusted by Thyn'tel to venture deep into neutral and contested territory to uncover the truth.",["class:Warrior"]="Positioned right among the trainers on the Warrior's Terrace, Thyn'tel is a familiar sentinel face to Alliance warriors passing through Darnassus."},kw={"bladeweaver","darnassus","scythe of elune","sentinel","starsong","thyn'tel","velinde","warrior's terrace"},rel={"quest:1037","quest:1038","quest:1039","quest:1044","subzone:warrior-s-terrace","zone:darnassus","zone:barrens","topic:night-elf"},src={"Thyn'tel Bladeweaver"}}
E["npc:warsong-outrider"] = {t="npc",n="Warsong Outrider",z="ashenvale",s="Stationed along the contested road leading east from Ashenvale into Azshara, the Warsong Outrider keeps watch over the Horde's frontier. She serves as an advanced scout for the Warsong clan, monitoring travelers and relaying crucial intelligence back to their forward encampments. Although armed and vigilant against night elf incursions, she maintains a passive watch unless directly provoked.",h="Stationed along the contested road leading east from Ashenvale into Azshara, the Warsong Outrider keeps watch...",sec={{t="Eyes on the Eastern Frontier",b="The borderlands between Ashenvale and the shattered ruins of Azshara are fraught with danger. Operating far from the fortified safety of Splintertree Post or the lumber camps, the Warsong Outrider observes troop movements and patrols the transit corridor. Armed with a bow and toxic stingers, she stands ready to defend the Horde's claim over the region, though she conserves her strength by only firing upon Alliance trespassers who actively attack her.",sp=0}},faq={{q="Where can the Warsong Outrider be found?",a="She is posted along the main roadway in eastern Ashenvale that leads directly into the neighboring territory of Azshara.",al={"outrider location","where is warsong outrider","warsong outrider map"}},{q="Will the Warsong Outrider attack Alliance players on sight?",a="No. Despite being flagged for Horde PvP combat, she remains neutral in disposition toward passing Alliance players and will only fight back in self-defense if struck first.",al={"is she aggressive","does warsong outrider attack alliance","warsong outrider aggro"}},{q="What is her role in the Warsong clan's operations?",a="She acts as a frontier scout watching the border between Ashenvale and Azshara, observing threats and providing field reports through scouts delivering updates to the clan's leadership.",al={"what does outrider do","warsong outrider purpose","why is she here"}},{q="Does defeating the Warsong Outrider yield any treasure?",a="No, defeating her yields no loot or specialized equipment, serving only to clear the road or disrupt Horde reconnaissance in the area.",al={"warsong outrider loot","does she drop loot","outrider drops"}}},ang={["faction:Horde"]="Outriders like her maintain the fragile supply and scouting routes connecting Ashenvale's contested logging operations with the wild coasts of Azshara.",["faction:Alliance"]="While an enemy combatant, this scout holds her fire against Alliance travelers unless provoked, allowing wary adventurers to pass by unmolested."},kw={"ashenvale","azshara","horde scout","outrider update","warsong clan","warsong outrider"},rel={"quest:6546","zone:ashenvale","zone:azshara","topic:horde","topic:alliance"},src={"Warsong Outrider"}}
E["quest:1007"] = {t="quest",n="The Ancient Statuette",z="ashenvale",s="Talen, an elf camped near the dangerous Zoram Strand in northwestern Ashenvale, seeks recovery of a lost relic. After being ambushed and run aground by vicious naga, he dropped his prized ancient statuette along the surf and needs an adventurer to retrieve it from the ruins.",h="Talen, an elf camped near the dangerous Zoram Strand in northwestern Ashenvale, seeks recovery of a lost...",sec={{t="Ambush on the Coast",b="The sunken ruins of Zoram along Ashenvale's northwestern shoreline have long attracted those curious about the ancient night elven past. Talen was navigating the shallows in a small vessel when hostile naga surfaced and tore into him with claw and trident. He managed to scramble ashore with bare provisions to make a hasty camp, but in his desperate sprint for survival, his most precious find was dropped into the sands.",sp=0},{t="Secrets of Old Zoram",b="The ancient statuette left half-buried on the beach is more than a simple souvenir. Talen considers it the entire justification for braving the monster-infested Zoram Strand. Upon its recovery, he reveals that the drowned city holds centuries of forgotten mysteries, and this delicate carving acts as a vital key to understanding what remains hidden beneath the tides.",sp=0}},faq={{q="Who is Talen and why is he alone on the Strand?",a="Talen is an elf explorer camping along the southern edge of the Zoram Strand. Driven by historical curiosity, he journeyed to explore the drowned ruins of Zoram, only to be cast ashore when vicious naga ambushed his craft.",al={"who is talen","talen lore","talen ashenvale"}},{q="Where did Talen lose the statuette?",a="Talen lost the carving near the shoreline north of his camp. It rests half-buried in the sand near an overturned boat and a fallen tree along the surf where his vessel was attacked.",al={"where is ancient statuette","statuette location","find ancient statuette"}},{q="What is the ancient statuette?",a="It is an ancient night elven relic salvaged from the submerged ruins of Zoram. According to Talen, the carving holds historical and mystical significance, acting as a crucial key to unlocking the drowned city's lingering secrets.",al={"what is the statuette","significance of statuette"}},{q="Why are there naga at the Zoram Strand?",a="The coastline of Ashenvale contains ancient pre-Sundering elven ruins that sank into the sea ten thousand years ago. Naga have claimed the drowned structures of Zoram as their territory, aggressively patrolling the beaches against outsiders.",al={"why naga here","zoram strand naga","naga in ashenvale"}},{q="What happens after returning the statuette?",a="Recovering the statuette allows Talen to decipher more of the region's mysteries. However, dealing with the naga threat along the strand requires further action, directing you toward their leader, Ruuzel.",al={"what next after statuette","quest follow up"},sp=1},{q="Is the statuette guarded?",a="The statuette lies along the water's edge in territory crawling with hostile naga warriors and shore-stalking beasts, making its retrieval perilous for lone wanderers.",al={"is statuette guarded","enemies near statuette"}}},ang={["race:NightElf"]="The ruins of Zoram represent lost Kaldorei civilization from before the Great Sundering, making the preservation of artifacts like this statuette a matter of ancestral memory.",["faction:Alliance"]="Alliance forces pushing through Ashenvale face threats not only from Horde outposts in the east, but from hostile naga staking claim over the western coastline."},kw={"ancient statuette","ashenvale","naga","ruins of zoram","ruuzel","talen","zoram strand"},rel={"npc:talen","quest:1009","subzone:zoram-strand","topic:naga","zone:ashenvale","quest:1008"},m={start="Talen",level="20",faction="Alliance",id=1007},src={"The Ancient Statuette"}}
E["quest:1008"] = {t="quest",n="The Zoram Strand",z="ashenvale",s="Shindrell Swiftfire of Astranaar charges Alliance champions with scouring the northwestern coast of Ashenvale, where an ancient ruined city lies. Naga have surfaced in force along the Zoram Strand, threatening to push inward from the sea. Halting their foothold protects the forest from a haunting echo of the night elves' distant past.",h="Shindrell Swiftfire of Astranaar charges Alliance champions with scouring the northwestern coast of...",sec={{t="Shadows on the Shore",b="Northwest of Astranaar, where the dense canopy of Ashenvale meets the Great Sea, lies the windswept shore known as the Zoram Strand. Long quiet and littered with the bleached stones of a civilization torn apart ten millennia ago, the beach has suddenly teemed with serpentine horrors. The Wrathtail naga have slithered out from the dark tides, establishing a hostile beachhead right on the borders of night elven territory.",sp=0},{t="The Drowned City of Zoram",b="Beneath the pounding surf rests the doomed city of Zoram, shattered and submerged during the Great Sundering. For ages it remained an abandoned relic, nearly forgotten by the kaldorei. The sudden emergence of the naga among its ruins stirs bitter memories among the defenders in Astranaar. Sentinels like Shindrell Swiftfire recognize the serpentine invaders as twisted cousins borne of their own ancient catastrophe, and they refuse to allow the depths to claim the shore once more.",sp=0}},faq={{q="What is the Zoram Strand?",a="The Zoram Strand is the rugged northwestern shoreline of Ashenvale, facing the Veiled Sea. It marks the site of ancient Zoram, a kaldorei city swallowed by the ocean during the Sundering ten thousand years ago.",al={"zoram strand","where is zoram strand","what is zoram"}},{q="Why are the naga attacking Ashenvale's coast?",a="Their precise motives remain mysterious to the Sentinels in Astranaar. Whatever drew them up from the deeps, their military encampments and aggression make them an immediate threat to the forests, forcing the night elves to strike preemptively.",al={"why are naga here","naga motive zoram","why wrathtails"}},{q="Who is Shindrell Swiftfire?",a="Shindrell Swiftfire is a night elf sentinel stationed in the heart of Astranaar. She monitors regional threats to Ashenvale and organizes strikes against hostile incursions, including the naga upon the coast.",al={"shindrell","quest giver astranaar","swiftfire"}},{q="What history do the night elves share with the naga?",a="The naga were once Highborne night elves who served Queen Azshara. When the Well of Eternity collapsed during the Sundering, they were dragged into the abyssal depths and transformed into serpentine creatures, making every encounter deeply bitter for modern kaldorei.",al={"naga elf connection","history with naga","shared history"}},{q="What happens after clearing the Zoram Strand?",a="After thinning the naga along the strand, Shindrell Swiftfire redirects Alliance defenders to handle other emerging aerial threats along the border, sending scouts south toward Stonetalon to deal with vicious pridewings.",al={"next quest","what after zoram strand","pridewings"},sp=1},{q="Is the Horde also present at the Zoram Strand?",a="Yes. While Alliance champions hunt the shoreline's naga from Astranaar, the Horde maintains a fortified seaside outpost called Zoram'gar Post on the strand, contesting the region and battling both the naga and Alliance alike.",al={"horde zoram strand","zoram'gar","is the horde there"}}},ang={["race:NightElf"]="Every naga slain on the strand is a grim reminder of Azshara's arrogance and the Sundering that broke the ancient world. Sentinels will never permit these twisted kin to regain ground in Kalimdor.",["faction:Alliance"]="Securing the western flank of Ashenvale prevents Astranaar from being caught between coastal invaders and encroaching Horde lumber operations.",["class:Hunter"]="The wind-battered coast and broken ruins provide prime vantage points for tracking the amphibious raiders as they emerge from the breakers."},kw={"ashenvale","astranaar","naga","shindrell","strand","sundering","swiftfire","wrathtail","zoram"},rel={"subzone:zoram-strand","npc:shindrell-swiftfire","subzone:astranaar","topic:naga","zone:ashenvale","quest:1134"},m={start="Shindrell Swiftfire",level="19",faction="Alliance",id=1008},src={"The Zoram Strand (quest)"}}
E["quest:1009"] = {t="quest",n="Ruuzel",z="ashenvale",s="Ruuzel is an Alliance quest offered by Talen on the edges of the Zoram Strand in Ashenvale. After recovering an ancient Kaldorei statuette from the coast, adventurers are sent to wrest the Ring of Zoram from the naga leader Ruuzel to unlock its sealed secrets.",h="Ruuzel is an Alliance quest offered by Talen on the edges of the Zoram Strand in Ashenvale.",sec={{t="The Master Key of Zoram",b="Before the Great Sundering tore Kalimdor apart and cast its grand coastal cities beneath the sea, the city of Zoram was governed by powerful night elven nobility. Chief among their regalia was the Ring of Zoram, a band enchanted to act as a master key capable of opening any lock within the city's bounds. Following the cataclysm, the ring was lost to the tides for millennia, preserving the secrets of sunken relics from curious eyes.",sp=0},{t="The Naga Incursion",b="With the recent arrival of the naga on the Zoram Strand, the serpentine invaders began scouring the ruins of their former homeland. Ruuzel, the matriarch leading the local brood, successfully unearthed the Ring of Zoram and carried it off to her sanctuary on an island to the north. Seeking to unseal the statuette dragged from the shallows, the night elf Talen tasks Alliance travelers with hunting down Ruuzel and reclaiming the ancient heirloom.",sp=0}},faq={{q="Who is Ruuzel?",a="Ruuzel is the leader of the naga occupying the Zoram Strand in northwestern Ashenvale. She makes her lair on an offshore island to the north, guarding salvaged treasures of the sunken night elf civilization.",al={"ruuzel lore","who is the naga leader","ruuzel boss"}},{q="What is the Ring of Zoram?",a="The Ring of Zoram was an enchanted heirloom belonging to the ancient rulers of Zoram before the Sundering. It serves as a master key capable of opening any lock crafted within the city.",al={"ring of zoram lore","what does the ring do","zoram key"}},{q="Why does Talen need the ring?",a="Talen seeks to uncover the secrets inside an ancient Kaldorei statuette recently retrieved from the strand. The artifact is sealed with a lock that only the Ring of Zoram can turn.",al={"why get ring of zoram","talen statuette lock"}},{q="Where did the city of Zoram go?",a="Zoram was an ancient Kaldorei city destroyed during the Great Sundering ten thousand years ago. Most of its grand stonework collapsed into the Veiled Sea, leaving only scattered coastal ruins.",al={"what happened to zoram","zoram ruins"}},{q="Where is Ruuzel located?",a="Ruuzel dwells on a large rocky island off the northern edge of the Zoram Strand, surrounded by her serpentine followers.",al={"where is ruuzel","ruuzel island location"}},{q="What happens after retrieving the ring?",a="Returning the ring to Talen completes his investigation on the strand. Grateful for your aid in unlocking the artifact's secrets, he rewards you and remembers your service.",al={"what does talen do next","ruuzel follow up"}}},ang={["race:NightElf"]="Reclaiming the Ring of Zoram restores a piece of your ancestral heritage from the naga who desecrate the sunken ruins of your forebears.",["faction:Alliance"]="By slaying Ruuzel and aiding Talen, Alliance forces blunt the naga threat pushing ashore along northern Ashenvale."},kw={"ashenvale","naga","ring of zoram","ruuzel","sundering","talen","zoram strand"},rel={"npc:talen","quest:1007","subzone:zoram-strand","topic:naga","zone:ashenvale","quest:1008"},m={start="Talen",level="25",faction="Alliance",id=1009},src={"Ruuzel (Classic)"}}
E["quest:1010"] = {t="quest",n="Bathran's Hair",z="ashenvale",s="Bathran's Hair is an Alliance quest offered by Orendil Broadleaf at Maestra's Post in western Ashenvale. Desperate to treat a mysteriously afflicted night elf child whose illness transcends the physical body, Orendil sends adventurers north to scour the ancient ruins of Bathran's Haunt for a restorative plant renowned for mending ailments of the spirit.",h="Bathran's Hair is an Alliance quest offered by Orendil Broadleaf at Maestra's Post in western Ashenvale.",sec={{t="An Ailment of the Spirit",b="At Maestra's Post, just south of the Darkshore border, the night elf herbalist Orendil Broadleaf faces a troubling medical crisis. A young child in the settlement has fallen grievously ill, exhibiting symptoms that resist ordinary physical remedies. Convinced that the sickness plagues the child's spirit rather than merely the flesh, Orendil seeks Bathran's Hair, an uncommon restorative herb historically gathered amidst the ancient elven ruins to the north.",sp=0},{t="Trespassers in the Ruins",b="The search leads adventurers to Bathran's Haunt, a ruined enclave tucked along the eastern side of the road leading into Darkshore. Gathering the bundled herbs proves hazardous, as Forsaken agents have infiltrated the ancient site. Returning the plants allows Orendil to brew a soothing draught, yet the discovery of undead interlopers operating openly in northern Ashenvale leaves the herbalist deeply unsettled.",sp=1}},faq={{q="What is Bathran's Hair?",a="Bathran's Hair is a rare medicinal plant native to the ruins of Bathran's Haunt in Ashenvale. Night elf herbalists value it for its potent restorative qualities, specifically its ability to soothe and heal ailments affecting the spirit rather than standard physical wounds.",al={"bathrans hair plant","what is the hair","bathran herb"}},{q="Who is sick at Maestra's Post?",a="A young night elf child residing in the village has fallen deeply ill. The child's condition worsens by the hour, and ordinary remedies have failed because the sickness appears spiritual in nature, prompting Orendil Broadleaf to seek ancient botanical aids.",al={"sick child maestra","who is orendil healing","who needs the cure"}},{q="Where is Bathran's Haunt located?",a="Bathran's Haunt lies in northwestern Ashenvale, north of Maestra's Post and just east of the main road heading toward the Darkshore border. The ruins are overrun with hostile Forsaken operatives.",al={"bathrans haunt location","where to find bathrans hair","where is bathran"}},{q="Why are there Forsaken at Bathran's Haunt?",a="Forsaken forces have established an encampment among the ruins to conduct dark experiments and gather regional resources, marking an unsettling encroachment into night elf territory that alarms Orendil and local sentinels.",al={"undead at bathran","why forsaken in ashenvale","forsaken bathrans haunt"}},{q="What happens after collecting the plant?",a="Once brought five bundles of the herb, Orendil prepares a medicinal concoction and asks you to rush it to the ailing child in Astranaar, beginning the follow-up quest 'Orendil's Cure'.",al={"next quest after bathrans hair","what does orendil do with the hair","orendils cure chain"},sp=1},{q="Can herbalists find the plant bundles easier?",a="Yes. The bundles holding the harvested plant lie scattered on the ground and can be difficult to spot with the naked eye, but adventurers trained in Herbalism can detect them using their herb tracking ability.",al={"herbalism bathrans hair","tracking bathrans hair","plant bundle herb track"}}},ang={["profession:Herbalism"]="The bundled plants scattered throughout Bathran's Haunt can be identified via herbalism tracking, making the search among the ruins far easier.",["race:NightElf"]="The encroaching presence of the Forsaken at Bathran's Haunt poses a grave threat to the sanctified borders of northern Ashenvale and the well-being of its children.",["faction:Alliance"]="Securing medicine for the child at Maestra's Post reinforces the frontline settlements holding western Ashenvale against hostile Horde and Forsaken expansion."},kw={"ashenvale","bathran's hair","bathran's haunt","darkshore","forsaken","maestra's post","orendil broadleaf","plant bundle"},rel={"npc:orendil-broadleaf","subzone:bathran-s-haunt","subzone:maestra-s-post","quest:1020","quest:1033","zone:ashenvale","zone:darkshore","topic:forsaken"},m={start="Orendil Broadleaf",level="20",faction="Alliance",id=1010},src={"Bathran's Hair (Classic)"}}
E["quest:1011"] = {t="quest",n="Forsaken Diseases",z="ashenvale",s="Deep in eastern Ashenvale, the night elf scout Kayneth Stillwind watches the encroaching Forsaken with growing alarm. Believing the undead are brewing blights to ravage sacred elven lands, he directs Alliance champions to raid an encampment near the Dor'Danil Barrow Den and secure a sample of their foul concoctions.",h="Deep in eastern Ashenvale, the night elf scout Kayneth Stillwind watches the encroaching Forsaken with...",sec={{t="A Plague on the Forests",b="The night elves of Forest Song have long contended with satyrs, raging elementals, and orcish logging crews, but the arrival of the Forsaken marks a darker turn. Rather than merely felling timber, the undead arm of the Horde is establishing footholds near ancient ruins and sacred barrow dens. Their presence brings not only war, but the horrific specter of alchemical plague into pristine Kaldorei groves.",sp=0},{t="Infiltration at Dor'Danil",b="South of Forest Song, near the Dor'Danil Barrow Den, Forsaken apothecaries and scouts have set up a fortified camp. There, amidst brewing caldrons and foul reagents, they bottle untested toxins. Kayneth Stillwind tasks scouts with infiltrating the camp to retrieve an intact Bottle of Disease so its volatile contents can be analyzed before the Forsaken can unleash it across the forest.",sp=0}},faq={{q="Who is Kayneth Stillwind?",a="Kayneth Stillwind is an Alliance scout stationed at the outpost of Forest Song in eastern Ashenvale. He monitors hostile movements throughout the region, specifically tracking threats posed by the Forsaken and corrupting influences near the barrow dens.",al={"kayneth stillwind","who gives forsaken diseases","forest song questgiver"}},{q="Where is the Forsaken camp located?",a="The Forsaken encampment lies directly south of Forest Song, established in the vicinity of the Dor'Danil Barrow Den. The undead forces have gathered there around brewing tables and tents to concoct their biological mixtures.",al={"where is the camp","where are the diseased bottles","dor'danil camp location"}},{q="Why are the Forsaken in Ashenvale?",a="While the orcs primarily seek lumber and territory in Ashenvale, the Forsaken pursue sinister alchemical and biological goals. Operating near ancient Kaldorei barrows, they gather reagents and brew toxic compounds, raising elven fears that they intend to infect the land itself.",al={"why forsaken in ashenvale","undead in ashenvale","forsaken motives"}},{q="What happens after retrieving the bottle?",a="Kayneth Stillwind examines the captured bottle to identify its composition. His investigation immediately leads into discovering the plight of the sleeping druids inside the nearby Dor'Danil Barrow Den, prompting the follow-up quest Insane Druids.",al={"what next","after forsaken diseases","quest follow up"},sp=1},{q="What is Forest Song?",a="Forest Song is an Alliance encampment and ruined night elf settlement in far eastern Ashenvale, situated near the border of Azshara. It serves as a vital staging post for night elf scouts watching the surrounding wilderness.",al={"forest song outpost","what is forest song"}},{q="What are the barrow dens in Ashenvale?",a="Barrow dens are sacred underground sanctuaries where night elf druids slumber in communion with the Emerald Dream. Dor'Danil Barrow Den is one such site, making the nearby presence of the Forsaken particularly alarming to the Kaldorei.",al={"what is a barrow den","dor'danil purpose","barrow dens"}}},ang={["race:NightElf"]="For the Kaldorei, the undead intrusion near a sacred barrow den is an intolerable desecration. Defending the slumbering druids and the purity of Ashenvale from vile toxins is a matter of survival and honor.",["class:Druid"]="Druids hold the barrow dens as sacred ground for their communion with the Emerald Dream. Uncovering bottled blights near Dor'Danil strikes at the very heart of the Cenarion Circle's guardianship.",["faction:Alliance"]="The Horde's Forsaken allies bring horrifying chemical warfare to Ashenvale, proving to Alliance leadership that the conflict in the forest extends far beyond simple border disputes over wood."},kw={"apothecary","ashenvale","bottle of disease","dor'danil barrow den","forest song","forsaken","forsaken diseases","kayneth stillwind","night elf"},rel={"quest:1012","quest:4581","subzone:forest-song","subzone:dor-danil-barrow-den","zone:ashenvale","topic:forsaken","topic:druid","topic:horde"},m={start="Kayneth Stillwind",level="29",faction="Alliance",id=1011},src={"Forsaken Diseases"}}
E["quest:1012"] = {t="quest",n="Insane Druids",z="ashenvale",s="Investigating Forsaken incursions in eastern Ashenvale, Kayneth Stillwind uncovers a tragic massacre deep within the Dor'Danil Barrow Den. The resident druids were poisoned and slaughtered in their sleep by undead agents, leaving their maddened spirits trapped in torment. Alliance adventurers are tasked with granting eternal rest to their slain leaders to soothe the agonizing spiritual blight.",h="Investigating Forsaken incursions in eastern Ashenvale, Kayneth Stillwind uncovers a tragic massacre deep...",sec={{t="A Vision of Slaughter",b="While battling the effects of virulent Forsaken toxins recovered in eastern Ashenvale, the night elf sentinel Kayneth Stillwind was struck by a terrifying waking vision. Beneath the earthen mounds of the nearby Dor'Danil Barrow Den, he witnessed an atrocity: the druids resting within had been quietly poisoned and slaughtered by undead infiltrators. Rather than passing peacefully into nature's embrace, their souls were severed violently from their flesh, warped by unnatural venom into shrieking, errant specters.",sp=0},{t="Mercy for the Slain Leaders",b="Driven mad by the unnatural circumstances of their deaths, the druids' phantoms haunt the subterranean chambers of Dor'Danil, unable to find release. To quiet the echoing anguish beneath the earth, Kayneth bids champions to venture into the depths and strike down the lingering spirits of the circle's three venerable leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak. Only by laying these tortured figures to rest can the restless den begin to heal from the defilement.",sp=0}},faq={{q="Who poisoned the druids in Dor'Danil Barrow Den?",a="The druids were poisoned and murdered by Forsaken infiltrators. Kayneth Stillwind perceived this foul crime in a vision while suffering from the effects of Forsaken toxins collected from undead agents active in Ashenvale.",al={"who killed dor'danil druids","who murdered the druids","forsaken poison druids"}},{q="Why did the druids become insane ghosts?",a="The druids were killed abruptly while resting in their barrows. The vile nature of the Forsaken's alchemical poisons severed their souls from their bodies in an unnatural, agonizing fashion, twisting their disembodied spirits with madness.",al={"why are the druids ghosts","why are druids mad","why insane druids"}},{q="Who are Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak?",a="They were the venerable leaders of the druidic circle dwelling within Dor'Danil Barrow Den. In death, their spirits anchor the madness of the den, making their destruction necessary to grant peace to the rest of the haunting.",al={"druid leaders","taneel darkwood","uthil mooncall","mavoris cloudsbreak"}},{q="Where is the Dor'Danil Barrow Den located?",a="Dor'Danil Barrow Den is an underground night elven earthen barrow located in the southeastern reaches of Ashenvale, not far south of the outpost at Forest Song.",al={"dor'danil location","where is dor danil","barrow den ashenvale"}},{q="Who gives the quest to put the druids to rest?",a="Kayneth Stillwind, a night elf stationed at Forest Song in eastern Ashenvale, offers the quest after you assist him with researching Forsaken diseases.",al={"who gives insane druids","kayneth stillwind quest","where to start insane druids"}},{q="Does slaying the leaders purge the den entirely?",a="Destroying the three leaders significantly lessens the spiritual anguish gripping the barrow den, but Kayneth notes it is merely a step toward allowing the remaining maddened spirits to gradually find peace.",al={"is dor'danil saved","does the den get cleansed"}}},ang={["race:NightElf"]="The desecration of Dor'Danil Barrow Den and the slaughter of sleeping druids is an outrageous crime against nature and the Kaldorei, demanding swift vengeance against the Forsaken.",["class:Druid"]="Putting down Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak is a solemn act of mercy, freeing fellow practitioners of the Cenarion arts from alchemical madness.",["faction:Alliance"]="This tragedy reveals the horrifying reach and cruelty of the Horde's Forsaken, who smuggle insidious plagues far beyond Lordaeron to slaughter sleeping innocents."},kw={"ashenvale","dor'danil barrow den","forest song","forsaken","insane druids","kayneth stillwind","mavoris cloudsbreak","taneel darkwood","uthil mooncall"},rel={"quest:1011","quest:4581","subzone:dor-danil-barrow-den","subzone:forest-song","topic:druid","topic:forsaken","zone:ashenvale"},m={start="Kayneth Stillwind",level="32",faction="Alliance",id=1012},src={"Insane Druids (Classic)"}}
E["quest:1016"] = {t="quest",n="Elemental Bracers",z="ashenvale",s="Water elementals have begun tainting the pristine lakes and streams of Ashenvale, troubling the night elves stationed at Silverwind Refuge. Sentinel Velene Starstrike tasks travelers with collecting intact bracers from these creatures to divine the identity of the rogue spellcaster responsible for conjuring them.",h="Water elementals have begun tainting the pristine lakes and streams of Ashenvale, troubling the night elves...",sec={{t="Tainted Waters",b="The sacred waters of Ashenvale are suffering under an unnatural blight, overrun by rogue water elementals. Unlike the wild spirits that naturally inhabit the world, these entities bear signs of artificial conjuration. To the Sentinels stationed at Silverwind Refuge, the sudden arrival of hostile elementals is an alarming symptom of outside corruption creeping deeper into the forest's pristine waterways.",sp=0},{t="Divining the Conjurer",b="Believing these elementals were deliberately bound and unleashed, Sentinel Velene Starstrike provides a magical divining scroll to unmask the culprit. The spell requires raw reagents tied to the summoned beings—specifically, intact bracers salvaged from the spirits before they dissipate. By focusing the scroll upon these enchanted bindings, the magic reads the lingering arcane signature of whoever originally called the elementals into being.",sp=0},{t="A Wizard's Meddling",b="Once the scroll is successfully cast over the intact bracers, the arcane residue confirms Velene's worst fears: a solitary mage is deliberately churning corrupt elementals into Ashenvale's pools. The discovery outrages the night elf defenders, setting the stage for swift retribution against the summoner threatening the sanctity of the woodlands.",sp=1}},faq={{q="Why are there water elementals in Ashenvale?",a="The hostile water elementals plaguing Ashenvale are not natural inhabitants living in balance with the forest. They have been artificially summoned by an outside spellcaster, disturbing the sacred pools and provoking the night elves.",al={"why are elementals here","ashenvale water elementals","where did elementals come from"}},{q="Who gives the quest Elemental Bracers?",a="The quest is offered by Sentinel Velene Starstrike, an officer stationed at Silverwind Refuge on the shores of Mystral Lake in Ashenvale.",al={"quest giver","who starts elemental bracers","where to pick up elemental bracers"}},{q="What is the purpose of the Divining Scroll?",a="The Divining Scroll is an enchanted parchment designed to read the magical signature remaining on the elementals. When cast over five intact bracers, it traces the arcane tether back to the summoner who created them.",al={"what does the scroll do","divining scroll purpose","why use divining scroll"}},{q="Why do only intact bracers work for the ritual?",a="Destroying an elemental often damages or shatters its magical binding bracers. Only bracers that remain intact retain enough stable arcane resonance for the scroll's magic to analyze and reveal the conjurer.",al={"why intact bracers","broken bracers","intact elemental bracers"}},{q="What happens after divining the scroll?",a="After returning the Divined Scroll to Sentinel Velene Starstrike, she identifies the rogue spellcaster responsible and immediately tasks you with hunting down the summoner in the follow-up quest, Mage Summoner.",al={"elemental bracers follow up","what comes next","next quest after elemental bracers"},sp=1},{q="Why does Sentinel Velene care so much about these elementals?",a="Night elves revere the natural purity of Ashenvale's forests and waters. Having a mortal wizard deliberately pollute and destabilize their lakes with corrupted elementals is an intolerable insult to their guardianship.",al={"sentinel velene motivation","why night elves care about elementals"}}},ang={["race:NightElf"]="Ashenvale's natural pools are sacred ground, and seeing arcane summoners deliberately introduce foreign corruption is an intolerable affront to the Kaldorei.",["class:Mage"]="The bindings worn by conjured elementals carry the distinct arcane signature of their master, allowing an educated eye to trace reckless conjuration back to its origin.",["faction:Alliance"]="Assisting the Silverwind Sentinels solidifies Alliance standing in the contested heartlands of central Ashenvale."},kw={"ashenvale","divined scroll","divining scroll","elemental bracers","mage summoner","mystral lake","sentinel velene starstrike","silverwind refuge"},rel={"npc:sentinel-velene-starstrike","quest:1017","subzone:silverwind-refuge","zone:ashenvale"},m={start="Sentinel Velene Starstrike",level="24",faction="Alliance",id=1016},src={"Elemental Bracers (quest)"}}
E["quest:1017"] = {t="quest",n="Mage Summoner",z="ashenvale",s="Mage Summoner is an Alliance strike mission directed by Sentinel Velene Starstrike from Silverwind Refuge. After investigating corrupted water elementals near Mystral Lake, the Sentinels dispatch adventurers across the border into the Barrens to execute the undead mage Sarilus Foulborne atop Dreadmist Peak.",h="Mage Summoner is an Alliance strike mission directed by Sentinel Velene Starstrike from Silverwind Refuge.",sec={{t="A Crossing of Borders",b="The night elves rarely send scouts southward into the sun-scorched savannas of the Barrens without dire cause. After investigating unnatural disturbances among the water elementals around Mystral Lake, Sentinel Velene Starstrike traces the meddling directly to Sarilus Foulborne, a Forsaken conjurer practicing his arts just across the border. For the Sentinels guarding Silverwind Refuge, letting an enemy sorcerer defile nature right on their doorstep is intolerable.",sp=0},{t="The Conjurer on the Peak",b="Sarilus Foulborne has taken up roost high upon Dreadmist Peak, an craggy mountain crawling with Burning Blade cultists. From this elevation, he summons and bends ranks of water elementals to his will, mocking night elf authority from within Horde-dominated lands. Taking him down requires braving enemy territory, cutting through his summoned forces, and severing his head as proof that the Sentinels' vengeance reaches beyond the forest line.",sp=0},{t="Blessing of Elune",b="Upon receiving Foulborne's severed head, Velene Starstrike wipes away the sorcerer's mockery and rewards the slayer with an extraordinary gift: the Light of Elune. This sacred draught of moonlight is a treasured ward among the priestesses and Sentinels, granting absolute invulnerability in the face of imminent death. It serves as a potent reminder of the night elves' divine favor against the foul magic creeping into Kalimdor.",sp=1}},faq={{q="Who is Sarilus Foulborne?",a="Sarilus Foulborne is an undead mage who fled into the Barrens and established himself atop Dreadmist Peak. He uses arcane summoning to enslave water elementals, drawing the wrath of the Sentinels in nearby Ashenvale.",al={"sarilus foulborne","who is the mage summoner","foulborne lore"}},{q="Where is Dreadmist Peak located?",a="Dreadmist Peak is a prominent craggy mountain located in the northern Barrens, directly south of the border with Ashenvale. Sarilus Foulborne waits at its highest vantage point.",al={"where is dreadmist peak","dreadmist peak location","how to find dreadmist peak"}},{q="Why does Sentinel Velene Starstrike want Sarilus dead?",a="Sarilus has been defiling and corrupting water elementals near the Ashenvale border. Velene finds his insolence intolerable and seeks to put an end to his unnatural conjurations while proving that enemies cannot mock the Sentinels from across the border.",al={"why kill sarilus","velene starstrike motive"}},{q="What is the Light of Elune given as a reward?",a="The Light of Elune is a rare consumable vial blessed with divine moonlight. When ingested in dire moments, it renders the user entirely immune to all damage and spell effects for a brief period, saving them from otherwise certain death.",al={"light of elune potion","light of elune lore"}},{q="What comes before this quest?",a="This quest immediately follows 'Elemental Bracers', where adventurers gather intact bracers from the divining water elementals around Mystral Lake in Ashenvale to help Velene identify who is manipulating them.",al={"prerequisite for mage summoner","quest before mage summoner"}},{q="Why is entering the Barrens dangerous for Alliance players?",a="The Barrens is sovereign territory of the Horde, home to the tauren and orcs. Alliance soldiers and adventurers entering the region risk being intercepted by Horde patrols and rival champions.",al={"barrens dangerous","horde territory quest"}}},ang={["race:NightElf"]="Sarilus's arcane defilement of nature right across the forest border is an insult to the Kaldorei, making his execution a matter of both woodland balance and pride.",["faction:Alliance"]="Striking at a Forsaken target deep inside the Barrens offers a bold show of force against Horde encroachments along the southern Ashenvale frontier.",["class:Mage"]="Confronting Foulborne pits the disciplined arcanists of the Alliance against a rogue undead practitioner twisting elemental conjuration to reckless extremes.",["class:Priest"]="Earning the Light of Elune directly from the Sentinels connects the mission to the Goddess's rare, miraculous grace against the corruption of the undead."},kw={"ashenvale","dreadmist peak","light of elune","sarilus foulborne","silverwind refuge","the barrens","velene starstrike","water elementals"},rel={"npc:sentinel-velene-starstrike","quest:1016","subzone:silverwind-refuge","subzone:dreadmist-peak","topic:sentinels","topic:elune","zone:barrens","zone:ashenvale"},m={start="Sentinel Velene Starstrike",["end"]="Sentinel Velene Starstrike",level="25",faction="Alliance",id=1017},src={"Mage Summoner"}}
E["quest:1020"] = {t="quest",n="Orendil's Cure",z="ashenvale",s="Orendil's Cure is an urgent delivery errand tasked to Alliance travelers by the herbalist Orendil Broadleaf. After concocting a remedy from rare flora, Orendil sends the courier racing down the woodland roads to Astranaar to save a dying night elf child.",h="Orendil's Cure is an urgent delivery errand tasked to Alliance travelers by the herbalist Orendil Broadleaf.",sec={{t="A Father's Despair",b="In the central settlement of Astranaar, Pelturas Whitemoon watches over his daughter, Relara, as she wastes away from a severe and mysterious sickness. Facing the limits of local knowledge, Pelturas sought aid across the wild forest of Ashenvale, turning to the wisdom of distant herbalists before hope slipped entirely through his fingers.",sp=0},{t="A Race Across the Woodlands",b="Having successfully procured the necessary components—specifically Bathran's hair—Orendil Broadleaf brews a specialized draught capable of halting the affliction. Entrusting the fragile cure to a passing adventurer, Orendil directs them south and east along the beaten forest highway to deliver the flask before it is too late.",sp=0},{t="A Fragile Respite",b="While Orendil's draught provides much-needed relief to Relara, the herbal remedy is not a permanent solution for the supernatural malignancy gnawing at her spirit. Delivering the potion buys vital time, opening a broader search across ancient Kaldorei ruins for consecrated relics blessed by Elune to complete her salvation.",sp=1}},faq={{q="Who is sick in Astranaar?",a="Relara Whitemoon, the young daughter of Pelturas Whitemoon, is lying bedridden in Astranaar. Her condition is critical, leaving her father desperate for any remedy to stay her decline.",al={"who is ill","who needs the cure","sick child astranaar"}},{q="Who brewed Orendil's Cure?",a="Orendil Broadleaf, a skilled night elf herbalist stationed in northern Ashenvale, prepared the mixture after receiving plant matter collected from Bathran's Haunt.",al={"who made the cure","orendil broadleaf","where did cure come from"}},{q="Where is Pelturas Whitemoon located?",a="Pelturas Whitemoon resides in Astranaar, the primary Alliance town nestled along the main road in central Ashenvale. He can be found watching over his daughter's sickbed inside one of the woodland dwellings.",al={"pelturas location","where is pelturas","find pelturas astranaar"}},{q="Does Orendil's Cure completely heal Relara?",a="No. While the herbal draught successfully stabilizes Relara's immediate condition and offers her father renewed hope, her sickness requires deeper spiritual intervention that sends travelers searching for Elune's Tear.",al={"is relara cured","does the cure work","cure result"},sp=1},{q="What ingredients were used to create this cure?",a="The primary ingredient was Bathran's hair, a rare and potent plant gathered from the cursed ground of Bathran's Haunt north of Maestra's Post.",al={"cure ingredients","what is cure made of","bathrans hair"}},{q="Why didn't Astranaar's local healers brew the cure themselves?",a="Relara's affliction proved resistant to Astranaar's everyday remedies, prompting Pelturas to call upon the specialized botanical expertise of Orendil Broadleaf, who knows how to handle the potent flora found in northern Ashenvale.",al={"why orendil","why astranaar healers failed","why broadleaf"}}},ang={["profession:Herbalism"]="The delivery demonstrates the critical line between raw botany and battlefield medicine, highlighting how harvested Ashenvale herbs like Bathran's hair can hold a child's life in the balance.",["race:NightElf"]="For the Kaldorei, protecting Astranaar means safeguarding its young; assisting Pelturas and Relara touches the heart of night elf community survival in a contested forest.",["class:Priest"]="While herbs provide temporary physical relief for Relara, the lingering malady soon demands the sacred intervention and lunar rites of Elune."},kw={"ashenvale","astranaar","bathran's hair","cure","orendil broadleaf","pelturas whitemoon","relara"},rel={"npc:pelturas-whitemoon","npc:orendil-broadleaf","quest:1010","quest:1033","subzone:astranaar","zone:ashenvale","topic:elune","quest:1034"},m={start="Orendil Broadleaf",["end"]="Pelturas Whitemoon",level="22",faction="Alliance",id=1020},src={"Orendil's Cure (Classic)"}}
E["quest:1021"] = {t="quest",n="Vile Satyr! Dryads in Danger!",z="ashenvale",s="Vile Satyr! Dryads in Danger! is an urgent Alliance quest begun in Ashenvale by the dryad Illiyana. Desperate for aid, she recruits travelers to search for her missing sisters who ventured into the corrupted ruins of Xavian to recover a stolen sacred relic.",h="Vile Satyr!",sec={{t="A Desperate Sister",b="While resting in Ashenvale, the dryad Illiyana finds herself overwhelmed with worry. A band of her dryad sisters departed into the corrupted northern reaches of the forest on a perilous mission to recover the Branch of Cenarius, a holy relic stolen by the vile satyrs. Though they promised to return swiftly, two days have passed in silence, prompting Illiyana to plead with passing Alliance travelers to track them down before it is too late.",sp=0},{t="The Ruins of Xavian",b="The dryads directed their journey toward Xavian, an ancient night elf temple complex to the northwest that has long fallen under the shadow of the Burning Legion's lingering corruption. Swarming with fel-tainted satyrs, Xavian is an exceptionally dangerous hunting ground. Venturing deep into these ruins leads directly to Anilia, the leader of the dryad expedition, who lies gravely wounded and near death after suffering the brutal wrath of the ruins' demonic inhabitants.",sp=1}},faq={{q="Who is Illiyana?",a="Illiyana is a dryad living in the forests of Ashenvale. Anxious over the fate of her sisters, she sends travelers toward the ruins of Xavian to search for their missing party.",al={"illiyana","who gives vile satyr dryads in danger","quest giver"}},{q="What is the Branch of Cenarius?",a="The Branch of Cenarius is a sacred relic deeply precious to the dryads and night elves. Satyrs in northern Ashenvale stole it, prompting Anilia and her sisters to stage a dangerous retrieval mission into Xavian.",al={"branch of cenarius","what relic were they looking for","dryad artifact"}},{q="What is Xavian?",a="Xavian is the ruins of an ancient night elf temple located in northwestern Ashenvale. Overrun by demonic satyrs, the site is steeped in fel corruption and hostility toward nature's protectors.",al={"xavian","ruins of xavian","where are the dryads"}},{q="Who is Anilia?",a="Anilia is a dryad who led the search party to reclaim the Branch of Cenarius from the satyrs. Travelers find her inside the corrupted ruins of Xavian, grievously injured and clinging to life.",al={"anilia","missing dryad leader","where is anilia"},sp=1},{q="Why are the dryads in conflict with the satyr?",a="Dryads are the daughters of the demigod Cenarius, dedicated to preserving nature and the balance of the forest. Satyrs are ancient night elves twisted by demonic fel magic who actively corrupt the wilderness and desecrate sacred groves.",al={"why do dryads hate satyrs","dryad satyr war","satyr corruption"}},{q="What quest follows this one?",a="Finding Anilia completes this search and immediately leads into 'The Branch of Cenarius', where the dying dryad asks you to avenge her fallen kin and finish their mission to recover the relic.",al={"next quest","dryads in danger chain","after vile satyr"},sp=1}},ang={["race:NightElf"]="The dryads are the sacred daughters of Cenarius, making their distress and the defilement of ancient elven temples in Xavian a matter of personal honor and spiritual duty.",["class:Druid"]="Druids share a deep kinship with the children of Cenarius and are sworn to cleanse the demonic corruption spreading from satyr strongholds like Xavian.",["faction:Alliance"]="Helping Illiyana strengthens the Alliance's bond with the mystical denizens of Ashenvale amid escalating regional threats."},kw={"anilia","ashenvale","branch of cenarius","cenarius","dryad","illiyana","satyr","xavian"},rel={"quest:1031","subzone:xavian","topic:satyr","topic:cenarius","npc:illiyana","zone:ashenvale","topic:night-elf"},m={start="Illiyana",["end"]="Anilia",level="32",faction="Alliance",id=1021},src={"Vile Satyr! Dryads in Danger! (Classic)"}}
E["quest:1022"] = {t="quest",n="The Howling Vale",z="ashenvale",s="Assigned by Sentinel Melyria Frostshadow at Forest Song, this quest sends Alliance adventurers into the Howling Vale near the Felwood border. The ruined shrine of Mel'Thandris has been overrun by feral wolf-men known as worgen. By consulting the sacred Tome of Mel'Thandris, investigators hope to uncover why these bizarre creatures have emerged in Ashenvale.",h="Assigned by Sentinel Melyria Frostshadow at Forest Song, this quest sends Alliance adventurers into the...",sec={{t="A Chilling Presence",b="While night elf sentinels expend heavy resources holding the line against the demonic corruption spilling out of Felwood, a new threat has quietly nested in the northern hills of Ashenvale. The ruined shrine of Mel'Thandris, hidden beyond a cavern path near the Felwood border, has fallen to ferocious wolf-men whose haunting cries echo across the canopy. The area is now known as the Howling Vale, and Sentinel Melyria Frostshadow fears this beastly infestation may herald another disaster for the woodland realm.",sp=0},{t="The Living Chronicle",b="To understand where these beasts originated, Melyria directs seekers to the Tome of Mel'Thandris, resting inside the overrun shrine. The tome is far from an ordinary text; its leaves were blessed by Mel'Thandris herself to supernaturally reflect and capture significant events. When opened amid the hostile worgen, the artifact conjures a spectral vision of Priestess Velinde Starsong, unravelling the fateful invocation of a mysterious relic known as the Scythe of Elune.",sp=1}},faq={{q="Where is the Howling Vale located?",a="The Howling Vale sits in the northern reaches of Ashenvale, close to the border of Felwood. From Forest Song, take the road heading north toward Felwood. On the western side of the path, a trail leads up into a cave entrance that opens out into the hidden vale and the ruined shrine of Mel'Thandris.",al={"howling vale location","how to get to howling vale","where is the shrine of mel'thandris"}},{q="What are the wolf-men in the vale?",a="These savage wolf-men are worgen, specifically Terrowulf pack members. They are unnatural, ferocious bipedal beasts that suddenly appeared in Kalimdor, terrorizing the ruins near the Felwood frontier.",al={"wolf men ashenvale","what are the monsters in howling vale","terrowulf worgen"}},{q="What is the Tome of Mel'Thandris?",a="The Tome of Mel'Thandris is an enchanted relic resting within the shrine ruins. Rather than being inked like an ordinary book, its leaves were blessed by Mel'Thandris to record and project visions of pivotal historical moments directly to those who study it.",al={"tome of melthandris","what does the tome do","mel'thandris book"}},{q="Who was Velinde Starsong?",a="Velinde Starsong was a night elf priestess tasked with cleansing demons along the Felwood border. The vision preserved within the Tome of Mel'Thandris reveals that she prayed for aid and received a powerful artifact known as the Scythe of Elune, which brought the worgen into the world.",al={"velinde starsong","priestess velinde","who is the ghost in the tome"},sp=1},{q="Who gives this quest?",a="Sentinel Melyria Frostshadow provides the quest from the night elf outpost of Forest Song in eastern Ashenvale. She is deeply concerned about demonic incursions from Felwood and the unexplained emergence of the worgen nearby.",al={"who starts the howling vale","howling vale quest giver","melyria frostshadow"}},{q="Why does Sentinel Melyria care about the shrine?",a="Forest Song stands as a bulwark against corruption from Felwood. When mysterious wolf-men violently overtook an ancient night elf holy site right along that border, the Sentinels needed to discover whether this was a demonic scheme or an entirely new danger.",al={"why investigate howling vale","forest song sentinels"}}},ang={["race:NightElf"]="The desecration of Mel'Thandris's shrine and the tragic visions of Priestess Velinde Starsong strike at the heart of the night elves' sacred duty to protect Ashenvale from strange curses.",["faction:Alliance"]="The investigation at Forest Song marks the beginning of an Alliance search into the origin of the terrifying worgen beasts that stalk both northern Kalimdor and the Eastern Kingdoms.",["class:Priest"]="Priests will find the fate of Priestess Velinde Starsong illuminating, showing how answered prayers to Elune took a dark and unforeseen turn through the Scythe."},kw={"ashenvale","felwood","forest song","howling vale","mel'thandris","melyria frostshadow","scythe of elune","terrowulf","tome of mel'thandris","velinde starsong","worgen"},rel={"npc:sentinel-melyria-frostshadow","subzone:forest-song","subzone:howling-vale","quest:1037","topic:worgen","topic:elune","zone:ashenvale","zone:felwood"},m={start="Sentinel Melyria Frostshadow",level="30",faction="Alliance",id=1022},src={"The Howling Vale (quest)"}}
E["quest:1023"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This quest marks the tragic continuation of the search for Teronis, a night elf sentinel sent to Lake Falathim. Upon discovering his remains on the shore, the task shifts to recovering his research journal and retrieving the glowing gem held by local murlocs before reporting the grim news back to Astranaar.",h="This quest marks the tragic continuation of the search for Teronis, a night elf sentinel sent to Lake...",sec={{t="A Fallen Scout",b="Sent to Lake Falathim by Raene Wolfrunner, adventurers discover Teronis dead along the waterside. Rather than a rescue, the mission turns into salvage and investigation. Among his belongings lies an intact journal detailing his assignment and findings regarding the strange disturbances in Ashenvale.",sp=0},{t="The Glowing Gem",b="Teronis had tracked a rare, luminous stone to the lake, which fell into the possession of the aggressive Greymist murlocs infesting the shallows. Recovering both Teronis' journal and pryed-away gem is necessary to carry forward the late scout's original mission.",sp=0},{t="Grief in Astranaar",b="Returning to Astranaar brings sorrow to Raene Wolfrunner, who must arrange a patrol to recover the body of her fallen comrade. Yet with the forest facing corruption, Raene cannot afford prolonged mourning, asking the adventurer to pick up Teronis' mantle and finish the cleansing ritual he died trying to assemble.",sp=1}},faq={{q="Who was Teronis?",a="Teronis was a night elf scout dispatched from Astranaar by Raene Wolfrunner. He was tasked with investigating the waters of Lake Falathim and securing a mystical gem, but he was overwhelmed and slain by the local hostile wildlife before he could complete his duty.",al={"teronis","who is teronis","teronis lore"}},{q="Where is the Glowing Gem found?",a="The Glowing Gem is carried by the murlocs inhabiting the shores and waters of Lake Falathim in northwestern Ashenvale, near the spot where Teronis' corpse was found.",al={"where is the glowing gem","glowing gem location","find glowing gem"}},{q="Why is Raene Wolfrunner so focused on this task?",a="Raene is coordinating the defense and purification of Ashenvale from Astranaar. She cannot allow the corruption spreading across the forest's waterways to go unchecked, making Teronis' incomplete mission a vital priority despite the loss of his life.",al={"why raene cleansing","raene wolfrunner motive"}},{q="What happens to Teronis' body after this quest?",a="Raene Wolfrunner pledges to dispatch a detachment of Sentinels from Astranaar to properly retrieve Teronis' remains for mourning and traditional night elf funeral rites.",al={"teronis corpse fate","what happens to teronis"}},{q="What is Teronis' Journal for?",a="The journal outlines Teronis' progress and instructions concerning the cleansing ritual and the mystical artifacts required to purify corrupted waters within the ancient forest.",al={"teronis journal","what is the journal"}},{q="Does this quest chain continue after turning it in?",a="Yes. Upon bringing the gem and journal back to Raene Wolfrunner, she asks you to continue Teronis' work, leading into the next steps of creating and utilizing the cleansing wand.",al={"quest progression","next quest after teronis"}}},ang={["race:NightElf"]="The death of a fellow Sentinel at Lake Falathim highlights the creeping danger threatening the ancient sacred groves of Kalimdor.",["faction:Alliance"]="Securing Astranaar's northern approaches and aiding Raene Wolfrunner cements Alliance ties with the Sentinels holding Ashenvale."},kw={"ashenvale","astranaar","glowing gem","lake falathim","murloc","raene's cleansing","sentinels","teronis"},rel={"quest:991","npc:raene-wolfrunner","npc:teronis-corpse","subzone:astranaar","topic:murloc","topic:sentinels","zone:ashenvale"},m={start="Teronis' Corpse",["end"]="Raene Wolfrunner",level="21",faction="Alliance",id=1023},src={"Raene's Cleansing (2)"}}
E["quest:1024"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This intermediate step in the investigation of Ashenvale's corruption sends Alliance adventurers deep into the sacred groves east of Iris Lake. Entrusted with a recovered Glowing Gem, you must consult the dryad Shael'dryn to learn how to restore Dartol's ancient rod.",h="This intermediate step in the investigation of Ashenvale's corruption sends Alliance adventurers deep into...",sec={{t="A Clue in Teronis's Notes",b="Following the tragic death of the sentinel Teronis, Raene Wolfrunner examines the field notes he left behind. His research indicates that cleansing the tainted waters and blighted soil of Ashenvale hinges on an ancient artifact: a rod crafted long ago by a night elf named Dartol. With only a Glowing Gem in hand, Raene admits her tactical expertise as a huntress is ill-suited to deciphering lost arcane and natural mysteries.",sp=0},{t="Seeking the Daughters of Cenarius",b="Rather than guessing at the remaining pieces of Dartol's Rod, Raene directs travelers northeast toward Iris Lake. Tucked away beside a tranquil moonwell dwells Shael'dryn, a dryad whose natural communion with the forest grants her deep insight into ancient relics. By delivering the gem to her, adventurers hope to uncover the missing components and learn how to reforge the rod.",sp=0}},faq={{q="Who was Teronis?",a="Teronis was a night elf scout sent by Astranaar to investigate foul corruption spreading through Ashenvale. Though he was slain during his mission, his recovered journal provided the crucial clue that restoring Dartol's Rod could aid the land.",al={"teronis","teronis notes","who is teronis"}},{q="What is Dartol's Rod?",a="Dartol's Rod is a fabled relic created by an ancient night elf artisan named Dartol. It holds the power to sense and purge foul corruptions afflicting the sacred waters and wildlife of Ashenvale.",al={"dartols rod","what is the rod","rod of dartol"}},{q="Where can I find Shael'dryn?",a="Shael'dryn resides beside a secluded moonwell northeast of Astranaar, nestled in the hills just east of Iris Lake. The safest approach is following the road east and turning north before reaching the perilous lands near Raynewood Retreat.",al={"where is shael'dryn","shaeldryn location","find the dryad"}},{q="What is the Glowing Gem?",a="The Glowing Gem is an integral component of Dartol's Rod, recovered from the ruins of Teronis's doomed investigation. It resonates with potent magic and is needed by Shael'dryn to divine the rest of the rod's pieces.",al={"glowing gem","what is the gem for","teronis gem"}},{q="Why does Raene Wolfrunner send you to a dryad?",a="As a huntress and leader of the Astranaar sentinels, Raene focuses on martial defense. Understanding ancient relic crafting and natural restoration falls under the spiritual domain of dryads, the Daughters of Cenarius.",al={"why see a dryad","raene wolfrunner dryad","why shael'dryn"}},{q="Why is the forest around Iris Lake in danger?",a="Since the Third War and the demonic taint unleashed by the Burning Legion, darkness has seeped into Ashenvale's elemental spirits, wildlife, and satyr haunts, prompting the Sentinels to seek purifying relics.",al={"ashenvale corruption","why is ashenvale corrupted","iris lake danger"}}},ang={["race:NightElf"]="Restoring Dartol's legacy honors fallen scouts and preserves sacred ancient holdings around the secluded moonwells of Ashenvale.",["class:Druid"]="Assisting the dryad Shael'dryn aligns directly with the Cenarion duty to mend the shattered bonds between nature and Kaldorei magic.",["faction:Alliance"]="Strengthening Astranaar's northern perimeter and securing ancient artifacts aids the Alliance war effort against rising regional threats."},kw={"ashenvale","dartol's rod","glowing gem","iris lake","moonwell","raene wolfrunner","raene's cleansing","shael'dryn","teronis"},rel={"npc:raene-wolfrunner","npc:shael-dryn","subzone:iris-lake","subzone:moonwell-ashenvale","subzone:raynewood-retreat","zone:ashenvale"},m={start="Raene Wolfrunner",["end"]="Shael'dryn",level="21",faction="Alliance",id=1024},src={"Raene's Cleansing (3)"}}
E["quest:1025"] = {t="quest",n="An Aggressive Defense",z="ashenvale",s="An Aggressive Defense is an Alliance quest given by Sentinel Raene Wolfrunner in Astranaar. Faced with rampant furbolg corruption along the central thoroughfares of Ashenvale, the night elves are forced to mount an active cull against the maddened Foulweald tribe.",h="An Aggressive Defense is an Alliance quest given by Sentinel Raene Wolfrunner in Astranaar.",sec={{t="Threat to the Highway",b="The road running east from Astranaar toward the Falfarren River serves as a vital lifeline through Ashenvale, but it has grown exceedingly dangerous. Furbolgs driven mad by demonic corruption have begun raiding travelers directly off the main trail. Rather than simply manning barricades and waiting for the next ambush, Sentinel Raene Wolfrunner dispatches capable adventurers to break the Foulweald camps located just south of the highway.",sp=0},{t="A Bitter History",b="Striking down the Foulweald furbolgs carries a tragic weight for the night elves. The bear-folk were longtime friends and allies of the kaldorei throughout ancient ages, sharing reverence for nature and the wild gods. However, the lingering taint of the Burning Legion's invasion shattered the minds of many tribes, warping peaceful neighbors into bloodthirsty reavers whose violence threatens innocent travelers.",sp=0}},faq={{q="Who offers this task and where are they located?",a="The quest is provided by Raene Wolfrunner, a Sentinel commander stationed in Astranaar, the principal night elf settlement in central Ashenvale.",al={"quest giver","who gives an aggressive defense","raene wolfrunner location"}},{q="Why are the furbolgs in Ashenvale hostile?",a="The Foulweald tribe, like several other furbolg clans across Kalimdor, succumbed to the demonic taint left behind by the Burning Legion during the Third War. Their minds became warped and violent, driving them to butcher travelers and attack former allies.",al={"why are furbolgs mad","foulweald hostile","furbolg corruption"}},{q="Where are the Foulweald camps found?",a="Their encampments lie south of the main eastern road running out of Astranaar, situated west of the Falfarren River.",al={"foulweald location","where to find foulweald","where are the furbolgs"}},{q="Were the furbolgs always enemies of the night elves?",a="No. For thousands of years, the furbolgs and night elves lived side by side in harmony. It was only after demonic corruption swept through Ashenvale and Felwood that tribes like the Foulweald lost their sanity and turned hostile.",al={"furbolg night elf lore","were furbolgs good","kaldorei and furbolgs"}},{q="Does this quest connect to other events in Astranaar?",a="Yes. Raene Wolfrunner offers this task as an interim defensive strike while directing heroes on investigations into corrupted moonwells and the broader cleansing of the forest.",al={"quest prerequisites","raene cleansing connection"}},{q="What specific furbolgs must be eliminated?",a="Raene requires the culling of a Foulweald Den Watcher, two Ursas, ten Totemics, and twelve Warriors in order to shatter their command structure and disperse the threat near the road.",al={"quest targets","who do i kill","foulweald targets"}}},ang={["race:NightElf"]="For the kaldorei, executing the Foulweald is a somber necessity born of tragedy, turning blades upon former forest brethren who have completely lost their minds to corruption.",["faction:Alliance"]="Clearing the Foulweald protects vital Alliance supply and transit lanes connecting Astranaar to eastern outposts across Ashenvale.",["class:Druid"]="Druids view the madness of the Foulweald as a harrowing reminder of the fel taint afflicting Kalimdor's sacred wild sanctuaries."},kw={"ashenvale","astranaar","falfarren","foulweald","furbolg","raene wolfrunner","sentinels"},rel={"npc:raene-wolfrunner","subzone:astranaar","topic:furbolg","topic:sentinels","zone:ashenvale","subzone:falfarren-river","subzone:moonwell-ashenvale","quest:1066"},m={start="Raene Wolfrunner",level="24",faction="Alliance",id=1025},src={"An Aggressive Defense"}}
E["quest:1026"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This quest represents a pivotal step in restoring Dartol's Rod of Transformation, an ancient night elf artifact being sought by Raene Wolfrunner. Guided by Shael'dryn at her moonwell, adventurers must venture north toward the foul border of Felwood to recover an iron shaft locked inside a hidden chest. The mission carries a tragic undertone, forcing the Alliance to confront corrupted ancients who guard the key.",h="This quest represents a pivotal step in restoring Dartol's Rod of Transformation, an ancient night elf...",sec={{t="A Fragment Near the Blight",b="Following the clues to repair Dartol's Rod, Raene directs the search to Shael'dryn, a knowledgeable keeper watching over a tranquil moonwell deep in Ashenvale. Shael'dryn knows the whereabouts of the rod's iron shaft, yet retrieving it requires confronting the creeping taint threatening the northern woods. The piece lies locked in an old chest tucked away in a quiet glade near the border of Felwood.",sp=0},{t="The Fallen Guardians",b="Reaching the chest requires a wooden key, but the key itself has fallen into the hands of the forest's warped protectors. Along the mountain road running north toward Felwood, treants known as Crazed and Withered Ancients wander in agony. The corruption leaching southward from the demonic wastes has shattered their natural harmony, turning former stewards of the wild into hostile, tormented creatures that must be subdued to reclaim Dartol's relic.",sp=0}},faq={{q="Who is Shael'dryn?",a="Shael'dryn is a night elf keeper stationed at a secluded moonwell in Ashenvale, east of Astranaar and south of the Felwood road. She possesses deep knowledge of the forest's history and Dartol's ancient craft, offering quiet counsel to those trying to mend the rod.",al={"shaeldryn","who is the moonwell keeper","shael'dryn lore"}},{q="Why are the treants corrupted?",a="The treants dwell along the northern ridges adjoining Felwood. The pervasive demonic taint lingering from the Third War continues to bleed southward into Ashenvale, warping the trees, driving the ancient protectors insane, and twisting their natural connection to the land.",al={"corrupted treants","why are treants crazy","crazed ancients lore"}},{q="What is Dartol's Rod?",a="Dartol's Rod is an enchanted relic crafted long ago by a night elf named Dartol. Once fully assembled and purified, it carries strong transformative magic capable of disguising the bearer as a furbolg, making it vital to Raene's plans for investigating the local tribes.",al={"dartols rod","rod of transformation","what does the rod do"},sp=1},{q="Where is the hidden chest located?",a="The worn chest containing the iron shaft rests in a small, quiet glade just west of the mountain road that climbs north out of Ashenvale toward the Felwood border.",al={"worn chest location","where is the iron shaft","where is the chest"}},{q="Why does Shael'dryn mourn the treants?",a="Treants are timeless caretakers of the Kaldorei forests, revered as sacred spirits of nature. Watching them fall to madness and corruption without any known cure pains Shael'dryn deeply, as putting them down is an act of sorrow rather than malice.",al={"shaeldryn treants","why is shaeldryn sad"}},{q="How does this task fit into the wider cleansing chain?",a="It serves as the stage where the physical components of Dartol's broken rod are assembled. Once the iron shaft and other pieces are gathered, the effort shifts toward purifying the rod's lingering magical power.",al={"raene's cleansing chain","raene questline"}}},ang={["race:NightElf"]="Putting down the Crazed Ancients is an agonizing duty, as these living trees were once beloved companions and forest wardens before the demonic blight poisoned their spirits.",["class:Druid"]="Seeing the ancients driven to madness by Felwood's encroaching taint is a grim reminder of the Emerald Dream's struggle to heal the wounded surface world.",["faction:Alliance"]="Rebuilding Dartol's relic is essential to securing the road network in northern Ashenvale against rising hostilities from corrupted furbolgs and demonic forces."},kw={"ashenvale","crazed ancient","dartol's rod","felwood","iron shaft","moonwell","raene's cleansing","shael'dryn","withered ancient","wooden key"},rel={"npc:shael-dryn","subzone:moonwell-ashenvale","subzone:raynewood-retreat","zone:felwood","zone:ashenvale"},m={start="Shael'dryn",level="27",faction="Alliance",id=1026},src={"Raene's Cleansing (4)"}}
E["quest:1027"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This quest marks the search for the final component needed to restore Dartol's Rod, an ancient relic tied to cleansing Ashenvale. Shael'dryn directs travelers toward the fallen druid sanctuary of Dor'Danil to recover the missing iron pommel.",h="This quest marks the search for the final component needed to restore Dartol's Rod, an ancient relic tied to...",sec={{t="The Ruins of Dor'Danil",b="The final piece of Dartol's Rod—an iron pommel—was entrusted to the night elf druids dwelling at the Dor'Danil barrow den. Tragically, the sanctuary fell to disaster, and its caretakers were slain. With the druids dead and their refuge overrun, the exact hiding place of the relic was lost, leaving scavengers and wandering oozes to swallow up whatever was left behind in the ruins east of the southern road.",sp=0},{t="Rebuilding Dartol's Legacy",b="Dartol was a revered night elf figure whose rod possessed remarkable warding and transformative powers. Raene Wolfrunner and Shael'dryn seek to reassemble the artifact to push back against the demonic and corruptive blight choking Ashenvale's forests. Securing the iron pommel is the last step required before Shael'dryn can attempt to mend the fractured rod at the moonwell.",sp=0}},faq={{q="What is the iron pommel?",a="The iron pommel is the finishing segment of Dartol's Rod. Without it, the relic cannot be reforged or channeled to cleanse Ashenvale.",al={"iron pommel","final rod piece","what is pommel"}},{q="What happened to the druids of Dor'Danil?",a="The druids residing at the Dor'Danil barrow den were recently slain when their sanctuary fell, leaving the refuge abandoned to lurking oozes and beasts. Shael'dryn considers their tragic fate a painful subject to discuss.",al={"dordanil druids","who killed the druids","dor danil"}},{q="Where is Dor'Danil located?",a="Dor'Danil sits in southern Ashenvale, east of the main road heading down toward the Barrens border, south of Splintertree Post.",al={"where is dordanil","dor danil location"}},{q="Who is Shael'dryn?",a="Shael'dryn is a night elf tending a sacred moonwell in Ashenvale. She aids Raene Wolfrunner by tracking down the scattered remnants of Dartol's Rod and guiding heroes in repairing it.",al={"shaeldryn","who is shaeldryn"}},{q="Why is the pommel swallowed by oozes?",a="After the barrow den fell, gelatinous slimes infested the area and consumed discarded relics, chests, and corpses, inadvertently engulfing the iron pommel along with other debris.",al={"slime chest","pommel slime","why do slimes have it"}},{q="What happens after finding the pommel?",a="Returning the pommel to Shael'dryn allows her to begin repairing the rod so it can finally be used to assist Raene Wolfrunner in cleansing the forest.",al={"next step","what does shaeldryn do"}}},ang={["class:Druid"]="Visiting the desecrated grounds of Dor'Danil is a sobering reminder of the losses the Cenarion Circle and Kaldorei druids have suffered in Ashenvale.",["race:NightElf"]="Recovering Dartol's heirloom honors both the fallen caretakers of Dor'Danil and the ongoing defense of ancient Kaldorei lands.",["faction:Alliance"]="Securing Ashenvale against corruption is vital to the Alliance's hold on northern Kalimdor, especially with Horde forces advancing from Splintertree."},kw={"ashenvale","dartol's rod","dor'danil","iron pommel","moonwell","raene's cleansing","shael'dryn"},rel={"npc:shael-dryn","zone:ashenvale","subzone:moonwell-ashenvale","subzone:splintertree-post","zone:barrens","topic:druid"},m={start="Shael'dryn",level="28",faction="Alliance",id=1027},src={"Raene's Cleansing (5)"}}
E["quest:1028"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This step in the cleansing of Ashenvale tasks you with taking the rebuilt Rod of Dartol to a secluded mountain shrine. Hidden among the ridges southeast of Shael'dryn's retreat, the sacred basin holds the latent magic needed to re-enchant the relic.",h="This step in the cleansing of Ashenvale tasks you with taking the rebuilt Rod of Dartol to a secluded...",sec={{t="A Path into the Heights",b="After assembling the shattered pieces of Dartol's Rod, the night elf priestess Shael'dryn directs travelers away from her moonwell into the untamed slopes to the southeast. The ancient shrines of Ashenvale were often deliberately nestled high in the mountain crags, far from the road and shielded by dense forest canopies. Reaching this quiet sanctum requires navigating unmarked terrain along the rock faces, climbing winding trails known mostly to Sentinels and woodland hermits.",sp=0},{t="Restoring Dartol's Rod",b="The shrine itself rests within a quiet alcove surrounded by vibrant forest. Even dormant, the stone hums with the latent protective magic imbued by the night elves of antiquity. By resting the reconstructed rod inside the shrine's stone basin, the site's dormant power awakens, bathing the glade in a soft resonance and infusing Dartol's creation with pristine enchantment so it may finally serve to cleanse the land.",sp=0}},faq={{q="Where is the hidden shrine located?",a="The shrine is tucked into the mountains southeast of Shael'dryn's moonwell. Rather than following main roads, you must skirt the rocky cliff faces and watch for a winding path that ascends upward into the ridges.",al={"shrine location","where is the shrine","how to find shrine","hidden shrine path"}},{q="Who was Dartol?",a="Dartol was an ancient night elf whose crafted rod held the power to commune with and cleanse woodland beings. Its pieces were scattered across Ashenvale before being gathered and reassembled by Shael'dryn.",al={"who is dartol","dartol lore","creator of the rod"}},{q="Why does Dartol's Rod need to be placed in the shrine?",a="While Shael'dryn could physically reconstruct the broken rod, its ancient enchantments were drained. The hidden shrine serves as an untouched reservoir of nature magic capable of reigniting the rod's power.",al={"why recharge rod","rod purpose","what does the shrine do"}},{q="Who is Shael'dryn?",a="Shael'dryn is a night elf keeper residing beside a quiet moonwell in eastern Ashenvale, assisting Raene Wolfrunner by researching relics and rites capable of cleansing the tainted wilderness.",al={"shaeldryn","quest giver","priestess at moonwell"}},{q="What happens after the rod is recharged?",a="Once the shrine imbues the rod with power, it becomes Dartol's Rod once more, prepared to be taken back into the field to aid Astranaar and purge the corruption spreading through Ashenvale's furbolgs.",al={"what next","after shrine","next step"}},{q="Is the shrine guarded?",a="The shrine itself is a peaceful sanctuary, though the surrounding mountains and forests are prowled by wild beasts and corrupt furbolg tribes that make the climb treacherous.",al={"are there mobs at shrine","shrine dangers"}}},ang={["race:NightElf"]="The hidden mountain shrines of Ashenvale represent the quiet, enduring sanctuaries woven into the wilderness by your ancestors before the modern invasions.",["class:Druid"]="The subtle resonance that awakens within the shrine reveals how deeply ancient night elven craft aligned itself with the untamed energies of nature.",["faction:Alliance"]="Restoring this relic is an essential step toward helping Raene Wolfrunner secure Astranaar and heal the corrupted lands of northern Kalimdor."},kw={"ashenvale","basin","dartol's rod","hidden shrine","moonwell","raene's cleansing","reconstructed rod","shael'dryn"},rel={"npc:shael-dryn","zone:ashenvale","subzone:moonwell-ashenvale"},m={start="Shael'dryn",["end"]="Hidden Shrine",level="28",faction="Alliance",id=1028},src={"Raene's Cleansing (6)"}}
E["quest:1029"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This step in the long-running Ashenvale investigation sees Dartol's Rod of Transformation fully restored. Entrusted with the completed artifact by the priestess Shael'dryn, you return to Raene Wolfrunner in Astranaar to report success and honor the memory of the fallen scout Teronis.",h="This step in the long-running Ashenvale investigation sees Dartol's Rod of Transformation fully restored.",sec={{t="The Rod Restored",b="After scouring the corrupted reaches of Ashenvale for components and ancient gem fragments, the relic known as Dartol's Rod of Transformation has finally been reforged. Entrusted to the dryad and priestess Shael'dryn at Iris Lake, its magical properties were cleansed and renewed. With the craftsmanship complete, she directs you back across the forest roads to Astranaar to present the artifact to Raene Wolfrunner.",sp=0},{t="Honoring Teronis",b="The entire endeavor began as an expedition led by Teronis, a promising young night elf sentinel who sought ancient relics to push back against demonic and satyr corruption in Ashenvale. Teronis died at the hands of the vile murlocs of the lake before he could see his task fulfilled. Returning the restored rod to Raene Wolfrunner marks a bittersweet victory, ensuring his dangerous sacrifice was not in vain.",sp=1}},faq={{q="What is Dartol's Rod of Transformation?",a="It is an ancient night elf artifact sought by the fallen scout Teronis. When assembled and empowered, it holds subtle shapeshifting magic capable of altering the bearer's form into a furbolg, though its primary purpose here is serving as a cleansed relic for the defense of Ashenvale.",al={"dartols rod","what does the rod do"}},{q="Who was Teronis?",a="Teronis was a young night elf sentinel tasked by Raene Wolfrunner to locate components of ancient magic in Ashenvale. He was ambushed and slain by corrupted murlocs near Lake Falathim, leaving the completion of his vital mission to passing Alliance travelers.",al={"who is teronis","teronis death"}},{q="Who is Raene Wolfrunner?",a="Raene Wolfrunner is an experienced night elf sentinel commander stationed in the heart of Astranaar. She oversees the defense of central Ashenvale against invading demonic taint, hostile satyrs, and local beast corruptions.",al={"raene","raene wolfrunner"}},{q="Who is Shael'dryn?",a="Shael'dryn is an Elune-devoted priestess residing quietly near the Moonwell at Iris Lake. Her deep spiritual knowledge and attunement to sacred night elf rituals allow her to purify corrupted relics and restore ancient tools of power.",al={"shaeldryn","iris lake priestess"}},{q="Where does this quest take place?",a="This errand takes you from the tranquil banks of Iris Lake in north-central Ashenvale back south along the main trails into Astranaar, the primary Alliance hub of the zone.",al={"quest location","where do i go"}},{q="What happens after presenting the rod to Raene?",a="Raene expresses deep relief and pride that Teronis's final mission succeeded. However, the cleansing of Ashenvale is far from over, and she immediately looks for ways to employ the rod's power against the woodland's persistent corruption.",al={"next quest","raenes cleansing continuation"},sp=1}},ang={["race:NightElf"]="Carrying Teronis's legacy brings closure to Astranaar, proving that fallen kin will not be forgotten amid the rising threats to Kalimdor's sacred groves.",["faction:Alliance"]="Astranaar stands as the Alliance's anchor in Ashenvale; assisting Raene Wolfrunner directly cements your standing among the reclusive Sentinels."},kw={"ashenvale","astranaar","dartol's rod","raene wolfrunner","raene's cleansing","shael'dryn","teronis"},rel={"npc:raene-wolfrunner","npc:shael-dryn","subzone:astranaar","zone:ashenvale"},m={start="Shael'dryn",["end"]="Raene Wolfrunner",level="28",faction="Alliance",id=1029},src={"Raene's Cleansing (8)"}}
E["quest:1030"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This critical stage of Raene Wolfrunner's mission requires the use of Dartol's newly restored rod to disguise an outsider and initiate contact with an uncorrupted furbolg. Southeast of Mystral Lake, an outcast named Krolg offers a rare glimpse into the surviving furbolgs' deep resentment toward the night elves.",h="This critical stage of Raene Wolfrunner's mission requires the use of Dartol's newly restored rod to disguise...",sec={{t="A Guise of Fur and Claw",b="With Dartol's Rod of Transformation restored, Raene Wolfrunner suspects the late night elf intended to disguise himself in order to safely approach the furbolgs. The woods of Ashenvale have grown perilous, and the madness spreading through the tribes makes direct diplomacy impossible. By harnessing the arcane relic, an adventurer takes on the appearance of a furbolg, hoping to slip past instinctive territorial rage and find someone willing to speak.",sp=0},{t="The Exile's Bitterness",b="Southeast of Mystral Lake lies Krolg, an isolated furbolg who has managed to escape the corrupting touch of Fel Moss. Believing he is speaking to a clean member of his own kin, Krolg speaks freely of his exile and profound sorrow. Yet rather than seeing the night elves as allies or protectors, he harbors deep bitterness toward them, openly blaming night elven hubris and ancient failures for the demonic taint ravaging his people.",sp=1}},faq={{q="What does Dartol's Rod of Transformation do?",a="Dartol's Rod of Transformation temporarily changes the bearer's appearance into that of a furbolg. This disguise allows an adventurer to walk among uncorrupted furbolgs without inciting an immediate violent attack.",al={"what does the rod do","dartol rod transformation","furbolg disguise rod"}},{q="Who is Krolg?",a="Krolg is an uncorrupted furbolg living in exile southeast of Mystral Lake. Having avoided the Fel Moss that infected his kin, he lives alone across a torch-lined stream, mourning the loss of his tribe while holding a deep grudge against night elf kind.",al={"who is krolg","uncorrupted furbolg mystral lake","furbolg southeast of mystral lake"}},{q="Why will Krolg attack if you don't use the rod?",a="Krolg is terrified and deeply distrustful of outsiders, particularly the night elves whom he blames for his people's downfall. Without the illusion making you look like an uncorrupted furbolg, he will treat you as an intruder and defend his camp violently.",al={"why does krolg attack","krolg aggressive","why use the rod on krolg"}},{q="Why does Krolg blame the night elves for the corruption?",a="Krolg views the demonic corruption of the forest—brought on by the Legion's invasions and historical arcane meddling—as the direct fault of night elven pride. In his eyes, the ancient Kaldorei brought ruin upon Kalimdor and left the indigenous tribes to suffer the consequences.",al={"why does krolg hate night elves","furbolg blame night elves","krolg night elf hatred"}},{q="Where can Krolg be found?",a="He can be found southeast of Mystral Lake in Ashenvale. Follow a winding dirt path marked by burning torches that leads down across a small stream to his solitary camp.",al={"where is krolg","krolg location","find uncorrupted furbolg"}},{q="What is Fel Moss and how did it affect the furbolgs?",a="Fel Moss is a demonic growth spreading through Ashenvale that seeps demonic taint into the soil and flora. The local furbolg tribes fell victim to its influence, driving them into a state of rabid, violent insanity that fractured their society.",al={"what is fel moss","fel moss furbolgs","why did furbolgs go mad"}}},ang={["race:NightElf"]="Hearing Krolg's words is a sobering reminder that many indigenous denizens of Ashenvale do not view the Kaldorei as benevolent guardians, but as the reckless architects of the land's recurring doom.",["class:Druid"]="Druids seeking to restore balance to the forest are confronted with the raw tragedy of the furbolgs, who were once close nature allies but now suffer horrific madness from lingering demonic filth.",["faction:Alliance"]="Astranaar's survival depends on unraveling the threats lurking along the border roads, making this covert parley essential for securing eastern Ashenvale."},kw={"ashenvale","dartol's rod of transformation","fel moss","furbolg","krolg","mystral lake","raene wolfrunner","raene's cleansing"},rel={"npc:krolg","npc:raene-wolfrunner","topic:furbolg","subzone:mystral-lake","zone:ashenvale"},m={start="Raene Wolfrunner",["end"]="Krolg",level="28",faction="Alliance",id=1030},src={"Raene's Cleansing (9)"}}
E["quest:1031"] = {t="quest",n="The Branch of Cenarius",z="ashenvale",s="Following a desperate plea from the dying dryad Anilia, an adventurer is tasked with recovering a sacred relic stolen by the vile satyr Geltharis. Reclaiming the Branch of Cenarius means confronting the demon-sworn corrupters lurking in eastern Ashenvale and returning the treasured bough to Forest Song.",h="Following a desperate plea from the dying dryad Anilia, an adventurer is tasked with recovering a sacred...",sec={{t="A Dying Request",b="Sent into the corrupted folds of eastern Ashenvale to search for missing dryads, Alliance travelers stumble upon Anilia clinging to the very edge of life. With her final breaths, the wounded daughter of Cenarius gestures toward the satyr ruins to the north. Gasping out the name of her killer—Geltharis—she begs with her fading strength for the recovery of the Branch of Cenarius before succumbing to her wounds.",sp=0},{t="Corruption in the Ruins",b="The thief, Geltharis, is a vile satyr nested within the ancient elven ruins of Night Run. To the satyr, ancient relics tied to the demigod Cenarius are prized trophies ripe for defilement and demonic mockery. Defeating Geltharis and tearing the branch from his claws is not merely an act of justice for Anilia, but a defense against the spreading taint that the Burning Legion's ancient servants inflict upon Ashenvale's sacred flora.",sp=0},{t="Sorrow at Forest Song",b="Returning the branch to the dryad Illiyana at Forest Song brings a bittersweet close to the search. While the sacred relic is preserved from demonic degradation, the news of Anilia's demise strikes a heavy blow to her surviving kin. The dryads of Ashenvale, once accustomed to carefree frolics beneath the ancient boughs, are forced to face the harsh reality of war and encroaching corruption.",sp=1}},faq={{q="What is the Branch of Cenarius?",a="It is a sacred nature relic linked to the forest lord Cenarius, deeply cherished by his dryad daughters. The satyr Geltharis stole it from Anilia after mortally wounding her.",al={"branch of cenarius relic","what is the branch","cenarius branch"}},{q="Who killed Anilia?",a="Anilia was attacked and fatally wounded by the satyr Geltharis, who stole the Branch of Cenarius before leaving her to die in the forest.",al={"anilia killer","who attacked anilia","who killed the dryad"}},{q="Where is Geltharis located?",a="Geltharis can be found lurking beneath the stone arches and corrupted structures of the Night Run ruins, north of where Anilia lay dying.",al={"geltharis location","find geltharis","where to kill geltharis"}},{q="Where do I take the Branch of Cenarius once it is recovered?",a="You must take the recovered branch to the dryad Illiyana, who resides at the night elf outpost of Forest Song in eastern Ashenvale.",al={"turn in branch of cenarius","illiyana location","who gets the branch"}},{q="Why do the satyrs want Cenarius's artifacts?",a="Satyrs are ancient night elves transformed by demonic pacts, nursing an enduring hatred for nature and the demigod Cenarius. Corrupting or stealing sacred relics serves both their demonic masters and their spite against their former kin.",al={"satyr motives","why steal cenarius branch","why did geltharis take it"}},{q="Who was Anilia to Illiyana?",a="They were close dryad companions and sisters in spirit, who had spent countless days running and playing freely in the wilds of Ashenvale before the rising dangers of corruption took Anilia's life.",al={"anilia and illiyana","are the dryads sisters"}}},ang={["race:NightElf"]="The daughters of Cenarius are beloved allies of the Kaldorei. Avenge Anilia and purge the satyr filth desecrating your ancestral forests.",["class:Druid"]="Cenarius taught the first mortal druids, making his relics deeply sacred. Reclaiming his branch from a demon-tainted satyr is a spiritual imperative.",["faction:Alliance"]="The dryads of Forest Song rely on Alliance aid to push back demonic threats in the untamed east of Ashenvale."},kw={"anilia","ashenvale dryads","branch of cenarius","forest song","geltharis","illiyana","night run","satyr"},rel={"quest:1021","npc:illiyana","subzone:forest-song","topic:cenarius","topic:satyr","zone:ashenvale"},m={start="Anilia",["end"]="Illiyana",level="32",faction="Alliance",id=1031},src={"The Branch of Cenarius (Classic)"}}
E["quest:1032"] = {t="quest",n="Satyr Slaying!",z="ashenvale",s="Grieving the loss of her sister Anilia, the dryad Illiyana at Forest Song seeks vengeance against the satyrs lurking in Ashenvale. She asks Alliance champions to cull the corrupted creatures and return with their horns as proof of their downfall.",h="Grieving the loss of her sister Anilia, the dryad Illiyana at Forest Song seeks vengeance against the satyrs...",sec={{t="A Dryad's Grief",b="Dryads are typically playful and serene forest spirits, deeply bonded to nature and elusive to mortals. The brutal slaying of Anilia shatters this tranquility for Illiyana, who dwells among the ruins of Forest Song. Pushed past her carefree nature into unfamiliar sorrow, she turns to travelers of the Alliance to strike down the demonic beasts responsible.",sp=0},{t="The Corrupted Kin",b="Satyrs represent a dark, twisted branch of ancient night elf ancestry, irrevocably tainted by demonic energy during the War of the Ancients. Lurking in defiled groves across Ashenvale, these vile servants of the Burning Legion actively prey upon the denizens of the woods. Taking their horns serves not only as proof of vengeance, but strikes a direct blow against the fel presence encroaching upon eastern Ashenvale.",sp=0}},faq={{q="Who is Illiyana?",a="Illiyana is a dryad residing at Forest Song in eastern Ashenvale. Known for her gentle nature, she is mourning the tragic death of her sister, Anilia, who fell victim to the local satyrs.",al={"illiyana lore","who is the quest giver","forest song dryad"}},{q="Who was Anilia?",a="Anilia was a dryad and Illiyana's beloved sister. The two spent ages frolicking through Ashenvale's ancient canopies until Anilia was ambushed and killed by the region's prowling satyrs.",al={"anilia","illiyana sister","who died"}},{q="Why does Illiyana ask for satyr horns?",a="Satyr horns serve as undeniable, physical proof that the corrupted fiends responsible for Anilia's murder have been slain, granting her sister's spirit peace.",al={"why satyr horns","satyr horn proof"}},{q="What are satyrs?",a="Satyrs are former night elves cursed and mutated by the Burning Legion's demonic powers during the War of the Ancients. They dwell in corrupted enclaves, seeking to spread taint and destroy natural forest spirits.",al={"satyr lore","what are the satyrs in ashenvale"}},{q="Where is Forest Song?",a="Forest Song is an ancient, ruined night elf outpost situated in eastern Ashenvale, near the border of Azshara. It serves as a sanctuary for Alliance scouts and forest guardians.",al={"forest song location","where is forest song"}},{q="Is this connected to any other hunts at Forest Song?",a="Illiyana continues to accept satyr horns even after her sister is avenged, demonstrating an ongoing campaign by the defenders of Forest Song to purge the satyr menace from Ashenvale.",al={"satyr horns quest","followup quest","repeatable satyr quest"}}},ang={["class:Druid"]="Avenging a fallen dryad and severing the horns of demonic satyrs strikes directly at the corruption polluting Cenarius's favored wilderness.",["race:NightElf"]="Satyrs are a lingering, shameful reminder of the Highborne's ancient descent into fel servitude. Aiding Illiyana cleanses the land of this ancestral blight.",["faction:Alliance"]="Securing the perimeter of Forest Song provides Alliance forces in eastern Ashenvale with a safer haven against the wild threats surrounding them."},kw={"anilia","ashenvale","dryad","forest song","illiyana","satyr","satyr horns","satyr slaying"},rel={"npc:illiyana","subzone:forest-song","topic:satyr","zone:ashenvale","quest:6441"},m={start="Illiyana",level="32",faction="Alliance",id=1032},src={"Satyr Slaying! (Classic)"}}
E["quest:1033"] = {t="quest",n="Elune's Tear",z="ashenvale",s="Pelturas Whitemoon's young daughter Relara remains gripped by a foul and relentless malady, defying the herbal remedies brought from the northern ruins. Desperate for a stronger cure, Pelturas sends an adventurer to Iris Lake to retrieve Elune's Tear, a sacred mineral revered by night elves for its power to wash away corruption.",h="Pelturas Whitemoon's young daughter Relara remains gripped by a foul and relentless malady, defying the...",sec={{t="A Father's Growing Panic",b="Relara Whitemoon lies bedridden in Astranaar, wasting away from a virulent sickness of unknown origin. Pelturas had placed his hopes on an alchemical draught prepared from Bathran's hair by the apothecary Orendil Broadleaf. While that brew managed to arrest the rapid advance of the affliction, it fell short of cleansing her body entirely. Facing the bitter reality that ordinary restorative magic and wild herbs are not enough, Pelturas turns to the ancient traditions of his people, pleading for aid in securing remedies imbued with divine cleansing light.",sp=0},{t="The Stone of Iris Lake",b="Before parting ways, Orendil shared darker precautions with Pelturas, naming legendary remedies should the herbal mixture prove insufficient. Foremost among them is Elune's Tear, a luminous, sacred stone found only upon an island resting within Iris Lake, east of Astranaar. Believed to carry the blessing of the Moon Goddess, the stone is said to hold the power to purge deep-seated corruption from living flesh. Recovering it is no gentle pilgrimage, as troubled water elementals patrol the shallows and banks of the lake, fiercely guarding the untouched heart of the water.",sp=0},{t="A Measure of Hope",b="When brought safely back to Astranaar, Pelturas prepares to steep the stone into a medicinal broth to feed his ailing daughter. Yet even as he offers his desperate thanks, the lingering nature of the corruption suggests this ordeal may demand still rarer reagents before the child's life is truly secure.",sp=1}},faq={{q="What is Elune's Tear?",a="Elune's Tear is a rare, consecrated stone discovered upon the central isle of Iris Lake in Ashenvale. Night elven lore attributes powerful purifying and curative qualities to the mineral, holding that it can wash away severe poisons and lingering corruption.",al={"what is elunes tear","elune tear item","stone of iris lake"}},{q="Why did Orendil's previous cure fail?",a="The brew concocted by Orendil Broadleaf from the plant known as Bathran's hair successfully slowed the disease's progress, but it could not overcome the virulent nature of Relara's illness. Her father Pelturas realized ordinary herbalism was insufficient, prompting the search for spiritually blessed cures.",al={"why did orendil cure fail","did orendil cure work","relara still sick"}},{q="Where is Iris Lake located?",a="Iris Lake lies east of Astranaar in Ashenvale. Travelers can reach it by following the main road east out of town and trailing a dirt path that winds northward alongside a feeding stream into the lake basin.",al={"where is iris lake","iris lake location","how to find iris lake"}},{q="What dangers lurk around Iris Lake?",a="The waters and central isle of Iris Lake are inhabited by territorial water elementals. Anyone attempting to approach the isle to claim the Tear must navigate past these hostile nature spirits.",al={"iris lake enemies","what attacks at iris lake"}},{q="How does Pelturas plan to use the stone?",a="Pelturas intends to steep Elune's Tear into a medicinal stew, relying on the sacred mineral's reputed cleansing properties to leech out the dark affliction consuming his daughter Relara.",al={"how to use elunes tear","elunes tear stew"}},{q="Who is Relara Whitemoon?",a="Relara is the young night elf daughter of Pelturas Whitemoon, residing in Astranaar. She has fallen gravely ill with an unnatural corruption that threatens her life.",al={"who is relara","pelturas daughter"}}},ang={["race:NightElf"]="For the kaldorei, turning to sacred stones named for the Moon Goddess reflects their absolute faith that Elune's grace can purify wounds that conventional remedies cannot touch.",["class:Priest"]="Priests devoted to Elune will recognize the deep spiritual reliance on holy relics to combat dark, unnatural plagues when prayer alone requires a physical catalyst.",["class:Druid"]="Druids understand both the delicate balance of Ashenvale's waters and the presence of erratic water elementals that guard the undisturbed heart of Iris Lake.",["faction:Alliance"]="Assisting the defenders of Astranaar with personal crises strengthens Alliance unity in Ashenvale during a period of mounting regional peril."},kw={"ashenvale","astranaar","cure","elune","elune's tear","iris lake","orendil broadleaf","pelturas whitemoon","relara","water elementals"},rel={"quest:1020","quest:1034","npc:pelturas-whitemoon","subzone:iris-lake","subzone:astranaar","topic:elune","quest:1010","quest:1035"},m={start="Pelturas Whitemoon",level="22",faction="Alliance",id=1033},src={"Elune's Tear (Classic)"}}
E["quest:1034"] = {t="quest",n="The Ruins of Stardust",z="ashenvale",s="Pelturas Whitemoon's desperate quest to heal his daughter Relara continues in Astranaar. While the sacred water of Elune's Tear calmed her terrifying nightmares, a fierce fever still grips her. Guided by Orendil Broadleaf's botanical knowledge, adventurers journey south to harvest a cooling, luminescent dust settled among ancient night elven stones.",h="Pelturas Whitemoon's desperate quest to heal his daughter Relara continues in Astranaar.",sec={{t="A Father's Lingering Despair",b="Pelturas Whitemoon has spent sleepless nights by the bedside of his daughter, Relara, watching a malignant affliction burn through her. Though offering an Elune's Tear provided a temporary respite from the tormenting dreams that plagued her thoughts, the illness remains deeply rooted. Her body is racked by an intense fever that mundane medicines have failed to quench. With the temple healers pushed to their limits, Pelturas turns once more to ancient, nature-infused remedies to preserve his daughter's life.",sp=0},{t="The Glint of Stardust",b="On the advice of the elder herbalist Orendil Broadleaf, Pelturas looks toward the Ruins of Stardust, located south across the river from Astranaar. The fallen marble columns and archways of this ancient kaldorei sanctuary harbor a peculiar phenomenon: a frosted, shimmering substance that settles over the local foliage. This powdered condensation, colloquially termed stardust, possesses natural cooling properties potent enough to draw out unnatural heat. Pelturas intends to grind the collected residue into a medicinal poultice, hoping its tranquil chill will finally break Relara's burning fever.",sp=0},{t="Prowlers in the Waters",b="Harvesting the frosted dust is perilous due to the guardians and wildlife inhabiting the flooded, sunken stones. Water elementals, corrupted or agitated by shifts in Ashenvale's balance, surge around the sunken plazas where the bushes grow thickest. Harvesters must wade into the tranquil-looking shallows while staying alert to sudden ambushes from the murky depths, scouring sparkling bushes for enough clean residue before rushing it back to Astranaar.",sp=0}},faq={{q="Why does Pelturas need stardust?",a="Pelturas Whitemoon's daughter, Relara, is dying of a severe magical or corrupted fever in Astranaar. While Elune's Tear eased her dark nightmares, her fever still rages unchecked. The elder herbalist Orendil advised that the frosted residue gathering in the Ruins of Stardust has potent cooling properties that can be crafted into a soothing poultice.",al={"why stardust","ruins of stardust purpose","relara fever cure"}},{q="Where are the Ruins of Stardust located?",a="The Ruins of Stardust lie directly south of Astranaar in central Ashenvale, situated around a small lake and surrounded by ancient, overgrown kaldorei masonry.",al={"ruins of stardust location","where is ruins of stardust","find stardust ruins"}},{q="What is stardust in this context?",a="Rather than cosmic debris, the stardust referenced here is a delicate, frosted powder that coats the shrubs and flora among the flooded ruins. It carries subtle natural and lunar enchantments that imbue it with an intense, restorative chill.",al={"what is stardust","nature of stardust","stardust lore"}},{q="Does the stardust cure Relara completely?",a="The poultice helps reduce Relara's raging fever, stabilizing her condition in the short term. However, it does not completely banish the deep-seated corruption affecting her body, forcing Pelturas to seek further aid at Fallen Sky Lake.",al={"does stardust cure relara","relara cured","is the girl saved"},sp=1},{q="What threats are found at the Ruins of Stardust?",a="The flooded ruins are inhabited by aggressive water elementals that lurk beneath the surface and defend the tranquil waters, posing a danger to anyone wading through the shallows to inspect the shimmering bushes.",al={"ruins of stardust enemies","what attacks at ruins of stardust"}},{q="Who is Orendil?",a="Orendil Broadleaf is a knowledgeable night elf herbalist residing in northern Ashenvale near Maestra's Post. He has studied the region's unique plants for centuries and advises Pelturas on rare botanical treatments when standard temple remedies fall short.",al={"who told pelturas about stardust","orendil broadleaf"}}},ang={["race:NightElf"]="The ruins scattered south of Astranaar are relics of ancient kaldorei civilization, reminding night elves that the magic lingering in the stones can still be marshaled for healing.",["class:Priest"]="While Elune's grace soothed Relara's nightmares, the physical body often demands earthly remedies alongside divine prayer to preserve mortal life.",["profession:Herbalism"]="The collection of sparkling powder from the brush showcases the specialized knowledge required to identify rare botanical phenomena in Ashenvale's damp microclimates.",["class:Druid"]="Gathering soothing stardust requires contending with the perturbed water spirits inhabiting the flooded ruins, a stark reminder of Ashenvale's fragile ecological harmony."},kw={"ashenvale","astranaar","cure","elune","fever","orendil","pelturas","poultice","relara","stardust"},rel={"npc:pelturas-whitemoon","subzone:ruins-of-stardust","subzone:astranaar","quest:1033","quest:1035","quest:1020","quest:1010","zone:ashenvale"},m={start="Pelturas Whitemoon",level="23",faction="Alliance",id=1034},src={"The Ruins of Stardust (quest)"}}
E["quest:1035"] = {t="quest",n="Fallen Sky Lake",z="ashenvale",s="\"Fallen Sky Lake\" is the emotional culmination of Pelturas Whitemoon's quest chain to save his dying daughter, Relara, in Astranaar. Although her initial fever has broken, her vitality remains dangerously depleted, requiring a celestial moonstone to restore her life force. Players must journey into the untamed waters of Fallen Sky Lake to wrest one of these hoarded stones from a corrupted Shadethicket Oracle.",h="\"Fallen Sky Lake\" is the emotional culmination of Pelturas Whitemoon's quest chain to save his dying...",sec={{t="A Daughter's Fading Breaths",b="Pelturas Whitemoon has spent agonizing days watching his young daughter, Relara, slip closer to death. While powerful curatives brewed from Bathran's hair and stardust helped break her raging fever, the ordeal left her body hollowed and frail. Time is no longer on her side; Pelturas fears that without supernatural intervention, she has only breaths remaining before her spirit fades permanently into the night.",sp=0},{t="The Fallen Moonstone",b="To revitalize the girl, Pelturas turns to the magic of the moonstones—celestial fragments that once fell freely into the waters of Fallen Sky Lake, southeast of Astranaar. Traditionally gathered by the night elves for their restorative properties, these remnants of lunar grace have been claimed by aggressive elemental or corrupted bark, making their collection a matter of blade and spell rather than peaceful harvesting.",sp=0},{t="The Shadethicket Domain",b="The night elves lost easy access to the lake when the Shadethicket treants moved in and seized the surrounding wilderness. Their leader, the Shadethicket Oracle, hoards every fallen moonstone on an isolated islet in the center of the waters. Reclaiming even a single relic requires confronting and slaying the Oracle before Relara's strength runs out entirely.",sp=1}},faq={{q="Why does Relara need a moonstone if her fever already broke?",a="The intense fever drained Relara's life force so severely that natural rest cannot revive her. Her father Pelturas believes only the pure restorative power held within a fallen moonstone can restore her depleted spirit before she succumbs to exhaustion.",al={"why moonstone","relara still sick","relara fever gone"}},{q="Where is Fallen Sky Lake located?",a="Fallen Sky Lake lies in central-eastern Ashenvale, southeast of Astranaar. It is dominated by ancient, hostile treants and features a small central island.",al={"where is fallen sky lake","lake location","shadethicket lake location"}},{q="Who has the fallen moonstone?",a="The moonstone is held by the Shadethicket Oracle, the leader of the hostile treants inhabiting the lake. The Oracle lairs on an island right in the center of Fallen Sky Lake.",al={"who drops moonstone","shadethicket oracle location","where to get moonstone"}},{q="What happens after this quest?",a="This quest marks the final chapter in the quest chain concerning Relara's illness. Once you bring the fallen moonstone to Pelturas, her life is saved, and he offers a treasured family keepsake as his deepest gratitude.",al={"is there a follow up","what next","quest continuation"},sp=1},{q="Why are the Shadethickets hoarding the moonstones?",a="As wild creatures and treants of Ashenvale grow increasingly volatile and corrupted, the Shadethickets began violently driving off outsiders. Their Oracle systematically gathered and guarded the lunar relics, denying them to the night elves of Astranaar.",al={"why treants taking stones","oracle hoarding moonstones"}},{q="What previous quests lead up to this task?",a="The chain begins with Bathran's Hair, followed by Orendil's Cure, Elune's Tear, and The Ruins of Stardust. Each step gathers rare components to treat Relara's worsening condition.",al={"chain before fallen sky lake","quest prerequisites","what comes before"}}},ang={["race:NightElf"]="For the Kaldorei, protecting Astranaar's young is a sacred communal duty, and retrieving holy moonstones tied to Elune's blessings is an act of both mercy and reverence.",["class:Druid"]="Culling the hostile Shadethicket treants highlights the tragic discord spreading through Ashenvale's natural guardians, demanding a heavy heart to restore balance.",["class:Priest"]="Sought for their divine energies, the fallen moonstones represent the tangible, healing grace of the Moon Goddess Elune channeled to save a dying child.",["faction:Alliance"]="Helping Pelturas Whitemoon cements the Alliance's commitment to defending Astranaar's citizens against the creeping corruption overtaking Ashenvale."},kw={"ashenvale","astranaar","fallen moonstone","fallen sky lake","pelturas whitemoon","relara","shadethicket oracle"},rel={"npc:pelturas-whitemoon","subzone:astranaar","quest:1034","quest:1033","quest:1020","quest:1010","zone:ashenvale","topic:elune"},m={start="Pelturas Whitemoon",level="30",faction="Alliance",id=1035},src={"Fallen Sky Lake (quest)"}}
E["quest:1037"] = {t="quest",n="Velinde Starsong",z="ashenvale",s="This quest bridges an eerie investigation in Ashenvale with the military hierarchy in Darnassus. After uncovering unsettling events tied to the vanished night elf commander Velinde Starsong, adventurers are sent across the sea to consult Sentinel leadership regarding her mysterious fate.",h="This quest bridges an eerie investigation in Ashenvale with the military hierarchy in Darnassus.",sec={{t="A Vanished Predecessor",b="Sentinel Melyria Frostshadow holds watch in Ashenvale, but she was not the first to shoulder that burden. Before her stood Velinde Starsong, a priestess tasked with containing the demonic corruption bleeding southward out of Felwood. Though initial reports suggested Starsong had the peril well in hand, her defensive campaign gradually unraveled. Then, without warning or formal relief, she vanished entirely, leaving behind an unfinished war and unanswered questions.",sp=0},{t="Secrets of the Terrace",b="Unwilling to let the mystery linger after discovering disturbing clues in the forest, Melyria directs seekers to the capital of Darnassus. There, high upon the Warrior's Terrace, Sentinel commander Thyn'tel Bladeweaver oversees military deployments. While Starsong's sudden departure is whispered about throughout the ranks, the exact circumstances remain closely guarded by the high command, requiring earnest persuasion before any deeper records are unsealed.",sp=1}},faq={{q="Who was Velinde Starsong?",a="Velinde Starsong was an elven priestess and commander of the Sentinels stationed in Ashenvale. She was tasked with holding the northern border against the demonic horrors creeping out of Felwood before mysteriously disappearing from duty.",al={"velinde starsong lore","who is velinde","priestess velinde"}},{q="Why is Sentinel Melyria asking about her now?",a="Sentinel Melyria Frostshadow replaced Velinde after her unexplained disappearance. Following discoveries tied to the Howling Vale, Melyria recognizes that whatever happened to her predecessor remains a lingering concern for the safety of Ashenvale.",al={"why investigate velinde","melyria quest reason"}},{q="Where do I need to go to complete this quest?",a="You must travel from Ashenvale to the night elf capital of Darnassus atop Teldrassil. Commander Thyn'tel Bladeweaver can be found stationed at the Warrior's Terrace.",al={"where to turn in velinde starsong","thyntel bladeweaver location"}},{q="Why is Commander Bladeweaver reluctant to talk?",a="While it is common knowledge among the Sentinels that Velinde went missing, the specific circumstances and classified details surrounding her final missions are sensitive military matters that leadership will not share lightly with outsiders.",al={"why secret","why wont thyntel speak"}},{q="What connection does Velinde have to Felwood?",a="Velinde led the Sentinels' frontline efforts to contain the demonic corruption encroaching from Felwood. Although her initial containment efforts seemed successful, her campaign eventually faltered just before she vanished.",al={"velinde felwood","what happened in felwood"}},{q="What quest leads directly into this one?",a="This assignment follows 'The Howling Vale', where adventurers investigate the strange and hostile occurrences brewing deep within the forests of Ashenvale.",al={"velinde starsong prerequisite","previous quest"}}},ang={["race:NightElf"]="For night elf defenders, uncovering the fate of a respected commander and priestess touches upon the fragile state of northern Kalimdor following the Third War.",["class:Priest"]="Priests of Elune will find particular interest in how a fellow sister of the faith struggled while attempting to stem the demonic tide pouring from Felwood.",["faction:Alliance"]="The mission illustrates the rigid military protocol of Darnassus, where sensitive battlefield disappearances are tightly compartmentalized by Sentinel commanders."},kw={"ashenvale","darnassus","felwood","melyria frostshadow","sentinels","thyn'tel bladeweaver","velinde starsong","warrior's terrace"},rel={"npc:sentinel-melyria-frostshadow","npc:thyn-tel-bladeweaver","quest:1038","subzone:warrior-s-terrace","topic:sentinels","zone:ashenvale","zone:darnassus","zone:felwood"},m={start="Sentinel Melyria Frostshadow",["end"]="Thyn'tel Bladeweaver",level="30",faction="Alliance",id=1037},src={"Velinde Starsong (quest)"}}
E["quest:1040"] = {t="quest",n="Passage to Booty Bay",z="ashenvale",s="This errand traces the missing Sentinel Velinde Starsong across the Great Sea to the lawless haven of Booty Bay. Following shipping logs uncovered by Wharfmaster Dizzywig, Alliance travelers must journey from Ratchet to the Eastern Kingdoms in search of a goblin caravan driver named Ruzzgot.",h="This errand traces the missing Sentinel Velinde Starsong across the Great Sea to the lawless haven of Booty...",sec={{t="A Trail Across the Sea",b="The search for the night elf Sentinel Velinde Starsong leads away from the familiar boughs of Ashenvale and onto the ocean trade lanes. In the bustling goblin port of Ratchet, Wharfmaster Dizzywig eventually unearths old shipping manifests confirming that Velinde booked passage aboard a vessel named the Black Osprey, bound directly for the pirate haven of Booty Bay in Stranglethorn Vale.",sp=0},{t="The Road to Booty Bay",b="Reaching Booty Bay requires boarding the neutral goblin trans-oceanic ferry running between Ratchet and the southern tip of the Eastern Kingdoms. Upon arrival, the trail narrows toward Caravaneer Ruzzgot, a goblin transport master Dizzywig recommended to Velinde when she inquired about dangerous overland journeys through the southern wilderness.",sp=0}},faq={{q="Who is Velinde Starsong?",a="Velinde Starsong was a night elf Sentinel commander in Ashenvale who wielded the Scythe of Elune against the demonic remnants of the Burning Legion. After summoning worgen packs that soon spiraled out of her control, she set out on a solitary journey to seek guidance, eventually disappearing.",al={"velinde","who is velinde","velinde starsong lore"}},{q="Why did Velinde travel to Booty Bay?",a="Booty Bay is the primary maritime hub connecting central Kalimdor to the southern Eastern Kingdoms. Velinde needed passage across the Great Sea, and the Black Osprey out of Ratchet offered direct transit toward the human and dwarven kingdoms where she hoped to find answers about the Scythe.",al={"why booty bay","velinde booty bay","why did she go to booty bay"}},{q="Who is Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig manages the shipping docks in Ratchet for the Steamwheedle Cartel. Known for his impatient demeanor, he maintains the port's logbooks and passage manifests for all vessels traveling between Kalimdor and the Eastern Kingdoms.",al={"dizzywig","who is dizzywig","wharfmaster"}},{q="Who is Caravaneer Ruzzgot?",a="Caravaneer Ruzzgot is a goblin teamster based in Booty Bay who coordinates supply convoys and overland transport through the dangerous jungles of Stranglethorn Vale and beyond.",al={"ruzzgot","caravaneer ruzzgot","who is ruzzgot"}},{q="What ship did Velinde take?",a="According to Wharfmaster Dizzywig's shipping records, Velinde Starsong booked passage aboard the Black Osprey, which made a successful voyage from Ratchet across the Great Sea to Booty Bay.",al={"velindes ship","what boat did velinde take","black osprey"}},{q="How do I travel to Booty Bay from Ratchet?",a="The Steamwheedle Cartel operates a passenger ferry directly from the southern dock in Ratchet across the Great Sea, docking in the pirate port of Booty Bay on the southern tip of Stranglethorn Vale.",al={"getting to booty bay","how to get to booty bay","boat to booty bay"}}},ang={["race:NightElf"]="Finding Velinde Starsong is an urgent duty for the Kaldorei, as her disappearance with the Scythe of Elune left behind a lingering, dangerous mystery in the forests of Ashenvale.",["faction:Alliance"]="Navigating neutral goblin territory like Ratchet and Booty Bay requires patience and diplomacy, forcing Alliance travelers to deal with mercenaries and cartel bureaucrats."},kw={"black osprey","booty bay","caravaneer ruzzgot","passage to booty bay","ratchet","scythe of elune","velinde starsong","wharfmaster dizzywig"},rel={"quest:1039","quest:1041","quest:1492","subzone:booty-bay","zone:ashenvale","topic:goblin"},m={start="Wharfmaster Dizzywig",["end"]="Caravaneer Ruzzgot",level="30",faction="Alliance",id=1040},src={"Passage to Booty Bay"}}
E["quest:1041"] = {t="quest",n="The Caravan Road",z="ashenvale",s="The Caravan Road is an Alliance quest that traces the footsteps of the missing night elf priestess Velinde Starsong. Following information uncovered in Booty Bay, the trail leads north from the perilous jungles of Stranglethorn Vale into the shadowed town of Darkshire.",h="The Caravan Road is an Alliance quest that traces the footsteps of the missing night elf priestess Velinde...",sec={{t="A Priestess in the Jungle",b="Tracking Velinde Starsong across the world brings adventurers from the forests of Ashenvale all the way to the southern port of Booty Bay. There, Caravaneer Ruzzgot recalls an unusual passenger: a night elf priestess traveling alongside his dusty shipping caravan. Such solitary journeys are rare for her kind, making her journey through the lawless jungle of Stranglethorn Vale stand out in the minds of merchants.",sp=0},{t="North to Darkshire",b="According to Ruzzgot, he and Velinde parted company on their trek northward through the jungle, with the priestess striking out toward Duskwood. Her trail points directly to the beleaguered town of Darkshire, where the town's records are meticulously maintained by Clerk Daltry. In an era troubled by supernatural threats, Daltry logs every unfamiliar traveler entering the settlement, making his ledger the next vital link in unraveling Velinde's fate.",sp=0}},faq={{q="Who is Velinde Starsong?",a="Velinde Starsong is a night elf priestess of Elune who left her homeland in Kalimdor under mysterious circumstances. Her disappearance prompted an extensive search across the continents, tracing her passage from Ashenvale through the Eastern Kingdoms.",al={"velinde","who is velinde","who are we looking for"}},{q="Why was Velinde traveling with a caravan?",a="Velinde traveled disguised or unattended through goblin territory, hiring passage with Caravaneer Ruzzgot's shipping outfit in Booty Bay to make the hazardous overland journey north through Stranglethorn Vale.",al={"why caravan","velinde caravan","ruzzgot caravan"}},{q="Who is Clerk Daltry?",a="Clerk Daltry is the town clerk and archivist of Darkshire in Duskwood. Given the pervasive threats and strange occurrences plaguing the region, he keeps close records of outsiders and visitors entering town.",al={"clerk daltry","daltry darkshire","who is daltry"}},{q="Where does this quest chain lead after Darkshire?",a="After consulting Clerk Daltry's municipal records, he directs travelers to speak with Jonathan Carevin, initiating the quest 'The Carevin Family' to uncover more details about Velinde's stay in Duskwood.",al={"next quest","what comes next","after darkshire"},sp=1},{q="Why is traveling from Booty Bay to Darkshire dangerous?",a="Stranglethorn Vale is overrun with predatory beasts, hostile troll tribes, and Bloodsail buccaneers far more dangerous than the local fauna of Duskwood. Navigating north requires sticking closely to the main road.",al={"jungle danger","stranglethorn level","stranglethorn dangerous"}},{q="Where did this investigation start?",a="The search began in Ashenvale, where night elf investigators noted Velinde's unexplained departure with an artifact of great power, following clues that pointed to a ship bound for the southern seas.",al={"starting point","where did chain start","ashenvale start"}}},ang={["race:NightElf"]="Velinde Starsong is an esteemed Sentinel priestess of Elune whose secretive actions in the Eastern Kingdoms cause deep concern among her kin in Kalimdor.",["faction:Alliance"]="Carrying news between the neutral goblin ports and remote Alliance outposts like Darkshire reinforces ties in a world fractured by recent wars."},kw={"booty bay","caravaneer ruzzgot","clerk daltry","darkshire","duskwood","stranglethorn vale","the caravan road","velinde starsong"},rel={"npc:clerk-daltry","subzone:darkshire","subzone:booty-bay","quest:1040","quest:1042","zone:stranglethorn","zone:ashenvale","topic:night-elf"},m={start="Caravaneer Ruzzgot",["end"]="Clerk Daltry",level="30",faction="Alliance",id=1041},src={"The Caravan Road"}}
E["quest:1042"] = {t="quest",n="The Carevin Family",z="ashenvale",s="The Carevin Family is a short Alliance investigation quest that connects the mystery of Velinde Starsong to the monster hunters of Duskwood. Guided by town records clerk Daltry, adventurers seeking the lost priestess turn to Jonathan Carevin, patriarch of a family dedicated to culling beasts and fiends.",h="The Carevin Family is a short Alliance investigation quest that connects the mystery of Velinde Starsong to...",sec={{t="A Trail of Claws and Shadows",b="Searching for Velinde Starsong leads away from the ancient forests of Kalimdor and deep into the haunted gloom of Duskwood. Upon arriving in Darkshire, municipal clerk Daltry finds no official log of an elven priestess ever boarding in town. However, mentioning the savage wolf-men she sought immediately catches his ear, as beasts fitting that description have recently begun terrorizing the surrounding woods.",sp=0},{t="Hunters of the Night",b="Rather than standard town guards, dealing with such unnatural terrors falls to the Carevin family. Renowned locally as relentless hunters of demons, undead, and other horrors, their tracker Calor recently dragged a grisly string of severed wolf-men heads right through Darkshire's streets. Clerk Daltry directs outsiders to Jonathan Carevin, the stern head of the household, to learn what the family knows of these ferocious worgen.",sp=0},{t="A Cold Reception",b="Approaching the patriarch of the Carevin household is no casual encounter. Beset by the relentless horrors consuming Duskwood, Jonathan Carevin treats any unannounced stranger probing into worgen with deep wariness. Before sharing what his hunters have discovered about the beasts, he demands to know who stands before him and why they seek things best left buried in the dark.",sp=1}},faq={{q="Who is Jonathan Carevin?",a="Jonathan Carevin is the head of the Carevin household in Darkshire. He leads a family known throughout the blighted region as seasoned hunters specializing in tracking and slaying demons, undead, and monstrous beasts.",al={"jonathan carevin","who is carevin","carevin family head"}},{q="Why does Clerk Daltry direct you to the Carevin family?",a="While Clerk Daltry has no record of the missing night elf Velinde Starsong, he recognizes the description of the wolf-men she was tracking. The Carevins' tracker, Calor, recently brought severings of these creatures into Darkshire, making the family the town's premier experts on the monsters.",al={"why see carevin","clerk daltry carevin","why go to jonathan"}},{q="Who is Calor?",a="Calor is a hunter and tracker allied with the Carevin family in Darkshire. He recently made a gruesome impression on the town by marching in with a string of severed worgen heads, proving that the wolf-men are active nearby.",al={"calor","who is calor","carevin hunter calor"}},{q="How does this quest connect Ashenvale to Duskwood?",a="The quest chain originates in Ashenvale with the disappearance of Velinde Starsong and the mysterious appearance of the worgen. Tracking the caravan route leads from Kalimdor across the sea to Duskwood, where the same monstrous wolf-beasts have surfaced.",al={"velinde starsong connection","why duskwood","ashenvale to darkshire"}},{q="Why is Jonathan Carevin so suspicious of strangers?",a="Duskwood is thoroughly overrun by shadows, undead, and sinister forces, fostering deep paranoia among its surviving residents. When an unknown adventurer arrives suddenly inquiring about deadly worgen, Jonathan suspects ill intent until the traveler proves themselves.",al={"why carevin hostile","carevin suspicion"}},{q="What monsters do the Carevins specialize in fighting?",a="The Carevin family dedicates themselves to exterminating monstrous threats, primarily demons, undead, and bizarre aberrant beasts like the worgen that haunt Duskwood.",al={"carevin monsters","what do carevins hunt"}}},ang={["race:NightElf"]="Finding human monster hunters holding the severed heads of creatures tied to Velinde Starsong is an unsettling clue for night elves tracing the priestess's fateful journey.",["class:Hunter"]="The Carevin family represents a gritty, urban-adjacent cadre of beast hunters who specialize in purging unnatural fiends and cursed predators.",["faction:Alliance"]="This leg of the investigation highlights how isolated and vigilant the Alliance settlements in Duskwood must remain in order to endure the blighted woods."},kw={"calor","carevin","clerk daltry","darkshire","duskwood","jonathan carevin","velinde starsong","wolf-men","worgen"},rel={"npc:jonathan-carevin","npc:clerk-daltry","npc:calor","quest:1041","subzone:darkshire","quest:1037","topic:worgen","topic:night-elf"},m={start="Clerk Daltry",["end"]="Jonathan Carevin",level="30",faction="Alliance",id=1042},src={"The Carevin Family"}}
E["quest:1043"] = {t="quest",n="The Scythe of Elune",z="ashenvale",s="The Scythe of Elune is an Alliance investigation bridging an ancient night elf relic in Kalimdor with the sudden worgen infestation plaguing Duskwood. Sent by Jonathan Carevin in Darkshire, adventurers delve into the haunted depths of Roland's Doom to uncover what brought these ravenous beasts to the Eastern Kingdoms.",h="The Scythe of Elune is an Alliance investigation bridging an ancient night elf relic in Kalimdor with the...",sec={{t="A Hunt in the Dark",b="After tracing the enigmatic Priestess Velinde Starsong across Kalimdor and speaking with the Carevin household in Darkshire, travelers find common cause with Jonathan Carevin. The Nightbane worgen have overrun southern Duskwood, pushing out miners and threatening what little remains of the township. Although Carevin does not fully grasp the supernatural origin of these beasts, he recognizes the value of someone willing to root them out, pointing searchers toward Roland's Doom—the very mine where the fiends were first sighted.",sp=0},{t="Ghosts of Roland's Doom",b="Deeper within Roland's Doom, amidst packs of vicious Nightbane, lies an undisturbed mound of earth. Disturbing the soil reveals a lingering specter of Velinde Starsong herself. The ghostly manifestation confirms that the night elf priestess made her way into this wretched cave carrying the Scythe of Elune, but met a tragic and mysterious end beneath the soil of Duskwood. Her demise left the staff vulnerable, directly unleashing the worgen scourge across the realm.",sp=1}},faq={{q="Where do I look for signs of the Scythe?",a="Head into Roland's Doom, an abandoned mine located in southeastern Duskwood. Fight your way through the Nightbane worgen to an undisturbed pile of earth inside the tunnels.",al={"where is the scythe","scythe of elune location","roland's doom cave"}},{q="Who is Jonathan Carevin?",a="Jonathan Carevin is a member of the Carevin family residing in Darkshire. Faced with dwindling defenders against evil, he eagerly trades information with outsiders who seek to cull the dangerous worgen numbers.",al={"jonathan carevin","carevin darkshire"}},{q="What happened to Velinde Starsong in the mine?",a="Velinde Starsong carried the Scythe of Elune into Roland's Doom while trying to reach the Eastern Kingdoms. Her shade appears at the site of her fall, proving she perished deep inside the mine, which subsequently unleashed the worgen in Duskwood.",al={"velinde starsong fate","what happened to velinde"},sp=1},{q="What is the Scythe of Elune?",a="The Scythe of Elune is a sacred and volatile night elf artifact forged during ancient conflicts. It wields the wild power of Elune and the pack, capable of summoning worgen from other realms across space and time.",al={"what is the scythe","scythe of elune lore"}},{q="Why did the worgen appear in Duskwood?",a="The worgen first broke free into the Eastern Kingdoms from Roland's Doom, where Priestess Velinde Starsong was lost while carrying the Scythe. After her demise, the beasts ran wild through the haunted woods.",al={"why worgen in duskwood","duskwood worgen origin"},sp=1},{q="Who is Calor?",a="Calor is an associate of the Carevin family in Darkshire whom Jonathan instructs to focus entirely on containing the worgen threat following your discoveries in Roland's Doom.",al={"npc calor","who is calor"},sp=1}},ang={["race:NightElf"]="Finding the final resting place of Priestess Velinde Starsong reveals the terrible price paid when the Scythe of Elune slipped beyond the supervision of the Sisterhood.",["faction:Alliance"]="Unraveling the mystery of the Nightbane worgen provides Darkshire and the Alliance with their first real answers regarding the horrors stalking southern Duskwood.",["class:Druid"]="The wild and untamed worgen summoned by the Scythe carry deep roots in primordial pack magic, offering druids a sober warning about forces beyond control."},kw={"calor","darkshire","duskwood","jonathan carevin","nightbane","roland's doom","scythe of elune","velinde starsong","worgen"},rel={"quest:1042","quest:1044","quest:1037","subzone:roland-s-doom","subzone:darkshire","zone:duskwood","npc:jonathan-carevin","npc:calor"},m={start="Jonathan Carevin",level="30",faction="Alliance",id=1043},src={"The Scythe of Elune (Classic)"}}
E["quest:1044"] = {t="quest",n="Answered Questions",z="ashenvale",s="Answered Questions is an Alliance quest concluding a cross-continental investigation into the disappearance of the night elf priestess Velinde Starsong. Following clues across Kalimdor and the Eastern Kingdoms, an adventurer returns to Darnassus to deliver a final report to Thyn'tel Bladeweaver.",h="Answered Questions is an Alliance quest concluding a cross-continental investigation into the disappearance...",sec={{t="A Tragic Truth",b="The quest chain tracing Velinde Starsong begins in Ashenvale and stretches across continents to the haunted groves and abandoned mines of Duskwood. Following her trail reveals that Velinde, desperate to defend Kalimdor from demonic forces, wielded the Scythe of Elune and summoned the ferocious worgen. However, her control faltered, leading to tragedy and her demise deep in the Roland's Doom mine, while leaving Duskwood to grapple with the monstrous fallout.",sp=1},{t="Return to Darnassus",b="Following the recovery of Velinde's journal and learning her ultimate end, Jonathan Carevin in Duskwood urges the adventurer to return to Teldrassil. In Darnassus, sentinel Thyn'tel Bladeweaver receives the report. Velinde was a close friend to High Priestess Tyrande Whisperwind, making the news of her fall a heavy personal and spiritual blow to the Sisterhood of Elune.",sp=0},{t="A Missing Artifact",b="While Velinde's fate is finally resolved, a deeper danger remains unresolved: the Scythe of Elune itself has vanished. Given by the goddess as a sacred boon and weapon, the scythe is now lost to the wild, far from the hands of the priestesses who revered it. The presence of the feral worgen across Eastern Kingdoms stands as a lingering, unpredictable threat born from that loss.",sp=1}},faq={{q="What is the quest Answered Questions?",a="Answered Questions is an Alliance quest that concludes the investigation into Velinde Starsong. Started by Jonathan Carevin in Duskwood, it directs the player to deliver news of Velinde's death and the Scythe of Elune back to Thyn'tel Bladeweaver in Darnassus.",al={"answered questions quest","answered questions classic","end of scythe of elune quest"},sp=1},{q="Who was Velinde Starsong?",a="Velinde Starsong was a night elf priestess of Elune who received the Scythe of Elune during the Third War to fight the Burning Legion. She inadvertently summoned the feral worgen, lost control of them, and journeyed to the Eastern Kingdoms searching for answers before dying in Duskwood.",al={"velinde starsong","who is velinde","what happened to velinde"},sp=1},{q="Where is the Scythe of Elune at the end of this quest?",a="The Scythe of Elune remains missing. Though the adventurer uncovers Velinde's journal and learns her fate in the mine of Roland's Doom, the ancient artifact itself has slipped out of the night elves' custody and into unknown hands.",al={"where is the scythe of elune","did we find the scythe","scythe of elune location"},sp=1},{q="How is Tyrande Whisperwind connected to Velinde?",a="High Priestess Tyrande Whisperwind and Velinde Starsong were close friends prior to Velinde's disappearance. Thyn'tel Bladeweaver notes upon the quest's completion that Tyrande will take the news of Velinde's demise hard.",al={"tyrande and velinde","high priestess connection"},sp=1},{q="Who is Jonathan Carevin?",a="Jonathan Carevin is a human resident of Duskwood who assists the adventurer in the search through the local mines. Despite the horror of the worgen unleashed upon Duskwood, he holds no personal grudge against Velinde and sends the player back to Kalimdor to inform her people.",al={"jonathan carevin","who gives answered questions"}},{q="Where does Thyn'tel Bladeweaver stand?",a="Thyn'tel Bladeweaver is stationed in Darnassus on the isle of Teldrassil, serving the night elf leadership and overseeing the search for missing sentinels and priestesses.",al={"where is thyntel bladeweaver","thyntel bladeweaver location","hand in answered questions"}}},ang={["race:NightElf"]="For the night elves, this report brings mourning for a lost sister of the faith and deep concern that a sacred gift of Elune remains lost somewhere across the Great Sea.",["class:Priest"]="Priests of Elune feel a keen spiritual resonance with Velinde's story, recognizing both the power of the goddess's gifts and the perilous folly of trying to bend unknown beasts to one's will.",["faction:Alliance"]="The quest highlights the fragile cross-continental ties between the night elves of Kalimdor and the beleaguered human settlements of Duskwood dealing with common, shadowy threats."},kw={"answered questions","darnassus","duskwood","jonathan carevin","roland's doom","scythe of elune","thyn'tel bladeweaver","velinde starsong","worgen"},rel={"quest:1043","npc:thyn-tel-bladeweaver","npc:jonathan-carevin","zone:duskwood","zone:darnassus","topic:worgen","topic:elune","zone:ashenvale"},m={start="Jonathan Carevin",["end"]="Thyn'tel Bladeweaver",level="30",faction="Alliance",id=1044},src={"Answered Questions"}}
E["quest:1045"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="While tracking down the means to cleanse Lake Falathim, adventurers must secure the cooperation of Krolg, a Furbolg shaman near Lake Mystral. Disillusioned with both the arrogant night elves and the corruption rotting his own kin, Krolg demands the death of the depraved chieftain Ran Bloodtooth before he will aid in restoring the forest.",h="While tracking down the means to cleanse Lake Falathim, adventurers must secure the cooperation of Krolg, a...",sec={{t="A Bitter Hermit",b="Near the waters of Lake Mystral, Krolg keeps a secluded vigil. Displaced and weary, he carries deep resentment toward the night elves, whose ancient hubris he blames for bringing ruin upon Kalimdor and stirring the dark rot festering in Ashenvale. To reach him, seekers use Dartol's Rod of Transformation to walk among furbolgs undetected. Yet despite his bitter hatred of the kaldorei, Krolg does not seek senseless butchery or innocent deaths.",sp=0},{t="Policing Their Own",b="Rather than surrendering entirely to the demonic taint gripping the tribes, Krolg believes his people must remain accountable for their own deeds. The demonic corruption did not originate their flaws—it merely amplified their worst impulses. Ran Bloodtooth embodies this fall: already ruthless and power-hungry before the taint, Ran embraced the darkness eagerly, posing an existential threat to elves and innocent beasts alike. Krolg refuses to let such malice speak for all furbolgs.",sp=0},{t="A Shared Duty",b="By asking an outsider—disguised by Dartol's magic—to strike down Ran Bloodtooth and his elite guards, Krolg ensures justice is served without igniting further internal tribal strife. Ran's death strikes a blow against the encroaching madness, briefly uniting an embittered shaman and an Alliance agent in a shared desire to cleanse the sacred woodland.",sp=1}},faq={{q="Why does Krolg hate the night elves?",a="Krolg views the night elves as arrogant stewards whose historical meddling with dangerous magic brought corruption upon the land. He holds them responsible for the tainted state of Ashenvale and the suffering of the native tribes.",al={"krolg night elf hatred","why does krolg hate elves","krolg backstory"}},{q="Who is Ran Bloodtooth?",a="Ran Bloodtooth is a corrupt and power-hungry furbolg chieftain camped in the mountains east of Lake Mystral. Driven mad by the dark forces poisoning Ashenvale, his lust for violence poses a threat to all natural creatures in the forest.",al={"ran bloodtooth lore","who is bloodtooth","ran bloodtooth"}},{q="Why does Krolg want Ran Bloodtooth dead?",a="Even though Krolg resents the night elves, he draws the line at wanton savagery against the innocent. He believes the furbolgs must police their own evil and that Ran's corruption has turned him into a monster who threatens the entire forest.",al={"why kill ran bloodtooth","krolg motive bloodtooth"}},{q="How can Alliance players speak to Krolg without being attacked?",a="Alliance heroes use Dartol's Rod of Transformation, a sacred furbolg artifact provided during the quest chain, to take on the guise of a furbolg and safely approach Krolg.",al={"how to talk to krolg","dartols rod krolg","why is krolg friendly"}},{q="Where is Ran Bloodtooth located?",a="Ran Bloodtooth and his guards maintain an encampment along the mountains east of Krolg's refuge near Lake Mystral.",al={"ran bloodtooth location","where is ran bloodtooth","bloodtooth camp"}},{q="How does killing Ran Bloodtooth help cleanse Ashenvale?",a="Culling the most violent, taint-empowered chieftains curtails the spread of demonic madness among the wildlife and native tribes, fulfilling Krolg's condition for helping purify the waters of Lake Falathim.",al={"cleansing ashenvale ran","why is bloodtooth part of raenes cleansing"}}},ang={["race:NightElf"]="Confronting Krolg offers night elves an uncomfortable mirror: despite thousands of years guarding Ashenvale, local tribes hold kaldorei pride directly accountable for the ancient sundering and lingering taint.",["class:Druid"]="For druids dedicated to preserving Ashenvale's balance, Ran Bloodtooth represents the tragic fall of natural creatures yielding entirely to demonic corruption.",["faction:Alliance"]="Aided by Dartol's enchanted rod, Alliance champions act as clandestine intermediaries to quell rogue chieftains deep behind enemy lines."},kw={"ashenvale","bloodtooth guard","corruption","dartol's rod","furbolg","krolg","lake mystral","ran bloodtooth"},rel={"npc:krolg","zone:ashenvale"},m={start="Krolg",level="30",faction="Alliance",id=1045},src={"Raene's Cleansing (10)"}}
E["quest:1046"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This quest marks the final chapter in the search to uncover what befell Teronis and halt the furbolg threat looming over Ashenvale. Bearing Ran Bloodtooth's skull from Krolg, an adventurer returns to Sentinel Raene Wolfrunner in Astranaar to report the culmination of their perilous journey.",h="This quest marks the final chapter in the search to uncover what befell Teronis and halt the furbolg threat...",sec={{t="A Bitter Trophy",b="Following the defeat of the fierce corrupted furbolg chieftain Ran Bloodtooth, Krolg sends the champion back to Astranaar. With Bloodtooth's severed skull in hand, you return as proof that the savage threat prowling the forest depths has been decisively struck down.",sp=0},{t="In Memory of Teronis",b="Upon receiving the skull, Raene Wolfrunner places it alongside Dartol's Rod in a place of reverence. The grim token honors the memory of Teronis, whose tragic investigation into cleansing the corrupted furbolgs set the entire desperate effort into motion.",sp=1}},faq={{q="Who is Ran Bloodtooth?",a="Ran Bloodtooth was considered the fiercest corrupted furbolg threat terrorizing the forests of Ashenvale. His defeat removes a dangerous chieftain actively preying upon the woodland.",al={"ran bloodtooth","bloodtooth skull","who was ran bloodtooth"}},{q="Why does Raene Wolfrunner want the skull?",a="Raene Wolfrunner keeps the skull alongside Dartol's Rod as a symbol of victory and remembrance. It serves as undeniable proof that the Sentinel forces and their allies struck down a mortal danger to Ashenvale.",al={"why skull","wolfrunner skull","what does raene do with the skull"}},{q="Who was Teronis?",a="Teronis was a night elf investigator whose death early in the questline spurred the search for the cleansing gemstones and Dartol's Rod. Finishing the task fulfills his unfinished mission.",al={"teronis","who is teronis","teronis proud"},sp=1},{q="Where does this quest end?",a="It is completed in Astranaar, the primary night elf hub in Ashenvale, by speaking with Sentinel Raene Wolfrunner.",al={"turn in location","where is raene","raene wolfrunner location"}},{q="Who is Krolg?",a="Krolg is an ally who directs you to carry the severed skull of Ran Bloodtooth back to Astranaar to claim your recognition and bask in victory among your own people.",al={"krolg","who gives quest","npc krolg"}},{q="What is Dartol's Rod?",a="Dartol's Rod is a powerful enchanted relic assembled during the quest chain that holds deep magical connections to furbolg nature and cleansing.",al={"dartol's rod","rod of transformation","furbolg rod"}}},ang={["race:NightElf"]="For the kaldorei, ending the fury of Ran Bloodtooth honors fallen Sentinels like Teronis and helps reclaim the sanctity of Ashenvale's sacred groves.",["faction:Alliance"]="Delivering Bloodtooth's skull cements the Alliance's commitment to defending Astranaar and standing shoulder to shoulder with the night elf Sentinels."},kw={"ashenvale","astranaar","dartol's rod","furbolg","krolg","raene wolfrunner","raene's cleansing","ran bloodtooth","teronis"},rel={"npc:raene-wolfrunner","subzone:astranaar","zone:ashenvale","topic:furbolg","topic:sentinels","npc:krolg","topic:alliance"},m={start="Krolg",["end"]="Raene Wolfrunner",level="30",faction="Alliance",id=1046},src={"Raene's Cleansing (11)"}}
E["quest:1054"] = {t="quest",n="Culling the Threat",z="ashenvale",s="Culling the Threat is an Alliance defensive operation issued by Raene Wolfrunner in Astranaar. Faced with rapidly multiplying Thistlefur furbolgs directly to the north, the night elves seek to preempt an assault on the settlement by slaying their warlord, Dal Bloodclaw. It reflects the grim reality that former woodland allies must now be culled to safeguard kaldorei homes.",h="Culling the Threat is an Alliance defensive operation issued by Raene Wolfrunner in Astranaar.",sec={{t="A Looming Peril to the North",b="Astranaar lies in the heart of Ashenvale, constantly surrounded by danger. Just north of the settlement dwell the Thistlefur furbolgs. Once peaceable dwellers of the ancient forest, they have fallen into madness and aggression like so many of their kin. Sentinel scouts watched their populations swell over recent months, raising fears that a coordinated assault on Astranaar itself was only a matter of time.",sp=0},{t="Striking the Chieftain",b="Rather than waiting for the Thistlefur horde to overrun Astranaar's modest palisades, Raene Wolfrunner commissions travelers to take offensive action. The objective is Dal Bloodclaw, the chieftain whose leadership organizes and emboldens the den. By severing the tribe's head and bringing Dal's skull back to Astranaar, the Sentinels hope to break the furbolgs' coordination and buy precious time for the beleaguered town.",sp=0}},faq={{q="Who gives the quest Culling the Threat?",a="Raene Wolfrunner, a Sentinel commander stationed in the night elf town of Astranaar in Ashenvale, offers this task.",al={"quest giver","who starts culling the threat","where do i get culling the threat"}},{q="Why does Astranaar want Dal Bloodclaw dead?",a="Dal Bloodclaw leads the Thistlefur tribe directly north of Astranaar. With their numbers multiplying rapidly, Wolfrunner fears Bloodclaw will lead a direct raid on the town if his leadership is not severed.",al={"why kill dal bloodclaw","dal bloodclaw lore","why attack thistlefur"}},{q="Why are the Thistlefur furbolgs hostile to the night elves?",a="Although furbolgs and night elves were historic allies, demonic and corrupting influences across Ashenvale have driven many tribes, including the Thistlefur, into violent frenzy and territorial paranoia.",al={"why do furbolgs attack","corrupted furbolgs ashenvale","thistlefur lore"}},{q="Where can Dal Bloodclaw be found?",a="Dal Bloodclaw resides in the Thistlefur Village and its nearby barrows directly north of Astranaar in Ashenvale.",al={"dal bloodclaw location","where is dal bloodclaw"}},{q="Does killing Dal Bloodclaw solve the furbolg threat permanently?",a="No. Raene Wolfrunner notes that slaying Dal Bloodclaw only stifles their aggression for a time. As long as corruption grips Ashenvale, the furbolg population remains an enduring danger.",al={"is thistlefur defeated","did we save astranaar"}},{q="What proof of Dal Bloodclaw's death is required?",a="You must take Dal Bloodclaw's Skull and deliver it directly to Raene Wolfrunner in Astranaar.",al={"what do i bring raene","culling the threat turn in item"}}},ang={["race:NightElf"]="For kaldorei, striking down the furbolgs is a tragic necessity, mourning the corruption of ancient allies while taking brutal measures to shield Astranaar from ruin.",["faction:Alliance"]="Holding Astranaar is essential for Alliance supply lines and communication across central Kalimdor, making any threat north of town an urgent tactical priority.",["class:Druid"]="Druids view the madness of the Thistlefur tribe with deep sorrow, witnessing how the lingering taint upon Ashenvale drives noble wildkin into bloodthirsty beasts."},kw={"ashenvale","astranaar","culling the threat","dal bloodclaw","furbolg","raene wolfrunner","thistlefur"},rel={"npc:raene-wolfrunner","subzone:astranaar","zone:ashenvale","topic:furbolg","zone:darnassus","topic:elune"},m={start="Raene Wolfrunner",level="25",faction="Alliance",id=1054},src={"Culling the Threat"}}
E["quest:1055"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="This task marks the completion of the Rod of Transformation at the hidden shrine in Ashenvale. With the sacred artifact assembled, it must be returned immediately to the priestess Shael'dryn at her moonwell sanctuary.",h="This task marks the completion of the Rod of Transformation at the hidden shrine in Ashenvale.",sec={{t="A Restored Relic",b="The arduous effort to cleanse and assemble the Rod of Transformation reaches a quiet turning point at the secluded shrine hidden deep within Ashenvale's wilds. Piecing together corrupted components, gathering elemental purities, and scouring the forest for ancient gems has produced an intact, newly consecrated rod. The artifact now hums with restored magic, ready to serve as a weapon against the demonic and foul corruptions spreading through the ancient night elf territory.",sp=0},{t="Return to Shael'dryn",b="With the assembly complete, word and relic must be delivered swiftly back to Shael'dryn. Stationed beside the calm waters of the forest moonwell, the devoted priestess has guided every step of this restoration effort. Presenting the assembled rod to her not only confirms that the forest's sacred craft remains unbroken, but also allows the Sentinel defenders to take the next critical steps in defending their besieged homeland.",sp=0}},faq={{q="What is the purpose of this stage of the quest?",a="Having successfully assembled the Rod of Transformation at the hidden shrine, you simply need to take the finished rod back to the priestess Shael'dryn, who waits at the moonwell in northern Ashenvale.",al={"what to do raenes cleansing 7","what is this quest","quest goal"}},{q="Who is Shael'dryn?",a="Shael'dryn is a night elf priestess tending a sacred moonwell in Ashenvale. Working to cleanse the ancient forest of spreading corruption, she directs trusted allies to gather relics, purify components, and restore sacred artifacts.",al={"shaeldryn","who is shael'dryn","priestess at moonwell"}},{q="Where is Shael'dryn located?",a="Shael'dryn resides at a quiet moonwell nestled in northern Ashenvale, east of the main road leading between Astranaar and Felwood, surrounded by the tranquil waters she watches over.",al={"shael'dryn location","where is shaeldryn","where moonwell"}},{q="What is the Rod of Transformation?",a="The Rod of Transformation is an ancient artifact associated with night elf magic and forest lore. When restored and empowered, it holds the power to break dark hexes, see through foul curses, and reshape the forms of creatures afflicted by lingering corruption.",al={"what is rod of transformation","rod of transformation lore","the rod"}},{q="Why is assembling the rod so important to Astranaar?",a="Ashenvale faces unprecedented corruption from lingering demonic taint, foul furbolg tribes, and foreign invaders. Raene Wolfrunner and her fellow night elves depend on sacred relics like the rod to cleanse sacred sites and protect Astranaar from falling to dark forces.",al={"why raenes cleansing","why astranaar cares","raene importance"}},{q="Does assembling the rod end the cleansing chain?",a="No. Returning the assembled rod to Shael'dryn completes this step, but she will immediately enlist your help to wield the restored power of the relic against the remaining threats poisoning Ashenvale.",al={"is this the last quest","does raenes cleansing end here","chain end"}}},ang={["race:NightElf"]="Restoring the sacred Rod of Transformation aids your sisters in the Sisterhood of Elune as they fight to rescue the sacred groves of Ashenvale from rot and dark sorcery.",["faction:Alliance"]="Securing Ashenvale is crucial for the Alliance's standing in northern Kalimdor, safeguarding Astranaar against relentless attacks by local corruption and hostile forces.",["class:Priest"]="Assisting Shael'dryn highlights the ancient rituals of Elune, demonstrating the moonwells' power to cleanse even the most persistent curses through consecrated faith."},kw={"ashenvale","astranaar","elune","hidden shrine","moonwell","raene's cleansing","rod of transformation","shael'dryn"},rel={"npc:shael-dryn","subzone:moonwell-ashenvale","zone:ashenvale"},m={start="Hidden Shrine",["end"]="Shael'dryn",level="28",faction="Alliance",id=1055},src={"Raene's Cleansing (7)"}}
E["quest:1133"] = {t="quest",n="Journey to Astranaar",z="ashenvale",s="Journey to Astranaar is an introductory Alliance quest guiding newcomers arriving on the Kalimdor coast to the inland heart of Ashenvale. Directed by Fiora Longears at Auberdine, travelers make their way south and east along the forest roads to report to Shindrell Swiftfire in Astranaar. It marks an adventurer's entry into the growing conflicts surrounding the night elves' ancestral forest.",h="Journey to Astranaar is an introductory Alliance quest guiding newcomers arriving on the Kalimdor coast to...",sec={{t="From the Coast into the Woods",b="Alliance travelers arriving in Darkshore aboard the ferry from Menethil Harbor often look for purpose in northern Kalimdor. At Auberdine, Fiora Longears directs capable hands to move deeper inland toward Astranaar, the main night elven settlement within Ashenvale. The journey follows winding paths under ancient, shadowed canopies, leading straight into a forest strained by war and unrest.",sp=0},{t="An Unspoken Recommendation",b="Curiously, Fiora tells travelers not to bother mentioning her name when arriving in Astranaar, stating plainly that Shindrell Swiftfire does not know her. Her role is simply to funnel fresh Alliance talent where it is needed most. Upon arriving, Shindrell readily welcomes any able-bodied defender, acknowledging that while Ashenvale remains breathtaking, it is no longer the peaceful sanctuary it once was.",sp=0}},faq={{q="Where does the Journey to Astranaar quest begin?",a="The quest is given by Fiora Longears in Auberdine, located on the coast of Darkshore. She offers it to Alliance travelers who arrive from the Eastern Kingdoms looking to help out in Kalimdor.",al={"who gives journey to astranaar","journey to astranaar start","where to pick up journey to astranaar"}},{q="Who do I need to talk to in Astranaar?",a="You must speak with Shindrell Swiftfire, a night elf stationed in Astranaar, the central Alliance town in Ashenvale.",al={"where to turn in journey to astranaar","journey to astranaar end npc","who is shindrell swiftfire"}},{q="Why does Fiora say not to mention her name?",a="Fiora Longears explicitly tells adventurers not to mention who sent them simply because Shindrell does not know her personally. She is merely directing eager newcomers toward an outpost that desperately needs assistance.",al={"why not mention fiora","fiora longears connection to shindrell"}},{q="What is the purpose of this quest?",a="It acts as a breadcrumb leading Alliance characters out of Darkshore into the higher-level region of Ashenvale, introducing them to Astranaar as their primary base of operations in the forest.",al={"why do journey to astranaar","journey to astranaar lore purpose"}},{q="What kind of trouble is happening in Ashenvale?",a="As Shindrell Swiftfire points out upon your arrival, Ashenvale is no longer the tranquil grove it used to be. The forest faces incursions from the Horde, demonic corruption lingering from the Third War, and local wildlife agitated by recent conflicts.",al={"why does astranaar need help","ashenvale troubles lore"}},{q="What quest leads into Journey to Astranaar?",a="It is directly preceded by a short introductory breadcrumb quest named 'Fiora Longears,' which directs travelers arriving in Darkshore to speak with her in Auberdine.",al={"journey to astranaar prerequisite","fiora longears chain"}}},ang={["faction:Alliance"]="This trek represents an Alliance recruit's direct deployment from the relatively safe ports of Darkshore into the contested wilderness of Ashenvale.",["race:NightElf"]="For night elves, this journey is a return to their heartland under siege, defending the sacred boughs of Ashenvale alongside foreign allies.",["race:Human"]="Fresh off the ship from Menethil Harbor, human travelers take their first steps deep into Kalimdor's interior, honoring the Alliance pledge to aid the night elves."},kw={"ashenvale","astranaar","auberdine","darkshore","fiora longears","journey to astranaar","menethil harbor","shindrell swiftfire"},rel={"subzone:astranaar","zone:ashenvale","npc:shindrell-swiftfire","quest:1132","topic:alliance"},m={start="Fiora Longears",["end"]="Shindrell Swiftfire",level="20",faction="Alliance",id=1133},src={"Journey to Astranaar"}}
E["quest:1134"] = {t="quest",n="Pridewings of Stonetalon",z="ashenvale",s="Concerned about covert Horde attacks, the Sentinels in Astranaar seek to intercept a deadly weapon before it can strike their people. Intelligence from Theramore reveals that orc assassins harvest toxic venom from the wyverns of Stonetalon Mountains for clandestine raids. To protect their fragile border, Alliance scouts are dispatched south to harvest the venom sacs first and starve the enemy of their lethal poison.",h="Concerned about covert Horde attacks, the Sentinels in Astranaar seek to intercept a deadly weapon before it...",sec={{t="A Fragile Truce",b="Though open war has not been declared between the Alliance and the Horde across northern Kalimdor, the peace between them is razor-thin. Skirmishes break out under thick forest canopies, and quiet, deniable strikes have replaced full-scale armies. Sentinel commanders in Astranaar maintain constant vigilance against covert enemy movements, knowing that complacency could cost them their sanctuary.",sp=0},{t="Poison from the Crags",b="Intelligence passed from secretive contacts in Theramore brought word of a sinister enterprise underway in the crags of Stonetalon. Orcish stalkers have been gathering venom from wild pridewings around Mirkfallon Lake, using the potent biological agent to coat their blades for fatal ambush raids against Alliance personnel. To blunt the threat, Shindrell Swiftfire directs champions to cull the beasts and seize the venom sacs before Horde agents can harvest them.",sp=0},{t="A Painful Duty",b="Ordering the destruction of native beasts weighs heavily on the night elves, who hold deep reverence for Kalimdor's wilderness. Shindrell herself laments that innocent creatures must suffer for a war they have no role in choosing. Yet in the grim calculus of border defense, denying an enemy lethal arms takes precedence over ecological preservation.",sp=0}},faq={{q="What are pridewings?",a="Pridewings are dangerous, venomous flying beasts related to wyverns that nest in high crags, particularly around Mirkfallon Lake in the Stonetalon Mountains. Their potent venom makes them lethal predators and a coveted resource for poisoners.",al={"what are pridewings","pridewing lore","stonetalon pridewings"}},{q="Why is the Alliance hunting them?",a="Alliance intelligence indicates that Horde assassins are actively harvesting pridewing venom to coat weapons used in covert raids against Alliance positions. By slaughtering the beasts and claiming their venom sacs first, the Alliance deprives the Horde of this deadly poison.",al={"why kill pridewings","quest purpose","alliance pridewing venom"}},{q="Who provided the intelligence about the orc assassins?",a="The warning originated from hidden Alliance informants stationed in Theramore, who keep close watch on Horde movements and supply networks throughout the southern barrens and Stonetalon.",al={"who warned the alliance","theramore spy info","shindrell intel source"}},{q="Where is Mirkfallon Lake located?",a="Mirkfallon Lake lies in the northern reaches of the Stonetalon Mountains, just south of the border trail leading from Ashenvale.",al={"mirkfallon lake location","where are the pridewings","find pridewings"}},{q="Are the Alliance and Horde at open war in Ashenvale?",a="Officially, the two factions maintain a fragile peace, avoiding declared, open warfare. In reality, covert assassinations, resource skirmishes, and border conflicts flare up continuously beneath the forest canopy.",al={"are horde and alliance at war","ashenvale war status","peace treaty ashenvale"}},{q="How does Shindrell Swiftfire feel about killing the beasts?",a="Shindrell grieves having to order the slaughter of beasts that did not willingly join the conflict. However, as an officer charged with defending Astranaar, she views it as a tragic necessity to keep her people safe.",al={"shindrell reaction","druidic guilt","night elf killing beasts"}}},ang={["race:NightElf"]="Night elves struggle with the grim necessity of slaying wild pridewings, balancing their spiritual stewardship of nature against the harsh reality of border warfare.",["faction:Alliance"]="This mission demonstrates the quiet intelligence network linking Jaina's settlement in Theramore to the Sentinel outposts of Ashenvale in an effort to thwart Horde aggression.",["class:Rogue"]="Rogues can appreciate the lethal utility of pridewing venom, understanding exactly how devastating coated blades can be in covert wilderness ambushes.",["class:Druid"]="Druids often mourn the waste of natural life, lamenting that innocent creatures must be culled simply to deny their toxins to warmongers."},kw={"assassins","astranaar","mirkfallon lake","pridewings","shindrell swiftfire","stonetalon mountains","theramore","venom"},rel={"npc:shindrell-swiftfire","subzone:mirkfallon-lake","zone:stonetalon","subzone:astranaar","zone:ashenvale","topic:alliance","topic:horde"},m={start="Shindrell Swiftfire",level="21",faction="Alliance",id=1134},src={"Pridewings of Stonetalon"}}
E["quest:1918"] = {t="quest",n="The Befouled Element",z="ashenvale",s="Upon slaying the agitated water elementals around Mystral Lake, adventurers discover a foul, glowing globe of tainted water. Seeking to understand what has poisoned the lake and its elemental spirits, they carry the specimen back to Mastok Wrilehiss at Splintertree Post.",h="Upon slaying the agitated water elementals around Mystral Lake, adventurers discover a foul, glowing globe of...",sec={{t="Tainted Waters of Mystral Lake",b="Mystral Lake, nestled in southeastern Ashenvale, has fallen into severe distress. The water elementals inhabiting its shallows have grown violently aggressive and visibly corrupted. When struck down, their remains yield strange, intensely glowing spheres of putrid fluid rather than pure elemental essence. Whatever corruption has settled over the lake is concentrated inside these globes, signaling that the disturbance is far more than natural territorial aggression.",sp=0},{t="Seeking Splintertree's Counsel",b="With no clear understanding of the foul magic at work, Horde scouts look to the garrison at Splintertree Post for guidance. Mastok Wrilehiss, one of the outpost's overseers, is initially disgusted by the vile specimen brought to him. A soldier rather than a scholar, Mastok quickly realizes that mundane steel cannot cure diseased water, prompting him to point the adventurer toward the elemental specialists of the Earthen Ring.",sp=1}},faq={{q="What is inside the Befouled Water Globe?",a="The globe holds a disgusting, concentrated sample of the corruption currently poisoning Mystral Lake. It forms from the remnants of slain elementals, demonstrating that their spiritual corruption is physical and potent.",al={"befouled globe contents","what is in the water globe","mystral lake water globe"}},{q="Where does this quest begin?",a="The quest begins as an item drop while fighting the enraged or befouled water elementals inhabiting Mystral Lake in south-central Ashenvale.",al={"where do i find the water globe","how to start the befouled element","quest start"}},{q="Why does Mastok Wrilehiss want nothing to do with it?",a="Mastok Wrilehiss is a Horde officer focused on military survival and logistics at Splintertree Post. He has no affinity for diagnosing diseased magical waters, which is why he suggests seeking out the Earthen Ring instead.",al={"who is mastok","why talk to mastok","mastok wrilehiss role"}},{q="What is the Earthen Ring's interest in this?",a="The Earthen Ring is an order of shaman dedicated to studying, soothing, and restoring harmony to the elements. Corrupted elementals like those at Mystral Lake fall directly under their spiritual jurisdiction.",al={"why earthen ring","earthen ring connection","who are the earthen ring"}},{q="How does this connect to Stonetalon Standstill?",a="The quest is closely tied to the Horde's containment efforts at Mystral Lake, where previous operations like Stonetalon Standstill require fighters to cull the rampant elementals threatening nearby travel paths.",al={"stonetalon standstill connection","prerequisites for befouled element"}},{q="Where does the investigation lead next?",a="Mastok points you toward Je'neu Sancrea, an Earthen Ring shaman stationed along the western shore of Ashenvale at Zoram'gar Strand, who can properly examine the tainted relic.",al={"what comes next","next quest after befouled element","where do i go next"},sp=1}},ang={["class:Shaman"]="The twisted state of Mystral Lake's spirits is a grave concern for shamans, who hear the pain of the elements and recognize the need for the Earthen Ring's intervention.",["faction:Horde"]="Splintertree Post cannot afford a chaotic elemental menace festering in its backyard while Alliance sentinels and furbolgs threaten Horde supply routes.",["race:Tauren"]="Tauren travelers feel a deep cultural duty to heal the land's corrupted waters, making the restoration of Mystral Lake an urgent spiritual task."},kw={"ashenvale","befouled water globe","corrupted elementals","earthen ring","mastok wrilehiss","mystral lake","splintertree post"},rel={"npc:mastok-wrilehiss","subzone:mystral-lake","subzone:splintertree-post","quest:824","quest:25","zone:ashenvale"},m={start="Befouled Water Globe",["end"]="Mastok Wrilehiss",faction="Horde",id=1918},src={"The Befouled Element"}}
E["quest:1944"] = {t="quest",n="Waters of Xavian",z="ashenvale",s="Waters of Xavian is a Horde mage quest offered by Deino in Orgrimmar. Seeking to plumb ancient elven secrets, she tasks her apprentice with traveling to the ruins of Xavian in Ashenvale to draw a sample from its highest waterfall.",h="Waters of Xavian is a Horde mage quest offered by Deino in Orgrimmar.",sec={{t="A Mage's Curiosity",b="Within the dark crevices of the Valley of Spirits, the troll mage Deino seeks out lingering reservoirs of primal arcane energy across Kalimdor. Her gaze turns to Xavian, an ancient night elf city hidden deep in the eastern canopy of Ashenvale. Legends among scholars whisper that the city was steeped in magical knowledge before the Sundering, and its waters are said to retain potent arcane properties that modern casters yearn to dissect.",sp=0},{t="The Ruins of Xavian",b="Reaching the source of these waters is no simple errand. Xavian no longer belongs to peaceful elven sages; it has fallen into ruin and is now overrun by feral, corrupt satyrs who fiercely guard their territory from outsiders. Prying mages must navigate past Satyrnaar and tread through dangerous waterways, avoiding both prowling beasts and demonic sentinels to fill Deino's flask at the base of the city's towering waterfall.",sp=0}},faq={{q="Who is Deino?",a="Deino is a troll mage trainer and scholar located in the Valley of Spirits in Orgrimmar. She instructs Horde mages and investigates relics of ancient Kalimdor magic.",al={"who gives waters of xavian","deino orgrimmar"}},{q="Where is Xavian located?",a="Xavian is an ancient ruined city situated in northeastern Ashenvale, north of Splintertree Post and just northwest of the satyr stronghold of Satyrnaar.",al={"xavian location","where is xavian","finding xavian"}},{q="Why does Deino want this water?",a="Scholarly accounts claim Xavian once held vast magical knowledge, and its waters are believed to hold lingering arcane power. Deino wants a fresh sample from the waterfall's source to analyze its properties.",al={"why get xavian water","purpose of xavian water"}},{q="What dangers guard the ruins of Xavian?",a="The ruins are infested with satyrs—demonic, corrupted beings who despise trespassers and guard their territory aggressively against prying mages.",al={"xavian enemies","who controls xavian"}},{q="Where exactly is the water sample collected?",a="The sample must be scooped into Deino's flask from the pool at the very base of the highest waterfall within the ruins of Xavian.",al={"waterfall location","where to fill flask","xavian waterfall"}},{q="What comes next after returning the sample to Deino?",a="Satisfied with the water sample, Deino sends the mage on the next stage of study involving the dryads in Ashenvale with the quest Laughing Sisters.",al={"waters of xavian followup","next quest after waters of xavian"},sp=1}},ang={["class:Mage"]="This quest is an exclusive rite of study for Horde mages, testing their ability to venture into hostile wilderness to extract untamed arcane reagents.",["faction:Horde"]="Splintertree Post serves as the Horde's nearest staging ground in eastern Ashenvale for navigating the satyr-infested wilds surrounding Xavian."},kw={"ashenvale","deino","flask","mage quest","orgrimmar","satyr","splintertree","waters of xavian","xavian"},rel={"npc:deino","subzone:xavian","quest:1945","quest:1943","zone:ashenvale","subzone:satyrnaar","subzone:splintertree-post","topic:satyr"},m={start="Deino",level="26",faction="Horde",id=1944},src={"Waters of Xavian"}}
E["quest:1945"] = {t="quest",n="Laughing Sisters",z="ashenvale",s="Laughing Sisters is a Horde quest that sends warlocks into the heart of Ashenvale to gather enchanted locks of hair from wild dryads. The material is destined for Kil'hala, an experienced troll tailor at the Crossroads, to spin into an empowered warlock robe. Hunting the daughters of Cenarius underscores the relentless friction between Horde spellcasters and the native defenders of the ancient woodland.",h="Laughing Sisters is a Horde quest that sends warlocks into the heart of Ashenvale to gather enchanted locks...",sec={{t="Weaving the Arcane",b="Following their efforts to secure corrupted water from Xavian, rising warlocks are directed by Deino in Orgrimmar to assist in crafting their own enchanted vestments. Arcane tailoring of this nature demands materials imbued with raw magical essence. Dryad locks, naturally suffused with the primeval vitality of the forest, hold the necessary qualities to thread intricate magical garments capable of shielding and augmenting a dark caster's powers.",sp=0},{t="Stalking Raynewood",b="To harvest these locks, warlocks must venture south toward Raynewood Retreat in Ashenvale. The laughing sisters—nimble, woodland dryads allied with the night elves—guard these groves fiercely against encroaching woodsmen and fel practitioners alike. Because these woodland fey would never willingly surrender their hair to practitioners of shadow and fel magic, the harvest is inevitably paid in blood beneath the canopy of ancient trees.",sp=0},{t="The Weaver's Prerogative",b="Once gathered, the locks are carried south across the border to the dusty settlement of the Crossroads in the Barrens. There, the troll tailor Kil'hala receives the tribute without remorse. While acknowledging the loss of the woodland creatures with a touch of irony, Kil'hala wastes no time putting the enchanted strands to practical use, recognizing that power in the Horde often requires unyielding resolve.",sp=0}},faq={{q="Who assigns the quest to hunt the Laughing Sisters?",a="Deino, a troll warlock trainer stationed in the dark recesses of the Cleft of Shadows in Orgrimmar, sends warlocks on this errand as reward and preparation for crafting their class robes.",al={"who gives laughing sisters quest","laughing sisters quest giver","deino quest"}},{q="What are the laughing sisters?",a="Laughing sisters are dryads, daughters of the demigod Cenarius. Possessing the upper body of night elf women and the lower body of fawns, they protect the woodlands and sacred clearings of Ashenvale.",al={"what is a laughing sister","laughing sister dryad","are laughing sisters dryads"}},{q="Where can the laughing sisters be found?",a="They roam the forested areas near Raynewood Retreat and the Laughing Sister clearing in central Ashenvale, not far from the trade road.",al={"laughing sisters location","where are laughing sisters","where to find laughing sisters"}},{q="Why does Kil'hala need dryad hair?",a="Dryad hair is steeped in natural enchantment, making it an ideal thread for Kil'hala to weave into specialized, magically resonant robes suited for warlock arts.",al={"why dryad hair","why laughing sister hair","what is the hair for"}},{q="Where do I deliver the hair once it is collected?",a="Deliver the hair to Kil'hala, an artisan tailor located in the bustling outpost of the Crossroads within the Barrens.",al={"where is kilhala","turn in laughing sisters","crossroads tailor warlock"}},{q="What happens after Kil'hala takes the hair?",a="After receiving the hair, Kil'hala takes a brief moment to work with the material before offering the follow-up task, Nether-lace Garment, to finalize the robe.",al={"next quest after laughing sisters","after laughing sisters","nether lace garment follow up"}}},ang={["class:Warlock"]="This rite of passage teaches rising warlocks that no woodland spirit or primeval sacredness is exempt from being harvested to weave instruments of dark power.",["profession:Tailoring"]="The quest highlights the rare art of infusing living magical fibers into cloth armor, showcasing the high-level technique Kil'hala employs at the Crossroads.",["faction:Horde"]="Striking down the dryads of Ashenvale sharpens the conflict between the Horde's expansionist presence and the sacred forest guardians answering to the night elves."},kw={"ashenvale","crossroads","deino","dryad","hair","kil'hala","laughing sisters","raynewood","warlock robe"},rel={"quest:1944","quest:1946","npc:kil-hala","npc:deino","zone:ashenvale","zone:barrens","subzone:crossroads","subzone:raynewood-retreat"},m={start="Deino",["end"]="Kil'hala",level="26",faction="Horde",id=1945},src={"Laughing Sisters"}}
E["quest:2"] = {t="quest",n="Sharptalon's Claw",z="ashenvale",s="Sharptalon's Claw is a trophy quest representing the defeat of the ferocious hippogryph Sharptalon in Ashenvale. Taking the creature's severed talon back to Senani Thunderheart at Splintertree Post proves your skill and protects Horde supply lines through the ancient forest.",h="Sharptalon's Claw is a trophy quest representing the defeat of the ferocious hippogryph Sharptalon in...",sec={{t="A Scourge of the Forest Trails",b="As the Horde attempts to carve out resources in Ashenvale, the native fauna proves just as perilous as the night elven sentinels. Sharptalon, a notoriously aggressive hippogryph, haunted the canopies and paths winding toward Splintertree Post. The beast preyed upon vulnerable peons and couriers traveling between the forward logging camps and the outpost, severely hampering Horde operations in the region.",sp=0},{t="Proof of the Hunt",b="Under the guidance of the tauren huntress Senani Thunderheart, Horde stalkers are tasked with clearing out the deadlier predators lurking beneath Ashenvale's canopy. Carving the massive talon from Sharptalon serves as undeniable evidence that the sky-terror has fallen. Delivering the trophy to Splintertree Post earns honor among the outpost's defenders and brings relief to the frightened laborers who must walk the woods.",sp=0}},faq={{q="What is Sharptalon?",a="Sharptalon is a named, predatory hippogryph inhabiting Ashenvale. Known for its ferocity, it relentlessly ambushed travelers moving through the ancient woodlands.",al={"who is sharptalon","sharptalon mob","what kind of beast is sharptalon"}},{q="Why does Senani Thunderheart want the claw?",a="Senani Thunderheart coordinates the Ashenvale Hunt from Splintertree Post. The claw serves as physical proof that a major predator threatening Horde workers and supply routes has been eliminated.",al={"why turn in claw","senani thunderheart trophy","purpose of sharptalon's claw"}},{q="Where do I turn in Sharptalon's Claw?",a="You turn the claw in to Senani Thunderheart, a tauren located at Splintertree Post in eastern Ashenvale.",al={"where turn in","who takes the claw","claw hand in location"}},{q="How does killing Sharptalon help the Horde?",a="Sharptalon regularly attacked peons traveling between the remote lumber mills and Splintertree Post. Slaying the beast ensures safer transit for supplies, lumber, and messengers.",al={"why kill sharptalon lore","horde interest in sharptalon"}},{q="Is this quest part of a larger chain?",a="Yes. It is part of 'The Ashenvale Hunt', a series of beast-stalking trials offered by Senani Thunderheart that culminates in 'The Hunt Completed'.",al={"ashenvale hunt chain","quest chain sharptalon"}},{q="Who is Senani Thunderheart?",a="Senani Thunderheart is a tauren huntress stationed at Splintertree Post who observes the balance of the forest and tests the mettle of Horde hunters against Ashenvale's most dangerous creatures.",al={"senani lore","who is senani"}}},ang={["faction:Horde"]="Defeating Sharptalon secures vital trails for the Warsong lumber operations and protects vulnerable peons walking between forward outposts and Splintertree Post.",["class:Hunter"]="Besting a legendary airborne predator like Sharptalon stands as an ultimate test of tracking and marksmanship under the thick canopy of Ashenvale.",["race:Tauren"]="Following the rites of the hunt through Senani Thunderheart demonstrates the traditional tauren reverence for testing oneself against nature's fiercest beasts.",["race:Orc"]="Removing aerial terrors from the forest eases the burden on the Warsong clan's grueling wood-gathering campaign."},kw={"ashenvale","ashenvale hunt","hippogryph","peons","senani thunderheart","sharptalon","splintertree post","warsong"},rel={"quest:235","quest:247","npc:senani-thunderheart","subzone:splintertree-post","zone:ashenvale"},m={start="Sharptalon's Claw",["end"]="Senani Thunderheart",level="30",faction="Horde",id=2},src={"Sharptalon's Claw (Classic)"}}
E["quest:216"] = {t="quest",n="Between a Rock and a Thistlefur",z="ashenvale",s="Between a Rock and a Thistlefur is a Horde military task issued by Karang Amakkar at Splintertree Post in Ashenvale. To bypass the heavily defended night elf stronghold of Astranaar, the Horde aims to clear a northern passage obstructed by the hostile Thistlefur tribe. By thinning the ranks of Thistlefur Village, Horde champions help secure vital overland routes across the disputed forest.",h="Between a Rock and a Thistlefur is a Horde military task issued by Karang Amakkar at Splintertree Post in...",sec={{t="Bypassing the Sentinels",b="The main road running east-west through central Ashenvale is dominated by Astranaar, the fortified heart of night elf resistance in the forest. Moving troops, lumber shipments, and supply trains past Astranaar's watchful sentinels invites constant ambushes and catastrophic losses. For the commanders at Splintertree Post, finding an alternate route is not merely convenient—it is an operational necessity if the Horde hopes to maintain a foothold in the canopy.",sp=0},{t="The Thistlefur Obstacle",b="North of the central road lies Thistlefur Village, nestled in the rocky ridges and dens of Ashenvale. While this northern trail would allow Horde forces to move freely around Astranaar, the Thistlefur furbolgs control the territory with fierce aggression. Corrupted and territorial, the tribe attacks any outsiders who step near their dens. Karang Amakkar demands preemptive strikes against the tribe, clearing out their warriors so the Horde can establish a secure alternate passage.",sp=0}},faq={{q="Why does Karang Amakkar want the Thistlefur furbolgs killed?",a="The Thistlefur furbolgs occupy a critical northern pass connecting Horde positions without needing to march directly past the night elf settlement of Astranaar. Clearing out the furbolgs opens up a safer expansion route for Horde troops and supply lines.",al={"why kill thistlefur","thistlefur quest reason","karang amakkar motive"}},{q="Where is Thistlefur Village located?",a="Thistlefur Village is situated in northern Ashenvale, northwest of Astranaar and west of Splintertree Post. The village is nestled against the foothills, featuring hollowed dens, winding paths, and a dense furbolg population.",al={"thistlefur village location","where are thistlefur furbolgs","how to find thistlefur"}},{q="Who is Karang Amakkar?",a="Karang Amakkar is an orc officer stationed in Ashenvale serving the Horde war effort. He focuses on securing strategic movement corridors and subduing local threats that hinder Horde expansion against the Alliance.",al={"karang amakkar lore","who is karang","quest giver karang"}},{q="Why can't the Horde just use the main road?",a="The central highway of Ashenvale passes right alongside Astranaar, a heavily fortified night elf bastion. Marching supply wagons and reinforcements within bowshot of night elf sentinels leads to heavy casualties and choked logistical routes.",al={"why avoid the road","why bypass astranaar","ashenvale road danger"}},{q="Why are the Thistlefur furbolgs so hostile?",a="Like many furbolg tribes across Kalimdor following the Third War, the Thistlefur have fallen to foul demonic corruption lingering in the woods. Their minds twisted by rage and madness, they violently butcher any travelers who stray into their territory.",al={"why are furbolgs mad","thistlefur corruption","furbolg hostility"}},{q="What happens after clearing the furbolgs?",a="Thinning the Thistlefur provides temporary breathing room, but deeper threats remain among the local tribes. Karang Amakkar and other Horde scouts continue directing efforts to destabilize other hostile enclaves, including the Foulweald tribe deeper in the forest.",al={"next quest after between a rock","quest follow up","what next"}}},ang={["faction:Horde"]="Controlling the passage through northern Ashenvale is essential for linking front-line outposts and securing timber operations without losing caravans to night elf archers.",["race:Orc"]="Ashenvale's conquest requires iron discipline and clear supply lines; clearing violent beast-men out of strategic terrain is standard warfare for the warchief's vanguard.",["race:NightElf"]="The Horde's efforts to circumvent Astranaar threaten to unravel the Sentinels' defensive perimeter, endangering northern sacred sites from aggressive logging parties."},kw={"ashenvale","astranaar","between a rock and a thistlefur","furbolg","horde expansion","karang amakkar","splintertree post","thistlefur"},rel={"npc:karang-amakkar","subzone:thistlefur-village","subzone:splintertree-post","subzone:astranaar","topic:furbolg","zone:ashenvale","topic:horde","quest:6621"},m={start="Karang Amakkar",["end"]="Karang Amakkar",faction="Horde",id=216},src={"Between a Rock and a Thistlefur"}}
E["quest:23"] = {t="quest",n="Ursangous's Paw",z="ashenvale",s="This quest represents the proof of felling Ursangous, one of the most ferocious and legendary predators prowling Ashenvale. Bringing the beast's severed paw to Senani Thunderheart at Splintertree Post earns honor among the Horde's trackers and reveals a subtle connection between the great bear and the local night elves.",h="This quest represents the proof of felling Ursangous, one of the most ferocious and legendary predators...",sec={{t="A Trophy of the Great Hunt",b="As part of the Ashenvale Hunt, trackers operating out of Splintertree Post are tasked with pursuing the ancient beasts that dominate the dense forest canopy. Ursangous ranks among the fiercest of these apex predators, known for killing numerous travelers and warriors who crossed his path. Taking down such a beast is no small feat, and claiming his paw serves as undeniable physical proof that the mighty creature has finally met his match.",sp=0},{t="The Night Elf Connection",b="Upon closer examination of Ursangous's paw, a small quarter-crescent emblem is visible carved or marked into the flesh. When presented to Senani Thunderheart, she identifies this mark as a clear indicator of kaldorei influence. The night elves often train and bond with the forest's formidable beasts to defend their sacred borders, meaning Ursangous was likely more than just a wild predator—he served as an unwitting guardian or weapon of the Alliance.",sp=0}},faq={{q="What is Ursangous?",a="Ursangous is an exceptionally massive and deadly bear roaming the forests of Ashenvale. Feared by hunters and wayfarers alike, he has claimed countless lives before falling to the Horde's hunt.",al={"who is ursangous","ursangous bear","ursangous lore"}},{q="What does the crescent emblem on the paw mean?",a="According to Senani Thunderheart, the quarter-crescent emblem suggests the bear was trained by the night elves of Ashenvale, who frequently enlist indigenous beasts into their service.",al={"crescent mark on paw","paw emblem","why is there a crescent"}},{q="Who do I bring Ursangous's Paw to?",a="The paw must be delivered to Senani Thunderheart, the tauren huntress stationed at Splintertree Post in eastern Ashenvale.",al={"where turn in paw","who wants ursangous paw","senani thunderheart location"}},{q="How does this fit into the Ashenvale Hunt?",a="Ursangous is one of three great beasts targeted in the Ashenvale Hunt, alongside Shadumbra and Sharptalon. Defeating all three and presenting their trophies is required to complete the overall rite.",al={"ashenvale hunt chain","what is the hunt","hunting quest line"}},{q="Why is the Horde hunting the great beasts of Ashenvale?",a="Horde hunters, particularly the tauren and orcs at Splintertree Post, hunt these apex creatures both to test their martial prowess and to curb the deadliest threats lurking near their vulnerable supply lines and encampments.",al={"why hunt bears","splintertree hunting lore"}},{q="What happens after turning in the paw?",a="Once you have collected the trophies of Ursangous and the other designated quarry, Senani Thunderheart will acknowledge your triumph in the concluding trial, The Hunt Completed.",al={"next quest after paw","what follows ursangous"}}},ang={["race:Tauren"]="For tauren hunters, taking Ursangous's paw is a sacred matter of honoring the beast while demonstrating martial resolve and respect for the spirits of the hunt.",["faction:Horde"]="Eliminating a massive bear suspected of being trained by the night elves directly weakens kaldorei control over the perilous roads around Splintertree Post.",["class:Hunter"]="Tracking and besting one of Ashenvale's oldest and deadliest predators stands as a premier test of fieldcraft, survival, and combat skill."},kw={"ashenvale","ashenvale hunt","bear","crescent emblem","paw","senani thunderheart","splintertree post","ursangous"},rel={"npc:senani-thunderheart","quest:235","quest:247","subzone:splintertree-post","zone:ashenvale"},m={start="Ursangous' Paw",["end"]="Senani Thunderheart",level="24",faction="Horde",id=23},src={"Ursangous's Paw (quest)"}}
E["quest:24"] = {t="quest",n="Shadumbra's Head",z="ashenvale",s="This quest represents the proof of victory over Shadumbra, a notoriously ferocious nightsaber stalking the western paths of Ashenvale. Taking the beast's severed head back to Senani Thunderheart at Splintertree Post fulfills a key trial of the Ashenvale Hunt and secures travel routes toward the Zoram Strand.",h="This quest represents the proof of victory over Shadumbra, a notoriously ferocious nightsaber stalking the...",sec={{t="A Menace of the Western Road",b="Shadumbra is no ordinary predator among the towering trees of Ashenvale. The great nightsaber stalked the wilderness west of Splintertree Post, preying upon Horde scouts and couriers attempting to journey toward the Zoram Strand. Her speed, stealth, and sheer savagery made travel on foot perilous, leaving Splintertree's defenders on edge whenever patrols moved west.",sp=0},{t="Proof of the Hunt",b="As part of the Ashenvale Hunt, the tauren huntress Senani Thunderheart challenges Horde champions to track and fell the forest's apex beasts. Presenting Shadumbra's head is not merely a grim display of prowess; it serves as undeniable proof that the roads have been made safer and that the hunter has mastered one of Kalimdor's deadliest native stalkers.",sp=0}},faq={{q="Who was Shadumbra?",a="Shadumbra was an exceptionally savage nightsaber that prowled the forests west of Splintertree Post. Known for ambushing travelers making the long trek toward the coast, she was considered one of Ashenvale's most dangerous local beasts.",al={"what is shadumbra","shadumbra lore","who is the cat"}},{q="Why does Senani Thunderheart want the head?",a="Senani Thunderheart oversees the Ashenvale Hunt at Splintertree Post. Claiming the head serves both as a traditional trophy of an impressive hunt and as confirmation that the threat to westward travelers has been eliminated.",al={"why bring head","senani thunderheart trophy","ashenvale hunt proof"}},{q="Where does this fit into the Ashenvale Hunt?",a="It is one of the primary trials initiated after accepting the Ashenvale Hunt. Slaying Shadumbra, along with the other great beasts of the forest like Ursangous and Sharptalon, leads to final recognition and the quest The Hunt Completed.",al={"what is ashenvale hunt","hunt questline","next hunt quest"}},{q="Why is clearing this beast important to the Horde?",a="Splintertree Post relies on scouts and runners traveling west toward the Horde encampment at Zoram'gar Outpost on the Zoram Strand. Shadumbra's predatory nature posed a constant danger to Horde foot traffic through the untamed woods.",al={"why horde care","zoram strand road danger","splintertree post safety"}},{q="Where can Shadumbra be found?",a="Shadumbra stalks the woodlands west of Splintertree Post, prowling among the trees between the road and the ancient night elf ruins scattered through central and western Ashenvale.",al={"shadumbra location","where is shadumbra","find shadumbra"}},{q="Is Shadumbra allied with the night elves?",a="No. While nightsabers are often tamed and revered by the night elves, Shadumbra is a wild, feral terror of the forest that acts purely on raw predatory instinct, threatening any who cross her territory.",al={"is shadumbra a pet","sentinel pet","shadumbra night elf"}}},ang={["race:Tauren"]="For the tauren, hunting a beast of Shadumbra's caliber honors the Earth Mother's natural order by testing skill against an apex predator while protecting tribal brothers on the road.",["class:Hunter"]="Tracking and conquering an elusive nightsaber like Shadumbra is a quintessential trial of marksmanship, patience, and survival in dense woodland terrain.",["faction:Horde"]="Splintertree Post remains an isolated Horde stronghold; eliminating local threats like Shadumbra keeps vital supply lines open to the Zoram Strand."},kw={"ashenvale hunt","nightsaber","senani thunderheart","shadumbra","splintertree post","trophy","zoram strand"},rel={"quest:235","npc:senani-thunderheart","subzone:splintertree-post","quest:247","subzone:zoram-strand","zone:ashenvale","quest:1008"},m={start="Shadumbra's Head",["end"]="Senani Thunderheart",level="27",faction="Horde",id=24},src={"Shadumbra's Head (Classic)"}}
E["quest:247"] = {t="quest",n="The Hunt Completed",z="ashenvale",s="The Hunt Completed is the culminating moment of Senani Thunderheart's great beast trials in Ashenvale. By felling Ursangous, Shadumbra, and Sharptalon, a Horde champion proves their strength, tenacity, and primal prowess in a contested forest.",h="The Hunt Completed is the culminating moment of Senani Thunderheart's great beast trials in Ashenvale.",sec={{t="A Hunter's Proof",b="Senani Thunderheart, stationed among the Horde forces in Ashenvale, tests travelers not merely by their loyalty to the warchief, but by their understanding of wild survival. The Ashenvale Hunt targets three legendary predators stalked beneath the ancient boughs: the bear Ursangous, the cat Shadumbra, and the fierce hippogryph Sharptalon. Felling all three and securing their trophies proves a hunter's blood flows true in the challenger's veins.",sp=0},{t="Honoring the Ancestors",b="For the tauren, the hunt is a sacred act of balance and respect, even amidst an active warfront. By overcoming Ashenvale's apex terrors, a hunter honors the spirits of the land and earns the ancestral blessings of Thunderheart. The hunt concludes with a formal commendation and a token of favor, cementing the champion's reputation throughout the forest.",sp=0}},faq={{q="Who offers this quest and where are they located?",a="The quest is concluded by Senani Thunderheart, a tauren hunter stationed with the Horde within the ancient forests of Ashenvale.",al={"quest giver","where to turn in","senani thunderheart location"}},{q="What are the requirements to complete the hunt?",a="You must slay three apex predators wandering Ashenvale and deliver proof of their demise: the paw of the bear Ursangous, the head of the nightstalker Shadumbra, and the claw of the hippogryph Sharptalon.",al={"what beasts to kill","prerequisites","which animals"}},{q="Why does Senani Thunderheart want these beasts slain?",a="The hunt serves as a trial of strength and tenacity. Felling such formidable beasts proves that a traveler possesses the true heart and instinct of a predator capable of surviving Ashenvale's treacherous wilderness.",al={"why hunt them","senani motive","purpose of hunt"}},{q="What is the cultural significance of the hunt to the Horde?",a="For tauren like Senani Thunderheart, testing one's mettle against mighty beasts is an honorable tradition that appeals to the spirits and ancestors. It demonstrates mastery of the wilderness without reckless dishonor.",al={"tauren hunt lore","cultural meaning","why do tauren hunt beasts"}},{q="Is this trial recognized by the entire Horde?",a="Yes. Completing the hunt marks you as a proven hunter in the eyes of the Horde stationed in Ashenvale, earning ancestral blessings and the respect of your comrades.",al={"horde recognition","is it official","horde commendation"}},{q="Which three beasts are targeted in the Ashenvale hunt?",a="The targets are Ursangous the great bear, Shadumbra the stealthy nightsaber, and Sharptalon the deadly hippogryph.",al={"the three beasts","hunt targets","named animals"}}},ang={["class:Hunter"]="Besting three apex predators of Ashenvale is the definitive rite of tracking and marksmanship, proving your instincts equal the wild beasts themselves.",["race:Tauren"]="For the Shu'halo, hunting Ursangous, Shadumbra, and Sharptalon is a time-honored test of respect, balance, and ancestral pride.",["faction:Horde"]="Taming the beasts of Ashenvale helps secure the Horde's foothold in a dangerous, hostile woodland filled with predators and Alliance sentinels alike."},kw={"ashenvale","beasts","hunt","predator","senani","shadumbra","sharptalon","thunderheart","trophy","ursangous"},rel={"quest:235","npc:senani-thunderheart","zone:ashenvale","topic:horde"},m={start="Senani Thunderheart",level="30",faction="Horde",id=247},src={"The Hunt Completed"}}
E["quest:25"] = {t="quest",n="Stonetalon Standstill",z="ashenvale",s="Stonetalon Standstill is a Horde assignment given by Mastok Wrilehiss at Splintertree Post to secure the vital passage toward the Stonetalon Mountains. Befouled water elementals in Mystral Lake have brought supply transports to a halt, prompting the Horde to cull the hostile spirits and scout an elven gazebo overlooking nearby Alliance movements.",h="Stonetalon Standstill is a Horde assignment given by Mastok Wrilehiss at Splintertree Post to secure the...",sec={{t="A Choked Supply Route",b="Maintaining the Horde's foothold in Ashenvale requires a constant flow of lumber, supplies, and messengers moving between the forest and the peaks of the Stonetalon Mountains. The Talondeep Path serves as this critical artery, skirting past the eastern shore of Mystral Lake. When the waters violently churned to life with hostile elementals, travel stopped dead in its tracks. Transport caravans found themselves battered by enraged water spirits, prompting Mastok Wrilehiss to demand swift action before logistical lines collapse entirely.",sp=0},{t="The Corrupted Waters",b="Mystral Lake is no longer a peaceful woodland refuge. The elementals that drift through its depths have become befouled, aggressive, and unpredictable, striking indiscriminately at anyone attempting to traverse the surrounding trails. Culling these watery fiends—and breaking the reign of the greater spirit Tideress—is essential to restoring a semblance of safety. Yet the origins of their taint remain an ominous riddle amidst the wider turmoil gripping Ashenvale's sacred groves.",sp=0},{t="Eyes Across the Water",b="Beyond subduing the lake's angry spirits, the Horde recognizes a strategic opportunity in Mystral Lake's central island. An ancient night elf gazebo sits upon the islet, commanding a clear vantage point across the water toward the nearby Alliance stronghold of Silverwing Outpost. By scouting the structure, Horde scouts assess whether the ruins can serve as a forward observation post, ensuring Splintertree's commanders can keep a close eye on their Kalimdor rivals without being detected.",sp=0}},faq={{q="What is causing the standstill near Stonetalon?",a="Befouled water elementals inhabiting Mystral Lake have grown violent, attacking travelers along the adjacent Talondeep Path. This aggression has halted supply transports traveling between Ashenvale and the Stonetalon Mountains.",al={"why are transports stopped","talondeep path blocked","what stopped the supply route"}},{q="Who orders the elementals cleared?",a="Mastok Wrilehiss, an orc stationed at Splintertree Post in central Ashenvale, orders the mission to restore the Horde's trade routes and probe the Alliance position.",al={"who gives stonetalon standstill","mastok wrilehiss quest","who is mastok"}},{q="Why scout the gazebo in the middle of Mystral Lake?",a="The gazebo provides an elevated vantage point over the lake and directly faces the nearby Alliance encampment. Mastok hopes to evaluate it as a covert observation post to monitor enemy movements.",al={"why scout gazebo","mystral lake gazebo purpose","gazebo observation post"}},{q="What is the Talondeep Path?",a="The Talondeep Path is the primary mountain trail connecting the southwestern reaches of Ashenvale to the Stonetalon Mountains, running right past the eastern shoreline of Mystral Lake.",al={"talondeep path location","path to stonetalon","stonetalon road"}},{q="Why are the water elementals in Mystral Lake befouled?",a="Dark energies and widespread turmoil in Ashenvale have disrupted the natural balance, driving the spirits of Mystral Lake mad and turning their normally tranquil waters hostile to outsiders.",al={"why are elementals corrupted","mystral lake water corrupted","befouled elementals origin"}},{q="Which Alliance outpost is being watched from the gazebo?",a="The gazebo overlooks Silverwing Outpost, the regional base of the Silverwing Sentinels who defend Ashenvale against the Horde's lumber-harvesting operations.",al={"what alliance base near mystral lake","alliance outpost ashenvale","silverwing outpost view"}}},ang={["faction:Horde"]="Splintertree Post cannot survive without open logistical corridors; securing the Talondeep Path is vital to maintaining communication and trade with Stonetalon.",["class:Shaman"]="The twisted state of Mystral Lake's water elementals reveals deep elemental disharmony taking root within the ancient forests of Ashenvale.",["race:Orc"]="Warriors of the Horde rely on the timber and trails of Ashenvale to fuel their settlements, making the disruption of mountain supply lines unacceptable."},kw={"befouled water elemental","gazebo","mastok wrilehiss","mystral lake","splintertree post","stonetalon standstill","talondeep path","tideress"},rel={"subzone:mystral-lake","subzone:talondeep-path","subzone:splintertree-post","npc:mastok-wrilehiss","zone:ashenvale","topic:alliance","zone:barrens"},m={start="Mastok Wrilehiss",level="25",faction="horde",id=25},src={"Stonetalon Standstill"}}
E["quest:4581"] = {t="quest",n="Kayneth Stillwind",z="ashenvale",s="This quest sends an Alliance courier from Astranaar eastward to the ancient outpost of Forest Song. Carrying a scouting missive from Sentinel Shindrell Swiftfire, travelers seek out the druid Kayneth Stillwind to help him monitor the spread of corruption across the ancient woods.",h="This quest sends an Alliance courier from Astranaar eastward to the ancient outpost of Forest Song.",sec={{t="A Dispatch to the East",b="In the town of Astranaar, Sentinel Shindrell Swiftfire stands watch over the western half of the forest. Word reaches her from the druid Kayneth Stillwind, stationed far out in Forest Song near the eastern reaches of Ashenvale. Deeply concerned by shifting wildlife behaviors and dark omens stirring along the coasts and woodlands, Kayneth requested a formal appraisal of the region's security. Swiftfire drafts her observations into a sealed note, trusting an able-bodied traveler to convey the dispatch safely across the treacherous central forest.",sp=0},{t="Watchers at Forest Song",b="Reaching Forest Song requires enduring the wilderness of Nightsong Woods, an area threatened by encroaching satyrs, hostile wildlife, and Horde excursions from the south. At the shrine of Forest Song, Kayneth Stillwind studies the delicate balance of Ashenvale's natural spirits. Reading Swiftfire's reconnaissance confirms his grim suspicions: the tainted influence creeping through the forest is neither isolated nor fleeting, and the druids will require further aid to confront the wickedness taking root.",sp=0}},faq={{q="Where is Kayneth Stillwind located?",a="Kayneth Stillwind can be found at Forest Song, a tranquil night elven sanctuary situated in the Nightsong Woods on the far eastern side of Ashenvale, north of the main road.",al={"where is kayneth","kayneth stillwind location","find kayneth stillwind"}},{q="Who gives this quest?",a="The quest is offered by Sentinel Shindrell Swiftfire, who is stationed at the night elf settlement of Astranaar in western Ashenvale.",al={"quest giver","who starts kayneth stillwind","where do i start"}},{q="What is in Shindrell's Note?",a="The note contains a detailed security dispatch detailing occurrences along Ashenvale's western coast and around the Astranaar woodlands, written to help Kayneth Stillwind investigate unnatural corruption in the forest.",al={"shindrell's note contents","what did shindrell write","shindrell note"}},{q="Why is Kayneth Stillwind investigating the forest?",a="As a druid, Kayneth strives to uphold the natural balance. He fears a dark, pervasive wickedness is spreading through Ashenvale and needs field reports from the Sentinels to track where it is taking hold.",al={"why does kayneth care","kayneth stillwind motive","druid corruption"}},{q="Is Forest Song safe for Alliance travelers?",a="Forest Song itself is a peaceful Alliance refuge with friendly sentinels and druids. However, the surrounding Nightsong Woods are filled with hostile beasts and corrupted satyrs, making the road to reach it hazardous.",al={"is forest song safe","alliance town forest song","forest song guards"}},{q="What happens after delivering the note?",a="After reviewing Shindrell's report, Kayneth Stillwind looks into the specific nature of the forest's corruption and enlists travelers to take direct action against the blighted forces endangering the region.",al={"what comes next","follow up quest","kayneth continuation"}}},ang={["class:Druid"]="For druids, assisting Kayneth Stillwind is a fundamental calling, directly supporting the Cenarion Circle's ongoing struggle to heal Ashenvale from spreading demonic and elemental blights.",["race:NightElf"]="Sentinels and kaldorei wayfarers share a duty to keep lines of communication open between key bastions like Astranaar and distant holdings like Forest Song.",["faction:Alliance"]="Traversing from central Ashenvale to eastern Nightsong Woods is essential for establishing stable communication and defense against both wilderness threats and Horde encroachment."},kw={"ashenvale","astranaar","corruption","druid","forest song","kayneth stillwind","nightsong woods","shindrell swiftfire"},rel={"npc:shindrell-swiftfire","subzone:forest-song","subzone:astranaar","subzone:nightsong-woods","zone:ashenvale","topic:druid"},m={start="Shindrell Swiftfire",["end"]="Kayneth Stillwind",level="29",faction="Alliance",id=4581},src={"Kayneth Stillwind (quest)"}}
E["quest:6382"] = {t="quest",n="The Ashenvale Hunt",z="ashenvale",s="The Ashenvale Hunt is a directive guiding proven Horde adventurers out of the arid Barrens and northward into the dense forests of Ashenvale. Entrusted by Jorn Skyseer at Camp Taurajo, travelers are sent to Splintertree Post to assist Senani Thunderheart and test their tracking skills against a wild, contested land.",h="The Ashenvale Hunt is a directive guiding proven Horde adventurers out of the arid Barrens and northward into...",sec={{t="Into the Ancient Canopy",b="After proving their hunting prowess in the sun-bleached plains of the Barrens, Horde hunters and warriors are directed toward an entirely different proving ground. Jorn Skyseer recognizes when a traveler has outgrown the local game and points them north to Ashenvale. For the young Horde, these ancient woodlands represent both a bounty of resources and a profound political and spiritual frontier that they must learn to understand and claim.",sp=0},{t="Splintertree Post",b="Following the winding road north past the Mor'shan Rampart brings travelers to Splintertree Post, a fortified Horde encampment nestled deep within the tree line. There, the tauren huntress Senani Thunderheart welcomes seasoned arrivals looking for greater tests of survival. To thrive in Ashenvale, the Horde relies on skilled trackers who can navigate not only aggressive native predators, but also the hostile watchful eyes of the forest's defenders.",sp=0}},faq={{q="Who sends me on the Ashenvale Hunt?",a="Jorn Skyseer, a tauren hunter stationed at Camp Taurajo in the southern Barrens, offers this task once you have demonstrated your skill at local beast hunting.",al={"who gives the ashenvale hunt","quest giver ashenvale hunt","jorn skyseer quest"}},{q="Where is Splintertree Post located?",a="Splintertree Post lies in east-central Ashenvale. If you follow the main road north from the Barrens past the Mor'shan Rampart and continue up through the woods, the fortified outpost sits along the northern side of the road.",al={"splintertree post location","where is senani thunderheart","find splintertree post"}},{q="Who is Senani Thunderheart?",a="Senani Thunderheart is a tauren huntress based at Splintertree Post. She coordinates hunting efforts across Ashenvale, teaching incoming Horde adventurers how to pursue the fiercest predators and spirits of the ancient forest.",al={"senani thunderheart","who is senani","huntress senani"}},{q="What other Horde outposts are nearby in Ashenvale?",a="Beyond Splintertree Post, the Horde maintains the Warsong Lumber Camp to the south and an outpost on the far western coast at the Zoram Strand, along with small camps like Silverwind Refuge nearby.",al={"horde bases ashenvale","other camps ashenvale"}},{q="Why is the Horde interested in hunting in Ashenvale?",a="The untamed wilderness provides critical meat, pelts, and resources that the arid lands of Durotar and the Barrens lack. Facing the forest's dangerous beasts is also considered a vital test of will and spiritual strength for Horde warriors and hunters.",al={"why hunt ashenvale","horde ashenvale motivation"}},{q="What challenges follow this journey?",a="Senani Thunderheart enlists seasoned hunters in tracking down notable woodland threats, sending them out into the canopy to hunt apex predators such as the great bear Ursangous, the cat Shadumbra, and the hippogryph Sharptalon.",al={"next quest after ashenvale hunt","what does senani give you"}}},ang={["class:Hunter"]="Moving from the plains of Kalimdor into Ashenvale represents a massive shift in terrain, offering exotic beasts to track, study, and tame under the dense canopy.",["race:Tauren"]="Both Jorn Skyseer and Senani Thunderheart guide this journey, viewing the hunt not merely as slaughter, but as a spiritual balance and a way to honor the wilderness.",["faction:Horde"]="Ashenvale is a crucial strategic frontier; establishing a foothold here provides vital timber and food supplies to fuel the settlements across Durotar and the Barrens."},kw={"ashenvale","ashenvale hunt","barrens","camp taurajo","jorn skyseer","senani thunderheart","splintertree post"},rel={"npc:senani-thunderheart","subzone:splintertree-post","zone:ashenvale","zone:barrens","subzone:zoram-strand","topic:horde"},m={start="Jorn Skyseer",["end"]="Senani Thunderheart",level="20",faction="Horde",id=6382},src={"The Ashenvale Hunt (The Barrens)"}}
E["quest:6383"] = {t="quest",n="The Ashenvale Hunt",z="ashenvale",s="The Ashenvale Hunt is a traditional rite overseen by Senani Thunderheart at Silverwind Refuge and Splintertree Post. Horde hunters are challenged to track and overcome three legendary woodland predators prowling the ancient forest: the bear Ursangous, the nightsaber Shadumbra, and the fierce hippogryph Sharptalon. It is conceived not merely as a test of arms, but as a journey to learn cunning, respect, and self-knowledge.",h="The Ashenvale Hunt is a traditional rite overseen by Senani Thunderheart at Silverwind Refuge and...",sec={{t="A Tauren Tradition in an Ancient Forest",b="As the Horde establishes footholds deep within Ashenvale, the spiritual teachings of the Earth Mother find expression through Senani Thunderheart. Unlike the Orcs' aggressive lumber gathering, Senani's hunt treats the shadowed woodlands as a sacred testing ground. By matching wits with the forest's apex predators, a hunter is expected to commune with the untamed wilderness and develop the quiet humility that survival in Ashenvale demands.",sp=0},{t="The Three Great Beasts",b="The hunt centers on three solitary legends wandering the boughs. Near the Talondeep Path roams Ursangous, an immense elder bear whose strength tests physical resilience. Further west, prowling the borders near Raynewood Retreat and the elusive Laughing Sisters, stalks Shadumbra, a stealthy nightsaber revered for her cunning. Finally, south of Splintertree Post wheels Sharptalon, a vicious hippogryph whose mastery of the forest canopy completes the trial.",sp=0}},faq={{q="Who starts the Ashenvale Hunt?",a="The hunt is directed by Senani Thunderheart, a tauren hunter stationed in Ashenvale. She issues the challenge to Horde travelers seeking to prove their survival skills against the wilderness.",al={"quest giver ashenvale hunt","who gives the hunt","senani thunderheart quest"}},{q="What beasts do I need to track down?",a="You must track and slay three legendary predators: Ursangous the great bear, Shadumbra the nightsaber cat, and Sharptalon the fierce hippogryph.",al={"what animals to kill","three beasts","ashenvale hunt targets"}},{q="Where can Ursangous be found?",a="Ursangous roams a small territory slightly west of the Talondeep Path, pacing amongst other wild bears of the woodland.",al={"ursangous location","where is the bear","find ursangous"}},{q="Where is Shadumbra prowling?",a="Shadumbra prowls the region south of Raynewood Retreat, hunting near the road where the dryads known as Laughing Sisters dwell.",al={"shadumbra location","where is shadumbra","nightsaber location"}},{q="Where can Sharptalon be tracked?",a="Sharptalon patrols a wide expanse of territory south of Splintertree Post, sweeping through the trees and clearing.",al={"sharptalon location","where is sharptalon","hippogryph location"}},{q="Why does Senani Thunderheart send hunters after these beasts?",a="Senani intends the hunt as an honorable trial rather than wanton slaughter. By testing their mettle against the forest's deadliest natural residents, hunters are meant to understand the wilderness and gain insight into their own inner strength.",al={"why do the hunt","purpose of the hunt","hunt lore"}}},ang={["race:Tauren"]="For tauren hunters, stalking Ursangous, Shadumbra, and Sharptalon reflects traditional reverence for the Earth Mother's creation, balancing respect for nature's ferocity with the honor of the stalk.",["class:Hunter"]="The hunt serves as a classic rite of passage, forcing a tracker to scour vast stretches of forest, read terrain, and tackle beasts capable of easily overcoming an unwary scout.",["faction:Horde"]="Contrasting with the Warsong's destructive clear-cutting of the forest, the hunt offers the Horde a path of martial honor and spiritual integration within contested Ashenvale."},kw={"ashenvale hunt","raynewood retreat","senani thunderheart","shadumbra","sharptalon","splintertree post","talondeep path","ursangous"},rel={"npc:senani-thunderheart","quest:24","quest:2","zone:ashenvale","subzone:splintertree-post","subzone:raynewood-retreat","subzone:talondeep-path","quest:1945"},m={start="Senani Thunderheart",level="20",faction="Horde",id=6383},src={"The Ashenvale Hunt (Ashenvale)"}}
E["quest:6441"] = {t="quest",n="Satyr Horns",z="ashenvale",s="Satyr Horns is a mercenary contract offered by the traveling goblin Pixel at Splintertree Post in Ashenvale. Recognizing a lucrative trade opportunity back in the port town of Ratchet, Pixel hires capable Horde adventurers to cull local satyr enclaves and harvest their prized horns.",h="Satyr Horns is a mercenary contract offered by the traveling goblin Pixel at Splintertree Post in Ashenvale.",sec={{t="A Lucrative Opportunity",b="While resting at the Horde forward encampment of Splintertree Post, an opportunistic goblin traveler named Pixel noticed an opening in the frontier market. Horns taken from the demonic satyrs of Ashenvale are in high demand across the Barrens in Ratchet. Unwilling to risk life and limb facing the corrupted creatures directly, Pixel enlists passing adventurers to gather sixteen intact horns before the return journey south.",sp=0},{t="Haunts of the Corrupted",b="The satyrs of Ashenvale dwell in scattered, fel-tainted ruins across the ancient forest, remnants of their betrayal during the ancient sundering. To fill Pixel's order, hunters are directed toward known satyr strongholds, including Night Run, the fortified camp of Satyrnaar, and the shadowed groves of Xavian. Harvesting from any of these enclaves provides the valuable demonic trophies sought on the merchant wharves of Ratchet.",sp=0}},faq={{q="Who is Pixel?",a="Pixel is an entrepreneurial goblin traveler staying temporarily at Splintertree Post in Ashenvale before traveling back south toward the neutral port of Ratchet.",al={"who is quest giver","pixel lore","goblin at splintertree"}},{q="Why does Ratchet want satyr horns?",a="Pixel notes that satyr horns fetch a high price in Ratchet, where merchants, alchemists, and exotic collectors pay well for raw demonic reagents and curio materials brought in from the northern woods.",al={"why satyr horns","what are horns used for","ratchet satyr horns"}},{q="Where can satyr horns be found in Ashenvale?",a="Satyrs inhabit several tainted areas in Ashenvale. Notable enclaves include Night Run east of Splintertree Post, Satyrnaar along the central road, and Xavian to the far northwest.",al={"satyr locations","where to find satyrs","night run xavian satyrnaar"}},{q="What are satyrs?",a="Satyrs are ancient night elves who succumbed to the demonic corruption of the Burning Legion thousands of years ago. Transformed into cloven-hoofed, horned beasts, they serve dark powers and actively corrupt the forest around them.",al={"what is a satyr","satyr lore","are satyrs demons"}},{q="Why is this contract handled at Splintertree Post?",a="Splintertree Post serves as the primary Horde fortress in central Ashenvale. Pixel uses it as a safe rest stop between trade routes, employing nearby Horde warriors who are already locked in conflict with the forest's dangers.",al={"splintertree satyr quest","why horde only"}},{q="Does Pixel have any allegiance to the Horde?",a="No. Pixel is an independent goblin merchant looking to turn a profit. Like many goblins based around Ratchet, Pixel works with whoever can provide valuable trade goods without caring about faction politics.",al={"is pixel horde","pixel faction"}}},ang={["faction:Horde"]="Clearing out the satyrs in central Ashenvale weakens dangerous demonic enclaves that threaten Splintertree Post's fragile supply lines.",["class:Warlock"]="Satyrs are infused with potent fel magic, making their physical remnants valuable curiosities for those who study demonic power.",["class:Hunter"]="Stalking demonic humanoids across corrupted woodland ruins like Satyrnaar and Night Run puts wilderness tracking skills to a dangerous test."},kw={"ashenvale","night run","pixel","ratchet","satyr horns","satyrnaar","splintertree post","xavian"},rel={"npc:pixel","subzone:splintertree-post","topic:satyr","zone:ashenvale","subzone:satyrnaar","subzone:night-run","subzone:xavian","subzone:ratchet"},m={start="Pixel",faction="horde",id=6441},src={"Satyr Horns (quest)"}}
E["quest:6442"] = {t="quest",n="Naga at the Zoram Strand",z="ashenvale",s="Naga at the Zoram Strand is a Horde quest tasking adventurers with culling the aggressive serpentine invaders along northwestern Ashenvale's coastline. Stationed at Zoram'gar Outpost, the orc warrior Marukai seeks to secure the contested coast by driving the Wrathtail naga away from the sunken ruins of ancient Zoram.",h="Naga at the Zoram Strand is a Horde quest tasking adventurers with culling the aggressive serpentine invaders...",sec={{t="A Precarious Foothold",b="The Horde's presence on the Zoram Strand is tenuous. Surrounded by hostile night elf territory and bitter woodland skirmishes in Ashenvale, the outpost provides a vital coastal connection. However, the unexpected emergence of aggressive naga crawling ashore threatens to cut the Horde off from the sea and overrun the small defensive garrison before their position can be fully fortified.",sp=0},{t="Echoes of Doomed Zoram",b="The sandy shoals of the strand conceal the shattered remnants of Zoram, an ancient elven city swallowed by the Great Sundering thousands of years ago. Marukai and the defenders of the outpost know little of why the serpentine Wrathtail tribe has crawled out of the deep trenches now, but their sudden interest in the sunken ruins bodes ill for anyone walking the surface.",sp=0},{t="The Price of Survival",b="Marukai views the situation through the lens of straightforward survival: reason does not matter when swords and tridents are drawn. By demanding twenty severed heads from the Wrathtail invaders, he aims to throw the serpentine monsters back into the depths through sheer force, securing the shoreline for the Horde.",sp=0}},faq={{q="Who gives the quest Naga at the Zoram Strand?",a="The quest is offered by Marukai, an orc warrior stationed at the Horde outpost of Zoram'gar along the Zoram Strand in northwestern Ashenvale.",al={"quest giver","who starts this","marukai location"}},{q="What is the history behind the Zoram Strand?",a="The strand marks the resting place of the ancient doomed city of Zoram. Destroyed and submerged beneath the Great Sea long ago during the Sundering, its ruins now lie partially underwater along the Ashenvale coastline.",al={"what is zoram","history of zoram","sunken city"}},{q="Why are the naga attacking the shore?",a="The Horde garrison does not know the exact motive behind the Wrathtail tribe's arrival, only that the creatures have surged out of the deep ocean to claim the sunken ruins and drive off any land-dwellers.",al={"why are naga here","wrathtail motive","naga goal"}},{q="Which enemies do I need to fight for this quest?",a="You need to slay members of the Wrathtail naga tribe that crawl across the beaches and surf of the Zoram Strand, collecting twenty of their severed heads for Marukai.",al={"which naga","wrathtail heads","target enemies"}},{q="What quest follows Naga at the Zoram Strand?",a="Completing this task allows Marukai to direct you further into the mystery and defense of the coast with the follow-up quest, Deep Despair.",al={"next quest","follow up","marukai next"}},{q="Why does the Horde care about this remote beach?",a="Ashenvale is fiercely contested between the Horde and the Night Elves. Establishing a secure maritime beachhead at the Zoram Strand gives the Horde strategic access and supply lines away from the dense inland forests.",al={"why is horde here","zoram'gar outpost purpose"}}},ang={["faction:Horde"]="Holding Zoram'gar Outpost is crucial for the Horde's expansion into Ashenvale, making the clearing of the naga a matter of military survival.",["race:Orc"]="Marukai's straightforward strategy of brutal repelling matches the pragmatic martial culture of orcs holding a frontier border."},kw={"ashenvale","marukai","naga","wrathtail","wrathtail heads","zoram strand","zoram'gar outpost"},rel={"npc:marukai","subzone:zoram-strand","topic:naga","zone:ashenvale","quest:1008"},m={start="Marukai",faction="Horde",id=6442},src={"Naga at the Zoram Strand"}}
E["quest:6462"] = {t="quest",n="Troll Charm",z="ashenvale",s="Troll Charm is a Horde quest offered by the Darkspear troll Mitsuwa at Zoram'gar Outpost in Ashenvale. After a traveling party of trolls was ambushed and slaughtered by the Thistlefur furbolgs, Mitsuwa asks adventurers to delve into their den to recover sacred talismans stolen from the dead.",h="Troll Charm is a Horde quest offered by the Darkspear troll Mitsuwa at Zoram'gar Outpost in Ashenvale.",sec={{t="An Ambushed Caravan",b="Zoram'gar Outpost serves as a remote western refuge for the Horde on Ashenvale's coast, making travel along the woodland paths fraught with danger. A party of Darkspear trolls journeying toward the post never arrived, having fallen victim to a violent ambush by the territorial Thistlefur tribe of furbolgs. While Mitsuwa accepts the deaths of her kin as an eventual reunion in the afterlife, the desecration and theft of their sacred charms is an intolerable insult.",sp=0},{t="Sacred Trinkets",b="In troll culture, charms and talismans are deeply tied to identity, spiritual protection, and connection with the Loa. Mitsuwa considers a troll without her charm to be as hollow and worthless as an orc devoid of battle scars. The Thistlefur furbolgs dragged these purloined artifacts back into Thistlefur Hold, deep within the cave systems past Thistlefur Village, stashing them in chests away from their rightful owners.",sp=0}},faq={{q="Who gives this quest and where are they located?",a="The quest is given by Mitsuwa, a Darkspear troll stationed at Zoram'gar Outpost along the Zoram Strand on the northwestern coast of Ashenvale.",al={"quest giver","where is mitsuwa","who starts troll charm"}},{q="Why are the troll charms so important to Mitsuwa?",a="To trolls, sacred charms carry deep spiritual and cultural significance. Mitsuwa compares a troll without her charm to an orc without battle scars, viewing the possession of these relics by hostile furbolgs as an outrageous desecration of her slain kin.",al={"charm importance","why troll charms matter","significance of charms"}},{q="Where are the troll charms located?",a="The charms are stored inside chests within Thistlefur Hold, a deep cavern complex located at the northern edge of Thistlefur Village, situated north of the night elf settlement of Astranaar.",al={"charm location","where are chests","find charms"}},{q="Who stole the charms?",a="The Thistlefur furbolgs ambushed and murdered Mitsuwa's kinfolk as they traveled toward Zoram'gar Outpost, looting their belongings and hauling the sacred charms into their caverns.",al={"who took charms","ambush culprits"}},{q="What happened to the trolls who originally carried the charms?",a="They were killed by the Thistlefur furbolgs along the trail. Mitsuwa mourns their loss but believes she will eventually reunite with them in the afterlife, prioritizing the retrieval of their sacred relics.",al={"caravan fate","slain trolls","mitsuwa kin"}},{q="Is this quest available to the Alliance?",a="No. The quest originates at Zoram'gar Outpost and is strictly available to Horde players helping the Darkspear tribe.",al={"alliance troll charm","can alliance do it"}}},ang={["race:Troll"]="Recovering the charms is an act of spiritual duty for Darkspear trolls, ensuring sacred ancestral items are rescued from the clutches of savage furbolgs.",["faction:Horde"]="Pushing into Thistlefur territory strikes back against woodland threats that ambush Horde supply lines and travelers moving through Ashenvale."},kw={"ashenvale","darkspear","furbolg","mitsuwa","thistlefur hold","thistlefur village","troll charm","zoram'gar outpost"},rel={"npc:mitsuwa","subzone:zoram-gar-outpost","subzone:thistlefur-hold","subzone:thistlefur-village","topic:furbolg","topic:troll","zone:ashenvale","subzone:astranaar"},m={start="Mitsuwa",faction="Horde",id=6462},src={"Troll Charm (quest)"}}
E["quest:6482"] = {t="quest",n="Freedom to Ruul",z="ashenvale",s="Deep within Thistlefur Hold in northern Ashenvale, a caged bear named Ruul awaits rescue from the corrupted Thistlefur furbolgs. Horde adventurers can assist the captive in fighting his way out of the furbolg den to safety.",h="Deep within Thistlefur Hold in northern Ashenvale, a caged bear named Ruul awaits rescue from the corrupted...",sec={{t="A Druid in Chains",b="While venturing into the corrupted woods of northern Ashenvale, the druid Ruul Snowhoof wandered too close to Thistlefur Hold while in his bear form. The corrupted furbolgs, lacking their ancestral wisdom and driven by feral paranoia, mistook the shapeshifted tauren for a common beast. Rather than treating him with reverence, they caged and starved him, sapping his magical reserves and leaving him unable to break free on his own.",sp=0},{t="Escape from the Den",b="Weakened by hunger and imprisonment, Ruul cannot shift forms or fight through the cavernous furbolg settlement unassisted. Once freed by an ally of the Horde, he relies on his rescuer to clear a path past waves of hostile Thistlefurs. Upon safely reaching the outskirts of Splintertree Post, he briefly reveals his true tauren form to offer heartfelt thanks before returning to the wilderness to sleep off his exhaustion.",sp=1}},faq={{q="Why was Ruul Snowhoof locked up by the furbolgs?",a="Ruul was exploring the forests in his bear form. The corrupted Thistlefur furbolgs failed to recognize him as a druid, mistaking him for a wild beast, and locked him in a cage where they starved him until he lacked the strength to escape.",al={"why is ruul trapped","how did ruul get captured","why caged"},sp=1},{q="Who is Yama Snowhoof?",a="Yama Snowhoof is Ruul's sister, stationed at Splintertree Post in Ashenvale. She had grown deeply worried after Ruul disappeared into the forest days earlier without returning.",al={"ruul sister","yama splintertree","who is yama"}},{q="Why couldn't Ruul just shift out of bear form to escape?",a="The prolonged captivity and deliberate starvation inflicted by the Thistlefur furbolgs left Ruul severely weakened. Without food and strength, his reserves of natural energy were completely depleted, leaving him helpless until rescued.",al={"why didnt ruul shapeshift","druid bear trap"},sp=1},{q="What happens after Ruul reaches safety?",a="Once escorted out of the hostile den to the borders of Splintertree Post, Ruul briefly shifts into his natural tauren form to express his gratitude before retreating back into bear form to find a quiet place to sleep and recover.",al={"where does ruul go","ruul ending"},sp=1},{q="Are all furbolgs in Ashenvale hostile like the Thistlefurs?",a="No. While many furbolg tribes possess a noble heritage and deep ties to nature, the Thistlefurs of northern Ashenvale have succumbed to dark, corruptive influences that have turned them aggressive and unpredictable.",al={"are furbolgs evil","thistlefur corruption"}},{q="Where does the rescue take place?",a="Ruul is imprisoned inside Thistlefur Hold, a furbolg den located in the hills northwest of Splintertree Post and north of Astranaar in Ashenvale.",al={"where is ruul","ruul snowhoof location"}}},ang={["class:Druid"]="Ruul's capture is a humbling reminder of the risks of wandering feral territories in animal guise, where corrupted locals cannot tell friend from quarry.",["race:Tauren"]="Rescuing a stranded brother of the Cenarion circle and easing the worries of his kin at Splintertree Post honors the bonds of the Earthmother and the Horde.",["faction:Horde"]="Every soul rescued from the corrupted hollows of northern Ashenvale strengthens the Horde's precarious outpost at Splintertree Post."},kw={"ashenvale","druid escort","furbolg","ruul snowhoof","splintertree post","thistlefur hold","yama snowhoof"},rel={"npc:ruul-snowhoof","subzone:splintertree-post","zone:ashenvale","topic:furbolg","topic:tauren"},m={start="Ruul Snowhoof",["end"]="Yama Snowhoof",faction="Horde",id=6482},src={"Freedom to Ruul"}}
E["quest:6503"] = {t="quest",n="Ashenvale Outrunners",z="ashenvale",s="Ashenvale Outrunners is a Horde patrol-interception mission issued by Kuray'bin in Ashenvale. Night elf scouts have fanned out from Silverwing Outpost to gather intelligence on nearby Horde encampments, prompting a preemptive strike to keep the outpost's defenses hidden. By hunting down these stealthy scouts, the Horde blinds the local Alliance forces and discourages future incursions.",h="Ashenvale Outrunners is a Horde patrol-interception mission issued by Kuray'bin in Ashenvale.",sec={{t="Eyes in the Canopies",b="The forests of Ashenvale remain a contested frontier where every path and ridge is fiercely watched. Intelligence is as deadly as an axe, and reports reaching Kuray'bin confirm that night elf scouts known as Ashenvale Outrunners have slipped out from the Alliance stronghold at Silverwing Outpost. Operating in the dense wilderness east of their base and south of local Horde holdings, these scouts stalk the woodland paths to map out fortifications and track troop movements.",sp=0},{t="Blinding the Alliance",b="To prevent an organized assault, the Horde relies on eliminating enemy reconnaissance before it can return home. By hunting down the outrunners, Horde champions deny the commanders at Silverwing Outpost vital knowledge about troop strength and outpost perimeter defenses. Stripped of their forward eyes, the night elves are left disoriented and far less willing to risk aggressive maneuvers through the contested woodlands.",sp=0}},faq={{q="Who gives the quest Ashenvale Outrunners?",a="The quest is given by Kuray'bin, a Horde scout coordinator stationed in Ashenvale who works to track and counter night elf movements across the forest.",al={"quest giver","who gives quest","kuray'bin quest"}},{q="Where are the Ashenvale Outrunners located?",a="The outrunners prowl the forests east of Silverwing Outpost and south of Kuray'bin's camp, patrolling through the underbrush to gather intelligence.",al={"outrunners location","where are outrunners","where to find outrunners"}},{q="Why are the outrunners a threat to the Horde?",a="The outrunners are advanced scouts operating out of Silverwing Outpost. If they successfully map Horde encampments and troop counts, the Alliance can coordinate precise raids against vulnerable positions.",al={"why kill outrunners","threat of outrunners","outrunner purpose"}},{q="What is Silverwing Outpost?",a="Silverwing Outpost is a prominent night elf military installation in Ashenvale, serving as a frontline base for Alliance forces defending the forest and contesting Horde expansion.",al={"silverwing outpost lore","what is silverwing outpost","silverwing alliance"}},{q="Is this quest part of a longer storyline?",a="This quest stands primarily as a standalone tactical task designed to reduce Alliance reconnaissance in the sector, rewarding fighters who aid Kuray'bin in securing the perimeter.",al={"quest chain","follow up quest","outrunner chain"}},{q="Can Alliance players complete this quest?",a="No, this quest is exclusive to the Horde. Kuray'bin operates strictly on behalf of the Horde's frontlines in Ashenvale.",al={"is this horde only","alliance version","can alliance do this"}}},ang={["faction:Horde"]="Every night elf scout cut down in Ashenvale protects local encampments and lumber operations from coordinated Alliance counter-offensives.",["class:Hunter"]="Tracking down concealed outrunners in deep woodland terrain relies on keen instincts, heightened tracking senses, and sharp marksmanship.",["class:Rogue"]="Neutralizing enemy outrunners turns the tables on night elf stealth, ensuring Horde infiltrators hold dominion over the shadows of the forest."},kw={"alliance","ashenvale","ashenvale outrunners","horde","kuray'bin","night elf scouts","silverwing outpost"},rel={"npc:kuray-bin","subzone:silverwing-outpost","zone:ashenvale","topic:alliance"},m={start="Kuray'bin",level="24",faction="Horde",id=6503},src={"Ashenvale Outrunners (Classic)"}}
E["quest:6504"] = {t="quest",n="The Lost Pages",z="ashenvale",s="While transporting a newly acquired goblin shredder from Ratchet to the Warsong Lumber Camp, the orc Gurda Ragescar lost the machine's operating manual to a sudden gust of wind. Stranded near Splintertree Post, she cannot run the complex engineering marvel without recovering the scattered pages.",h="While transporting a newly acquired goblin shredder from Ratchet to the Warsong Lumber Camp, the orc Gurda...",sec={{t="A Gust of Bad Luck",b="The Warsong Clan relies heavily on steam-powered shredders bought from the goblins of the Venture Company and the port of Ratchet to clear lumber across Ashenvale. Operating these delicate, noisy contraptions is far from intuitive for an ordinary orc warrior. When Gurda Ragescar made the journey north with a freshly purchased shredder, a sudden blast of wind tore the instruction booklet from her hands, scattering twelve fragile parchment leaves across the forest floor.",sp=0},{t="Pages in the Wilderness",b="Because the wild winds swept the manual over the canopy, individual pages have drifted into the hands of wandering creatures, cultists, and forest denizens across the entire region. Without all three gathered chapters, the complex machine remains an inert block of steel and whirring sawblades, leaving Gurda stranded along the road to Splintertree Post unable to report for logging duty.",sp=0}},faq={{q="Who is Gurda Ragescar?",a="Gurda Ragescar is a Horde laborer tasked with ferrying a goblin shredder from the merchant port of Ratchet up into Ashenvale to join the logging efforts of the Warsong Lumber Camp.",al={"gurda","ragescar","who is the quest giver"}},{q="Why does Gurda need an instruction manual to drive the shredder?",a="Goblin engineering is famously finicky and counterintuitive, reliant on volatile boilers, intricate pressure valves, and complex levers. Even an eager orc cannot safely operate the contraption without reading the manufacturer's manual.",al={"why manual","why cant she drive it","shredder operating manual"}},{q="How did the manual pages end up scattered all over Ashenvale?",a="While traveling north along the forest road, a violent gust of wind whipped the book from Gurda's grip. The loose pages fluttered across the woods, leaving her holding only the empty front cover.",al={"how did pages get lost","wind blew pages"}},{q="Where does the shredder ultimately belong?",a="The machine is destined for the Warsong Lumber Camp, where the Horde maintains an aggressive clear-cutting campaign to supply timber for Orgrimmar and Durotar.",al={"where is the shredder going","warsong shredder destination"}},{q="Where can the missing pages be found?",a="The winds swept the pages far and wide, and they have been picked up by various humanoids and hostile forest denizens roaming across Ashenvale.",al={"where to find pages","who drops the pages"}},{q="Why does the Horde purchase machinery from Ratchet?",a="Ratchet is the nearest neutral port with active trade networks connected to goblin cartels. The Horde regularly purchases specialized engineering, demolition tools, and steam-driven vehicles to augment its military logistics.",al={"horde goblin machinery","ratchet trade horde"}}},ang={["profession:Engineering"]="Tinkers will understand Gurda's dilemma all too well: piloting a goblin-built shredder without the manufacturer's guidelines is an easy recipe for catastrophic boiler failure.",["faction:Horde"]="Every shredder that reaches the Warsong Lumber Camp speeds up the gathering of precious timber needed to construct walls, huts, and warships in Durotar.",["race:Orc"]="Manual labor and warrior traditions leave little patience for detailed goblin paperwork, making Gurda's exasperation with lost technical sheets deeply relatable."},kw={"ashenvale","gurda ragescar","ratchet","shredder","shredder operating manual","splintertree post","the lost pages","warsong lumber camp"},rel={"npc:gurda-ragescar","subzone:splintertree-post","subzone:warsong-lumber-camp","subzone:ratchet","zone:ashenvale"},m={start="Gurda Ragescar",level="30",faction="Horde",id=6504},src={"The Lost Pages"}}
E["quest:6544"] = {t="quest",n="Torek's Assault",z="ashenvale",s="Torek's Assault is a direct Horde raid launched from the wilds of Ashenvale against the nearby night elf garrison at Silverwing Outpost. Led by the orc raider Torek under orders from Splintertree Post, the strike aims to crush local Sentinel resistance and slay their commander, Duriel Moonfire. It marks one of the most brazen, bloody skirmishes in the ongoing war for Ashenvale's borders.",h="Torek's Assault is a direct Horde raid launched from the wilds of Ashenvale against the nearby night elf...",sec={{t="A Strike from the Shadows",b="Ashenvale is locked in an escalating border war between the Horde lumber camps and the native night elves. Seeking to break the Alliance's defensive perimeter, Torek gathers a pack of Splintertree raiders just outside Silverwing Outpost. Rather than waiting for a counter-attack, Torek coordinates a head-on charge to shatter the outpost's defenses before the night elves can mount a reinforced campaign against Splintertree Post.",sp=0},{t="Taking Silverwing",b="Silverwing Outpost stands as a fortified woodland bastion garrisoned by vigilant Silverwing Sentinels and fierce elven warriors. Torek's primary target is their leader, Duriel Moonfire. Bringing down Duriel decapitates the local night elf military hierarchy in the area, allowing the raiders to report a bloody victory back to commander Ertog Ragetusk near the Falfarren River.",sp=0}},faq={{q="Who is Torek?",a="Torek is an aggressive orc raider operating out of Splintertree Post in Ashenvale. Fierce and hungry for battle, he commands a detachment of raiders tasked with taking the fight directly to the night elf forces entrenched in the forest.",al={"torek npc","who is torek","torek orc"}},{q="What is Silverwing Outpost?",a="Silverwing Outpost is a fortified night elf settlement in Ashenvale. Guarded by elite Sentinels and warriors, it serves as a military bulwark to watch over Horde troop movements along the woodland trails.",al={"silverwing outpost","what is silverwing"}},{q="Who is Duriel Moonfire?",a="Duriel Moonfire is the night elf commander defending Silverwing Outpost. As the head of the garrison, she directs the local Sentinels against Horde incursions until Torek's raiding party breaches the camp to strike her down.",al={"duriel moonfire","duriel"},sp=1},{q="Who is Ertog Ragetusk?",a="Ertog Ragetusk is a Horde officer stationed at Splintertree Post. He serves as Torek's superior officer, overseeing military operations in the region and receiving reports of victories against the Alliance.",al={"ertog ragetusk","ertog"}},{q="Why does the Horde attack Silverwing Outpost?",a="The Horde and the night elves are locked in active territorial warfare across Ashenvale. Striking Silverwing Outpost relieves pressure on Horde supply lines and directly weakens the Sentinel defense network guarding the deeper forest.",al={"why attack silverwing","ashenvale conflict silverwing"}},{q="Where does this attack take place?",a="The assault begins just outside Silverwing Outpost, located west of the Falfarren River in Ashenvale, culminating inside the night elf encampment itself.",al={"torek assault location","where is torek"}}},ang={["faction:Horde"]="For the Horde, pushing past Silverwing Outpost is a vital test of strength that weakens the night elf blockade encircling Splintertree Post.",["faction:Alliance"]="The fall of Duriel Moonfire exposes Silverwing Outpost and threatens the night elves' ancestral woodland holdings.",["class:Warrior"]="A brutal, frontal melee that tests raw physical endurance against seasoned Sentinel archers and blademasters.",["race:NightElf"]="The raid strikes at the heart of the Sentinels' frontline command, spilling elven blood beneath the boughs of Ashenvale."},kw={"ashenvale","duriel moonfire","ertog ragetusk","raiders","sentinels","silverwing outpost","splintertree post","torek"},rel={"subzone:silverwing-outpost","subzone:splintertree-post","zone:ashenvale","topic:sentinels","topic:night-elf","subzone:falfarren-river"},m={start="Torek",["end"]="Ertog Ragetusk",faction="horde",id=6544},src={"Torek's Assault"}}
E["quest:6545"] = {t="quest",n="Warsong Runner Update",z="ashenvale",s="Warsong Runner Update is a Horde communication task connecting the forward defenses of Ashenvale with commanders along the border. Entrusted to couriers and fresh recruits, the missive details the rising military pressure facing Warsong scouts, notably the aggression of encroaching naga.",h="Warsong Runner Update is a Horde communication task connecting the forward defenses of Ashenvale with...",sec={{t="Frontline Dispatches",b="The Warsong Clan maintains a string of scouts and runners throughout Ashenvale to monitor surrounding hostilities and keep lines of supply intact. Between territorial skirmishes with night elf sentinels and the harsh environment, swift intelligence is vital. Couriers carrying frontline dispatches are essential in ensuring remote garrisons remain coordinated with commanders like Kadrak posted on the Mor'shan Rampart.",sp=0},{t="The Naga Threat",b="While the Horde expects fierce opposition from the night elves among the trees, outpost sentries have reported increasingly bold assaults from the naga. These serpentine invaders strike from waterways and ancient ruins, testing the outpost's barricades and forcing defenders to divert attention away from forestry and border patrols. The update carried back to the Mor'shan Rampart sounds the alarm regarding these coordinated amphibious attacks.",sp=0}},faq={{q="Who is the report being sent to?",a="The report is carried directly back to Kadrak, an overseer stationed at the Mor'shan Rampart along the border between Ashenvale and the Northern Barrens.",al={"who receives update","kadrak report","where does report go"}},{q="What threats are mentioned in the update?",a="The scout reports that the local outpost has weathered repeated assaults, highlighting an escalating threat from hostile naga operating in the nearby waters.",al={"what is in report","runner update content","naga attacks"}},{q="Why does the Horde rely on foot runners here?",a="Dense foliage, active night elf marksmen, and isolated outposts make aerial transit difficult or exposed across parts of Ashenvale. Ground messengers allow swift, discreet communication along guarded paths.",al={"why runners","warsong runners lore","why not wyverns"}},{q="Who are the Warsong Outrunners?",a="They are scouts, couriers, and vanguard fighters of the Warsong Clan tasked with securing supply lines and watching enemy movements around the forest's contested borders.",al={"warsong clan ashenvale","who are warsong runners"}},{q="Where are the naga attacking in Ashenvale?",a="Naga have established strongholds in the ruins along the shores and lakes of Ashenvale, often ambushing travelers and raiding nearby camps.",al={"where are naga","ashenvale naga"}},{q="What is the outpost's purpose in this area?",a="The post serves as an early warning station and defensive anchor, ensuring hostile forces cannot sever communications between deep forest lumber operations and the Barrens.",al={"why is the outpost here","horde camp purpose"}}},ang={["faction:Horde"]="Every soldier counts along the forest frontier, where maintaining communication lines between the Barrens and forward outposts is critical to survival.",["race:Orc"]="The Warsong Clan depends on the grit and vigilance of its runners to hold ground claimed under Warchief Thrall's command."},kw={"ashenvale","kadrak","mor'shan","naga","rampart","report","runner","scout","warsong"},rel={"npc:kadrak","topic:naga","zone:ashenvale"},m={start="Warsong Runner",level="19",faction="Horde",id=6545},src={"Warsong Runner Update (quest)"}}
E["quest:6546"] = {t="quest",n="Warsong Outrider Update",z="ashenvale",s="Warsong Outrider Update is a Horde delivery quest originating along the perilous paths of eastern Ashenvale. A lone Warsong scout entrusts an adventurer with vital intelligence detailing threats from the nearby Alliance, entrenched satyr, and encroaching naga in neighboring Azshara.",h="Warsong Outrider Update is a Horde delivery quest originating along the perilous paths of eastern Ashenvale.",sec={{t="Eyes Along the Forest Edge",b="Eastern Ashenvale is a contested border zone where Horde supply lines face constant harassment. The Warsong Outriders maintain a vigilant screen across the woods, scouting enemy movements long before raiding parties can strike outposts like the Mor'shan Rampart or Splintertree Post. Encountering an outrider on patrol means stepping directly into an active theater of reconnaissance, where information can mean the difference between holding a fortification or losing it to ambush.",sp=0},{t="Threats on Every Horizon",b="The report compiled by the outrider paints a grim tactical picture for the Horde in Kalimdor's central forests. Beyond the ever-present skirmishes with the night elves and the broader Alliance, eastern Ashenvale crawls with cunning, demonic satyr. Compounding the danger, scouts have uncovered a massive naga presence spreading across the ruined coastal lands of neighboring Azshara, warning commanders that the Horde is hemmed in by hostile powers from almost every direction.",sp=0}},faq={{q="What is the Warsong Report?",a="It is an intelligence dispatch written by a Warsong Outrider summarizing enemy troop dispositions and regional dangers. It highlights threats from nearby Alliance forces, active satyr covens in eastern Ashenvale, and newly discovered naga movements across Azshara.",al={"warsong report quest item","what does the report say","scout report"}},{q="Who is Kadrak?",a="Kadrak is a Horde commander stationed at the Mor'shan Rampart, the defensive barricade guarding the northern border between the Barrens and Ashenvale. He oversees incoming scouts and coordinates forward operations into the forest.",al={"who is kadrak","where is kadrak","kadrak turn in"}},{q="Why are the naga in Azshara mentioned?",a="Azshara directly borders eastern Ashenvale. The outriders track foreign movements in adjacent territories to ensure Horde flanks are not surprised by massive incursions while they contend with the night elves.",al={"naga azshara connection","why mention azshara","azshara naga threat"}},{q="What makes eastern Ashenvale so dangerous for the Horde?",a="The region is caught between active Alliance detachments, ancient satyr ruins infused with demonic corruption, and untamed woodland beasts, leaving Horde couriers and patrols vulnerable to ambushes from all directions.",al={"why is eastern ashenvale dangerous","ashenvale threats","satyr threat"}},{q="Who are the Warsong Outriders?",a="They are the forward vanguard and reconnaissance cavalry of the Warsong clan in Ashenvale, responsible for tracking night elf movements, screening logging camps, and securing trade roads.",al={"what are outriders","warsong scouts","outriders lore"}},{q="Why can't the outrider deliver the report himself?",a="The outrider is tasked with maintaining his watch on the trail to track developing hostile movements in real time. Leaving his vantage point would blind the frontline to unexpected Alliance or satyr advances.",al={"why do i deliver report","why not deliver himself"}}},ang={["faction:Horde"]="Every dispatch carried along the Mor'shan line reinforces the Horde's fragile foothold in the lush forests of Ashenvale.",["race:Orc"]="The Warsong clan takes pride in holding the vanguard, but their scouts know bravery alone cannot stop enemies surrounding them on all sides."},kw={"ashenvale","azshara","kadrak","mor'shan rampart","naga","satyr","warsong outrider","warsong report"},rel={"npc:warsong-outrider","npc:kadrak","zone:ashenvale","zone:azshara","topic:satyr","topic:naga","topic:alliance"},m={start="Warsong Outrider",level="25",faction="Horde",id=6546},src={"Warsong Outrider Update (quest)"}}
E["quest:6547"] = {t="quest",n="Warsong Scout Update",z="ashenvale",s="Warsong Scout Update is a Horde communication task connecting the outpost commanders along the borders of Ashenvale with forward scouts watching the contested forest. Carrying strategic orders from Kadrak, couriers ensure the Warsong Clan maintains tight surveillance against ambushing night elves. It highlights the tenuous, hostile grip the Horde strives to maintain over their newly claimed territory.",h="Warsong Scout Update is a Horde communication task connecting the outpost commanders along the borders of...",sec={{t="Eyes in the Shadows",b="The borderlands of Ashenvale remain a powder keg where neither side yields an inch. Horde forces under Kadrak rely heavily on dispersed Warsong scouts stationed in high-risk outposts to track night elf movements and secure contested supply lines. Because the forest itself provides natural cover to the stealthy sentinels of the Alliance, regular reports and written updates are critical to keeping isolated scouts from being cut off and overwhelmed.",sp=0},{t="Holding the Ground",b="For the Warsong clan, every stretch of forest cleared or occupied has been paid for in blood. The scouts watch constantly for retaliatory night elf raids aiming to reclaim the woodlands. Delivering Kadrak's orders reassures the vanguard that reinforcements and coordination remain active, allowing the scouts to report back that their defensive measures are succeeding despite continuous elven resistance.",sp=0}},faq={{q="Who is Kadrak?",a="Kadrak is a Horde commander stationed along the boundary between the Barrens and Ashenvale. He coordinates scouting missions, border defense, and logistical support for Warsong operations encroaching into the ancient forest.",al={"kadrak","who is kadrak","kadrak role"}},{q="Why are the Warsong scouts so paranoid about night elves?",a="Night elves naturally blend into the shadows of their ancestral forests, executing sudden ambushes on Horde patrols. Because the Warsong Clan is actively clearing lumber and settling land the elves consider sacred, the scouts are under constant threat of lethal surprise attacks.",al={"why fear night elves","night elves in shadows","warsong scout elven danger"}},{q="Why is Ashenvale being fought over?",a="The Horde requires lumber and resources from Ashenvale to construct Orgrimmar and fuel its settlements in the arid Barrens and Durotar. The native night elves view the forest as sacred ground and aggressively fight to drive the orcish loggers and garrisons out.",al={"why fight over ashenvale","ashenvale war","horde ashenvale conflict"}},{q="What is the Warsong Clan's role here?",a="The Warsong Clan spearheads the Horde's expansion and resource harvesting in Ashenvale. Originally led into the woods by Grom Hellscream during the Third War, their presence has remained deeply entrenched, operating lumber camps and fighting ongoing skirmishes against the Sentinels.",al={"warsong clan ashenvale","warsong role"}},{q="Where does this report go after reaching the scout?",a="After the scout receives Kadrak's updated instructions, they send word back regarding their local success against elven counterattacks, ensuring Horde leadership remains fully aware of the front lines' stability.",al={"who gets report","kadrak report","scout update result"}},{q="Are the Horde's plans in Ashenvale succeeding at this point?",a="The frontline scouts consider their defensive efforts a success, managing to hold their fortified positions and fend off elven strikes, though the region remains a fiercely contested battleground with neither side securing absolute dominance.",al={"is horde winning ashenvale","warsong progress"}}},ang={["faction:Horde"]="Every runner who carries orders between Kadrak and the outer scouts helps keep the Horde's foothold in Ashenvale secure against unrelenting night elf ambushes.",["race:Orc"]="The legacy of the Warsong Clan is defined by their tenacity in Ashenvale, claiming vital timber despite the hostility of the land and its ancient defenders.",["race:NightElf"]="The presence of Warsong scouts lurking along the borders represents an ongoing desecration of the sacred forests of Elune that the Sentinels strive to purge."},kw={"ashenvale","barrens","kadrak","night elves","report","scout","sentinels","warsong"},rel={"npc:kadrak","zone:ashenvale"},m={start="Warsong Scout",level="21",faction="Horde",id=6547},src={"Warsong Scout Update (quest)"}}
E["quest:6564"] = {t="quest",n="Allegiance to the Old Gods",z="ashenvale",s="Allegiance to the Old Gods is a Horde quest initiated by recovering a waterlogged message from the naga along the Zoram Strand. Delivering the note to Je'neu Sancrea at Zoram'gar Outpost uncovers a sinister ritual plot unfolding deep within the flooded ruins of Blackfathom Deeps.",h="Allegiance to the Old Gods is a Horde quest initiated by recovering a waterlogged message from the naga along...",sec={{t="A Scribbled Declaration",b="While battling the Wrathscale naga along the coast of Ashenvale, Horde scouts discover a damp, crumpled note bearing frantic handwriting. The scribbled parchment details instructions directed toward the naga priestesses, ordering them to gather elemental water crystals. Far from random pillaging, these crystals are being collected to fuel the summonings of naga aquamancers, marshaling elemental forces for a far darker objective.",sp=0},{t="Whispers of the Deep",b="The recovered orders reveal that the naga intend to use the elemental energy within the crystals to appease and fully summon Aku'mai, a monstrous hydra favored by ancient cosmic masters. The note boldly proclaims that doing so will herald a return to the world's 'greatest era'—the prehistoric reign of the Old Gods. Upon receiving the parchment at Zoram'gar Outpost, the Darkspear mystic Je'neu Sancrea identifies the author behind this conspiracy: the naga leader Lorgus Jett.",sp=1}},faq={{q="What is the Damp Note?",a="The Damp Note is a set of recovered orders written by the naga leader Lorgus Jett. It instructs naga priestesses to collect elemental-infused crystals to bolster their aquamancers and summon the monstrous servant Aku'mai.",al={"damp note","what does the note say","note lore"}},{q="Who is Je'neu Sancrea?",a="Je'neu Sancrea is a Darkspear troll seer and scholar stationed at Zoram'gar Outpost in Ashenvale. Representing the Earthen Ring, he investigates elemental imbalances and ancient threats rising from the nearby ruins of Blackfathom Deeps.",al={"jeneu sancrea","who is jeneu","zoram outpost questgiver"}},{q="Who is Lorgus Jett?",a="Lorgus Jett is a prominent leader among the Wrathscale naga operating in and around the Zoram Strand. He oversees the harvesting of elemental crystals to empower naga rituals and reawaken dark ancient horrors.",al={"lorgus jett","who wrote the note","naga leader zoram"}},{q="What is Aku'mai?",a="Aku'mai is a colossal three-headed hydra dwelling within the submerged depths of Blackfathom Deeps. Bound closely to the primordial darkness of the Old Gods, the creature is revered by both the Twilight's Hammer cult and the Wrathscale naga.",al={"akumai","who is akumai","aku'mai lore"}},{q="Why are the naga collecting water crystals?",a="The water elemental spirits trapped inside the crystals provide raw power to naga aquamancers. By siphoning this elemental magic, they hope to appease Aku'mai and gather sufficient power to usher in the return of the Old Gods.",al={"why naga crystals","elemental crystals naga","aquamancer crystals"}},{q="Where does this quest chain lead?",a="Delivering the note to Je'neu Sancrea leads directly into a follow-up mission tasked with tracking down and executing Lorgus Jett to disrupt the naga's ritual plans on the Zoram Strand.",al={"what comes after allegiance to the old gods","allegiance to the old gods part 2","next quest"},sp=1}},ang={["faction:Horde"]="Uncovering Lorgus Jett's note helps secure Zoram'gar Outpost against the surrounding Wrathscale naga who threaten the Horde's foothold on Ashenvale's western coast.",["class:Shaman"]="The naga's subjugation of water elemental spirits inside ritual crystals represents a grave perversion of natural balance, demanding swift correction.",["race:Troll"]="Assisting your Darkspear kin Je'neu Sancrea unmasks ancient cosmic entities whose return would threaten every tribe across Azeroth."},kw={"aku'mai","allegiance","ashenvale","blackfathom deeps","damp note","je'neu sancrea","lorgus jett","old gods","wrathscale","zoram'gar outpost"},rel={"npc:je-neu-sancrea","npc:lorgus-jett","npc:aku-mai","zone:blackfathom","subzone:zoram-gar-outpost","zone:ashenvale","topic:old-god","topic:naga"},m={start="Damp Note",["end"]="Je'neu Sancrea",level="22",faction="Horde",id=6564},src={"Allegiance to the Old Gods"}}
E["quest:6571"] = {t="quest",n="Warsong Supplies",z="ashenvale",s="Warsong Supplies is an expansive Horde logistics quest issued by Locke Okarr at Splintertree Post. Keeping the Warsong Lumber Camp operational demands reclaiming vital logging gear scattered across hostile furbolg and satyr territories, alongside imports arriving from distant goblin ports.",h="Warsong Supplies is an expansive Horde logistics quest issued by Locke Okarr at Splintertree Post.",sec={{t="Keeping the Saws Spinning",b="The Warsong Clan's campaign to harvest Ashenvale's ancient timber requires an endless flow of heavy tools. From their outpost at Splintertree Post, Horde quartermasters face constant supply disruptions. Locke Okarr is charged with keeping the lumber camp fully outfitted, but local shipments have disintegrated under raids from indigenous wildlife and demonic cultists, leaving the operation starved for vital gear.",sp=0},{t="A Scattered Logistics Chain",b="Securing the needed equipment is an ordeal spanning much of Kalimdor and extending even across the sea. While circular saw blades await collection from the goblin engineer Pixel right in Splintertree Post, the crate of heavy axes requires picking up a delivery from Wharfmaster Lozgil down in Booty Bay. The remaining essential goods must be ripped directly from enemy hands: sturdy logging ropes seized by hostile Foulweald and Thistlefur furbolgs, and barrels of Warsong machinery oil stolen by the satyrs of Night Run, Satyrnaar, and Xavian to fuel their profane rituals.",sp=0}},faq={{q="What are the required Warsong Supplies?",a="Locke Okarr needs four essential items: a shipment of Warsong Saw Blades held by the goblin Pixel, a crate of Warsong Axes shipped to Booty Bay, heavy Logging Rope looted by local furbolgs, and barrels of Warsong Oil stolen by Ashenvale's satyrs.",al={"warsong supplies list","what items needed","supplies needed"}},{q="Who is Locke Okarr?",a="Locke Okarr is an orc stationed at Splintertree Post responsible for coordinating material deliveries to the Warsong Lumber Camp. Under heavy pressure to avoid operational delays, he enlists roaming Horde adventurers to recover his scattered shipments.",al={"locke okarr lore","who gives warsong supplies","splintertree quest giver"}},{q="Why is the Horde shipping equipment from Booty Bay?",a="The Horde relies on neutral trade networks like the Steamwheedle Cartel to import specialty manufactured goods that Durotar and the Barrens cannot easily forge in bulk. Heavy-duty lumbering axes ordered through goblin channels are routed via maritime trade hubs like Booty Bay before reaching Ashenvale.",al={"why booty bay","booty bay axe shipment","steamwheedle tools"}},{q="Why do the satyrs want Warsong Oil?",a="Rather than using it for machinery, the satyrs inhabiting ruins like Satyrnaar, Night Run, and Xavian divert the stolen industrial oil into dark, corrupted rites dedicated to the Burning Legion and the spreading taint of Felwood.",al={"satyr oil lore","why do satyrs have oil","warsong oil rituals"}},{q="Which furbolgs stole the logging rope?",a="The Logging Rope was ambushed and taken by the Foulweald and Thistlefur furbolg tribes. Both tribes harbor fierce territorial hostility toward the Horde's clear-cutting operations across Ashenvale.",al={"who stole the rope","furbolg rope lore","foulweald thistlefur rope"}},{q="Why is the Warsong Lumber Camp so vital to the Horde?",a="The arid lands of Durotar provide virtually no usable timber for construction. The Warsong Clan was deployed into the lush borderlands of Ashenvale specifically to harvest the massive trees needed to build Orgrimmar and fuel the Horde's growing military infrastructure.",al={"why harvest ashenvale","warsong lumber importance","orcs cutting trees"}}},ang={["faction:Horde"]="The Horde's expansion into Durotar hinges entirely on lumber secured by the Warsong Clan. Reclaiming these tools directly bolsters the foundation of Orgrimmar.",["race:Orc"]="Honoring the Warsong Clan's legacy in Ashenvale means keeping their axes sharp and their camps supplied, despite constant harassment from forest natives.",["profession:Engineering"]="The goblin components of this shipment highlight the essential mechanical supply chain—from Pixel's saw blades to steam-engine lubricants—required to chop down ancient forests."},kw={"ashenvale","booty bay","locke okarr","logging rope","pixel","saw blades","splintertree post","warsong lumber camp","warsong oil","warsong supplies"},rel={"subzone:splintertree-post","subzone:warsong-lumber-camp","quest:6581","npc:pixel","subzone:booty-bay","subzone:satyrnaar","subzone:xavian","subzone:night-run"},m={start="Locke Okarr",level="27",faction="Horde",id=6571},src={"Warsong Supplies (quest)"}}
E["quest:6581"] = {t="quest",n="Warsong Saw Blades",z="ashenvale",s="Warsong Saw Blades is a Horde errand undertaken at Splintertree Post on behalf of the Warsong Outriders' logging campaign. To acquire heavy saw blades imported from Ratchet, adventurers must strike an under-the-table bargain with the courier Pixel, who demands personal protection before surrendering the shipment. Fulfilling her trade secures essential machinery needed to keep the Horde's lumber mills humming in Ashenvale.",h="Warsong Saw Blades is a Horde errand undertaken at Splintertree Post on behalf of the Warsong Outriders'...",sec={{t="A Courier's Shrewd Barter",b="The Warsong Outriders in Ashenvale rely entirely on imported heavy machinery to cut through the ancient timber of the deep forest. While Pixel has successfully brought a shipment of specialized saw blades straight from the goblin port of Ratchet to Splintertree Post, she has no intention of simply handing them over for free. Out in the perilous wilds of Ashenvale, coin is only worth so much; personal safety is worth far more. Rather than demanding gold, Pixel insists on bartering the heavy saw blades for a reliable Deadly Blunderbuss to keep herself safe during her dangerous travels through hostile territory.",sp=0},{t="Supplying the War Effort",b="Ashenvale's dense canopy is prized by the Horde, which faces severe timber shortages across the arid plains of Durotar and the Barrens. However, logging ancient sentinel groves quickly dulls standard axes, making goblin-forged industrial blades a necessity. Securing Pixel's shipment directly fuels the operations of the Warsong lumber camps, ensuring the Horde can continue constructing outposts and war machines despite fierce resistance from the night elves.",sp=0}},faq={{q="Who is Pixel and why does she have the saw blades?",a="Pixel is a courier currently stationed at Splintertree Post who transported a shipment of industrial saw blades directly from the goblin port of Ratchet. She holds onto the shipment until she can secure a reliable weapon for her own protection.",al={"who is pixel","pixie splintertree","saw blade courier"}},{q="Why does Pixel want a Deadly Blunderbuss instead of gold?",a="Traveling across the Barrens and deep into night elf territory in Ashenvale is extremely hazardous. Knowing the dangers of the road, Pixel prioritizes personal defense over coin and demands an engineer-crafted firearm to safeguard her journeys.",al={"why deadly blunderbuss","pixel gun trade","why want a gun"}},{q="Why are these saw blades so important to the Horde?",a="The Horde requires massive quantities of timber to build fortifications and war machines across Kalimdor. Standard cutting tools quickly wear out against Ashenvale's ancient ironwood trees, making imported mechanical saw blades vital for the Warsong Clan's logging machinery.",al={"why are saw blades needed","warsong lumber importance","why warsong supplies"}},{q="Where did the saw blades originally come from?",a="The saw blades were manufactured in and shipped from Ratchet, the neutral goblin port on the eastern coast of the Barrens, before being hauled overland to Splintertree Post.",al={"origin of saw blades","ratchet blades","where did saw blades come from"}},{q="Where does this quest fit into the Warsong logging effort?",a="This task is part of the larger effort to assemble Warsong Supplies for the lumber camps in Ashenvale. Recovering the saw blades from Pixel completes one of the key logistics requirements needed to sustain the Horde's logging operations.",al={"warsong supplies chain","warsong saw blades prerequisite"}},{q="Can anyone make the weapon Pixel wants?",a="A Deadly Blunderbuss is crafted by skilled Engineers using iron, heavy stone, and wood components, though couriers and warriors often trade for them through local markets or fellow adventurers.",al={"how to get deadly blunderbuss","blunderbuss source","engineering gun"}}},ang={["profession:Engineering"]="The Deadly Blunderbuss demanded by Pixel is a staple product of adept tinkerers, highlighting how goblin and mortal engineering drives the logistics of frontline war.",["faction:Horde"]="The lumber camps in Ashenvale provide the vital structural spine for Orgrimmar's expansions, making every delivery of machinery essential to the Horde's survival on Kalimdor.",["race:Orc"]="The Warsong Clan staked their pride on logging Ashenvale under Grommash Hellscream; keeping their industrial blades turning honors the clan's continued foothold in the forest."},kw={"ashenvale","deadly blunderbuss","pixel","ratchet","splintertree post","warsong outriders","warsong saw blades","warsong supplies"},rel={"npc:pixel","subzone:splintertree-post","quest:6571","zone:ashenvale","subzone:ratchet"},m={start="Pixel",level="27",faction="Horde",id=6581},src={"Warsong Saw Blades (quest)"}}
E["quest:6621"] = {t="quest",n="King of the Foulweald",z="ashenvale",s="King of the Foulweald is a Horde military strike commissioned by Karang Amakkar at Zoram'gar Outpost. Seeking to subdue the corrupted Foulweald furbolgs southeast of Astranaar, Horde champions plant a war banner directly atop the tribe's sacred totem mound, provoking and executing their chieftain, Chief Murgut.",h="King of the Foulweald is a Horde military strike commissioned by Karang Amakkar at Zoram'gar Outpost.",sec={{t="A Show of Force",b="While the night elves struggle to contain Ashenvale's corrupted native tribes, the Horde approaches the threat with calculated aggression. Karang Amakkar at Zoram'gar Outpost recognizes that while the Foulweald tribe may not rival the vast numbers of the northern Thistlefur, their unchecked ferocity represents a lurking danger along the southern road. Rather than wait for ambushes on Horde patrols, Karang orders a preemptive demonstration of martial dominance to break the tribe's will.",sp=0},{t="Desecration and Challenge",b="The strike targets Greenpaw Village, situated northeast of Mystral Lake. Karang crafts a tribal war banner intended to be driven directly into the center of the Foulweald totem mound—an unforgivable insult to the tribe's ancestral spirits and pride. Furbolg defenders rush the mound in desperation to tear down the offending standard, compelling Chief Murgut to emerge and defend his honor in open combat. Claiming Murgut's personal totem shatters their leadership and establishes Horde supremacy in the area.",sp=0}},faq={{q="Who orders the death of Chief Murgut?",a="Karang Amakkar, an orc stationed at Zoram'gar Outpost along the western coast of Ashenvale, issues the mission following his investigation into the neighboring Thistlefur furbolgs.",al={"quest giver king of the foulweald","who gives king of the foulweald","karang amakkar quest"}},{q="Where is Greenpaw Village located?",a="Greenpaw Village lies southeast of the night elf settlement of Astranaar, positioned northeast of Mystral Lake just south of Ashenvale's main eastern highway.",al={"where is greenpaw village","foulweald location","where to plant karang banner"}},{q="Why does the Horde plant a banner on the totem mound?",a="Planting Karang's Banner directly into the tribe's sacred totem mound is an intentional provocation. Desecrating their sacred grounds forces the Foulweald to attack in a fury and compels Chief Murgut to fight openly to protect his standing.",al={"why place banner","totem mound banner purpose","why challenge murgut"}},{q="Who are the Foulweald furbolgs?",a="The Foulweald are one of several furbolg tribes in Ashenvale that have fallen into madness and corruption following the Third War. Although fewer in number than the Thistlefur, they remain violent and hostile to outsiders.",al={"what are the foulweald","foulweald tribe lore","who is chief murgut"}},{q="What does retrieving Murgut's Totem accomplish?",a="Taking Chief Murgut's totem back to Zoram'gar Outpost proves the chief's defeat. Without their leader and with their sacred mound disgraced, the surviving Foulweald are intimidated into avoiding further conflict with the Horde.",al={"murgut totem purpose","what happens after murgut dies"}},{q="How does this quest fit into the earlier furbolg investigations?",a="This mission directly follows 'Between a Rock and a Thistlefur.' After dealing with the northern Thistlefur tribe, Karang turns his attention southward to preemptively crush the Foulweald before they can launch coordinated raids.",al={"between a rock and a thistlefur connection","prerequisite king of the foulweald"}}},ang={["faction:Horde"]="Karang Amakkar uses open displays of martial dominance to cow hostile Ashenvale tribes, securing safe passage along the central trails for Horde supply caravans.",["race:Orc"]="Placing a banner to provoke an enemy chieftain into single combat is classic orcish warfare, prioritizing strength and decisive confrontation over lengthy skirmishes.",["class:Shaman"]="The Foulweald's distorted totems and aggression reflect the ongoing spiritual imbalance that plagued Ashenvale's native tribes after the Burning Legion's invasion."},kw={"ashenvale","foulweald","furbolg","greenpaw village","karang amakkar","murgut","totem mound","zoram'gar"},rel={"npc:karang-amakkar","subzone:greenpaw-village","quest:216","topic:furbolg","zone:ashenvale","topic:horde","subzone:mystral-lake","subzone:astranaar"},m={start="Karang Amakkar",level="26",faction="Horde",id=6621},src={"King of the Foulweald (Classic)"}}
E["quest:6641"] = {t="quest",n="Vorsha the Lasher",z="ashenvale",s="Vorsha the Lasher is a violent hydra terrorizing the Horde's foothold at Zoram'gar Outpost along the coast of Ashenvale. Revering the creature's ferocity, the local naga maintain an offering brazier on an offshore island to honor her. By extinguishing this sacred flame, Horde champions provoke Vorsha and draw her ashore to end her predatory assaults.",h="Vorsha the Lasher is a violent hydra terrorizing the Horde's foothold at Zoram'gar Outpost along the coast of...",sec={{t="A Terror from the Deep",b="Zoram'gar Outpost sits on a tenuous strip of coast in northwestern Ashenvale, constantly besieged by hostile wildlife, night elves, and serpentine invaders. Among the most destructive threats prowling the Zoram Strand is Vorsha the Lasher, a gargantuan hydra known for brutal, unprovoked strikes against the outpost. The beast emerges from the surf to crush fortifications and butcher warriors before vanishing back into the deep tides.",sp=0},{t="The Brazier of the Naga",b="The nearby naga do not merely tolerate the ravenous hydra; they actively venerate her predatory malice. On a rocky outcrop off the strand, the serpentine fiends keep an offering brazier burning continuously in tribute to Vorsha. Muglash, an orc determined to end the constant harassment of the outpost, realized that defiling this ritual flame would bring the beast surging to the surface in a fury, allowing the defenders to lure her into an ambush rather than waiting for another surprise slaughter.",sp=0}},faq={{q="Who is Vorsha the Lasher?",a="Vorsha the Lasher is a fierce, massive hydra that haunts the waters off the Zoram Strand. She frequently makes unprovoked raids against Zoram'gar Outpost, destroying camp defenses and slaughtering Horde personnel.",al={"vorsha","what is vorsha","vorsha hydra"}},{q="Why do the naga honor Vorsha?",a="The naga of the Zoram Strand respect Vorsha for her unrelenting ferocity and destructive appetite. They maintain an offshore brazier kept lit in honor of her wicked nature, treating the beast as an avatar of savage coastal fury.",al={"why naga like hydra","vorsha naga brazier","why worship vorsha"}},{q="How is Vorsha lured out to fight?",a="Muglash leads an assault onto the island where the naga tend Vorsha's brazier. Extinguishing the sacred flame deeply enrages both the resident naga guardians and the hydra herself, compelling Vorsha to surface from the sea to retaliate.",al={"how to summon vorsha","how do you call vorsha","brazier island vorsha"}},{q="Who is Muglash?",a="Muglash is an orc stationed at Zoram'gar Outpost. Weary of living in terror of Vorsha's unprovoked coastline rampages, he devises the plan to snuff out the naga's ritual brazier and fight the beast alongside dependable allies.",al={"who is muglash","muglash orc","zoramgar muglash"}},{q="Why is Zoram'gar Outpost vulnerable to coastal beasts?",a="Zoram'gar Outpost is an isolated and exposed frontier camp situated directly on the beaches of Ashenvale. With naga dominating the ruins in the sea and wild hydras patrolling the surf, its proximity to the water leaves it open to amphibious attacks from all directions.",al={"why is zoramgar attacked","zoram strand danger"}},{q="What happens after Vorsha is slain?",a="With the hydra slain, the victory is reported back to the Warsong Runners maintaining the lines at Zoram'gar Outpost, easing the constant burden on the frontier guards and securing the immediate coast from sudden assault.",al={"vorsha quest turn in","who to report vorsha to"},sp=1}},ang={["faction:Horde"]="Defending Zoram'gar Outpost is essential for maintaining a northern logistical foothold in Ashenvale, where supply lines are perpetually under attack.",["race:Orc"]="Orcs like Muglash refuse to cower behind makeshift palisades, opting to charge out into the surf to hunt predatory beasts face to face."},kw={"ashenvale","brazier","hydra","muglash","naga","vorsha","zoram strand","zoram'gar"},rel={"subzone:zoram-gar-outpost","topic:naga","zone:ashenvale"},m={start="Muglash",["end"]="Warsong Runner",faction="Horde",id=6641},src={"Vorsha the Lasher (quest)"}}
E["quest:7863"] = {t="quest",n="Sentinel Basic Care Package",z="ashenvale",s="Sentinel Basic Care Package is a recognition of service provided to Alliance champions who take up arms for the Silverwing Sentinels. Offered by Illiyana Moonblaze in Ashenvale, this parcel equips frontline fighters with battlefield rations and bandages for the ongoing clash in Warsong Gulch.",h="Sentinel Basic Care Package is a recognition of service provided to Alliance champions who take up arms for...",sec={{t="A Token of Trust",b="The Silverwing Sentinels do not grant their trust lightly to outsiders, even those under the banner of the Grand Alliance. However, when an adventurer demonstrates willingness to bleed in defense of Ashenvale's ancient borders, the night elves acknowledge that commitment. Illiyana Moonblaze provides this package as a preliminary commendation for soldiers who have begun carving a name for themselves in the skirmishes against the Warsong Outriders.",sp=0},{t="Provisions for the Front",b="Warsong Gulch is a grinding battle of attrition, fought through dense canopies and fortified ramparts where regular supply lines struggle to reach. Inside this care package are specialty rations and medical supplies prepared exclusively for combat within the Gulch. As recruits deepen their standing among the Sentinels, higher-grade provisions and specialized stores become accessible, sustaining the continuous war effort against the Horde loggers.",sp=0}},faq={{q="What is the purpose of this care package?",a="The package serves as both an official recognition of your initial service to the Silverwing Sentinels and an emergency resupply. It contains rations and bandages designed exclusively to sustain fighters during skirmishes inside Warsong Gulch.",al={"what is in the care package","basic care package purpose","why get basic care package"}},{q="Who provides this package?",a="Illiyana Moonblaze, the supply officer for the Silverwing Sentinels located at Silverwing Grove in southern Ashenvale, issues the care package once you have proven your initial allegiance to their cause.",al={"who gives basic care package","quest giver","illiyana moonblaze role"}},{q="Where can the supplies inside be used?",a="The provisions and bandages provided in the parcel are specially enchanted and stocked for combat operations strictly within the borders of Warsong Gulch. They cannot be utilized in the open world.",al={"can i use outside wsg","wsg only items","battlefield supplies use"}},{q="How do you earn more advanced supplies from the Sentinels?",a="As you continue fighting the Warsong clan and improving your standing with the Silverwing Sentinels, standard provisions become purchasable. Rations become available at Friendly standing, while field bandages become accessible once you attain Honored rank.",al={"more supplies","next care package","silverwing reputation items"}},{q="What quest follows this one?",a="After earning this initial parcel, further distinction on the battlefield allows you to earn the Sentinel Standard Care Package, which offers greater reinforcements for sustained conflict.",al={"next quest","follow up quest","what after basic care package"}},{q="Why are the Sentinels fighting in Warsong Gulch?",a="The Silverwing Sentinels fight to safeguard the ancient forests of Ashenvale from the logging operations of the Warsong Outriders, who seek lumber to build and sustain the Horde capital of Orgrimmar.",al={"why wsg","ashenvale conflict lore","sentinels vs outriders"}}},ang={["faction:Alliance"]="The care package represents the growing military coordination between night elf defenders and the broader Alliance forces aiding their campaign in Kalimdor.",["race:NightElf"]="For night elf defenders, these provisions represent the shared sacrifices of the Sisterhood of Elune and the Sentinels to protect sacred ancestral woodland from Orcish axes."},kw={"ashenvale","bandages","care package","illiyana moonblaze","rations","silverwing sentinels","warsong gulch"},rel={"npc:illiyana-moonblaze","topic:sentinels","zone:ashenvale"},m={start="Illiyana Moonblaze",faction="Alliance",id=7863},src={"Sentinel Basic Care Package (quest)"}}
E["quest:7864"] = {t="quest",n="Sentinel Standard Care Package",z="ashenvale",s="The Sentinel Standard Care Package is an Alliance requisition offered to warriors proving their worth in Warsong Gulch. Distributed by Illiyana Moonblaze in Ashenvale, it equips dedicated defenders of the Silverwing Sentinels with essential combat supplies tailored specifically for the contested valley.",h="The Sentinel Standard Care Package is an Alliance requisition offered to warriors proving their worth in...",sec={{t="Supplying the Front Lines",b="The ongoing struggle against the Warsong Outriders in Ashenvale demands constant logistical support. To sustain Alliance champions fighting among the ancient trees of Warsong Gulch, the Silverwing Sentinels distribute prepared bundles of battle rations and field bandages. These care packages ensure that frontline skirmishers remain nourished and mended during fierce engagements to protect the sacred forest.",sp=0},{t="Earning Silverwing Trust",b="Illiyana Moonblaze oversees these allotments from the Silverwing grove. While initial recruits receive modest basic supplies, continued service and rising standing among the night elves unlock standard care packages. As a soldier becomes an established presence on the battlefield, the Sentinels open their regular quartermaster stores, allowing dependable fighters direct access to provisions and medical supplies for the war effort.",sp=0}},faq={{q="Who offers the Sentinel Standard Care Package?",a="The package is provided by Illiyana Moonblaze, the supply officer for the Silverwing Sentinels stationed near the entrance to Warsong Gulch in Ashenvale.",al={"who gives standard care package","care package quest giver","illiyana moonblaze quest"}},{q="What is inside the care package?",a="The care package contains battlefield rations and restorative bandages tailored specifically for use while fighting within Warsong Gulch.",al={"care package contents","what is in standard care package","package rewards"}},{q="Can the items from this package be used anywhere?",a="No. The specialized rations and bandages enclosed within the package are strictly designated for combat engagements inside Warsong Gulch.",al={"can i use rations outside","warsong gulch only bandages","where to use care package items"}},{q="What is required to earn this care package?",a="You must prove yourself in battle alongside the Silverwing Sentinels in Warsong Gulch and earn their ongoing trust, following the completion of your initial basic supply requisitions.",al={"how to get standard care package","silverwing reputation requirement","standard care package prerequisites"}},{q="Why are the Silverwing Sentinels fighting here?",a="The Silverwing Sentinels are defending Ashenvale's ancient forests from the Warsong clan of orcs, who have established logging operations and deep outposts throughout the sacred woodland.",al={"why are sentinels fighting","silverwing sentinels lore","warsong gulch conflict"}},{q="What comes after the Standard Care Package?",a="Continued distinction in the battleground leads to higher recognition from the Sentinels, eventually qualifying dedicated Alliance soldiers for the Sentinel Advanced Care Package.",al={"next quest after standard care package","care package chain","advanced care package"}}},ang={["faction:Alliance"]="The Silverwing Sentinels rely on Alliance champions of all races to blunt the Horde's expansion into Ashenvale, rewarding loyal fighters with dedicated battleground provisions.",["race:NightElf"]="For night elves, defending Ashenvale from the Warsong Outriders is a sacred duty to preserve their ancestral homeland from desecration."},kw={"ashenvale","battleground rations","illiyana moonblaze","sentinel standard care package","silverwing sentinels","warsong gulch","warsong outriders"},rel={"npc:illiyana-moonblaze","topic:sentinels","zone:ashenvale"},m={start="Illiyana Moonblaze",faction="Alliance",id=7864},src={"Sentinel Standard Care Package (quest)"}}
E["quest:7865"] = {t="quest",n="Sentinel Advanced Care Package",z="ashenvale",s="Sentinel Advanced Care Package is an Alliance supply requisition granted by Illiyana Moonblaze in Ashenvale. Offered to proven fighters of the Silverwing Sentinels, it provides essential battlefield rations and medical dressings tailored exclusively for the ongoing clashes in Warsong Gulch. It marks an escalation from basic survival supplies to formalized military logistical support.",h="Sentinel Advanced Care Package is an Alliance supply requisition granted by Illiyana Moonblaze in Ashenvale.",sec={{t="Logistics in the Canopy",b="The battle for Warsong Gulch is a grueling war of attrition against the Warsong Outriders. To sustain frontline combatants without bleeding dry the civilian stores of Ashenvale, the Silverwing Sentinels maintain strict logistical caches. Illiyana Moonblaze oversees the outfitting of soldiers who have demonstrated steadfast commitment in the field. Those who rise through the ranks receive specialized aid parcels stocked with battlefield provisions, ensuring vanguard forces remain fed and patched up during extended skirmishes beneath the trees.",sp=0},{t="Provisions of the Silverwing",b="The advanced package contains field-dressings and combat rations strictly designated for deployment inside Warsong Gulch. As soldiers deepen their standing with the Sentinels, these supplies shift from occasional commendation gifts into regular quartermaster requisitions. Sustaining warriors on the front lines allows the night elves to maintain constant pressure against orcish logging parties and keep the defilers from gaining uncontested control over the sacred borderlands.",sp=0}},faq={{q="What is the Sentinel Advanced Care Package?",a="It is a military supply bundle granted by Illiyana Moonblaze in Ashenvale to Alliance fighters who have proven their dedication to the Silverwing Sentinels. It contains field bandages and combat rations specifically intended for combat in Warsong Gulch.",al={"care package","sentinel supplies","warsong package"}},{q="Who provides this care package?",a="Illiyana Moonblaze, the Silverwing supply officer and representative stationed near the entrance to Warsong Gulch in Ashenvale, distributes the package.",al={"who gives care package","illiyana quest"}},{q="Why are these supplies restricted to Warsong Gulch?",a="The provisions are specially enchanted and apportioned military assets designated solely for the defense of the Gulch. The Silverwing Sentinels strictly limit their distribution to ensure their war reserves remain focused on repelling the Warsong Outriders.",al={"why only wsg","warsong gulch only items","ration restriction"}},{q="How does a soldier earn this package?",a="Fighters must earn standing with the Silverwing Sentinels by battling Horde forces in Warsong Gulch and complete the preliminary standard care package requisition before receiving this upgraded parcel.",al={"how to get package","sentinel reputation requirements"}},{q="What happens after receiving this package?",a="Once you earn sufficient standing with the Sentinels, the items within the package become regularly available for purchase from the Silverwing quartermaster, including combat rations and high-grade battlefield bandages.",al={"what unlocks after care package","purchasing wsg rations"}},{q="What is the conflict between the Silverwing Sentinels and the Horde here?",a="The Silverwing Sentinels fight to protect the sacred forests of Ashenvale from the Warsong clan, whose logging operations aggressively strip the woodland for timber to construct Orgrimmar and fuel the Horde war machine.",al={"why fight in ashenvale","warsong gulch conflict lore"}}},ang={["faction:Alliance"]="The defense of Ashenvale relies on joint Alliance mobilization, where volunteers from across the kingdoms stand shoulder-to-shoulder with the night elves against orcish expansion.",["race:NightElf"]="The Silverwing Sentinels are fighting on ancestral ground; every ration and bandage delivered preserves the defenders protecting Elune's sacred woods from deforestation."},kw={"ashenvale","bandages","battlefield rations","care package","illiyana moonblaze","silverwing sentinels","warsong gulch"},rel={"npc:illiyana-moonblaze","topic:sentinels","zone:ashenvale"},m={start="Illiyana Moonblaze",faction="Alliance",id=7865},src={"Sentinel Advanced Care Package (quest)"}}
E["quest:8725"] = {t="quest",n="Riversong the Elder",z="ashenvale",s="Elder Riversong is an ancestral night elf spirit honored during the Lunar Festival, found resting beneath a quiet shrine in Astranaar. Bathed in a beam of moonlight, he offers quiet wisdom to travelers and directs pilgrims toward other revered ancestors across the lands of Kalimdor.",h="Elder Riversong is an ancestral night elf spirit honored during the Lunar Festival, found resting beneath a...",sec={{t="A Beacon in Astranaar",b="Amid the ancient boughs and wooden walkways of Astranaar, Elder Riversong appears under an open night elf shrine. Marked by a distinct column of celestial light piercing the Ashenvale canopy, his ethereal presence serves as a focal point for participants in the Lunar Festival seeking communion with past generations.",sp=0},{t="Gazing at the Heavens",b="Elder Riversong reminds pilgrims of the ancient night elven tradition of reading truth and mystery in the starry sky. His words direct travelers to seek wisdom through patience and contemplation, guiding those honoring the season on toward fellow spirits, including Elder Starweave.",sp=0}},faq={{q="Where can I find Elder Riversong?",a="Elder Riversong stands inside the settlement of Astranaar in Ashenvale. He is situated under a small night elf shrine, bathed in a bright beam of starlight descending through the forest canopy.",al={"riversong location","where is riversong","elder riversong loc"}},{q="What is the purpose of visiting Elder Riversong?",a="Visiting Elder Riversong is part of honoring the ancestors during the Lunar Festival. Speaking with him grants an ancestral blessing and coins of ancestry, while also offering guidance on locating other elders across Kalimdor.",al={"why visit riversong","what does riversong do"}},{q="Which elder does Riversong direct you toward?",a="Elder Riversong points seekers toward Elder Starweave, another honored night elf spirit observing the festival.",al={"next elder after riversong","who does riversong mention"}},{q="Can Horde players speak to Elder Riversong?",a="Because Elder Riversong resides directly inside Astranaar, an Alliance hub, Horde players must contend with town guards and sentinels to approach him, though festival elders themselves do not refuse communion based on faction.",al={"can horde visit riversong","is riversong alliance only"}},{q="Why is Elder Riversong surrounded by a beam of light?",a="The shaft of celestial light represents the favor of Elune and the heavens, illuminating every ancestral spirit who manifests during the Lunar Festival.",al={"why does riversong glow","light on riversong"}},{q="What does Elder Riversong say when honored?",a="Elder Riversong reflects on the cosmos, observing that the countless stars in the heavens hold answers to earthly mysteries, and asks if the wise and lucky might gaze upward to find truth.",al={"riversong quote","riversong dialogue"}}},ang={["race:NightElf"]="For night elves, honoring Elder Riversong beneath an Astranaar shrine is an intimate act of communion with their people's long history under the stars of Ashenvale.",["faction:Alliance"]="Astranaar is one of the Alliance's primary strongholds in central Kalimdor, making Elder Riversong an easy and welcome visit for Alliance pilgrims during the Lunar Festival.",["class:Druid"]="The Lunar Festival and its celestial elders embody the ancient Cenarion bond with nature, spirits, and the night sky."},kw={"ancestor","ashenvale","astranaar","elder","lunar festival","riversong","shrine","starweave"},rel={"subzone:astranaar","zone:ashenvale","npc:elder-starweave","topic:night-elf","topic:light"},m={start="Elder Riversong",id=8725},src={"Riversong the Elder"}}
E["quest:945"] = {t="quest",n="Therylune's Escape",z="ashenvale",s="Deep in southwestern Ashenvale, a young night elf named Therylune has wandered into the ominous dig sites of the Master's Glaive and found herself cornered by hostile cultists. An Alliance escort is needed to guide her to safety and deliver word of her survival to her worried sister, Therysil, resting at the Shrine of Aessina.",h="Deep in southwestern Ashenvale, a young night elf named Therylune has wandered into the ominous dig sites of...",sec={{t="A Perilous Stroll",b="The Master's Glaive is one of the most unsettling landmarks in Ashenvale, dominated by the titanic skull of an ancient monstrosity impaled by an immense stone blade. Despite the dread that lingers over the valley, Therylune wandered right into the heart of the ravine. She soon found herself pinned down by cultists of the Twilight's Hammer, surviving only thanks to quick reflexes and an aptitude for hiding in the rough terrain.",sp=0},{t="Word to the Shrine",b="Therylune's sister, Therysil, resides far to the south at the peaceful Shrine of Aessina. While Therylune is known to be adventurous and unbothered by getting dirt on her clothes, venturing into the unwholesome excavations of the Master's Glaive shocked even her kin. Bringing word of Therylune's safety relieves a deeply troubled sister, who knows all too well the dark forces currently digging through Ashenvale's ancient earth.",sp=0}},faq={{q="Who is Therylune?",a="Therylune is an adventurous young night elf who strayed into the dangerous excavations at the Master's Glaive in southwestern Ashenvale. She is the sister of Therysil.",al={"therylune","who is the girl","trapped elf"}},{q="Who is Therysil?",a="Therysil is Therylune's sister, stationed at the tranquil Shrine of Aessina in Ashenvale. She is dismayed to learn her sibling wandered so close to such a dark and tainted location.",al={"therysil","therylune sister"}},{q="Why is the Master's Glaive so dangerous?",a="The Master's Glaive is an ancient, foreboding ravine home to the remains of an Old God's servant. Twilight's Hammer cultists swarm the area, aggressively excavating the site and attacking any trespassers.",al={"masters glaive danger","cultists masters glaive"}},{q="Where does Therylune need to be escorted?",a="Therylune needs an escort away from the immediate perimeter of the Master's Glaive to safety, after which the rescuer must travel to the Shrine of Aessina to notify her sister.",al={"escort destination","where does therylune go"}},{q="Where is the Shrine of Aessina located?",a="The Shrine of Aessina lies along the central forest paths in southern Ashenvale, southeast of Astranaar, serving as a sanctuary dedicated to the forest spirit Aessina.",al={"shrine of aessina location","where is therysil"}},{q="How did Therylune survive surrounded by cultists?",a="Therylune managed to avoid capture purely by finding a tight hiding spot amidst the rocks and terrain before the surrounding Twilight's Hammer cultists could spot her.",al={"how did therylune hide"}}},ang={["race:NightElf"]="The Master's Glaive is an ancient scar on Kalimdor's history. Seeing your fellow kaldorei wandering heedlessly into cultist excavations is a sobering reminder of the creeping threats inside Ashenvale.",["faction:Alliance"]="Helping stranded wayfarers like Therylune reinforces the Alliance's presence and goodwill among the native night elves defending Ashenvale."},kw={"ashenvale","cultists","escort","master's glaive","shrine of aessina","therylune","therysil","twilight's hammer"},rel={"npc:therylune","npc:therysil","subzone:master-s-glaive","subzone:shrine-of-aessina","zone:ashenvale","quest:944"},m={start="Therylune",["end"]="Therysil",level="18",faction="Alliance",id=945},src={"Therylune's Escape"}}
E["quest:9516"] = {t="quest",n="Destroy the Legion",z="ashenvale",s="At the night elf outpost of Forest Song, Vindicator Vedaar rallies the Alliance to strike at lingering Burning Legion remnants in southern Ashenvale. Hauntings from the Third War and earlier invasions still fester across Felfire Hill and Demon Fall Canyon, demanding immediate purge before they can spread.",h="At the night elf outpost of Forest Song, Vindicator Vedaar rallies the Alliance to strike at lingering...",sec={{t="A Bitter History",b="For Vindicator Vedaar, fighting the Burning Legion is deeply personal. His people endured catastrophic devastation across worlds, repeatedly forced to flee demonic onslaughts. Finding demonic entities festering openly in Kalimdor's sacred woods is an affront he refuses to abide. Instead of running again, he chooses to take a definitive stand.",sp=0},{t="Cleansing Southern Ashenvale",b="The targets of this offensive occupy the blighted lands of Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge. Lingering fiends—Mannoroc lashers, roaming felguards, and searing infernals—still stalk the jagged crags where demonic blood once corrupted the land. Eliminating them weakens the Legion's persistent foothold in eastern Ashenvale and protects Forest Song's fragile rebuilding efforts.",sp=0}},faq={{q="Who offers the quest Destroy the Legion?",a="Vindicator Vedaar gives this quest. You can find him stationed at the Alliance outpost of Forest Song in eastern Ashenvale.",al={"who gives destroy the legion","destroy the legion questgiver","where to get destroy the legion"}},{q="Why is Vedaar so determined to destroy these demons?",a="The Burning Legion chased his people across worlds, forcing endless retreats and slaughter. Seeing demons roaming freely in Kalimdor is unacceptable to him, prompting him to purge their presence rather than retreat again.",al={"vedaar motivation","why fight demons ashenvale","why vedaar hates legion"}},{q="Where are the demons located?",a="The demons are concentrated south of Forest Song in the scarred regions of Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.",al={"demon locations ashenvale","where are felguards ashenvale","where are searing infernals"}},{q="What kinds of enemies must be slain?",a="You need to eliminate Mannoroc lashers, roaming felguards, and searing infernals that roam the canyons and blighted hills to the south.",al={"destroy the legion objectives","what mobs to kill destroy the legion","mobs for destroy the legion"}},{q="How did these demons end up in Ashenvale?",a="They are remnants left behind from prior demonic invasions, notably the Third War when the pit lord Mannoroth corrupting orcs and fought Grommash Hellscream in the nearby canyon.",al={"why are there demons in ashenvale","demon fall canyon lore","how did demons get here"}},{q="What does completing this mission achieve for Forest Song?",a="Culling the roaming demons reduces the immediate threat to Forest Song, giving the Alliance a safer staging ground to rebuild and secure eastern Ashenvale.",al={"destroy the legion outcome","why help forest song","forest song demon threat"}}},ang={["faction:Alliance"]="The demonic presence in the south directly jeopardizes Forest Song, one of the Alliance's key outposts holding the line against both demonic corruption and Horde expansion.",["class:Paladin"]="Purging fiends from corrupted soil fulfills the holy calling to root out demonic corruption wherever it lingers.",["race:NightElf"]="The forests of Ashenvale have suffered millennia of demonic affliction; clearing the blighted ridges brings the woods one step closer to healing.",["class:Warlock"]="Facing loose, wild demons of the Legion provides a sharp contrast to the controlled, bound servants commanded through dark pacts."},kw={"ashenvale","burning legion","demon fall canyon","demon fall ridge","felfire hill","felguard","forest song","infernal","vedaar"},rel={"npc:vindicator-vedaar","subzone:forest-song","topic:burning-legion","subzone:demon-fall-canyon","subzone:demon-fall-ridge","subzone:felfire-hill","zone:ashenvale"},m={start="Vindicator Vedaar",level="30",faction="Alliance",id=9516},src={"Destroy the Legion (BC Classic Alliance)"}}
E["quest:9518"] = {t="quest",n="Agents of Destruction",z="ashenvale",s="At the outpost of Forest Song, Sentinel Luciel Starwhisper directs Alliance champions to strike deep into the Warsong Lumber Camp. The objective is to eliminate Overseer Gorthak, disable goblin-built shredders, and scatter the Horde deforesters ravaging eastern Ashenvale's ancient woodlands.",h="At the outpost of Forest Song, Sentinel Luciel Starwhisper directs Alliance champions to strike deep into the...",sec={{t="A Scar in the Canopy",b="The Warsong Lumber Camp represents an open wound across eastern Ashenvale. For the night elves, who hold the primeval trees sacred, the persistent clear-cutting is more than an economic territorial dispute—it is active desecration. Every strike against the lumber operations has only resulted in the Horde redoubling its logging, pushing further into ancient canopies.",sp=0},{t="Reckless Destruction",b="What enrages Sentinel Luciel Starwhisper most is not merely the logging, but its wanton carelessness. Overseer Gorthak's crew cuts far more timber than their wagons can haul away, leaving felled trunks to rot on the forest floor while metal blades and steam-powered shredders gnaw into fresh groves. Striking down Gorthak and destroying his machinery aims to shatter the camp's leadership before the woodland is hollowed out entirely.",sp=0}},faq={{q="Why is the Horde cutting so much lumber in Ashenvale?",a="The orcish capital of Orgrimmar and the settlement of Durotar sit in arid, barren badlands devoid of large timber. The Warsong Outriders harvest Ashenvale's dense forest to fuel Horde construction and siegecraft, though Overseer Gorthak's operation cuts far beyond necessity, leaving piles of felled wood to simply rot.",al={"why orcs logging ashenvale","warsong lumber camp purpose","why orcs need wood"}},{q="Who is Overseer Gorthak?",a="Overseer Gorthak commands the Warsong Lumber Camp in eastern Ashenvale. Rather than slowing down under night elf pressure, Gorthak pushed his peons, scouts, and deforesters to increase their felling pace, earning the direct wrath of Sentinel Luciel Starwhisper.",al={"overseer gorthak lore","who is gorthak","lumber camp boss"}},{q="Where is this mission launched from?",a="The strike is ordered by Sentinel Luciel Starwhisper at Forest Song, a night elf outpost located in the eastern reaches of Ashenvale, just north of the border road and the Warsong logging grounds.",al={"quest giver location","where is luciel starwhisper","where to start agents of destruction"}},{q="Why are shredders operating in the woods?",a="The Horde employs goblin-engineered shredders—bipedal steam-driven contraptions armed with buzz saws—to accelerate logging. To the night elves, these smoking, oil-dripping machines are unnatural horrors that churn pristine glades into muddy wastelands.",al={"warsong shredders","goblin shredders ashenvale"}},{q="What happens to the lumber camp after Gorthak falls?",a="Killing Gorthak stuns the operation and halts the immediate waste, but Starwhisper acknowledges that the Horde will likely attempt to replace him. She vows to strike down any foreman or overseer who attempts to resume logging until the camp is entirely reclaimed by nature.",al={"after killing gorthak","does the camp shut down"},sp=1},{q="Does the Alliance claim the cut wood?",a="No. The night elves view the slaughtered trees as a tragedy rather than a resource to be hoarded. Their aim is solely to halt the slaughter of living boughs and allow the forest time to heal.",al={"recovering lumber","what happens to the logs"}}},ang={["race:NightElf"]="For the kaldorei, watching ancient trees cut down and abandoned to rot is an unendurable sacrilege. Reclaiming the eastern groves is a duty to Elune and the spirits of the woods.",["class:Druid"]="The mechanical whine of goblin shredders tearing through Ashenvale's living timber pains any druid who communes with the wild, making Gorthak's camp an urgent target for cleansing.",["profession:Engineering"]="The Warsong Shredders represent the crude, noisy peak of Venture Company-style goblin mechanical power adapted for military-scale land clearing.",["faction:Alliance"]="Striking the Warsong Lumber Camp deprives the Horde of vital timber shipments while reinforcing the Alliance's contested hold on the Ashenvale borderlands."},kw={"agents of destruction","ashenvale","deforester","forest song","luciel starwhisper","overseer gorthak","warsong lumber camp","warsong shredder"},rel={"npc:sentinel-luciel-starwhisper","subzone:forest-song","subzone:warsong-lumber-camp","zone:ashenvale","topic:horde"},m={start="Sentinel Luciel Starwhisper",level="28",faction="Alliance",id=9518},src={"Agents of Destruction (BC Classic)"}}
E["quest:9520"] = {t="quest",n="Diabolical Plans",z="ashenvale",s="Recovered from Legion forces wandering the corrupted pockets of Ashenvale, these dropped orders reveal a coordinated plot targeting the fledgling settlement of Forest Song. Penned surprisingly in Common, the parchment outlines preparations directed by two dreadlords overseeing the local demonic presence. Delivering the missive alerts the defenders before the Burning Legion can strike.",h="Recovered from Legion forces wandering the corrupted pockets of Ashenvale, these dropped orders reveal a...",sec={{t="A Plot Against Forest Song",b="Forest Song stands as a developing Alliance outpost in eastern Ashenvale, where draenei arrivals work alongside night elves to restore ancient ruins. The discovery of these diabolical plans exposes that the settlement has drawn the malignant gaze of the Burning Legion. Rather than aimless marauders, the demons in the region are actively marshaling forces to wipe out the new enclave before it can take root.",sp=0},{t="The Dreadlord Overseers",b="The intercepted parchment explicitly references Diathorus and Gorgannon, two dreadlords commanding the local demonic thralls. Strangely scribed in the Common tongue—perhaps intended to be deciphered by cultists or merely ensuring universal comprehension among varied servants—the orders lay out systematic preparations for an offensive, requiring immediate intervention from Vindicator Vedaar.",sp=0}},faq={{q="What are the Diabolical Plans?",a="They are written orders dropped by demons in Ashenvale detailing an impending assault against the settlement of Forest Song. Amazingly penned in the Common tongue, they name the dreadlords Diathorus and Gorgannon as the orchestrators.",al={"what are these plans","diabolical plans item","who wrote the plans"}},{q="Who should I bring the plans to?",a="Deliver the plans to Vindicator Vedaar at Forest Song in eastern Ashenvale. As a protector of the burgeoning enclave, he needs the advance warning to organize a defense.",al={"where do i take the plans","turn in diabolical plans","vedaar location"}},{q="Who are Diathorus and Gorgannon?",a="They are two infamous dreadlords directing the remnants of the Burning Legion throughout Ashenvale's corrupted woods, using lesser demons to orchestrate terror against the Alliance.",al={"dreadlords ashenvale","diathorus","gorgannon"}},{q="Why is the Legion targeting Forest Song?",a="Forest Song is a new draenei and night elf settlement built amidst ancient ruins. The Burning Legion seeks to crush any Alliance foothold and purge draenei presence wherever it surfaces.",al={"why attack forest song","why forest song"}},{q="Why is the document written in Common?",a="While demons typically speak Eredun, they often employ mortal languages to coordinate with mortal pawns, cultists, or simply to ensure their commands are broadly understood across disparate servant races.",al={"why common tongue","why is demon parchment in common"}},{q="How does Vindicator Vedaar react to the parchment?",a="Vedaar reacts with righteous anger, invoking the Seven Crystals of Ata'mal and crumpling the parchment in his fist while swearing that the Legion will never take Forest Song on his watch.",al={"vedaar reaction","what does vedaar say"}}},ang={["faction:Alliance"]="Uncovering this intercepted missive protects an Alliance frontier post from being wiped out by Legion forces.",["class:Paladin"]="Handing enemy battle plans to a fellow champion of the Light at Forest Song directly aids the crusade against the Legion's dreadlords.",["race:NightElf"]="Demons scheming within Ashenvale threaten the sanctity of the sacred forests, making this discovery vital for defending the woods.",["class:Warlock"]="Interpreting demon field commands offers insight into how dreadlord commanders direct their lesser minions on the Kalimdor front."},kw={"ashenvale","burning legion","diabolical plans","diathorus","dreadlord","forest song","gorgannon","vindicator vedaar"},rel={"npc:vindicator-vedaar","subzone:forest-song","zone:ashenvale"},m={start="Diabolical Plans (starter)",["end"]="Vindicator Vedaar",faction="Alliance",id=9520},src={"Diabolical Plans (Alliance)"}}
E["quest:9521"] = {t="quest",n="Report from the Northern Front",z="ashenvale",s="This errand connects the night elf outposts opposing the Warsong Outriders in Ashenvale. Sentinel Luciel Starwhisper at Forest Song asks a traveler to carry a critical military dispatch southwest to Sentinel Farsong at Silverwing Grove.",h="This errand connects the night elf outposts opposing the Warsong Outriders in Ashenvale.",sec={{t="A Divided Front",b="The night elves waging war against the Warsong Lumber Camp cannot afford to stay cooped up in a single redoubt. While Forest Song stands watch in eastern Ashenvale, the Silverwing Sentinels maintain their main forward command farther southwest at Silverwing Grove, watching the border with the Barrens. Communication between these outposts is vital to monitoring orc incursions.",sp=0},{t="Desperate Measures",b="Carrying Luciel Starwhisper's dispatch down to Silverwing Grove reveals grim news for the night elf defenders. According to the report, the Horde is not relenting under pressure; instead, every Silverwing advance prompts the orcs to strip and destroy as much of the ancient woodland as they can before retreating, escalating the conflict into a war of environmental attrition.",sp=0}},faq={{q="Where does this report need to go?",a="The report must be carried southwest across Ashenvale from Forest Song to Silverwing Grove, near the border with the Barrens, where Sentinel Farsong commands local Silverwing forces.",al={"where do i take the report","report destination","farsong location"}},{q="Why can't Sentinel Luciel deliver the report herself?",a="Luciel is already overdue sending her update, but she cannot risk leaving the outpost at Forest Song unattended while the Warsong orcs remain active nearby.",al={"why cant luciel go","why does luciel need help"}},{q="What is Silverwing Grove?",a="Silverwing Grove is a fortified night elf encampment in southwestern Ashenvale, near the Barrens border, serving as a primary command base for Sentinel operations against Horde aggression.",al={"what is silverwing grove","silverwing base"}},{q="What news does the report contain?",a="Luciel's report details escalating devastation by the Horde. Rather than backing down under pressure, the Warsong forces are accelerating their logging and doing as much damage to the forest as possible.",al={"what is in the report","report contents","what did luciel write"}},{q="Who is fighting at the Warsong Lumber Camp?",a="The Silverwing Sentinels are fighting the orcs of the Warsong clan, who have established a massive logging operation to fuel the Horde's expansion and resource needs.",al={"who is at warsong lumber camp","who are the sentinels fighting"}},{q="Why is the defense split between Forest Song and Silverwing Grove?",a="Forest Song watches the eastern front and the northern approaches, while Silverwing Grove anchors the defense near the southern border where reinforcements and supplies push up from the Barrens.",al={"why two bases","forest song and silverwing grove"}}},ang={["race:NightElf"]="Every dispatch between Sentinels carries the grim reality of Ashenvale's defilement, underscoring your people's fight to protect sacred woodlands from orcish axes.",["faction:Alliance"]="Carrying dispatches between these isolated frontier garrisons helps coordinate Alliance resistance against the Horde's territorial expansion."},kw={"ashenvale","forest song","luciel starwhisper","sentinel farsong","sentinel report","silverwing grove","warsong lumber camp"},rel={"npc:sentinel-luciel-starwhisper","npc:sentinel-farsong","subzone:silverwing-grove","subzone:forest-song","subzone:warsong-lumber-camp","zone:ashenvale","topic:horde","zone:barrens"},m={start="Sentinel Luciel Starwhisper",["end"]="Sentinel Farsong",level="25",faction="Alliance",id=9521},src={"Report from the Northern Front (BC Classic)"}}
E["quest:9533"] = {t="quest",n="A Helping Hand",z="ashenvale",s="A Helping Hand directs Alliance travelers toward eastern Ashenvale, where an ambitious construction effort is underway at Forest Song. Entrusted by Vindicator Palanaar, adventurers journey to reinforce Architect Nemos and his fellow builders as they rebuild a ruined outpost.",h="A Helping Hand directs Alliance travelers toward eastern Ashenvale, where an ambitious construction effort is...",sec={{t="A Beacon in Eastern Ashenvale",b="Eastern Ashenvale is a hostile frontier thick with satyrs, ferocious wild beasts, and Horde aggression pushed out from the Warsong logging operations. In response, an effort has begun to reclaim and revitalize Forest Song, an ancient night elf outpost that long stood quiet. Vindicator Palanaar directs capable travelers eastward to assist in fortifying the perimeter and laying the groundwork for a secure sanctuary.",sp=0},{t="Cooperation at Forest Song",b="The restoration of Forest Song is a shared venture overseen on the ground by Architect Nemos and Vindicator Vedaar. Working closely with their night elf allies, the builders aim to transform weather-worn elven foundations into a sturdy, enduring settlement. However, carving out a home in the ancient woods requires constant vigilance, abundant raw materials, and willing hands to turn back local threats while the work proceeds.",sp=0}},faq={{q="What is Forest Song?",a="Forest Song is an ancient night elf site located in eastern Ashenvale. Architect Nemos and Vindicator Vedaar are leading an effort to rebuild and revitalize the ruins into a functioning, fortified settlement with the cooperation of the kaldorei.",al={"forest song outpost","what is forest song","forest song ashenvale"}},{q="Who sends you to Forest Song?",a="Vindicator Palanaar offers the quest, directing capable Alliance adventurers across the forest to lend their strength to the construction efforts headed by Architect Nemos.",al={"quest giver","who gives a helping hand","vindicator palanaar"}},{q="Who is Architect Nemos?",a="Architect Nemos is the planner and overseer directing construction and restoration efforts at Forest Song. He coordinates building projects and relies on passing volunteers to secure the outpost and gather needed resources.",al={"nemos","who is nemos","architect nemos"}},{q="Why does Forest Song need outside help?",a="Eastern Ashenvale is surrounded by hostile forces, including corrupted satyrs, aggressive predators, and encroaching Horde lumber parties. Rebuilding the outpost requires defense and physical labor beyond what the small initial crew can supply alone.",al={"why need help","forest song danger","why help nemos"}},{q="Where is Forest Song located?",a="Forest Song lies nestled in the eastern woodlands of Ashenvale, situated east of Iris Lake and Astranaar along the route heading toward the border of Azshara.",al={"forest song location","where is forest song","how to find forest song"}},{q="Who works with Architect Nemos at the site?",a="Alongside Architect Nemos, Vindicator Vedaar helps oversee defense and operations at Forest Song, supported by local night elf allies who share an interest in reclaiming the ancient outpost.",al={"who is at forest song","vedaar and nemos","forest song leaders"}}},ang={["race:NightElf"]="Restoring Forest Song breathes new life into neglected kaldorei lands, fortifying the eastern woods against corruption and foreign intrusion.",["faction:Alliance"]="Establishing a firm foothold in eastern Ashenvale provides the Alliance with crucial strategic support to counter Horde territorial expansion and local threats."},kw={"architect nemos","ashenvale","forest song","helping hand","kaldorei","vindicator palanaar","vindicator vedaar"},rel={"subzone:forest-song","npc:architect-nemos","npc:vindicator-palanaar","npc:vindicator-vedaar","zone:ashenvale","topic:night-elf"},m={start="Vindicator Palanaar",["end"]="Architect Nemos",level="25",faction="Alliance",id=9533},src={"A Helping Hand (BC Classic)"}}
E["quest:9534"] = {t="quest",n="Destroy the Legion",z="ashenvale",s="Valusha at Splintertree Post orders Horde champions to strike back against lingering Burning Legion forces threatening the Warsong Lumber Camp. Lingering demons gather in the scarred canyons and hills of eastern Ashenvale, where Mannoroth once met his end.",h="Valusha at Splintertree Post orders Horde champions to strike back against lingering Burning Legion forces...",sec={{t="A Lingering Corruption",b="Though the Third War saw the defeat of the Burning Legion at Mount Hyjal, remnants of the demonic host still fester in Ashenvale's eastern ridges. The ground surrounding Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge remains blistered by fel energy, sustaining roaming felguards, fiery infernals, and ravenous lashers. These fiends frequently raid Horde operations, menacing the vital logging efforts of the Warsong Outriders.",sp=0},{t="Securing the Lumber Camp",b="The Warsong Lumber Camp is essential for supplying timber to build and fortify Orgrimmar. Demon incursions threaten not only the laborers but also the strategic foothold the Horde fights to maintain against the night elves. Stationed at Splintertree Post, Valusha directs warriors to thin the demonic ranks directly at their gathering grounds, crushing the assault before the lumber camp is overrun.",sp=0}},faq={{q="Why are there demons in Ashenvale?",a="During the Third War, the pit lord Mannoroth corrupted these lands with demonic blood, and the Legion staged massive armies throughout the forest. Although Archimonde was destroyed at Mount Hyjal, scattered demons, roving felguards, and summoned infernals still haunt the scarred eastern ridges.",al={"why demons ashenvale","burning legion ashenvale lore","felfire hill demons"}},{q="Who is Valusha?",a="Valusha is an orc warrior stationed at Splintertree Post. Fierce and aggressive, she coordinates strikes against threats encroaching on Horde holdings in Ashenvale, holding particular contempt for both demons and Alliance interlopers.",al={"valusha","who is valusha","splintertree questgiver"}},{q="Where are the demons attacking from?",a="The demons stage their attacks from the corrupted eastern reaches of Ashenvale, specifically across Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge, just south and east of the main road.",al={"demon locations","where to find demons","demon fall canyon location"}},{q="Why does the Horde care about these demons?",a="Demonic warbands regularly raid the Warsong Lumber Camp. The timber gathered there is critical for constructing Orgrimmar and maintaining the Horde's presence, making any disruption an existential threat to their war effort in Kalimdor.",al={"why fight demons here","warsong lumber camp threat"}},{q="What is the history behind Demon Fall Canyon?",a="Demon Fall Canyon is the historic site where Grommash Hellscream and Thrall confronted the pit lord Mannoroth. Grom struck down the demon lord at the cost of his own life, freeing the orcish race from the blood curse. The surrounding terrain still bears the taint of Mannoroth's dying burst of fel power.",al={"demon fall canyon history","mannoroth death place"}},{q="What kinds of demons are being targeted?",a="The task focuses on eliminating the front-line shock troops of the remnants: brutal Roaming Felguards, animated Searing Infernals, and the fel-infused plant horrors known as Mannoroc Lashers.",al={"which demons","types of demons to kill","target demons"}}},ang={["faction:Horde"]="Defending the Warsong Lumber Camp preserves the Horde's principal source of construction timber in Kalimdor while asserting military strength in Ashenvale.",["race:Orc"]="For orcs, slaying demons in the very canyons where Grommash Hellscream died defeating Mannoroth is both a matter of personal honor and proof of their hard-won freedom from the blood curse.",["class:Warrior"]="Facing massive felguards and searing stone infernals offers frontline combatants a brutal test of resolve against adversaries far more resilient than woodland sentinels.",["class:Warlock"]="The chaotic concentrations of roaming demons and fel energy in eastern Ashenvale provide a firsthand look at unsupervised Legion remnants running wild without a master."},kw={"burning legion","demon fall canyon","demon fall ridge","felfire hill","felguard","infernal","mannoroc lasher","mannoroth","splintertree post","valusha","warsong lumber camp"},rel={"subzone:splintertree-post","subzone:warsong-lumber-camp","subzone:demon-fall-canyon","subzone:felfire-hill","subzone:demon-fall-ridge","npc:valusha","topic:burning-legion","zone:ashenvale"},m={start="Valusha",level="30",faction="Horde",id=9534},src={"Destroy the Legion (BC Classic Horde)"}}
E["quest:9535"] = {t="quest",n="Diabolical Plans",z="ashenvale",s="Recovered from a demon in eastern Ashenvale, this parchment outlines an imminent demonic assault against Splintertree Post. Shockingly composed in the Orcish tongue, the orders reveal that the infamous dreadlords Diathorus and Gorgannon are coordinating forces against the Horde's forest outpost.",h="Recovered from a demon in eastern Ashenvale, this parchment outlines an imminent demonic assault against...",sec={{t="A Written Threat",b="While demons typically rely on raw carnage and fel dominance, this fallen parchment reveals deliberate strategy. The orders are penned in Orcish—a chilling testament to how intimately the Burning Legion understands its former thralls. The text explicitly outlines preparations for an organized strike on Splintertree Post to the northwest, proving the local fiends are acting under unified, calculating commanders.",sp=0},{t="Shadows of the Dreadlords",b="The recovered parchment specifically names Diathorus the Seeker and Gorgannon, two notorious dreadlords wielding dominion over the demonic forces lurking among the ruins and barrows of eastern Ashenvale. Rather than mindless remnants from the Third War, these nathrezim are actively organizing surviving satyrs, felguards, and cultists to push the Horde entirely out of the woods.",sp=0},{t="A Call to Arms at Splintertree",b="Splintertree Post serves as the Horde's vital bastion in central Ashenvale, constantly besieged by enraged night elves and woodland beasts. Word of an impending demonic offensive threatens to crush the outpost between two fronts. Delivering the plans into the hands of Valusha alerts the garrison to the impending strike, galvanizing the defenders to mount a preemptive counterattack before the dreadlords can march.",sp=1}},faq={{q="What are the Diabolical Plans?",a="They are strategic invasion orders dropped by a demon in Ashenvale. The parchment describes military preparations for a targeted demonic assault aimed at destroying the Horde encampment at Splintertree Post.",al={"what are the plans","diabolical plans explained","what does the scroll say"}},{q="Why are the demon plans written in Orcish?",a="The Burning Legion spent generations manipulating and enslaving the orcs through the blood curse. The dreadlords are master infiltrators who understand Orcish fluently, enabling them to draft orders that communicate precise targets or mock their intended prey.",al={"why orcish","who wrote the plans in orcish","how do demons know orcish"}},{q="Who are Diathorus and Gorgannon?",a="Diathorus the Seeker and Gorgannon are two dreadlords directing the remaining demonic forces in eastern Ashenvale. From tainted sanctuaries like the Fire Scar Shrine and Laughing Sister barrows, they coordinate remnants of the Legion to terrorize mortal settlements.",al={"who is diathorus","who is gorgannon","who are the dreadlords in ashenvale"}},{q="Who should receive these plans?",a="Take the parchment to Valusha, an orc officer stationed at Splintertree Post to the northwest. She organizes the garrison's defense against local threats and will prepare a counter-strike against the dreadlords.",al={"who do i turn diabolical plans in to","where to take diabolical plans"}},{q="Why is the Legion targeting Splintertree Post?",a="Splintertree Post is the primary Horde outpost securing the forest interior. Eliminating it would shatter the Horde presence in central Ashenvale, leaving the region fractured and defenseless against dreadlord domination.",al={"why attack splintertree","what do the demons want with splintertree"}},{q="What happens after giving the plans to Valusha?",a="Enraged that the dreadlords dare plot against the outpost, Valusha refuses to cower behind palisades. She rallies the garrison to strike first, sending heroes directly into demon territory to eliminate Diathorus and Gorgannon.",al={"what is the follow up quest","never again quest","what does valusha do"},sp=1}},ang={["faction:Horde"]="Splintertree Post already faces intense pressure from the Sentinel army. Discovering that dreadlords are orchestrating a second front makes securing the post's borders an urgent priority.",["race:Orc"]="Finding demonic plans written in the orc mother tongue is a bitter reminder of the Legion's historical corruption and lingering shadow over the orcish people.",["class:Warlock"]="The nathrezim remain master tacticians of fel sorcery; deciphering their battlefield orders gives insight into the command hierarchy of rogue demons in Kalimdor."},kw={"ashenvale","burning legion","diabolical plans","diathorus","dreadlords","fel","gorgannon","nathrezim","orcish","splintertree post","valusha"},rel={"subzone:splintertree-post","npc:valusha","quest:9536","zone:ashenvale"},m={start="Diabolical Plans (starter)",["end"]="Valusha",level="30",faction="Horde",id=9535},src={"Diabolical Plans (BC Classic)"}}
E["quest:9536"] = {t="quest",n="Never Again!",z="ashenvale",s="Never Again! is a Horde strike mission originating from Splintertree Post in Ashenvale. Prompted by intercepted demonic orders, champions are sent to eradicate two Burning Legion dreadlords commanding the hostile forces near the site of Mannoroth's demise.",h="Never Again!",sec={{t="Decapitating the Legion",b="Following the discovery of intercepted invasion schemes, the defenders at Splintertree Post refuse to wait for a demonic assault to materialize. The Burning Legion's lesser minions lack cohesive direction without cunning minds to bind them. By dispatching Gorgannon and Diathorus the Seeker, the Horde aims to shatter the fiends' chain of command before an army can marshal in the southern woods.",sp=0},{t="Shadows over Demon Fall",b="The targets lurk within Demon Fall Canyon and Demon Fall Ridge, the cursed expanse where Grom Hellscream sacrificed his life to slay the pit lord Mannoroth. Gorgannon lingers near the shattered remnants of Mannoroth's spear, while Diathorus makes his redoubt inside an overrun barrow den atop the nearby ridge. Slaying them on the very ground where orcs won their freedom serves as an emphatic declaration that the Horde will never submit to demonic bondage again.",sp=0}},faq={{q="Who orders the deaths of these dreadlords?",a="Valusha, an orc stationed at Splintertree Post in Ashenvale, issues the command after reviewing intercepted demonic battle plans.",al={"who gives never again","never again quest giver","valusha quest"}},{q="Why is this mission named 'Never Again!'?",a="The phrase refers directly to the blood curse that previously enslaved the orcish race to the Burning Legion. Slaying dreadlords in the very canyon where Mannoroth died reaffirms that the Horde will never fall under demonic mastery again.",al={"why never again","never again meaning","never again lore"}},{q="Where can Gorgannon be found?",a="Gorgannon is located in Demon Fall Canyon south of Felfire Hill, lingering near the shattered pieces of Mannoroth's floating weapon.",al={"where is gorgannon","gorgannon location","find gorgannon"}},{q="Where is Diathorus the Seeker located?",a="Diathorus the Seeker resides inside a barrow den on Demon Fall Ridge, accessible by a trail winding up from the canyon near Grom Hellscream's memorial.",al={"where is diathorus","find diathorus","diathorus location"}},{q="What happens to the remaining demons once their commanders fall?",a="According to Valusha, lesser demonic minions are largely mindless without dreadlord oversight, meaning the loss of Gorgannon and Diathorus effectively neutralizes their coordinated invasion threat.",al={"demons after commanders die","why kill dreadlords"}},{q="What prior task leads up to this mission?",a="It is the direct continuation of Diabolical Plans, in which an adventurer intercepts written directives from the demons operating in Ashenvale and brings them to Splintertree Post.",al={"quest prerequisite","never again prequest","diabolical plans followup"}}},ang={["faction:Horde"]="Striking down dreadlords on the sacred ground of Grom Hellscream's sacrifice is a profound matter of honor and defiance against the ancient masters who once enslaved the orcish people.",["class:Warlock"]="Warlocks who delve into fel secrets must confront the reality of Legion commanders who actively attempt to reclaim servitude over Azeroth's races."},kw={"ashenvale","burning legion","demon fall canyon","demon fall ridge","diathorus","dreadlord","gorgannon","mannoroth","never again","splintertree post","valusha"},rel={"quest:9520","npc:valusha","subzone:demon-fall-canyon","subzone:demon-fall-ridge","subzone:splintertree-post","topic:burning-legion","topic:horde","zone:ashenvale"},m={start="Valusha",level="32",faction="Horde",id=9536},src={"Never Again! (BC Classic)"}}
E["quest:976"] = {t="quest",n="Supplies to Auberdine",z="ashenvale",s="Supplies to Auberdine is an escort mission where Alliance adventurers protect Feero Ironhand as he carries critical provisions and messages from Maestra's Post northward toward Darkshore. Given the growing menace radiating from the Tower of Althalaxx and the presence of hostile infiltrators in Ashenvale, safe passage cannot be taken for granted.",h="Supplies to Auberdine is an escort mission where Alliance adventurers protect Feero Ironhand as he carries...",sec={{t="A Perilous Road North",b="Maestra's Post sits on the western frontier of Ashenvale, a quiet outpost caught between the wild tensions of the forest and the troubled lands of Darkshore. Following investigations into the sinister activity surrounding the Tower of Althalaxx, Delgren the Purifier gathers vital supplies and intelligence bound for Sentinel Starbreeze in Auberdine. Rather than risking solitary couriers, the outpost relies on armed escorts to accompany Feero Ironhand as he treks along the forest road.",sp=0},{t="Shadows Along the Trail",b="The journey reveals just how compromised the wilderness around the road has become. Feero's route is beset by coordinated ambushes. Cultists of the Dark Strand seek to silence any reports regarding their demonic rituals, Forsaken scouts stalk the woodland underbrush, and vicious commanders such as Balizar the Umbrage, Aligar the Tormentor, and Caedakar the Vicious attempt to cut down the caravan before it reaches the border.",sp=1}},faq={{q="Who is Feero Ironhand?",a="Feero Ironhand is a dwarven courier stationed at Maestra's Post in western Ashenvale. Entrusted by Delgren the Purifier to carry important messages and logistical aid to Auberdine, he is cautious enough to refuse to travel without capable bodyguards.",al={"feero","feero ironhand lore","who is the dwarf escort"}},{q="Why does Auberdine need these supplies?",a="Darkshore and northern Ashenvale face rising corruption and threats from demonic cultists operating out of the Tower of Althalaxx. The night elf Sentinels stationed in Auberdine, led locally by figures like Sentinel Starbreeze, need fresh provisions and up-to-date intelligence to maintain their defense of the coast.",al={"why send supplies to auberdine","auberdine supplies","sentinel starbreeze"}},{q="Who attacks Feero along the road?",a="The escort is intercepted by three waves of hostile forces: Dark Strand assassins affiliated with the cult at the Tower of Althalaxx, Forsaken scouts prowling the woods, and a strike team led by Balizar the Umbrage, Aligar the Tormentor, and Caedakar the Vicious.",al={"who ambushes feero","feero ambushers","who attacks on the road"}},{q="Why are Forsaken scouts in western Ashenvale?",a="Forsaken agents have been actively scouting Kalimdor's northern forests, seeking opportunities and monitoring Alliance movements. In Ashenvale, their scouts operate in the shadows, ready to eliminate Alliance couriers and exploit the instability caused by local cults.",al={"forsaken in ashenvale","undead ambush","why undead here"}},{q="What is the connection to the Tower of Althalaxx?",a="Delgren the Purifier has been orchestrating efforts to uncover and disrupt the dark rituals of the cultists at the Tower of Althalaxx. This escort is the culmination of that investigative chain, ensuring that intelligence and vital support reach the Night Elf leadership in Auberdine.",al={"althalaxx connection","tower of althalaxx","delgren connection"}},{q="Where do I report after protecting Feero?",a="After seeing Feero safely through the ambushes in Ashenvale, you report back to Delgren the Purifier at Maestra's Post to confirm the delivery succeeded.",al={"turn in supplies to auberdine","where do i go after escorting feero","quest turn in"}}},ang={["faction:Alliance"]="Safeguarding this corridor ensures that the outposts in Ashenvale remain connected to Auberdine's logistical hub, preserving the Alliance's fragile hold on northern Kalimdor.",["race:NightElf"]="The supplies and dispatches sent north directly aid the Sentinels in Auberdine as they contend with growing darkness across Darkshore and along the Ashenvale border.",["race:Dwarf"]="Feero Ironhand represents Ironforge's willingness to support Kaldorei allies deep within unfamiliar, dangerous ancient forests."},kw={"ashenvale","auberdine","balizar the umbrage","darkshore","delgren the purifier","feero ironhand","maestra's post","sentinel starbreeze","tower of althalaxx"},rel={"npc:delgren-the-purifier","npc:feero-ironhand","subzone:maestra-s-post","subzone:auberdine","quest:965","subzone:tower-of-althalaxx","zone:ashenvale","zone:darkshore"},m={start="Feero Ironhand",["end"]="Delgren the Purifier",level="24",faction="Alliance",id=976},src={"Supplies to Auberdine"}}
E["quest:990"] = {t="quest",n="Trek to Ashenvale",z="ashenvale",s="Trek to Ashenvale is an Alliance journey quest directing seasoned adventurers south from Darkshore into the primeval forests of Ashenvale. Dispatched by Sentinel Selarin after operations near the border, travelers are sent to report to Raene Wolfrunner in the town of Astranaar, where the Sentinels struggle against spreading corruption.",h="Trek to Ashenvale is an Alliance journey quest directing seasoned adventurers south from Darkshore into the...",sec={{t="Leaving the Coast",b="Having assisted Sentinel Selarin along the southern border of Darkshore, travelers leave behind the somber gray beaches and shadowed ruins of the coastline. The Sentinel recognizes capable fighters and scouts who can hold their own, pointing them directly toward the heart of night elf woodland territory. With local threats in Darkshore handled, attention turns toward the far greater perils encroaching from the south.",sp=0},{t="The Road to Astranaar",b="The path southward follows an ancient night elf road winding through the dense ancient canopies of Ashenvale. Raene Wolfrunner, leader of the Sentinels stationed in Astranaar, has put out an urgent call for reinforcements. Between demonic taints, rampant wildlife, and external incursions into ancestral lands, the Sentinels in Astranaar are stretched thin and require outside aid to maintain their hold on the sacred forest.",sp=0}},faq={{q="Who sends you on this trek?",a="Sentinel Selarin, a night elf sentinel stationed in southern Darkshore, directs you south toward Astranaar once you have proven your capabilities along the border.",al={"quest giver","who starts trek to ashenvale","selarin"}},{q="Who is Raene Wolfrunner?",a="Raene Wolfrunner is the head Sentinel commander residing in Astranaar, responsible for organizing the defense of Ashenvale and coordinating efforts to stem the corruption afflicting the forest.",al={"raene","wolfrunner","astranaar leader"}},{q="Why are adventurers being sent to Ashenvale?",a="The ancient forests of Ashenvale are succumbing to spreading corruption and mounting external threats. The local night elf sentinels are overwhelmed and urgently need capable allies to assist the citizens and defenders of Astranaar.",al={"why ashenvale","what is happening in ashenvale","corruption ashenvale"}},{q="Is the road between Darkshore and Ashenvale safe?",a="Sentinel Selarin specifically advises sticking close to the road. Wandering off the path into the deep woods exposes travelers to aggressive predators, satyrs, and hostile forces that roam the untamed borders.",al={"road safety","ashenvale road safe"}},{q="What should I do upon arriving in Astranaar?",a="After reporting directly to Raene Wolfrunner, she advises speaking with the other residents and defenders throughout Astranaar, as many of them require immediate aid dealing with local crises.",al={"what to do in astranaar","astranaar arrival"}},{q="What level of adventurer is this intended for?",a="This journey typically marks a graduation from Darkshore around level 19, transitioning intermediate adventurers into the broader and more contested frontier of Ashenvale.",al={"what level","level requirement"}}},ang={["race:NightElf"]="For night elves, this journey is a return into the sacred heartland of Kalimdor, answering the call of your sisters to protect ancient holy grounds from unnatural rot.",["faction:Alliance"]="As an Alliance champion, answering Astranaar's call strengthens ties with the night elves and shores up the faction's primary foothold in northern Kalimdor."},kw={"ashenvale","astranaar","darkshore","night elf","raene wolfrunner","sentinel selarin","trek to ashenvale"},rel={"npc:raene-wolfrunner","npc:sentinel-selarin","subzone:astranaar","zone:ashenvale","zone:darkshore","quest:938"},m={start="Sentinel Selarin",["end"]="Raene Wolfrunner",level="19",faction="Alliance",id=990},src={"Trek to Ashenvale"}}
E["quest:991"] = {t="quest",n="Raene's Cleansing",z="ashenvale",s="Raene's Cleansing begins when Raene Wolfrunner asks an adventurer to track down her missing friend, Teronis. Seeking a way to halt the rampant furbolg aggression across Ashenvale, Teronis set off toward Lake Falathim to recover a magic gemstone.",h="Raene's Cleansing begins when Raene Wolfrunner asks an adventurer to track down her missing friend, Teronis.",sec={{t="A Friend's Concern",b="Raene Wolfrunner serves alongside the Sentinels in Astranaar, defending Ashenvale against mounting threats. Among her closest companions was Teronis, who took it upon himself to find a potent defense against the increasingly violent furbolg tribes. When days passed without his return, Raene grew deeply worried, unable to abandon her post while fearing the worst.",sp=0},{t="The Quest for the Rod",b="Teronis pursued rumors of a powerful rod forged by a deceased, wicked wizard, believing its magic could quell the furbolg fury. To restore the artifact, he required an enchanted gem hidden within an elven shrine at Lake Falathim, located near the mountains to the west. Unfortunately, the tranquil waters had recently fallen to aggressive murloc tribes.",sp=0},{t="Tragedy at Lake Falathim",b="Following Teronis's trail to the island within Lake Falathim reveals a grim sight. Teronis never made it out of the waters alive; his body lies slain upon the shrine, covered in deep slashes delivered by murloc weapons and claws, marking an untimely end to his search.",sp=1}},faq={{q="Who is Raene Wolfrunner?",a="Raene Wolfrunner is a night elf allied with the Sentinels of Ashenvale, stationed in Astranaar. She oversees various defensive efforts to protect the forest from encroaching enemies.",al={"raene","who is raene","quest giver"}},{q="Who was Teronis?",a="Teronis was a close friend of Raene Wolfrunner who sought ancient magical solutions to save the forest. Believing an enchanted rod could calm the corrupted furbolgs, he journeyed alone to secure its components.",al={"who is teronis","teronis background","missing friend"}},{q="Where did Teronis go missing?",a="Teronis vanished at Lake Falathim, a body of water situated at the foot of the western mountains in Ashenvale, which had become overrun by hostile murlocs.",al={"where is teronis","teronis location","lake falathim"}},{q="Why was Teronis looking for a gem?",a="The gem was a vital component needed to empower a magic rod crafted by a deceased evil wizard. Teronis hoped the rod's power could be repurposed to stem the attacks of enraged furbolgs.",al={"what gem","why gem","teronis gem"}},{q="What killed Teronis?",a="Teronis was slaughtered by the murlocs dwelling around Lake Falathim. Deep lacerations from crude blades and talons cover his remains on the island shrine.",al={"how did teronis die","teronis killer","who killed teronis"},sp=1},{q="Why are the furbolgs attacking Ashenvale?",a="The furbolgs of Ashenvale have succumbed to demonic corruption and madness in the wake of the Third War, driving once-peaceful tribes into relentless, violent hostility against their old allies.",al={"furbolg attacks","why furbolgs aggressive","furbolg madness"}}},ang={["race:NightElf"]="The loss of Teronis is another bitter blow to the night elves, who are already stretched thin trying to heal Ashenvale and protect their shrines from corruption.",["faction:Alliance"]="Alliance recruits arriving in Astranaar quickly learn that Ashenvale's sacred groves are under siege by hostile wild beasts, furbolgs, and invasive murlocs."},kw={"ashenvale","falathim","furbolg","gem","murloc","raene","teronis","wolfrunner"},rel={"npc:raene-wolfrunner","npc:teronis-corpse","subzone:lake-falathim","zone:ashenvale","topic:furbolg","topic:murloc","topic:sentinels"},m={start="Raene Wolfrunner",["end"]="Teronis' Corpse",level="19",faction="Alliance",id=991},src={"Raene's Cleansing"}}
E["subzone:astranaar"] = {t="subzone",n="Astranaar",z="ashenvale",s="Astranaar is the primary Night Elf settlement in central Ashenvale, built across a serene lake island straddling the ancient forest road. Serving as the beating heart of Alliance operations in the region, it provides vital refuge to travelers facing encroaching threats from hostile furbolgs, satyrs, and the Horde.",h="Astranaar is the primary Night Elf settlement in central Ashenvale, built across a serene lake island...",sec={{t="Heart of the Forest",b="Situated atop an island in the middle of a forest lake, Astranaar stands as the largest night elven settlement in Ashenvale. Connected to the mainland by wooden footbridges spanning the waters, the town houses sentinels, priests, and artisans who keep vigil over the woodlands. In addition to offering basic comforts such as an inn, traders, and an expert leatherworker, its elevated perches host a flight master providing hippogryph travel to distant outposts across Kalimdor.",sp=0},{t="A Bastion Under Siege",b="Despite its tranquil waters and glowing lanterns, Astranaar exists in a state of perpetual readiness. Local leaders like Raene Wolfrunner coordinate patrols and defensive actions against the corrupted Thistlefur furbolgs encroaching from the north, fearful they may mount a direct assault on the settlement. The town also bears quiet historical sorrow: across the lake in the cemetery lies the resting place of Valstann Staghelm, who fell millennia ago during the War of the Shifting Sands.",sp=0}},faq={{q="What services are available in Astranaar?",a="Astranaar offers a full suite of amenities for Alliance travelers, including an inn, general goods vendors, an expert leatherworking trainer, and a flight master connecting to key outposts throughout Ashenvale and Kalimdor.",al={"astranaar amenities","what is in astranaar","astranaar flight master"}},{q="Who is buried in the graveyard across the lake?",a="The cemetery by the lake contains the tomb of Valstann Staghelm, son of Archdruid Fandral Staghelm, who was slain during the ancient War of the Shifting Sands against the Qiraji in Silithus.",al={"astranaar grave","valstann staghelm grave","who is buried here"}},{q="Why are the Sentinels in Astranaar worried about the local furbolgs?",a="The Thistlefur furbolgs to the north have fallen under dark, corrupting influences. Sentinel Raene Wolfrunner fears that left unchecked, their growing aggression will embolden them to mount an open assault against Astranaar itself.",al={"thistlefur threat","why fight furbolgs","raene wolfrunner quest"}},{q="Can Horde players visit Astranaar safely?",a="No. Astranaar is a heavily fortified Alliance stronghold guarded by armed Night Elf Sentinels who will attack Horde members on sight.",al={"is astranaar friendly to horde","horde in astranaar"}}},ang={["race:NightElf"]="For the Kaldorei, Astranaar is the central bastion of their ancient homeland in central Kalimdor, safeguarding sacred groves and housing the grave of fallen hero Valstann Staghelm.",["faction:Alliance"]="Astranaar serves as the Alliance's command post and primary logistical hub while maneuvering through the contested wilderness of Ashenvale."},kw={"ashenvale","astranaar","kalimdor","night elf","raene wolfrunner","sentinels","thistlefur","valstann staghelm"},rel={"zone:ashenvale","npc:raene-wolfrunner","quest:1054","quest:9432","subzone:forest-song","subzone:stardust-spire","topic:furbolg","topic:alliance"},src={"Astranaar"}}
E["subzone:bathran-s-haunt"] = {t="subzone",n="Bathran's Haunt",z="ashenvale",s="Bathran's Haunt is an ancient kaldorei ruin nestled in northwestern Ashenvale, east of the Zoram Strand. Recently, Forsaken herbalists and their guardians have overtaken the site to harvest local flora for their alchemical research, steadily withering the surrounding woodland.",h="Bathran's Haunt is an ancient kaldorei ruin nestled in northwestern Ashenvale, east of the Zoram Strand.",sec={{t="A Blighted Refuge in the Ancient Woods",b="North of the Ruins of Ordil'Aran, crumbling night elf pillars stand swallowed by thick Ashenvale foliage. What was once a tranquil kaldorei relic has fallen under the shadow of the Forsaken. Skulking among the broken marble, undead herbalists and their enforcers have set up a crude open-air laboratory. Their presence alone blights the ancient soil: grass rots into a sickly brown, vibrant blossoms wilt, and an unnatural decay creeps through the grove as they methodically harvest rare woodland reagents for their experiments.",sp=0},{t="The Harvest of Bathran's Hair",b="The primary draw of these ruins is Bathran's Hair, a unique remedial herb found taking root only among these particular stones. While night elf and Alliance scouts view the Forsaken presence as a vile desecration of sacred elven soil, the undead work diligently to extract the plant's potent properties. The Horde maintains a vested interest in the compound's botanical yield, though the Forsaken's secretive methods and the resulting corruption of the earth draw suspicion from outsiders and allies alike.",sp=0}},faq={{q="Where is Bathran's Haunt located?",a="Bathran's Haunt sits in northwestern Ashenvale, positioned directly north of the Ruins of Ordil'Aran and inland to the east of the Zoram Strand.",al={"where is bathrans haunt","bathrans haunt location","how to get to bathrans haunt"}},{q="Why are the Forsaken here?",a="Forsaken herbalists have established an encampment and laboratory among the ruins to gather and study the unique botanical life of the forest, most notably a rare remedial plant known as Bathran's Hair.",al={"what are undead doing in ashenvale","why are forsaken at bathrans haunt","forsaken purpose bathran"}},{q="What is Bathran's Hair?",a="Bathran's Hair is a distinctive, valuable herb with potent restorative qualities that grows exclusively around the crumbling stonework of Bathran's Haunt.",al={"bathrans hair plant","what is bathrans hair","bathran herb"}},{q="Why is the ground dying around the ruins?",a="The prolonged presence and alchemical activities of the Forsaken have corrupted the immediate area, causing the grass to wither brown and delicate woodland flowers to die.",al={"why is grass brown here","blight in bathrans haunt","why is the land decaying"}}},ang={["race:NightElf"]="The Forsaken encampment at Bathran's Haunt is an outrage to kaldorei heritage, where undead intruders defile ancient elven stonework and blight the sacred soil.",["profession:Herbalism"]="The ruins are botanically unique as the only known habitat for Bathran's Hair, an herb sought after for its rare remedial properties."},kw={"ashenvale","bathran's hair","bathran's haunt","forsaken","herbalism","kaldorei ruins","ruins of ordil'aran","zoram strand"},rel={"zone:ashenvale","quest:1010","subzone:ruins-of-ordil-aran","subzone:zoram-strand","topic:forsaken","topic:horde","topic:alliance"},src={"Bathran's Haunt"}}
E["subzone:blackfathom-camp"] = {t="subzone",n="Blackfathom Camp",z="ashenvale",s="Blackfathom Camp is a small Alliance outpost tucked away in the northwestern forests of Ashenvale. Led by Talen, the camp sits between the Horde-held Zoram'gar Outpost and the sunken ruins of Blackfathom Deeps. It serves as a forward staging ground for Alliance travelers keeping watch over the nearby coast.",h="Blackfathom Camp is a small Alliance outpost tucked away in the northwestern forests of Ashenvale.",sec={{t="A Precarious Foothold",b="Perched on the bluffs southeast of the entrance to Blackfathom Deeps, this humble campsite gives Alliance scouts an eye on both the ancient coastal temple and the nearby Horde outpost of Zoram'gar. Led on the ground by Talen, the camp provides weary adventurers with a brief respite in the contested wildlands of Ashenvale, where cultists, naga, and Warsong raiders all vie for control.",sp=0}},faq={{q="What is Blackfathom Camp?",a="Blackfathom Camp is a small Alliance campsite situated on the northwest coast of Ashenvale. It acts as a forward lookout near Blackfathom Deeps and keeps tabs on the nearby Horde post at Zoram'gar Outpost.",al={"blackfathom camp purpose","what is this camp","alliance camp ashenvale beach"}},{q="Who leads Blackfathom Camp?",a="The camp is under the watch of Talen, who oversees the small outpost and coordinates Alliance efforts in the area.",al={"who is in charge here","camp leader","who is talen"}},{q="Why is this camp so close to Zoram'gar Outpost?",a="The coastline of the Zoram Strand is a hotly contested front in Ashenvale. The camp sits in a precarious position, allowing the Alliance to monitor Horde maneuvers coming out of Zoram'gar Outpost while investigating the corruption radiating from the ruins of Blackfathom Deeps.",al={"why near horde","zoramgar proximity","horde camp nearby"}}},ang={["faction:Alliance"]="For Alliance forces delving into the sunken temple of Blackfathom Deeps or patrolling the hostile Zoram Strand, this small camp serves as the closest safe haven in the northwestern woods.",["faction:Horde"]="Situated just up the coast from Zoram'gar Outpost, this camp represents a persistent Alliance presence watching your movements along the strand."},kw={"ashenvale","blackfathom camp","blackfathom deeps","talen","zoram strand","zoram'gar"},rel={"zone:blackfathom","subzone:zoram-gar-outpost","npc:talen","zone:ashenvale","topic:alliance"},src={"Blackfathom Camp"}}
E["subzone:blackfathom-deeps"] = {t="subzone",n="Blackfathom Deeps",z="ashenvale",s="Blackfathom Deeps is a flooded subterranean temple ruin buried beneath the Zoram Strand along Ashenvale's northwestern coast. Once a glorious house of worship dedicated to the moon goddess Elune, its drowned halls have been overtaken by naga, satyr, and the sinister Twilight's Hammer cult.",h="Blackfathom Deeps is a flooded subterranean temple ruin buried beneath the Zoram Strand along Ashenvale's...",sec={{t="From Elune's Temple to Darkest Abyss",b="Before the Great Sundering shattered ancient Kalimdor ten thousand years ago, this complex was known as Lathar'Lazal, the \"Seat of the Sky.\" Dedicated to the goddess Elune, its gem-encrusted bridges, sacred lakes, and moonwell were constructed under the personal supervision of Queen Azshara. When the Well of Eternity collapsed, the magnificent shrine sank beneath the ocean waves, presumed lost forever. Over millennia, receding shorelines and subterranean shifting left its remains partly flooded beneath the cliffs of Ashenvale.",sp=0},{t="The Rise of Aku'mai",b="In recent years, an insidious rot reached the temple's forgotten moonwell as Old God corruption seeped upward from the deep earth. Drawn by dark dreams and whispers, the Twilight's Hammer cult established a stronghold within the drowned ruins under the command of Twilight Lord Kelris. The cultists tend and nurture Aku'mai the Devourer, a monstrous three-headed hydra cherished by their ancient patrons. Alongside visiting naga headed by Lady Sarevess and prowling satyr, the cult conducts foul sacrificial rites in hopes of unleashing their beast upon the surface world.",sp=1}},faq={{q="What was Blackfathom Deeps originally built for?",a="Originally named Lathar'Lazal, it was an elven temple dedicated to the moon goddess Elune. It featured crystal-clear pools, gem-adorned architecture, and a sacred moonwell overseen by the ancient Highborne before it sank beneath the waves during the Sundering.",al={"bfd history","what was blackfathom deeps","lathar'lazal"}},{q="Why is the Twilight's Hammer cult here?",a="Guided by dark whispers and nightmares, the Twilight's Hammer came to worship and feed Aku'mai, a primeval hydra favored by the Old Gods. Led by Twilight Lord Kelris, the cult feeds captives and innocents to the beast to hasten its awakening.",al={"why are cultists in bfd","twilight's hammer blackfathom","kelris goal"}},{q="Where is the entrance located?",a="The entrance is tucked inside cavernous ruins along the Zoram Strand, located on the far northwestern coast of Ashenvale. Adventurers must navigate through submerged chambers and hostile naga outposts to reach the temple portal.",al={"where is bfd","blackfathom deeps location","how to enter bfd"}},{q="Who is Ghamoo-ra?",a="Ghamoo-ra was one of the last peaceful ancient creatures inhabiting the sunken temple. Upon claiming the ruins, the Twilight's Hammer cult captured the giant turtle and tormented it for years, driving it mad to serve as a vicious guard beast.",al={"giant turtle boss","ghamoo-ra lore","tortoise bfd"}}},ang={["race:NightElf"]="The desecration of Lathar'Lazal is a profound grievance for the Kaldorei, who mourn the defilement of a once-sacred shrine of Elune and its moonwell by void cultists and naga.",["faction:Horde"]="The Horde maintains a blood debt against the deeps; an earlier scouting venture into the ruins ended in disaster, with only the Darkspear scout Hekazi and Rokhan barely escaping with their lives."},kw={"aku'mai","blackfathom","deeps","ghamoo-ra","kelris","lathar'lazal","sarevess","twilight's hammer","zoram strand"},rel={"zone:blackfathom","zone:ashenvale","subzone:zoram-strand","npc:twilight-lord-kelris","npc:aku-mai","npc:lady-sarevess","npc:ghamoo-ra-classic","topic:twilight-s-hammer"},src={"Blackfathom Deeps"}}
E["subzone:bloodtooth-camp"] = {t="subzone",n="Bloodtooth Camp",z="ashenvale",s="Bloodtooth Camp is an encampment of hostile, corrupted furbolgs tucked into central Ashenvale, situated just west of the Falfarren River. Led by the chieftain Ran Bloodtooth, these once-peaceful creatures have succumbed to dark madness and attack anyone who approaches. The camp is a primary target for Alliance scouts working to cleanse the surrounding woodlands.",h="Bloodtooth Camp is an encampment of hostile, corrupted furbolgs tucked into central Ashenvale, situated just...",sec={{t="A Corrupted Den",b="Nestled southwest of the southern Moonwell and west of the Falfarren River, Bloodtooth Camp serves as a stark reminder of Ashenvale's encroaching decay. The furbolgs living here were once connected to the sacred wilderness of Kalimdor, but a lingering spiritual corruption has consumed their tribe. Under the command of Ran Bloodtooth, they guard their crude settlement with rabid hostility, turning upon travelers and night elven protectors alike.",sp=0},{t="Cleansing the Forest",b="Because Ran Bloodtooth's band poses an immediate danger to nearby sacred sites, Alliance sentinels and their allies cannot ignore the camp. As part of efforts to restore harmony to the forest—namely aiding Raene Wolfrunner's cleansing endeavors—adventurers are directed by Krolg to infiltrate the camp, cut down Ran Bloodtooth, and put an end to his ferocious bodyguards.",sp=1}},faq={{q="Where is Bloodtooth Camp located?",a="Bloodtooth Camp is situated in central Ashenvale, directly west of the Falfarren River and just southwest of the southern Moonwell.",al={"bloodtooth camp location","where is bloodtooth camp","find bloodtooth camp"}},{q="Why are the furbolgs here hostile?",a="Like many furbolg tribes across Ashenvale, the Bloodtooth clan has fallen victim to a dark demonic corruption lingering in the wilderness. It drives them into madness and boundless aggression toward all outsiders.",al={"why are bloodtooth furbolgs attacking","bloodtooth corruption","are furbolgs evil here"}},{q="Who leads the furbolgs at Bloodtooth Camp?",a="The camp is ruled by Ran Bloodtooth, a fierce chieftain who commands the local furbolgs alongside his personal cadre of bodyguards.",al={"bloodtooth camp boss","ran bloodtooth","who leads bloodtooth camp"}},{q="Why does the Alliance send scouts here?",a="During the efforts surrounding Raene's Cleansing, the scout Krolg directs Alliance champions to strike at the encampment, eliminate Ran Bloodtooth, and remove the threat his corrupted followers pose to the region.",al={"bloodtooth camp quest","why kill ran bloodtooth","krolg mission"}}},ang={["faction:Alliance"]="For Alliance adventurers, Bloodtooth Camp represents a localized hotspot of corruption that threatens the safety of Ashenvale's southern groves and moonwells.",["race:NightElf"]="Night elves view the maddened state of Ran Bloodtooth's tribe as a tragic symptom of the deep corruption blighting their ancient ancestral homeland."},kw={"ashenvale","bloodtooth camp","falfarren river","furbolg","krolg","raene's cleansing","ran bloodtooth"},rel={"quest:991","npc:krolg","topic:furbolg","zone:ashenvale","subzone:falfarren-river","subzone:moonwell-ashenvale","topic:alliance"},src={"Bloodtooth Camp"}}
E["subzone:bough-shadow"] = {t="subzone",n="Bough Shadow",z="ashenvale",s="Bough Shadow is a secluded grove tucked away in the far northeastern corner of Ashenvale, east of Forest Song. It centers around a colossal Great Tree rooted over an ancient portal leading directly into the Emerald Dream.",h="Bough Shadow is a secluded grove tucked away in the far northeastern corner of Ashenvale, east of Forest Song.",sec={{t="A Gateway to the Dream",b="Bough Shadow houses one of the rare Great Trees grown from a cutting of the World Tree, Nordrassil. Planted long ago by druids following Fandral Staghelm, its roots plunge deep into the earth around a natural crossing into the Emerald Dream. Today, the tranquil yet imposing grove is heavily guarded by the Green Dragonflight. Emerald drakes such as Phantim and Dreamstalker circle above the canopy, while patrols of Emeraldon dragonspawn and oracles keep a vigilant, unyielding watch over the swirling green portal at its base, turning away any mortal who approaches unbidden.",sp=0}},faq={{q="What is the glowing green portal here?",a="The swirling vortex at the foot of the Great Tree is a direct gateway leading into the Emerald Dream, the untamed spirit realm of Azeroth. It is one of several such natural crossings scattered across the world.",al={"bough shadow portal","what is the portal in bough shadow","green portal ashenvale"}},{q="Why are green dragons guarding Bough Shadow?",a="Ysera's Green Dragonflight is charged with watching over the Emerald Dream and its direct passages into the physical world. Emerald drakes and dragonspawn patrol Bough Shadow to ensure no corrupting forces or intruders slip through the threshold.",al={"why are there dragons in ashenvale","green dragonflight bough shadow","why green dragons here"}},{q="Who planted the Great Tree here?",a="The tree was planted centuries ago by night elf druids loyal to Fandral Staghelm, who used a cutting taken from the boughs of the World Tree, Nordrassil, to root over the site.",al={"who made bough shadow","who planted the tree","tree origin bough shadow"}},{q="Can players enter the portal?",a="No. The gateway remains tightly sealed to mortals in the physical world, and venturing too close will provoke the wrath of the surrounding elite dragonkin guards.",al={"can i go through the portal","enter bough shadow portal","how to enter dream portal"}}},ang={["class:Druid"]="Bough Shadow represents sacred ground for druids, housing one of the tangible thresholds linking Azeroth directly to the domain of the Green Flight and the Emerald Dream.",["race:NightElf"]="Lying deep beyond the ruins of Forest Song, this great tree was shaped by kaldorei hands from the branch of Nordrassil itself, standing as a living monument of ancient elven stewardship."},kw={"ashenvale","bough shadow","dragonspawn","dreamstalker","emerald dream","great tree","green dragons","phantim","portal"},rel={"zone:ashenvale","topic:emerald-dream","topic:druid","topic:nordrassil","npc:fandral-staghelm","subzone:forest-song"},src={"Bough Shadow"}}
E["subzone:demon-fall-canyon"] = {t="subzone",n="Demon Fall Canyon",z="ashenvale",s="Demon Fall Canyon is a scarred, fel-corrupted gorge situated in southern Ashenvale. It marks the legendary battleground where Grommash Hellscream and Thrall confronted the pit lord Mannoroth, ending the demonic blood curse that had enslaved the orcish race for a generation.",h="Demon Fall Canyon is a scarred, fel-corrupted gorge situated in southern Ashenvale.",sec={{t="The Fall of Mannoroth",b="Carved into the rugged southern borders of Ashenvale near Felfire Hill and Demon Fall Ridge, this canyon bears the heavy scars of the Third War. It was here that Warchief Thrall and chieftain Grommash Hellscream tracked down the pit lord Mannoroth to break his hold over the Horde. During the fierce duel, Mannoroth incapacitated Thrall, but Grom seized the opening to drive his axe, Gorehowl, straight into the demon's chest. The resulting infernal explosion shattered the pit lord and slew Grom as well, permanently liberating the orcs from their lingering demonic servitude.",sp=0},{t="A Sacred Yet Dangerous Chasm",b="Following Mannoroth's demise, the Horde dubbed the canyon to commemorate Grom's final stand, erecting a monument nearby to honor his redemption. Despite the pit lord's destruction, his violent death unleashed raw demonic power that thoroughly tainted the surrounding land. Today, the canyon remains saturated in fel magic and crawls with hostile lingering lesser demons, making any pilgrimage to this hallowed ground a perilous venture.",sp=0}},faq={{q="Why is this place called Demon Fall Canyon?",a="The canyon was named by the Horde to commemorate the death of the pit lord Mannoroth, who fell here after being slain by Grommash Hellscream.",al={"demon fall canyon name origin","why called demon fall canyon","how did it get its name"}},{q="What happened between Grom and Mannoroth here?",a="Thrall and Grom confronted Mannoroth together. Thrall was knocked unconscious, but Grom dealt a lethal blow with his axe. The violent explosion of demonic fire released by Mannoroth's demise fatally wounded Grom, freeing his people from the blood curse with his dying breath.",al={"grom death","grom vs mannoroth","how did grom die"}},{q="Why are there still demons roaming the canyon?",a="When the pit lord Mannoroth died, the tremendous blast of demonic energy permanently corrupted the canyon floor, leaving behind lingering fel corruption that attracts and harbors lesser demons.",al={"why demons in demon fall","demon fall canyon mobs","why is it fel corrupted"}},{q="Where is Grom Hellscream's memorial?",a="A memorial monument honoring Grom Hellscream stands nearby in the vicinity of Demon Fall Canyon, where Horde pilgrims come to pay tribute to the warrior who freed their people.",al={"grom monument location","hellscream memorial","where is grom's grave"}}},ang={["faction:Horde"]="This scorched ground is sacred to the Horde as the site of Grommash Hellscream's ultimate sacrifice, where the blood curse of the Burning Legion was finally broken.",["race:Orc"]="Every orc owes their spiritual and physical freedom to the battle fought in this canyon, where Grom traded his life to shatter their demonic bondage."},kw={"ashenvale","blood curse","demon fall canyon","gorehowl","grommash hellscream","mannoroth","pit lord","thrall"},rel={"subzone:demon-fall-ridge","subzone:felfire-hill","zone:ashenvale","topic:grommash-hellscream","npc:thrall","topic:burning-legion","topic:horde"},src={"Demon Fall Canyon"}}
E["subzone:demon-fall-ridge"] = {t="subzone",n="Demon Fall Ridge",z="ashenvale",s="Demon Fall Ridge is a blighted highland in south-eastern Ashenvale, overlooking the canyon where Mannoroth fell. Swarming with lesser demons and corrupting magic, the ridge centers around a desecrated night elf barrow den claimed by the Burning Legion.",h="Demon Fall Ridge is a blighted highland in south-eastern Ashenvale, overlooking the canyon where Mannoroth...",sec={{t="A Perch Over Corruption",b="Rising directly west and above Demon Fall Canyon, Demon Fall Ridge is stained with lingering fel residue from the Third War. While the canyon below marks the site of the catastrophic clash between Grommash Hellscream and the pit lord Mannoroth, this high ground serves as a staging area for surviving demonic invaders. Lesser demons patrol the rocky cliffs, defiling the ancient woodland and threatening any travelers traversing the southern border of Ashenvale.",sp=0},{t="The Desecrated Barrow",b="Carved into the side of the ridge rests an abandoned night elf barrow den, hollowed out and converted into a stronghold of dark sorcery. Rather than slumbering druids, the subterranean passages teem with fel fiends. Deep in the subterranean depths lurks Diathorus the Seeker, a cunning dreadlord who rules over this conclave, directing the remaining demonic remnants throughout the forest.",sp=0}},faq={{q="Where is Demon Fall Ridge?",a="Demon Fall Ridge is located in south-eastern Ashenvale. It sits elevated directly west and above Demon Fall Canyon, near the border with the Barrens.",al={"ridge location","where is demon fall ridge","ashenvale demon ridge"}},{q="Why are there demons on this ridge?",a="The ridge overlooks the site where the pit lord Mannoroth met his end during the Third War. Demons that survived the Legion's defeat scattered into the surrounding heights, entrenching themselves upon the ridge and inside an abandoned barrow den.",al={"why demons here","demon fall ridge demons","burning legion presence"}},{q="Who leads the demons here?",a="The conclave on the ridge is commanded by Diathorus the Seeker, a powerful nathrezim dreadlord who dwells in the deepest recesses of the barrow den.",al={"who is the boss here","demon leader","diathorus the seeker"}},{q="What is the structure carved into the ridge?",a="It is an ancient night elf barrow den. Once a sanctum used by druids for entering the Emerald Dream, it was abandoned and has since been overrun and desecrated by the Burning Legion.",al={"barrow den","demon fall cave","what is the den"}}},ang={["class:Druid"]="Seeing a barrow den—once a sacred haven of the Emerald Dream—desecrated and occupied by demons makes this ridge an affront to the Cenarion Circle.",["class:Warlock"]="The fel presence here is led by an active dreadlord, offering dark practitioners a glimpse of organized Legion remnants in Kalimdor."},kw={"ashenvale","barrow den","burning legion","demon fall canyon","demon fall ridge","diathorus the seeker","dreadlord"},rel={"subzone:demon-fall-canyon","zone:ashenvale"},src={"Demon Fall Ridge"}}
E["subzone:dor-danil-barrow-den"] = {t="subzone",n="Dor'Danil Barrow Den",z="ashenvale",s="Dor'Danil Barrow Den is an ancient night elven sanctuary carved into the earth of central Ashenvale, south of Splintertree Post. Once a tranquil resting place for slumbering druids commune with the Emerald Dream, it has fallen into horror following Forsaken meddling that severed the dreamers' spirits from their bodies.",h="Dor'Danil Barrow Den is an ancient night elven sanctuary carved into the earth of central Ashenvale, south of...",sec={{t="A Sanctuary Desecrated",b="Barrow dens across Kalimdor are revered sanctuaries where night elven druids historically slept for centuries, roaming the Emerald Dream while their mortal frames remained protected underground. When the Horde pushed into Ashenvale, Dor'Danil fell deep behind enemy lines. The orcs largely ignored the comatose elves, but the newly allied Forsaken saw an opportunity. Forsaken operatives infiltrated the depths and began gruesome experiments designed to sever the sleeping druids from their spirits, fracturing their minds and driving them hopelessly insane. The darkened hollows now crawl with sinister Forsaken assassins and the furious, torment-maddened spirits of druids who can no longer return to their bodies.",sp=0},{t="The Tormented Guardians",b="The corruption within Dor'Danil reaches deep into the subterranean tunnels, where three prominent druidic spirits wander in madness: Uthil Mooncall, Mavoris Cloudsbreak, and Taneel Darkwood. Alongside them stalks Darkslayer Mordenthal, an elite Forsaken agent overseeing the dark research. For night elves and allies of the Cenarion Circle, putting these anguished souls to rest is a grim mercy, while the ongoing Forsaken presence exposes the ruthless, morbid curiosity Sylvanas's agents bring to the conflicts of Kalimdor.",sp=1}},faq={{q="What is Dor'Danil Barrow Den?",a="Dor'Danil Barrow Den is an underground night elf refuge in Ashenvale, situated south of Splintertree Post and southwest of Felfire Hill. Traditionally, druids slept here in deep trances to enter the Emerald Dream while their physical bodies were sheltered.",al={"what is this place","dor danil barrow den info","dor'danil lore"}},{q="Why are the druid spirits inside hostile and insane?",a="Forsaken agents entered the den to conduct experiments on the slumbering druids, severing their spirits from their physical forms. The trauma of being torn between the waking world and the dream drove the druids violently insane.",al={"why are druids crazy here","why are spirits angry","insane druids lore"}},{q="Who is Darkslayer Mordenthal?",a="Darkslayer Mordenthal is a Forsaken assassin and operative stationed deep inside the barrow den, responsible for preying upon the sleeping night elves and directing the experiments that drove their spirits mad.",al={"mordenthal","who is the undead inside"}},{q="Which notable spirits haunt the depths?",a="Three prominent druidic spirits haunt the lower chambers: Uthil Mooncall, Mavoris Cloudsbreak, and Taneel Darkwood. All three were severed from their bodies and now wander the dark tunnels in unending rage.",al={"named mobs dor danil","named druids inside"}}},ang={["class:Druid"]="Barrow dens are sacred places of communion with the Emerald Dream, making the torture and mental fracturing of the druids inside Dor'Danil an unforgivable sacrilege.",["race:Undead"]="The twisted research conducted within Dor'Danil reflects the Forsaken's relentless curiosity regarding the threshold of life, death, and soul-severing magic, even on the distant battlefields of Kalimdor."},kw={"ashenvale","barrow den","dor danil","dor'danil","insane druids","mavoris cloudsbreak","mordenthal","taneel darkwood","uthil mooncall"},rel={"quest:1012","subzone:splintertree-post","zone:ashenvale","topic:forsaken","topic:druid","subzone:felfire-hill","quest:1152"},src={"Dor'Danil Barrow Den"}}
E["subzone:falfarren-river"] = {t="subzone",n="Falfarren River",z="ashenvale",s="The Falfarren River flows northeast to southwest through the heart of Ashenvale, originating on the slopes of Mount Hyjal before slipping underground beneath the Barrens' northern mountains. It forms a natural boundary between night elven domains around Astranaar to the west and the encroaching Horde outposts to the east. Travelers must tread carefully, as its shaded banks and shallows harbor hostile wildlife and mark the edge of open conflict.",h="The Falfarren River flows northeast to southwest through the heart of Ashenvale, originating on the slopes of...",sec={{t="A Contested Natural Boundary",b="Feeding down from Mount Hyjal, the waters of the Falfarren cascade across waterfalls into Xavian before winding between Splintertree Post and Night Run. While it is neither exceptionally deep nor impassable under ordinary weather, it serves as the rough geopolitical dividing line in central Ashenvale. To the west lie Astranaar and the core holdings of the Kaldorei; to the east sit the camps and lumber operations of the Horde. Crossing the main road's wooden bridges brings travelers into the contested heart of the forest, where patrols clash along the banks.",sp=0},{t="Hazards in the Shallows",b="Beyond the tensions of warring sentinels and grunts, the river conceals natural and unnatural dangers beneath its surface. Downstream near Felfire Hill and the Moonwell of Cleansing, corrupted bog beasts and aggressive water creatures prowl the muddy shallows. Rainfall can swell the currents, yet the true peril lies in the dense canopies flanking either shore, where ambushes and skirmishes routinely spill into the stream.",sp=0}},faq={{q="Where does the Falfarren River begin and end?",a="The Falfarren River starts in the heights of Mount Hyjal, cascading down waterfalls into the lake at Xavian. From there, it meanders southwest across Ashenvale before plunging underground into subterranean channels beneath the northern mountains of the Barrens.",al={"falfarren river source","where does the river go"}},{q="Why is the Falfarren River significant to the war in Ashenvale?",a="It serves as the rough borderline between night elf and Horde control in central Ashenvale. Night elf territory, centered around Astranaar and Silverwing Outpost, lies to the west, while the orc outpost of Splintertree Post and active Horde lumbering operations lie to the east.",al={"why is falfarren river important","river border ashenvale"}},{q="What threats should travelers expect along the riverbanks?",a="Aggressive bog beasts roam the shallows, particularly near the corrupted regions around Felfire Hill. In addition, patrols from both the Alliance and the Horde watch the bridges and crossings, making unattended river banks prime territory for skirmishes and ambushes.",al={"monsters in falfarren river","dangers at falfarren"}}},ang={["faction:Alliance"]="For the Night Elves and their allies, crossing eastward over the Falfarren signifies stepping directly into the Horde's front lines near Splintertree Post.",["faction:Horde"]="The Falfarren marks the western edge of the Horde's expansion out of Splintertree Post, beyond which lies fortified night elf territory."},kw={"ashenvale river","astranaar","falfarren","falfarren river","felfire hill","splintertree","xavian"},rel={"zone:ashenvale","subzone:splintertree-post","subzone:astranaar","subzone:silverwing-outpost","subzone:xavian","subzone:felfire-hill","subzone:moonwell-of-cleansing","subzone:night-run"},src={"Falfarren River"}}
E["subzone:fallen-sky-lake"] = {t="subzone",n="Fallen Sky Lake",z="ashenvale",s="Fallen Sky Lake is a secluded body of water nestled deep within the forests of eastern Ashenvale. Situated between Silverwing Outpost and the encroaching Warsong Labor Camp, the serene waters hide danger in the form of hostile shadethicket woodkin that aggressively defend the lake and its central isle.",h="Fallen Sky Lake is a secluded body of water nestled deep within the forests of eastern Ashenvale.",sec={{t="A Contested Sanctuary",b="Tucked south of Silverwing Outpost and just west of the Warsong Labor Camp, Fallen Sky Lake offers a fleeting glimpse of Ashenvale's natural splendor before the Orcish axes took root nearby. The shores and the small islet rising from the middle of the lake are inhabited by shadethickets—corrupted or territorial wildkin that view any two-legged intruder as a threat. The heart of the island serves as the domain of a powerful Shadethicket Oracle, whose presence keeps the local woodkin bound to the grove and relentlessly vigilant against travelers passing through.",sp=0}},faq={{q="Where is Fallen Sky Lake located?",a="Fallen Sky Lake is located in eastern Ashenvale, directly south of Silverwing Outpost, west of the Warsong Labor Camp, and northeast of Silverwing Grove.",al={"fallen sky lake location","where is fallen sky lake","how to find fallen sky lake"}},{q="What creatures live around Fallen Sky Lake?",a="The lake and its surrounding banks are overrun by shadethickets—aggressive wildkin creatures—led by a formidable Shadethicket Oracle who dwells on the central island.",al={"mobs at fallen sky lake","what is at fallen sky lake","fallen sky lake enemies"}},{q="Why is the Shadethicket Oracle important?",a="The Shadethicket Oracle is the matriarchal leader of the local woodkin gathered at the lake. Travelers and scouts in Ashenvale are often tasked with hunting down the oracle on her central isle to cull the hostile wildkin threat.",al={"oracle at fallen sky lake","shadethicket oracle","who is on the island"}}},ang={["class:Druid"]="Wildkin are traditionally sacred creatures touched by Elune's grace, making the corrupted, aggressive shadethickets infesting Fallen Sky Lake an unsettling sight to behold.",["race:NightElf"]="Positioned just south of Silverwing Outpost, the lake represents yet another corner of the sacred ancestral forest where wild beasts have grown erratic amidst the gathering drums of the Horde."},kw={"ashenvale","fallen sky lake","oracle","shadethicket","silverwing outpost","warsong labor camp","wildkin"},rel={"quest:1035","zone:ashenvale","subzone:silverwing-outpost","subzone:silverwing-grove","subzone:warsong-labor-camp"},src={"Fallen Sky Lake"}}
E["subzone:felfire-hill"] = {t="subzone",n="Felfire Hill",z="ashenvale",s="Felfire Hill is a blighted, demon-infested rise nestled in eastern Ashenvale. Struck by falling infernals during the Third War, its corrupted soil still burns with demonic power. The Horde maintains fortified guard posts on the bridges leading into the hill to safeguard their nearby settlements.",h="Felfire Hill is a blighted, demon-infested rise nestled in eastern Ashenvale.",sec={{t="A Scar of the Burning Legion",b="During the cataclysmic invasion of the Third War, flaming meteors fell across Kalimdor as the Burning Legion unleashed its dread infernals. Several of those fiery behemoths struck this ridge in Ashenvale, scouring away the ancient woodlands and corrupting the earth itself. Today, the scorched landscape remains saturated with fel energy and prowled by lingering demons who survived the Legion's defeat at Mount Hyjal.",sp=0},{t="Guarding the Crossings",b="Situated southeast of Splintertree Post and southwest of the Warsong Lumber Camp, Felfire Hill sits uncomfortably close to vital Horde operations. Because the demonic remnants threaten to spill out into the surrounding forest, Horde forces have erected fortified barricades and guard towers at both bridges approaching the hill, containing the foul creatures within their blighted haven.",sp=0}},faq={{q="Why is Felfire Hill corrupted?",a="During the Third War, Burning Legion infernals rained down from the sky and slammed into this hill. The impact and subsequent fel contamination burned away the pristine elven forest, leaving behind scarred rock and corrupting demonic energies that never dispersed.",al={"why is felfire hill green","felfire hill lore","what happened to felfire hill"}},{q="What creatures live on Felfire Hill?",a="The hill is occupied by surviving demons and infernal constructs left over from the Legion's invasion during the Third War. They remain hostile to all mortals who wander near their corrupted perimeter.",al={"monsters at felfire hill","felfire hill mobs"}},{q="Why did the Horde fortify the bridges here?",a="Felfire Hill lies directly between Splintertree Post and the Warsong Lumber Camp. Horde commanders fortified both bridges to ensure the roaming demons cannot break out and overrun their nearby camps, supply convoys, and lumber operations.",al={"horde bridge guards felfire","why are orcs guarding felfire hill"}},{q="Is Felfire Hill connected to the night elves?",a="Though the hill itself was once part of Ashenvale's sacred forest, it now sits menacingly northeast of the Dor'Danil Barrow Den. The creeping demonic taint and roaming fiends pose an enduring danger to the nearby slumbering grounds and the surrounding wildlands.",al={"dor danil felfire hill","barrow den demons"}}},ang={["faction:Horde"]="The Horde holds the fortified bridges around Felfire Hill to safeguard the transit road connecting Splintertree Post with the Warsong Lumber Camp against demonic raids.",["class:Warlock"]="The raw fel energies lingering where the Legion's infernals made landfall make this scarred ridge an object of dangerous curiosity for practitioners of dark magic."},kw={"ashenvale","burning legion","demons","felfire hill","infernals","splintertree post","warsong lumber camp"},rel={"zone:ashenvale","subzone:splintertree-post","subzone:warsong-lumber-camp","subzone:dor-danil-barrow-den","topic:third-war","topic:horde"},src={"Felfire Hill"}}
E["subzone:fire-scar-shrine"] = {t="subzone",n="Fire Scar Shrine",z="ashenvale",s="Fire Scar Shrine is a despoiled night elf shrine nestled in the southwestern forests of Ashenvale. Once a serene place of worship, it has been corrupted by demonic forces and turned into a blister of fel energy right on Astranaar's doorstep.",h="Fire Scar Shrine is a despoiled night elf shrine nestled in the southwestern forests of Ashenvale.",sec={{t="A Blight in the Forest",b="Located southwest of Astranaar and west of the Ruins of Stardust, Fire Scar Shrine stands as a grim reminder of the Burning Legion's lingering poison in Ashenvale. The shrine has fallen under the sway of demonic corruption, nurtured by servants of the shadowy Cult of the Dark Strand and the Shadow Council. Fel magic has twisted the surrounding earth into scorched rock, where roaming demons now gather in open defiance of the forest's defenders.",sp=0},{t="Shadows of the Dark Strand",b="The shrine's descent into darkness was spearheaded by agents like the orcish warlock Ilkrud Magthrull, operating under the orders of Athrikus Narassin. Though mortal sorcerers brought the corruption to bear, summoned fiends now patrol the altar stones unchecked. The localized tear in the veil occasionally draws greater horrors, including the towering doomguard Akkrilus.",sp=0}},faq={{q="Where is Fire Scar Shrine located?",a="Fire Scar Shrine is situated in southwestern Ashenvale, directly southwest of the night elf hub of Astranaar, south of the Shrine of Aessina, and just west of the Ruins of Stardust.",al={"fire scar shrine location","where is fire scar shrine","fire scar shrine map"}},{q="Why are there demons at Fire Scar Shrine?",a="The shrine was infiltrated and corrupted by agents of the Shadow Council and the Cult of the Dark Strand, notably the orc warlock Ilkrud Magthrull. Their dark rituals summoned demons and infused the sacred ground with lingering fel taint.",al={"why demons here","what corrupted fire scar shrine","who summoned the demons"}},{q="Who is Akkrilus?",a="Akkrilus is a formidable doomguard that occasionally manifests around Fire Scar Shrine, drawn to the potent demonic energies that pool around the corrupted stones.",al={"akkrilus","doomguard at fire scar","rare demon fire scar shrine"}},{q="What connection does this place have to the Cult of the Dark Strand?",a="The orc warlock who operated here, Ilkrud Magthrull, served Athrikus Narassin, the leader of the Cult of the Dark Strand. They leveraged the shrine as a foothold for their demonic summoning and dark ambitions within Ashenvale.",al={"cult of the dark strand fire scar","dark strand connection","athrikus narassin fire scar"}}},ang={["race:NightElf"]="The desecration of Fire Scar Shrine is a bitter affront so near to Astranaar, demanding swift retribution against any demonic trespassers who sully the forest.",["class:Warlock"]="The fel scarring and wild demonic summons here bear the clear signature of the Shadow Council's subtle infiltrations throughout Kalimdor."},kw={"akkrilus","ashenvale","astranaar","athrikus narassin","cult of the dark strand","fire scar shrine","ilkrud magthrull","shadow council"},rel={"zone:ashenvale","subzone:astranaar","subzone:shrine-of-aessina","subzone:ruins-of-stardust","topic:shadow-council"},src={"Fire Scar Shrine"}}
E["subzone:forest-song"] = {t="subzone",n="Forest Song",z="ashenvale",s="Forest Song is an ancient night elf ruin nestled in northeastern Ashenvale, near the tainted woods of Satyrnaar and the great portal at Bough Shadow. At present, it stands largely deserted save for the vigilant druid Kayneth Stillwind, who watches over the eastern border against emergent threats.",h="Forest Song is an ancient night elf ruin nestled in northeastern Ashenvale, near the tainted woods of...",sec={{t="A Lonely Vigil in Eastern Ashenvale",b="Tucked away in the dense woodlands of northeastern Ashenvale, Forest Song was once an elegant settlement of the kaldorei. Today, white stone columns and crumbling archways are overgrown with ivy and wild ferns. Located northeast of Satyrnaar and just north of the encroaching Warsong Lumber Camp, the ruins hold a quiet, strategic overlook along the eastern trails toward Azshara and Bough Shadow. While the woods around it are plagued by demonic corruption and Horde incursions, the ruin itself maintains a haunting, tranquil stillness.",sp=0},{t="Watcher of the Border",b="Forest Song is currently manned solely by the druid Kayneth Stillwind. From this crumbling outpost, Stillwind keeps a watchful eye on the dark designs of enemies entering the wilderness, including the unsettling presence of the Forsaken in the eastern forests. Though isolated far from Astranaar and lacking garrison fortifications, the sanctuary serves as an important rallying point for Alliance travelers venturing toward the northern road into Felwood or investigating the corruptions seeping across the canopy.",sp=0}},faq={{q="Who lives at Forest Song?",a="Currently, Forest Song is inhabited by the night elf druid Kayneth Stillwind, who stands watch alone amidst the ancient ruins.",al={"who is at forest song","forest song npcs","forest song inhabitants"}},{q="What threats are near Forest Song?",a="The ruins lie perilously close to Satyrnaar to the southwest, crawling with corrupted satyrs, and the Warsong Lumber Camp to the south. To the northeast lies Bough Shadow, where the green dragonflight guards a Great Tree leading into the Emerald Dream.",al={"forest song dangers","enemies near forest song"}},{q="Why is Kayneth Stillwind stationed here?",a="Kayneth monitors hostile movements throughout the eastern forests, directing allies against regional dangers—including sinister ventures and diseases spread by the Forsaken operating in the area.",al={"why is kayneth here","kayneth stillwind purpose"}},{q="Is Forest Song a major Alliance settlement?",a="No. Unlike Astranaar, Forest Song is largely an unfortified ruin without an active garrison, vendors, or military infrastructure, maintained only as a lone forward lookout post.",al={"alliance town forest song","is forest song a town"}}},ang={["class:Druid"]="The quiet presence of Kayneth Stillwind underscores the Cenarion Circle's solitary vigil in corrupted borderlands, situated right beneath the shadowed canopy near the Great Tree of Bough Shadow.",["faction:Alliance"]="Forest Song serves as a vital solitary outpost for Alliance adventurers cutting across northeastern Ashenvale toward Azshara or Felwood."},kw={"ashenvale","bough shadow","eastern ashenvale","forest song","kaldorei ruins","kayneth stillwind","satyrnaar"},rel={"quest:4581","quest:1011","zone:ashenvale","subzone:bough-shadow","subzone:satyrnaar","subzone:astranaar","subzone:warsong-lumber-camp","topic:druid"},src={"Forest Song"}}
E["subzone:greenpaw-village"] = {t="subzone",n="Greenpaw Village",z="ashenvale",s="Greenpaw Village is a furbolg settlement nestled in central Ashenvale, situated between Raynewood Retreat and Silverwind Refuge. It serves as the primary home of the Foulweald tribe, led by Chief Murgut and the shaman Oakpaw. Gripped by demonic corruption and embattled by outside forces, the village is an active conflict point for both Alliance and Horde travelers.",h="Greenpaw Village is a furbolg settlement nestled in central Ashenvale, situated between Raynewood Retreat and...",sec={{t="A Corrupted Settlement",b="Situated south of Raynewood Retreat and northeast of Silverwind Refuge, Greenpaw Village was once a quiet home for the forest's ursine denizens. In the wake of the Third War, its resident furbolgs—the Foulweald tribe—succumbed to the insidious corruption tainting Ashenvale's soil and spirits. Under the dominion of Chief Murgut and their corrupted spiritual guide, Shaman Oakpaw, the Foulweald have become hostile and unstable, attacking any travelers who stray into their forest territory.",sp=0},{t="Caught in the Crosshairs",b="Because of their relentless aggression and proximity to major roadways, Greenpaw Village draws hostility from every side. Alliance sentinels and night elf druids seek to purge the mad furbolgs to protect their nearby outposts and sacred moonwells. Simultaneously, Horde forces advancing into Ashenvale have fought bloody skirmishes against the Foulweald, leaving portions of the village shattered and its denizens captive as both factions push through the ancient woodland.",sp=0}},faq={{q="Where is Greenpaw Village located?",a="Greenpaw Village lies in central Ashenvale, directly south of Raynewood Retreat, northeast of Silverwind Refuge, and just northwest of the southern moonwell.",al={"greenpaw location","where is greenpaw village","find greenpaw"}},{q="Who lives in Greenpaw Village?",a="The settlement is populated by the Foulweald furbolg tribe, who are governed by Chief Murgut alongside their corrupted spiritual advisor, Shaman Oakpaw.",al={"who is here","greenpaw mobs","greenpaw furbolgs"}},{q="Why are the furbolgs in Greenpaw Village hostile?",a="Like many furbolg tribes across northern Kalimdor, the Foulweald tribe fell victim to the demonic corruption left behind after the Burning Legion invaded Ashenvale, driving their minds into maddened aggression.",al={"why are furbolgs mad","are greenpaw furbolgs corrupt"}},{q="Why are the Alliance and Horde fighting here?",a="Both factions view the aggressive Foulweald as a threat to their roads and settlements. The night elves seek to cleanse or contain the madness near their moonwells, while the Horde has actively struck into the camp, leaving sections damaged and furbolgs captured.",al={"greenpaw quests","who attacks greenpaw"}}},ang={["race:NightElf"]="For the night elves, seeing the Foulweald succumb to corruption so near Raynewood Retreat and their sacred moonwells is a tragic reminder of Ashenvale's lingering demonic scars.",["class:Druid"]="Druids witness the pain of the ancient bear folk firsthand at Greenpaw Village, where the balance of nature has broken down into rampant feral madness."},kw={"ashenvale","foulweald","furbolg","greenpaw village","murgut","oakpaw","raynewood retreat","silverwind refuge"},rel={"zone:ashenvale","topic:furbolg","subzone:raynewood-retreat","subzone:silverwind-refuge","subzone:moonwell-ashenvale","topic:alliance","topic:horde"},src={"Greenpaw Village"}}
E["subzone:howling-vale"] = {t="subzone",n="Howling Vale",z="ashenvale",s="Tucked away in north-central Ashenvale near the Felwood border, the Howling Vale is a darkened dell overrun by savage, alien wolf-beasts known as the Terrowulf worgen. Hidden deep within its caves lies the ancient Shrine of Mel'Thandris, an Elune-blessed ruin tied intimately to the tragic origins of the worgen curse on Kalimdor.",h="Tucked away in north-central Ashenvale near the Felwood border, the Howling Vale is a darkened dell overrun...",sec={{t="A Haunted Haven",b="North of the road toward Felwood, the calm majesty of Ashenvale gives way to eerie, predatory howling. The vale shelters ancient trees alongside corrupted Terrowulf packlords and aggressive wildlife. At its heart lies a cave enshrining the memory of Mel'Thandris, an ancient night elf priestess. While the shrine once stood as a place of quiet devotion, its tranquil halls have fallen into ruined disrepair, defiled by feral wolf-men whose origin puzzles the Sentinels stationed nearby.",sp=0},{t="The Scythe and the Starsong Legacy",b="During the ancient War of the Satyr, Mel'Thandris was entrusted with safeguarding the Scythe of Elune, a fateful artifact that bound away the feral Druids of the Scythe. After she fell in battle, her shrine sheltered the artifact for millennia. In recent times, the night elf Sentinel Velinde Starsong uncovered historical records in Darnassus, traveled here, and retrieved the Scythe. Her attempts to channel its power to fight demons inadvertently unleashed the worgen upon the surrounding woods, leaving the vale haunted by the very beasts she summoned.",sp=1}},faq={{q="Why is it called the Howling Vale?",a="The vale earned its grim name from the chilling calls of the Terrowulf worgen who claimed it. Their constant, echoing howls reverberate through the canyon and cavern, drowning out the natural sounds of Ashenvale's canopy.",al={"why howling vale","origin of howling vale name","why does it howl"}},{q="What is the Shrine of Mel'Thandris?",a="It is an ancient sanctuary dedicated to Elune and built in honor of Mel'Thandris, a night elf priestess who fought in the ancient War of the Satyr. Inscribed with Darnassian prayers, it served for millennia as the secret resting place of the Scythe of Elune.",al={"shrine of melthandris","who was mel'thandris","melthandris shrine"}},{q="Where did the worgen here come from?",a="They were summoned by the Sentinel commander Velinde Starsong. After retrieving the Scythe of Elune from the shrine, she prayed to Elune for aid against the Burning Legion and was granted power over the wolf-beasts. Eventually, the creatures broke from her control and overran the vale.",al={"how did worgen get to ashenvale","terrowulf origin","why are worgen in ashenvale"},sp=1},{q="What is the Tome of Mel'Thandris?",a="It is a sacred historical text resting at the shrine in the depths of the cave. Sentinel Melyria Frostshadow sends Alliance scouts to study the tome to understand the origins of the mysterious wolf-men plaguing the forest.",al={"tome of mel'thandris","tome in howling vale","melthandris book"}}},ang={["race:NightElf"]="The defilement of Mel'Thandris's shrine and the tragic missteps of Velinde Starsong serve as a bitter reminder of the perils of meddling with forbidden, primal magics.",["class:Druid"]="The feral packlords roaming the cave bear an ancient, cursed tie to forbidden shapeshifting traditions originating during the War of the Satyr."},kw={"ashenvale worgen","howling vale","mel'thandris","scythe of elune","terrowulf","velinde starsong"},rel={"quest:1022","quest:1037","zone:ashenvale","topic:worgen","topic:elune","topic:druid","npc:sentinel-melyria-frostshadow","zone:felwood"},src={"Howling Vale"}}
E["subzone:iris-lake"] = {t="subzone",n="Iris Lake",z="ashenvale",s="Iris Lake is a blighted body of water resting in north-central Ashenvale, east of Astranaar. Once pristine, its waters have turned a sickly yellowish-green from demonic corruption seeping down from Felwood, and hostile bog beasts now prowl its shores.",h="Iris Lake is a blighted body of water resting in north-central Ashenvale, east of Astranaar.",sec={{t="A Tainted Refuge",b="Nestled between Astranaar and the moonwell tended by Shael'dryn, Iris Lake stands as a grim reminder of the wounds inflicted during the Third War. Fel energies drifting south from the tainted heights of Felwood have poisoned the basin, turning its once-clear waters into a foul, sickly yellow-green mire. The corruption has twisted the native plant life and water spirits, raising aggressive bog beasts that lash out at any traveler who wanders near.",sp=0},{t="Tears of the Goddess",b="Despite the severe pollution choking the lake, sacred remnants of the past still linger along its edges. Rare crystalline stones known as Elune's Tears can sometimes be found resting along the muddy banks. Keepers of elven traditions, such as Shael'dryn, seek these holy stones to aid in purifying tainted moonwells and resisting the spreading demonic blight across Ashenvale.",sp=0}},faq={{q="Why is the water at Iris Lake green and murky?",a="Iris Lake has been tainted by demonic corruption bleeding down from neighboring Felwood. The dark magic has poisoned the water table, turning the lake into a yellowish-green pool that twists nearby wildlife into aggressive monstrosities.",al={"why is iris lake green","iris lake water","why is iris lake tainted"}},{q="What creatures roam around Iris Lake?",a="The lake and its shores are infested with corrupted bog beasts. These plant and mud elementals have been maddened by fel energy and will violently attack anyone approaching the water.",al={"iris lake monsters","iris lake mobs","what attacks at iris lake"}},{q="What are Elune's Tears?",a="Elune's Tears are sacred glowing blue stones found near the shores of Iris Lake. Priests and keepers of the night elves use their consecrated nature in purification rites, notably to cleanse corrupted moonwells.",al={"elunes tears","elune tear","what is elunes tear"}},{q="Where is Iris Lake located?",a="Iris Lake lies in north-central Ashenvale. It is positioned directly east of the night elf settlement of Astranaar and west of Shael'dryn's moonwell.",al={"where is iris lake","iris lake location","how to get to iris lake"}}},ang={["race:NightElf"]="Iris Lake is a heartbreaking example of the creeping corruption threatening Ashenvale, but recovering Elune's Tears from its fouled shores offers hope for cleansing the forest.",["class:Druid"]="The twisted bog beasts and stagnant, corrupted waters demonstrate the devastating toll that demonic energy takes on nature when left unchecked."},kw={"ashenvale","bog beasts","elune's tear","felwood corruption","iris lake","shael'dryn"},rel={"quest:1033","npc:shael-dryn","subzone:moonwell-ashenvale","zone:ashenvale","zone:felwood","subzone:astranaar","topic:elune"},src={"Iris Lake"}}
E["subzone:kargathia-keep"] = {t="subzone",n="Kargathia Keep",z="ashenvale",s="Kargathia Keep is a fortified Horde stronghold anchoring the eastern front of the Warsong Lumber Camp in Ashenvale. Serving as headquarters for the outpost's overseers, it guards the river border and ensures rapid reinforcement lines directly back to Orgrimmar.",h="Kargathia Keep is a fortified Horde stronghold anchoring the eastern front of the Warsong Lumber Camp in...",sec={{t="A Bastion on the Southfury",b="Perched on the eastern edge of the Warsong Lumber Camp just west of the Southfury River, Kargathia Keep serves as the command center for the Horde's logging operations in Ashenvale. Upgraded with heavy spiked barricades, this fortified outpost houses Overseer Gorthak and his officers. Its strategic position against the river border allows the Warsong clan to monitor incoming incursions and receive swift reinforcements directly from the neighboring lands of Durotar and Orgrimmar whenever night elf skirmishers strike.",sp=0},{t="Honoring the Bladefist",b="Like the fortress of Kargath in the Badlands and Bladefist Bay along the coast of Durotar, the outpost takes its name from the famed chieftain Kargath Bladefist. For the Warsong orcs braving Ashenvale's hostile woodlands, the keep's imposing classic architecture stands as an enduring symbol of martial resilience and Horde defiance in territory claimed by the night elves.",sp=0}},faq={{q="Where is Kargathia Keep located?",a="Kargathia Keep is situated in eastern Ashenvale, on the eastern edge of the Warsong Lumber Camp just west of the Southfury River.",al={"kargathia keep location","where is kargathia keep","kargathia outpost location"}},{q="Who leads the keep?",a="Overseer Gorthak commands the Warsong Lumber Camp from within Kargathia Keep, directing logging operations and coordinating defenses against Alliance attacks.",al={"who is in charge of kargathia keep","kargathia keep leader","overseer gorthak"}},{q="Why was the keep named Kargathia?",a="The stronghold was named in honor of Kargath Bladefist, the legendary chieftain of the Shattered Hand clan, sharing this naming heritage with Kargath in the Badlands and Bladefist Bay in Durotar.",al={"who is kargathia keep named after","kargath bladefist","why kargathia"}},{q="What is the strategic purpose of this stronghold?",a="The keep commands the eastern border of the logging camp along the Southfury River, securing the vital supply route and enabling rapid troop reinforcements to cross over from Orgrimmar.",al={"why is kargathia keep here","purpose of kargathia keep","kargathia keep importance"}}},ang={["faction:Horde"]="For Horde defenders, Kargathia Keep is an indispensable sanctuary on the frontline of Ashenvale, securing valuable timber shipments vital to Orgrimmar's construction.",["race:NightElf"]="To the night elves, this heavily spiked stronghold represents the aggressive, deeply entrenched nature of the Horde's intrusion into their sacred ancestral forest."},kw={"ashenvale","kargath bladefist","kargathia keep","kargathia outpost","overseer gorthak","southfury river","warsong lumber camp"},rel={"subzone:warsong-lumber-camp","topic:warsong-clan","subzone:southfury-river","zone:ashenvale","zone:orgrimmar","subzone:kargath","subzone:bladefist-bay","topic:horde"},src={"Kargathia Keep"}}
E["subzone:lake-falathim"] = {t="subzone",n="Lake Falathim",z="ashenvale",s="Lake Falathim is a tranquil body of water nestled in the forested hills of western Ashenvale, southwest of Maestra's Post. Revered for the constant touch of Elune's moonlight upon its surface day and night, it was once a beloved retreat for night elves. In recent days, however, aggressive murlocs have overrun its shores, turning a sacred haven into a perilous hazard.",h="Lake Falathim is a tranquil body of water nestled in the forested hills of western Ashenvale, southwest of...",sec={{t="Bathed in Moonlight",b="Tucked away southeast of the Zoram Strand, Lake Falathim was long cherished by the Kaldorei as a peaceful sanctuary for swimming and fishing. According to local lore, the gentle radiance of Elune rests upon these waters at all hours, day or night. Despite this sacred blessing, ferocious murlocs have surged inland to seize the shores, nesting in thick numbers and driving away local travelers and scholars alike.",sp=0},{t="The Scholar's Disappearance",b="The sudden occupation by murlocs has made the lake deadly to solitary wanderers. The night elf scholar Teronis was recently lost somewhere near the water's edge on a mission of inquiry. Given the savage hostility of the amphibians lurking on the banks and in the shallows, the Sentinels fear the worst for any who venture toward the moonlit pool alone.",sp=0}},faq={{q="Where is Lake Falathim located?",a="Lake Falathim lies in western Ashenvale, tucked into the hills southwest of Maestra's Post and southeast of the Zoram Strand.",al={"lake falathim location","where is lake falathim","find lake falathim"}},{q="Why is Lake Falathim special to the night elves?",a="The lake holds spiritual significance because the goddess Elune's moonlight is said to perpetually touch its waters, whether by day or by night. Historically, night elves visited its peaceful banks to fish and swim.",al={"why is lake falathim important","lake falathim lore","moonlight lake ashenvale"}},{q="What creatures inhabit the lake?",a="The lake has been infested by hostile murlocs that have migrated up from the nearby coastal regions, making the shoreline dangerous for travelers.",al={"lake falathim mobs","what is at lake falathim","lake falathim monsters"}},{q="Who was Teronis?",a="Teronis was a night elf scholar who ventured out near Lake Falathim and went missing, with his disappearance attributed to the vicious murlocs inhabiting the area.",al={"teronis lake falathim","who is teronis","missing scholar lake falathim"}}},ang={["race:NightElf"]="For the Kaldorei, Lake Falathim is a reminder of wilderness sanctity under siege, where an idyllic lake touched by Elune's constant moonlight is desecrated by savage murloc tribes.",["faction:Alliance"]="Alliance scouts out of Maestra's Post keep a watchful eye toward Lake Falathim, wary of murloc incursions and seeking word on lost scholars like Teronis."},kw={"ashenvale","elune","falathim","lake falathim","maestra's post","moonlight","murloc","teronis"},rel={"zone:ashenvale","subzone:maestra-s-post","subzone:zoram-strand","topic:murloc","quest:1008"},src={"Lake Falathim"}}
E["subzone:maestra-s-post"] = {t="subzone",n="Maestra's Post",z="ashenvale",s="Maestra's Post is a small Alliance settlement in western Ashenvale, perched along the road northwest of Astranaar and south of the Ruins of Ordil'Aran. Guarded by night elven Sentinels and hosting a rare human presence in Kalimdor's ancient forest, it serves as a forward watch against encroaching threats.",h="Maestra's Post is a small Alliance settlement in western Ashenvale, perched along the road northwest of...",sec={{t="A Forward Watch",b="Positioned under the canopy of western Ashenvale, Maestra's Post consists of a slender night elven tower and an open lodge. It sits as an essential waypoint for travelers marching between the coast of Darkshore and the larger hub of Astranaar. Despite its tranquil elven architecture, the outpost stands perpetually on edge. The local Sentinels keep a wary eye on the surrounding wilderness, where corrupted furbolg stir and nearby Horde movements constantly threaten the Alliance's supply lines.",sp=0},{t="An Alliance Gathering",b="Unlike many insular night elf enclaves deep within the woods, Maestra's Post is notable for housing a handful of human allies. Figures such as Feero Ironhand and Delgren the Purifier dwell alongside the Sentinels here, lending their martial strength and devotion to the holy Light in service to the broader Alliance. Their presence makes this remote campsite one of the earliest meeting grounds between the eastern kingdoms and the ancient defenders of Kalimdor.",sp=0}},faq={{q="Where is Maestra's Post located?",a="It is located in western Ashenvale, situated along the road northwest of Astranaar and just south of the Ruins of Ordil'Aran.",al={"maestra's post location","where is maestras post","find maestras post"}},{q="Who was Maestra?",a="The post takes its name from Moon Priestess Maestra, a night elf figure of reverence, though the priestess herself is not currently present at the outpost.",al={"who is maestra","moon priestess maestra","who was maestra"}},{q="Why are there humans at an elven outpost?",a="Following the third war and the night elves joining the Alliance, travelers and warriors like Feero Ironhand and Delgren the Purifier have ventured into Kalimdor to offer aid and strengthen ties with their night elf allies.",al={"why are humans in ashenvale","feero ironhand why here","delgren the purifier why here"}},{q="What threats face Maestra's Post?",a="The outpost must contend with corrupted furbolg clans lurking in the surrounding woodland, as well as scouting parties and incursions from the nearby Horde forces pushing into Ashenvale.",al={"who attacks maestras post","dangers at maestras post"}}},ang={["faction:Alliance"]="For Alliance travelers leaving the safety of Darkshore, this outpost represents your first friendly welcome and fortified sanctuary in the contested forests of Ashenvale.",["race:NightElf"]="The post demonstrates the burgeoning partnership of the new Alliance, showing Sentinels sharing hearth and watch duty with the younger races of the Eastern Kingdoms."},kw={"ashenvale","delgren the purifier","feero ironhand","maestra's post","maestras post","ordil'aran","sentinels"},rel={"zone:ashenvale","subzone:astranaar","subzone:ruins-of-ordil-aran","npc:delgren-the-purifier","npc:feero-ironhand","topic:sentinels","topic:alliance","topic:horde"},src={"Maestra's Post"}}
E["subzone:moonwell-ashenvale"] = {t="subzone",n="Moonwell (Ashenvale)",z="ashenvale",s="This secluded shrine, known to the night elves as the Moonwell of Purity, rests in central Ashenvale east of Iris Lake and west of Raynewood Retreat. Its blessed waters channel the grace of Elune to nourish the ancient forest and cleanse creeping foulness from the land. Alliance travelers and night elf sentinels often seek out its tranquil basin to purify corrupted artifacts found in the woodland.",h="This secluded shrine, known to the night elves as the Moonwell of Purity, rests in central Ashenvale east of...",sec={{t="Sanctuary of Purity",b="Tucked away beneath the canopy of central Ashenvale, this moonwell serves as a spiritual anchor for the kaldorei. Tended by wardens like Felore Moonray, its luminescent waters tap into nature's latent magic and the light of the Moon Goddess. As the surrounding forest suffers from satyr corruption, fel taint, and logging incursions, pure shrines like this one become vital lifelines for those trying to heal the woods.",sp=0},{t="Healing the Wood",b="The basin acts as the cleansing font in efforts to restore contaminated relics. Adventurers aiding Raene Wolfrunner come here to immerse defiled rod fragments, using the untouched lunar energies to banish corruption where ordinary remedies fail.",sp=1}},faq={{q="What is this specific moonwell called?",a="This site is known as the Moonwell of Purity. It is one of several moonwells across Ashenvale, located east of Iris Lake and west of Raynewood Retreat.",al={"which moonwell is this","moonwell name","moonwell of purity"}},{q="What are moonwells used for?",a="Moonwells are sacred basins consecrated to Elune that blend lunar power with natural magic. Night elves use them to sustain the land, replenish their spiritual strength, and purify items tainted by dark or demonic influences.",al={"what does a moonwell do","moonwell purpose","why moonwells exist"}},{q="Who tends this moonwell?",a="Felore Moonray watches over the Moonwell of Purity, tending to its sacred waters and offering guidance to those seeking Elune's aid in the forest.",al={"who is felore moonray","moonwell keeper"}},{q="Why do Alliance adventurers visit this moonwell?",a="Alliance heroes are directed here during the task of cleansing corrupted relics recovered from the forest, such as during the investigations led by Raene Wolfrunner out of Astranaar.",al={"raene's cleansing moonwell","why come here","cleanse rod here"}}},ang={["race:NightElf"]="Every moonwell is a sacred home away from home for the kaldorei, serving as both a spiritual font of Elune's grace and a frontline bulwark against the demonic taint threatening Ashenvale.",["profession:Tailoring"]="Tailors can harness the dense lunar energies pooling within the waters to weave pure Mooncloth from felcloth."},kw={"ashenvale","cleansing","elune","felore moonray","iris lake","moonwell","moonwell of purity","raynewood retreat"},rel={"quest:991","zone:ashenvale","subzone:iris-lake","subzone:raynewood-retreat","subzone:moonwell-of-cleansing","subzone:silverwing-outpost","subzone:greenpaw-village","topic:alliance"},src={"Moonwell (Ashenvale)"}}
E["subzone:moonwell-of-cleansing"] = {t="subzone",n="Moonwell of Cleansing",z="ashenvale",s="Tucked away in central Ashenvale along the southwestern bend of the Falfarren River, the Moonwell of Cleansing is a tranquil night elf shrine. Though unmarked on common maps, it sits nestled between Mystral Lake and Silverwing Outpost, offering a place of sacred waters beneath the forest canopy.",h="Tucked away in central Ashenvale along the southwestern bend of the Falfarren River, the Moonwell of...",sec={{t="A Secluded Shrine",b="The Moonwell of Cleansing rests near the southwestern banks of the Falfarren River, just east of Mystral Lake. While it lacks an official marking on regional parchment, a wooden footbridge spans the water to link the site directly to Silverwing Outpost to the east. Night elf travelers and defenders use this sanctuary as a quiet redoubt in a contested woodland, watched over by a solitary faerie dragon—a Blink Dragon—drifting in gentle circles through the silver mist.",sp=0},{t="Waters of the Goddess",b="Like all moonwells constructed by the kaldorei, the basin gathers the luminous blessing of Elune to nurture the surrounding flora and fauna. In a forest increasingly threatened by the Warsong lumber operations and demonic taint stirring near the southern peaks, these pure springs serve as both a spiritual hearth and a bulwark against corruption, preserving the sacred vitality of Ashenvale.",sp=0}},faq={{q="Where is the Moonwell of Cleansing located?",a="It is located in Ashenvale along the southwestern stretch of the Falfarren River, situated directly between Mystral Lake to the west and Silverwing Outpost to the east. It is accessible via an unmarked wooden bridge crossing the river.",al={"moonwell cleansing location","where is moonwell of cleansing","how to find moonwell of cleansing"}},{q="Why isn't this moonwell marked on the map?",a="Like several smaller shrines and natural crossings throughout Ashenvale, the Moonwell of Cleansing is a minor sanctuary overlooked by standard cartographers, making it a quiet, hidden retreat amidst the thick wilderness.",al={"why not on map","unmarked moonwell","map icon moonwell"}},{q="What is the creature circling above the basin?",a="A Blink Dragon—a type of faerie dragon native to the enchanted woods of the kaldorei—glides endlessly in circles above the shrine, drawn to its magical currents.",al={"flying dragon","what is flying over moonwell","blink dragon"}},{q="What purpose do moonwells serve for the night elves?",a="Moonwells are sacred pools filled with water blessed by Elune and woven with natural magic. Kaldorei druids and priestesses use them to replenish spiritual energy, nourish the wild lands, and counteract regional blights or corruption.",al={"what are moonwells","why do night elves have moonwells","moonwell purpose"}}},ang={["race:NightElf"]="Nestled near Silverwing Outpost, this serene pool offers kaldorei defenders a quiet sanctuary to commune with Elune's grace away from the front lines.",["class:Druid"]="The moonwell stands as a pure reservoir of restorative magic, drawing faerie dragons and sustaining the wild growth along the Falfarren River."},kw={"ashenvale","blink dragon","elune","falfarren river","moonwell","moonwell of cleansing","mystral lake","silverwing outpost"},rel={"zone:ashenvale","subzone:silverwing-outpost","subzone:falfarren-river","subzone:mystral-lake","subzone:moonwell-ashenvale"},src={"Moonwell of Cleansing"}}
E["subzone:mor-shan-rampart"] = {t="subzone",n="Mor'shan Rampart",z="ashenvale",s="The Mor'shan Rampart is a heavily fortified Horde barricade positioned at the northern border of the Barrens, guarding the entrance to Ashenvale. Constructed primarily by the Warsong clan, it shields Horde territory from night elf counterattacks while serving as a staging ground for incursions deeper into the forest.",h="The Mor'shan Rampart is a heavily fortified Horde barricade positioned at the northern border of the Barrens...",sec={{t="The Northern Gate",b="Standing at the northern terminus of the Gold Road, the Mor'shan Rampart marks the transition between the arid plains of the Barrens and the ancient canopies of Ashenvale. Built from heavy timber, defensive palisades, and fortified watchtowers, this bulwark was raised to stem the retaliatory strikes of night elven forces outraged by the Horde's logging operations. It acts both as a shield securing the northern gate to Kalimdor's interior and as a forward staging post for raiding parties pushing north toward Astranaar.",sp=0},{t="Warsong Outpost",b="Manned primarily by battle-hardened fighters affiliated with the Warsong clan, the rampart remains under constant military readiness. From these parapets, sentries monitor the tree line for night elf scouts and archers, keeping open supply lines between the frontline outposts of Ashenvale and the greater Horde settlements to the south.",sp=0}},faq={{q="What is the Mor'shan Rampart?",a="It is a fortified Horde border post situated where the Barrens meets Ashenvale. It was constructed to block Alliance counterattacks from entering the Barrens and to guard the northern end of the Gold Road.",al={"morshan rampart","what is this barricade","northern barrens gate"}},{q="Who controls this fortification?",a="The fortification is garrisoned by the Horde, specifically warriors and sentries tied to the Warsong clan. They maintain watchtowers and palisades along the forest boundary.",al={"who holds morshan","who guards the rampart","morshan defenders"}},{q="Why is the rampart here instead of deeper in Ashenvale?",a="It anchors the northern terminus of the Gold Road, making it the primary land route connecting the central Barrens with Ashenvale. Controlling this chokepoint ensures that night elf strikes cannot easily sweep south into the heart of Horde-held lands.",al={"why build ramparts here","strategic importance morshan"}},{q="Can Alliance travelers pass through the rampart safely?",a="No. The rampart is an active Horde military position. Alliance travelers approaching from either Ashenvale or the Barrens will be attacked on sight by the stationed guards.",al={"can alliance pass","alliance crossing morshan"}}},ang={["faction:Horde"]="For the Horde, the Rampart is the primary overland gate protecting the heart of the Barrens from night elf incursions, while keeping the supply lines to Ashenvale's logging operations intact.",["faction:Alliance"]="Alliance fighters view the Mor'shan Rampart as an aggressive barricade erected by Horde lumber operations to protect stolen territory and stage raids into Ashenvale."},kw={"ashenvale","barrens","gold road","mor'shan rampart","morshan","warsong clan","warsong outriders"},rel={"zone:ashenvale","subzone:gold-road","topic:warsong-clan","topic:horde","topic:alliance","subzone:astranaar","zone:orgrimmar"},src={"Mor'shan Rampart"}}
E["subzone:mystral-lake"] = {t="subzone",n="Mystral Lake",z="ashenvale",s="Mystral Lake is the largest body of water in Ashenvale, resting in the south-central forest just below Silverwind Refuge. Once a tranquil sanctuary guarded by water elementals loyal to the night elves, its waters have become fraught with danger due to corruption of the local elementals.",h="Mystral Lake is the largest body of water in Ashenvale, resting in the south-central forest just below...",sec={{t="A Corrupted Sanctuary",b="Spanning a vast expanse south of Silverwind Refuge and east of Talondeep Vale, Mystral Lake was long cherished by the kaldorei for its pure waters and peaceful guardian elementals. However, dark interference has broken that ancient peace. The rogue mage Sarilus Foulborne turned his arts upon the lake's water spirits, corrupting them into hostile, violent entities. Today, travelers from both the Horde and Alliance frequently find their journeys pulling them to these troubled shores, contending with the wrath of spirits that once sheltered the woods.",sp=0},{t="Spiritual Crossroads",b="Beyond the corruption troubling the local night elves, Mystral Lake draws attention across faction lines. Horde shaman traveling the path of elemental communion seek out its deep waters during their trials to understand the element of water. Despite the corruption infesting its guardian spirits, the raw primal resonance of the lake makes it an essential pilgrimage site for those learning to bind and respect the tidal spirits.",sp=0}},faq={{q="Where is Mystral Lake located?",a="Mystral Lake lies in south-central Ashenvale. It sits directly south of Silverwind Refuge and east of Talondeep Vale, making it the largest open body of water in the forest.",al={"where is mystral lake","mystral lake location","lake mystral map"}},{q="Why are the water elementals here hostile?",a="The water elementals were originally peaceful and loyal to the night elves of Ashenvale. However, a rogue caster named Sarilus Foulborne corrupted them, twisting their gentle nature into relentless hostility toward any who approach the lake.",al={"why are water elementals attacking","corrupted water elementals","who corrupted mystral lake"}},{q="Why do shaman visit Mystral Lake?",a="Horde shaman are directed to Mystral Lake during their spiritual trials for the Call of Water. The lake possesses a deep elemental resonance, making it an important location for understanding and attuning to water spirits.",al={"call of water mystral lake","shaman quest mystral lake"}},{q="Who controls Mystral Lake?",a="Neither faction holds direct military control over the lake itself. The night elves monitor it from nearby outposts like Silverwind Refuge, but hostile corrupted elementals currently dominate the waters, threatening members of both the Alliance and the Horde.",al={"is mystral lake horde or alliance","who owns mystral lake"}}},ang={["class:Shaman"]="The turbulent depths of Mystral Lake serve as a vital stop during the Call of Water, where aspiring shaman must confront the local spirits to master their elemental craft.",["race:NightElf"]="Once home to peaceful guardians aligned with your people, the lake stands as a bitter reminder of the outside corruption encroaching upon Ashenvale's sacred groves."},kw={"ashenvale","call of water","lake mystral","mystral lake","sarilus foulborne","silverwind refuge","water elementals"},rel={"zone:ashenvale","subzone:silverwind-refuge","subzone:talondeep-vale","quest:63","topic:alliance","topic:horde"},src={"Mystral Lake"}}
E["subzone:night-run"] = {t="subzone",n="Night Run",z="ashenvale",s="Night Run is a small, secluded satyr outpost perched atop a cliff-ringed bluff in east-central Ashenvale. Inhabited by the demonic Felmusk satyr, it serves as a corrupted encampment harboring dark soul magic within ancient elven ruins.",h="Night Run is a small, secluded satyr outpost perched atop a cliff-ringed bluff in east-central Ashenvale.",sec={{t="A Defended Cliffside Perch",b="Night Run is the smallest and most isolated of Ashenvale's three major satyr strongholds, alongside Xavian and Satyrnaar. Sheltered among crumbling elven stonework and broken pillars, the settlement juts outward on a high ridge bounded by steep, impassable cliffs. Reaching it requires a circuitous trek along the Falfarren River near the waters of Xavian or navigating a precarious northern ledge above Raynewood Retreat. Despite its modest size, the enclave poses a severe danger: the Felmusk satyr who dwell here work in concert with the shadowy Cult of the Dark Strand, anchoring twisted soulgems to pool demonic essence within the forest.",sp=0}},faq={{q="Who controls Night Run?",a="Night Run is occupied by the Felmusk satyr, a faction of demonic night elf corrupters affiliated with the Cult of the Dark Strand.",al={"who lives at night run","night run mobs","what is at night run"}},{q="How do you reach Night Run?",a="Because it sits on an elevated bluff bordered by sheer cliffs, travelers must approach either via a narrow ledge north of Raynewood Retreat or by tracking along the Falfarren River toward Xavian before cutting west up the ridge.",al={"how to get to night run","night run path","night run entrance"}},{q="What is the Cult of the Dark Strand doing here?",a="The cult works alongside the satyrs, maintaining a dark soulgem within Night Run to harvest and channel demonic energies across Ashenvale.",al={"cult of the dark strand night run","soulgem night run"}},{q="What historical events happened at Night Run?",a="Thousands of years ago, following the Great Sundering, early druids wielding the feral Pack Form attacked night elf Sentinels here, wounding Shandris Feathermoon and marking an explosive opening in the War of the Satyr.",al={"night run lore","war of the satyr night run"}}},ang={["race:NightElf"]="The defilement of Night Run is an enduring scar: these ancient stones were soaked in night elf blood during the War of the Satyr and remain corrupted by the twisted Felmusk.",["faction:Alliance"]="Nestled just north of Raynewood Retreat, Night Run represents an ever-present demonic menace overlooking crucial Sentinel supply lines."},kw={"ashenvale","cult of the dark strand","falfarren river","felmusk","night run","satyr","soulgem"},rel={"subzone:xavian","subzone:satyrnaar","subzone:raynewood-retreat","subzone:falfarren-river","zone:ashenvale","topic:satyr","topic:sentinels"},src={"Night Run"}}
E["subzone:nightsong-woods"] = {t="subzone",n="Nightsong Woods",z="ashenvale",s="Nightsong Woods forms the embattled eastern expanse of Ashenvale, reaching from Raynewood Retreat toward the borders of Azshara. It serves as the primary battleground between the night elves defending their sacred forest and the Warsong clan harvesting lumber for the Horde. Across its shadowed glades, ancient groves clash with fortified encampments amidst persistent demonic corruption.",h="Nightsong Woods forms the embattled eastern expanse of Ashenvale, reaching from Raynewood Retreat toward the...",sec={{t="A Forest Carved by War",b="Stretching eastward across Ashenvale to Azshara, Nightsong Woods is defined by escalating violence. The Falfarren River bisects the western reaches, creating a volatile boundary between Alliance settlements and Horde encroachments. Further east, the forest fractures into heavily disputed territories where Splintertree Post coordinates Horde campaigns against the Silverwing Sentinels and Forest Song. Orcish axes continuously clear southern groves to fuel the Horde's expansion, leaving clear-cut swaths that infuriate the Kaldorei. Adding to the peril, satyr strongholds like Satyrnaar and Xavian, alongside demonic remnants in Demon Fall Canyon and Felfire Hill, taint the eastern canopies.",sp=0}},faq={{q="Where are the Nightsong Woods located?",a="Nightsong Woods encompasses the eastern half of Ashenvale. Its boundaries extend from Raynewood Retreat and the northern road to Felwood all the way east to the untamed border of Azshara.",al={"nightsong woods location","where is nightsong woods","ashenvale east woods"}},{q="Why is there so much fighting in this part of Ashenvale?",a="The region sits on the frontline of the conflict between the Silverwing Sentinels and the Warsong clan. The Horde relies heavily on the dense timber harvested from the southern trees to build and sustain their settlements, while the night elves fight fiercely to halt the clear-cutting and reclaim their ancestral land.",al={"why fighting in nightsong woods","horde vs alliance ashenvale","warsong conflict"}},{q="Who controls Nightsong Woods?",a="No single faction holds dominion over the woods. The Falfarren River roughly separates western Alliance territory from eastern Horde positions around Splintertree Post and the Warsong Lumber Camp. Pockets of the woodland are also held by corrupt satyr at Satyrnaar and Xavian, as well as Legion forces near Demon Fall Canyon.",al={"who owns nightsong woods","nightsong woods faction control"}},{q="What demonic threats exist here?",a="The eastern wilderness hosts significant demonic and corruptive influences. Satyr dwell in fortified ancient ruins such as Satyrnaar and Xavian, while lingering Burning Legion fiends inhabit Felfire Hill and the depths of Demon Fall Canyon.",al={"demons in nightsong woods","satyr in eastern ashenvale","felfire hill demons"}}},ang={["race:NightElf"]="Nightsong Woods represents a sacred borderland under siege; defending its ancient groves from Warsong axes and purging lingering satyr corruption are matters of fundamental duty for the Kaldorei.",["faction:Horde"]="This eastern front secures vital building timber and strategic supply lanes through Splintertree Post, demanding vigilance against Sentinel ambushes and demonic beasts."},kw={"ashenvale","falfarren river","nightsong woods","satyrnaar","silverwing sentinels","splintertree post","warsong lumber camp"},rel={"zone:ashenvale","subzone:splintertree-post","subzone:silverwing-grove","subzone:warsong-lumber-camp","subzone:falfarren-river","subzone:raynewood-retreat","subzone:satyrnaar","subzone:demon-fall-canyon"},src={"Nightsong Woods"}}
E["subzone:raynewood-retreat"] = {t="subzone",n="Raynewood Retreat",z="ashenvale",s="Raynewood Retreat is an ancient night elf outpost perched around a massive great tree in north-central Ashenvale. Guarded by dryads and Cenarion protectors, it serves as a watchful sanctuary monitoring the northern passes toward corrupted Felwood. It is also the sanctuary of Keeper Ordanus, an elder son of Cenarius targeted by sinister outside forces.",h="Raynewood Retreat is an ancient night elf outpost perched around a massive great tree in north-central...",sec={{t="Bastion of the Great Tree",b="Long before the modern conflicts between the Alliance and Horde, Raynewood Retreat served as a military staging ground for night elf defenders during the ancient War of the Satyr millennia ago. Today, the encampment retains its sacred martial purpose. Nestled between Shael'dryn's moonwell and the satyr-infested ruins of Night Run, the outpost is fiercely guarded by Cenarion Protectors, faerie dragons, and Laughing Sisters. Their collective vigilance keeps a wary eye on the encroaching taint descending from Felwood just to the north.",sp=0},{t="The Hunt for Ordanus",b="High atop the boughs of the great tree resides Keeper Ordanus, one of Cenarius's eldest sons. While the canopy offers him refuge, it has also become a focal point of dark intrigue. Agents aligned with the shadowy remnants of the Shadow Council, notably Braelyn Firehand, seek the keeper's demise. Horde mercenaries are dispatched to storm the heights and claim his head, turning what should be a peaceful forest sanctuary into a battleground.",sp=1}},faq={{q="What is Raynewood Retreat?",a="Raynewood Retreat is a night elf and Cenarion settlement situated around a Great Tree in north-central Ashenvale. It acts as an Alliance-aligned sanctuary and watchpost monitoring the approaches to Felwood.",al={"raynewood retreat","what is this place","raynewood tree"}},{q="Who lives at Raynewood Retreat?",a="The outpost is defended by Cenarion Protectors, dryads known as Laughing Sisters, and faerie dragons. Its most prominent resident is Keeper Ordanus, who dwells high within the great tree.",al={"who is here","raynewood mobs","who guards raynewood"}},{q="Who is Keeper Ordanus?",a="Keeper Ordanus is a powerful keeper of the grove and one of the eldest sons of the demigod Cenarius. He oversees the sanctuary but finds himself hunted by hostile infiltrators.",al={"keeper ordanus","who is ordanus","ordanus lore"}},{q="Why does the Horde attack Raynewood Retreat?",a="A blood elf operative named Braelyn Firehand, acting on behalf of the Shadow Council, hires Horde adventurers to infiltrate the tree and assassinate Keeper Ordanus, seeking his head for dark purposes.",al={"horde raynewood quest","why kill ordanus","braelyn firehand quest"}},{q="What is the history of this place?",a="Nearly ten thousand years ago, during the War of the Satyr, the night elf military utilized Raynewood Retreat as an operational base to combat the demonic satyr forces threatening Kalimdor.",al={"raynewood history","war of the satyr raynewood"}}},ang={["class:Druid"]="Raynewood Retreat is holy ground under the stewardship of Cenarius's children, serving as a bulwark against demonic and fel corruption.",["faction:Horde"]="To the Horde, the retreat is an Alliance-friendly grove whose guardian, Keeper Ordanus, is targeted for elimination by covert questgivers."},kw={"ashenvale","braelyn","cenarius","felwood","laughing sister","ordanus","raynewood","retreat"},rel={"npc:braelyn-firehand","quest:1088","topic:cenarius","topic:satyr","zone:ashenvale","zone:felwood","subzone:night-run","npc:shael-dryn"},src={"Raynewood Retreat"}}
E["subzone:ruins-of-ordil-aran"] = {t="subzone",n="Ruins of Ordil'Aran",z="ashenvale",s="The Ruins of Ordil'Aran are the crumbling remnants of an ancient night elf settlement in northwestern Ashenvale, situated between Maestra's Post and Bathran's Haunt. Once a hidden redoubt for shadow cultists, the fallen stones have recently been overrun by the corrupted Thistlefur furbolgs.",h="The Ruins of Ordil'Aran are the crumbling remnants of an ancient night elf settlement in northwestern...",sec={{t="A Contested Ruin",b="Little remains of the original Kaldorei architecture at Ordil'Aran save for weathered pillars, cracked arches, and moss-draped stonework. For a time, the isolated ruins served as a lair for the Cult of the Dark Strand, who lurked among the debris to ambush travelers along the northwestern paths of Ashenvale. Recently, however, violent furbolgs of the Thistlefur tribe drove out the cultists in a bloody takeover. The bodies of fallen Dark Strand practitioners still litter the ground while aggressive furbolgs patrol the perimeter, fiercely guarding the site and the ancient Heartswood tree growing within.",sp=0}},faq={{q="What was Ordil'Aran originally?",a="Ordil'Aran was an ancient night elf settlement dating back before the Great Sundering. Like many Kaldorei outposts across Ashenvale, it fell into decay over millennia, leaving behind only overgrown stone arches and crumbling masonry.",al={"ordilaran history","what is ordil aran","who built ordil'aran"}},{q="Why are there dead cultists lying around the ruins?",a="The Cult of the Dark Strand previously used these ruins as a base of operations. The Thistlefur furbolgs violently attacked and ousted them, seizing the ruins for themselves and leaving slain cultists strewn across the site.",al={"dead cultists","dark strand corpses","why are cultists dead here"}},{q="What is the Heartswood?",a="The Heartswood is a distinctive ancient tree growing within the Ruins of Ordil'Aran. Its branches and wood are sought after for their potent magical and natural properties.",al={"heartswood tree","heartswood quest","heartswood ordil'aran"}},{q="Who currently controls the ruins?",a="The aggressive Thistlefur furbolgs currently occupy the ruins, having slain or driven out the Dark Strand cultists who previously inhabited the area.",al={"who lives here","who is at ordil aran","ordilaran mobs"}}},ang={["race:NightElf"]="The ruins are another painful reminder of the Kalimdor empire's collapse, now defiled by corrupt furbolgs and dark cultists.",["faction:Alliance"]="Positioned just north of Maestra's Post, the aggressive occupants of Ordil'Aran threaten Alliance scouts and travelers heading toward Darkshore."},kw={"ashenvale","cult of the dark strand","heartswood","maestra's post","ordil'aran","ordilaran","ruins","thistlefur"},rel={"subzone:maestra-s-post","subzone:bathran-s-haunt","subzone:tower-of-althalaxx","quest:1738","quest:965","zone:ashenvale","topic:furbolg","topic:night-elf"},src={"Ruins of Ordil'Aran"}}
E["subzone:ruins-of-stardust"] = {t="subzone",n="Ruins of Stardust",z="ashenvale",s="The Ruins of Stardust are an ancient, fallen night elven holy sanctuary nestled on a lake island in southwestern Ashenvale. Once a serene place of worship, the island's waters and native bog beasts have suffered corruption from demonic rot washing down from Felwood. Despite this pervasive blight, luminous stardust shrubs still thrive amidst the crumbling stones, retaining potent restorative power.",h="The Ruins of Stardust are an ancient, fallen night elven holy sanctuary nestled on a lake island in...",sec={{t="A Blighted Sanctuary",b="Resting on a solitary island south of Astranaar, the Ruins of Stardust were once a venerated night elf holy site. Today, an eerie, sickly yellowish-green hue hangs over the water—a consequence of foul demonic rot draining south from Felwood, much like at nearby Iris Lake. The local plant life has twisted into hostile bog beasts that prowl the fallen masonry, their temperaments warped by the tainted lake.",sp=0},{t="The Enduring Stardust",b="Despite the corruption saturating the soil and shoreline, the island possesses an unyielding spark of resilience. Scattered among the ruins are stardust shrubs, blooming unmarred by the demonic taint. Their leaves and blossoms hold remarkable cleansing and healing virtues, attracting shamans, herbalists, and local night elf defenders seeking remedies against Ashenvale's encroaching decay.",sp=0}},faq={{q="What were the Ruins of Stardust originally used for?",a="In ancient times, the site was a sacred holy ground tended by the night elves. Its classical marble pillars and lakeside perch served as a tranquil place of reverence long before demonic corruption took root in the forest.",al={"what are the ruins","stardust lore","who built stardust"}},{q="Why is the water around the island discolored?",a="Demonic corruption seeping down from the blighted peaks of Felwood into Ashenvale's waterways has tainted the lake, tinting the waters a murky, yellowish-green shade and disturbing the natural balance.",al={"why is water green","why is the lake corrupted","stardust water"}},{q="What makes the stardust shrubs special?",a="Despite growing in soil soaked in demonic runoff, stardust shrubs remain completely pure. They resist the ambient taint and possess exceptional restorative and healing properties, making them valuable reagents for cleansing rituals.",al={"what is stardust shrub","stardust plant","stardust bushes"}},{q="What creatures wander the ruins?",a="The island is overrun by large, corrupted bog beasts. The lake's tainted water has warped these nature elementals from peaceful forest guardians into aggressive, lumbering threats to anyone crossing the shallows.",al={"stardust mobs","what monsters are here","bog beasts"}}},ang={["class:Shaman"]="The uncorrupted stardust found here serves as a vital cleansing reagent during spiritual trials, including the vital Call of Water trials to master the restorative elements.",["race:NightElf"]="Watching this former sanctuary succumb to Felwood's slow, putrid runoff is a painful reminder of the ongoing struggle to protect Ashenvale from enduring demonic corruption."},kw={"ashenvale","bog beasts","felwood taint","night elf ruins","ruins of stardust","stardust shrubs","water corruption"},rel={"zone:ashenvale","quest:63","quest:1034","subzone:iris-lake","zone:felwood","subzone:astranaar","subzone:talondeep-path"},src={"Ruins of Stardust"}}
E["subzone:satyrnaar"] = {t="subzone",n="Satyrnaar",z="ashenvale",s="Satyrnaar is an ancient, ruined night elf settlement in northeastern Ashenvale that has fallen entirely into the hands of the Bleakheart satyrs. Perched just off the main road between Splintertree Post and Azshara, it is the most intact and easily accessible of the satyr strongholds in the forest.",h="Satyrnaar is an ancient, ruined night elf settlement in northeastern Ashenvale that has fallen entirely into...",sec={{t="A Den of Fel and Shadow",b="Located northeast of Splintertree Post and southwest of Forest Song, Satyrnaar stands as one of Ashenvale's three primary satyr settlements alongside Xavian and Night Run. Unlike the deeper wilderness ruins, Satyrnaar is relatively well-preserved, featuring pitched tents nestled among crumbled elven architecture. It serves as a bustling camp for the Bleakheart satyrs, making the nearby trade route fraught with peril for travelers moving east toward Azshara. Furthermore, dark ties fester here: the satyrs have forged an alliance with the shadowy Cult of the Dark Strand, harboring one of their insidious soulgems amidst the corrupted stones.",sp=0}},faq={{q="What is Satyrnaar?",a="Satyrnaar is a ruined night elf site in northeastern Ashenvale that has been claimed and occupied by the Bleakheart satyrs. It serves as one of their primary strongholds in the region.",al={"satyrnaar overview","what is this place","satyr camp"}},{q="Who lives in Satyrnaar?",a="The settlement is held by the Bleakheart tribe of satyrs. They have erected tents among the ancient ruins and work in league with the Cult of the Dark Strand.",al={"who is here","satyrnaar mobs","bleakheart satyrs"}},{q="Why is Satyrnaar significant compared to other satyr ruins?",a="Of the three main satyr sites in Ashenvale—Satyrnaar, Night Run, and Xavian—Satyrnaar is the most intact and centrally located, lying right off the road toward Azshara.",al={"satyrnaar vs xavian","why satyrnaar"}},{q="What is the dark artifact hidden in Satyrnaar?",a="Satyrnaar houses one of the corrupted soulgems belonging to the Cult of the Dark Strand, a mortal shadow cult allied with the Bleakheart satyrs.",al={"dark strand soulgem","satyrnaar crystal","soulgem"}}},ang={["race:NightElf"]="Seeing ancestral stonework defiled by fel corruption and inhabited by the cursed remnants of the Highborne is a bitter offense to any night elf traveling through Ashenvale.",["class:Druid"]="The twisted fel corruption spread by the Bleakheart satyrs actively chokes the natural spirit of Ashenvale, demanding swift cleansing."},kw={"ashenvale","bleakheart","dark strand","forest song","satyr","satyrnaar","soulgem","splintertree"},rel={"zone:ashenvale","topic:satyr","subzone:splintertree-post","subzone:forest-song","subzone:night-run","subzone:xavian","zone:azshara","topic:emerald-dream"},src={"Satyrnaar"}}
E["subzone:shrine-of-aessina"] = {t="subzone",n="Shrine of Aessina",z="ashenvale",s="The Shrine of Aessina is a sacred elven landmark nestled in the forests of southwestern Ashenvale, dedicated to the ancient forest spirit of nature and wild creatures. Located between Maestra's Post and Astranaar, it stands as a serene sanctuary amidst the growing border friction in the region.",h="The Shrine of Aessina is a sacred elven landmark nestled in the forests of southwestern Ashenvale, dedicated...",sec={{t="A Sanctuary of the Deep Woods",b="Tucked away south of the House of Edune and west of Astranaar, the Shrine of Aessina honors the mysterious Wild God who embodies the heart and spirit of the deep forests. For generations, night elves and their woodland kin have revered this quiet place, communing with nature away from the bustling main roads. However, with the Horde pushing into Ashenvale to gather timber and establish footholds, sacred grounds throughout the territory face an uncertain peace.",sp=0}},faq={{q="Who is Aessina?",a="Aessina is a revered ancient nature spirit and Wild God associated with the heart of pristine forests. Night elves and woodland beings honor her as the living soul of nature, embodying the untamed wilderness.",al={"aessina lore","who is aessina","shrine of aessina goddess"}},{q="Where is the Shrine of Aessina located?",a="The shrine lies in southwestern Ashenvale, situated southwest of Maestra's Post, west of the settlement of Astranaar, and just south of the House of Edune.",al={"shrine of aessina location","where is shrine of aessina","find shrine of aessina"}},{q="Why is this place significant to the night elves?",a="The shrine serves as an ancient holy retreat dedicated to woodland spirits. Sites like this connect night elf society and druidic traditions directly to the untamed wilderness of Kalimdor.",al={"importance of aessina shrine","night elf sacred site"}}},ang={["class:Druid"]="As an ancient sanctuary honoring the living spirit of the wild woods, the shrine is a place of profound significance to those devoted to preserving Kalimdor's natural balance.",["race:NightElf"]="For the Kaldorei, the shrine represents centuries of harmony with Ashenvale's native spirits, now constantly threatened by encroaching outside forces."},kw={"aessina","ashenvale","astranaar","kaldorei","maestra's post","nature shrine","shrine of aessina","wild god"},rel={"zone:ashenvale","subzone:astranaar","subzone:maestra-s-post","topic:alliance","topic:horde"},src={"Shrine of Aessina"}}
E["subzone:silverwind-refuge"] = {t="subzone",n="Silverwind Refuge",z="ashenvale",s="Silverwind Refuge is a serene night elven settlement nestled in south-central Ashenvale, situated just north of Mystral Lake. Protected by Sentinels and allied water elementals, it offers a welcoming haven for travelers along the forest's wooded trails.",h="Silverwind Refuge is a serene night elven settlement nestled in south-central Ashenvale, situated just north...",sec={{t="A Forest Sanctuary",b="Resting between the placid waters of Mystral Lake and Iris Lake to the north, Silverwind Refuge stands as one of the major night elven waystations in central Ashenvale alongside Astranaar. It boasts a comfortable inn, craftsmen, and wilderness trainers who instruct travelers in herbalism, alchemy, skinning, and hunting. Guarded by stalwart Sentinels alongside local water spirits, the retreat serves as a peaceful rest stop for allies moving through the shaded ancient woods.",sp=0}},faq={{q="Who controls Silverwind Refuge?",a="Silverwind Refuge is an Alliance settlement, built and maintained by the night elves. It is heavily guarded by the Sentinels, alongside water elementals who help protect the tranquil grounds.",al={"who owns silverwind refuge","is silverwind alliance or horde","who lives at silverwind"}},{q="Where is Silverwind Refuge located?",a="It is located in south-central Ashenvale, positioned directly north of Mystral Lake and south of Iris Lake.",al={"silverwind refuge location","where is silverwind refuge","how to get to silverwind"}},{q="What services are found at the refuge?",a="Travelers can find an inn, trade supply vendors, and professional trainers offering instruction in herbalism, alchemy, skinning, and hunter skills.",al={"what is at silverwind refuge","silverwind refuge trainers","silverwind vendors"}}},ang={["faction:Alliance"]="For Alliance wanderers traversing Ashenvale, Silverwind Refuge provides a reliable camp to rest, restock supplies, and refine wilderness trades without venturing all the way to Astranaar.",["profession:Herbalism"]="The refuge serves as a vital stop in Ashenvale for gatherers, offering on-site herbalism training surrounded by the rich flora of Mystral Lake."},kw={"ashenvale","iris lake","mystral lake","night elf","sentinels","silverwind refuge"},rel={"zone:ashenvale","subzone:mystral-lake","subzone:iris-lake","subzone:astranaar","topic:sentinels"},src={"Silverwind Refuge"}}
E["subzone:silverwing-grove"] = {t="subzone",n="Silverwing Grove",z="ashenvale",s="Tucked away in south-central Ashenvale near Fallen Sky Lake, Silverwing Grove serves as the staging grounds for the Silverwing Sentinels. From this fortified hollow, night elf warriors muster Alliance forces to push back the Warsong Clan loggers tearing through the forest.",h="Tucked away in south-central Ashenvale near Fallen Sky Lake, Silverwing Grove serves as the staging grounds...",sec={{t="Front Line of the Forest War",b="Hidden beneath the emerald canopy southwest of Silverwing Outpost, Silverwing Grove is a crucial military staging post for the Silverwing Sentinels. Rather than a tranquil woodland retreat, it functions as the operational heartbeat for the night elves' bitter territorial contest against the Horde's lumber operations in Warsong Gulch. High-ranking Alliance officers, provisions, and scouts gather here, organizing skirmishes and marshaling champions to defend ancient Ashenvale against orcish expansion.",sp=0}},faq={{q="What is the purpose of Silverwing Grove?",a="Silverwing Grove serves as the staging base for the Silverwing Sentinels. It is where the night elf military and their Alliance allies organize efforts to contest the Warsong Clan's deforesting efforts and enter the ongoing conflict in Warsong Gulch.",al={"why is silverwing grove here","what is silverwing grove","purpose of silverwing grove"}},{q="Where is Silverwing Grove located?",a="It is located in south-central Ashenvale, situated southwest of Silverwing Outpost and just west of Fallen Sky Lake.",al={"silverwing grove location","where is silverwing grove","how to find silverwing grove"}},{q="Who operates out of Silverwing Grove?",a="The grove is manned by the Silverwing Sentinels alongside Alliance military commanders, including an Alliance Brigadier General, logistical vendors, and officers such as Sentinel Farsong who coordinate efforts against the Horde.",al={"who is at silverwing grove","silverwing grove npcs","who runs silverwing grove"}},{q="Can Horde players enter Silverwing Grove?",a="No. The grove is an active military post populated by hostile Alliance sentinels and guards who will immediately attack any encroaching Horde members on sight.",al={"is silverwing grove hostile","can horde go to silverwing grove","horde silverwing grove"}}},ang={["race:NightElf"]="For the kaldorei, Silverwing Grove represents the steadfast resolve to halt the desecration of sacred trees at the axes of the Warsong Clan.",["faction:Alliance"]="The grove is the primary staging ground for Alliance champions seeking to muster and enter the bloody skirmishes of Warsong Gulch."},kw={"ashenvale","fallen sky lake","sentinel farsong","silverwing grove","silverwing sentinels","warsong gulch"},rel={"subzone:silverwing-outpost","topic:sentinels","npc:sentinel-farsong","quest:1035","zone:ashenvale","topic:alliance","topic:horde"},src={"Silverwing Grove"}}
E["subzone:silverwing-outpost"] = {t="subzone",n="Silverwing Outpost",z="ashenvale",s="Silverwing Outpost is a fortified night elf garrison positioned in south-central Ashenvale, east of the Falfarren River. Commanded by Duriel Moonfire, it stands as the easternmost bastion of the Alliance against the Horde in the contested woodland.",h="Silverwing Outpost is a fortified night elf garrison positioned in south-central Ashenvale, east of the...",sec={{t="East of the Falfarren",b="Situated southwest of Splintertree Post and just north of the border with the Barrens, Silverwing Outpost holds an inherently perilous strategic position. By sitting on the eastern side of the Falfarren River—territory heavily contested and patrolled by the Horde—the outpost serves as a direct shield for night elf holdings deeper in the forest. Duriel Moonfire and her Silverwing Sentinels remain under constant siege from nearby orcs determined to purge night elf forces from the area entirely.",sp=0},{t="The Constant Front",b="The skirmishes surrounding Silverwing Outpost are among the fiercest in Ashenvale. Orcish war parties based out of Splintertree Post, such as raiders led by Torek, launch relentless ambushes against the garrison's walls. For the Horde, neutralizing the outpost is essential to securing the road and expanding resource operations without the constant threat of Sentinel counterattacks.",sp=1}},faq={{q="Where is Silverwing Outpost located?",a="It is located in south-central Ashenvale, southwest of Splintertree Post, north of the Barrens border, and on the eastern side of the Falfarren River.",al={"silverwing location","where is silverwing","silverwing outpost map"}},{q="Who commands Silverwing Outpost?",a="The outpost is commanded by Duriel Moonfire, a night elf officer leading the Silverwing Sentinels defending the eastern reaches of the forest.",al={"silverwing leader","who leads silverwing outpost","duriel moonfire"}},{q="Why does the Horde target this outpost so aggressively?",a="Silverwing Outpost sits directly on the eastern side of the Falfarren River near Splintertree Post. Its presence allows the Sentinels to cut off Horde supply lines and directly threaten orcish operations in Ashenvale.",al={"why attack silverwing","horde interest in silverwing","splintertree vs silverwing"}},{q="Who are the Silverwing Sentinels?",a="The Silverwing Sentinels are a militant order of night elf warriors and huntresses dedicated to protecting Ashenvale from incursions, particularly against the encroaching lumber camps and war parties of the Horde.",al={"what are silverwings","silverwing sentinels lore","silverwing faction"}}},ang={["faction:Alliance"]="Silverwing Outpost serves as your vital forward redoubt on the Horde side of the river, checking orc expansion out of Splintertree Post.",["faction:Horde"]="For the Horde, the outpost is an intolerable thorn in the side of Splintertree Post, directly obstructing your movements and supply lines through southern Ashenvale."},kw={"ashenvale","duriel moonfire","falfarren river","silverwing outpost","silverwing sentinels","splintertree post","torek"},rel={"zone:ashenvale","subzone:splintertree-post","subzone:falfarren-river","quest:6544","topic:sentinels","topic:horde","topic:alliance","zone:barrens"},src={"Silverwing Outpost"}}
E["subzone:skunkworks"] = {t="subzone",n="Skunkworks",z="ashenvale",s="The Skunkworks is a bustling goblin experimental camp tucked within the northern reaches of Silverwind Refuge in Ashenvale. Operated by Venture-minded tinkerers under Horde contract, the site hums with dangerous prototypes and volatile explosives designed to bolster regional military efforts.",h="The Skunkworks is a bustling goblin experimental camp tucked within the northern reaches of Silverwind Refuge...",sec={{t="Gears and Gunpowder",b="Tucked away in the northern section of Silverwind Refuge, the Skunkworks serves as a covert proving ground for volatile goblin engineering. Supervised on-site by Foreman Jinx and driven by Chief Bombgineer Sploder, technicians labor day and night amid ticking gears and chemical fumes. The encampment centers around heavy machinery—including a towering Super Reaper 6000—where experimental armaments are assembled and tested under perilous conditions before being deployed across contested frontiers.",sp=0}},faq={{q="What is the Skunkworks?",a="The Skunkworks is a goblin engineering encampment situated within the northern half of Silverwind Refuge in Ashenvale. It acts as an open-air workshop for constructing and testing heavy munitions and machinery.",al={"what is skunkworks","skunkworks camp","goblin camp ashenvale"}},{q="Who leads the operation at the Skunkworks?",a="Chief Bombgineer Sploder oversees the technical and explosive development from atop a Super Reaper 6000, while Foreman Jinx manages logistical duties and directs operatives working in the area.",al={"who runs skunkworks","chief bombgineer sploder","foreman jinx"}},{q="Why is the Horde using goblin engineering here?",a="The Horde relies on goblin technical expertise to overcome Alliance resistance and regional wilderness threats throughout Ashenvale, utilizing outsourced inventions to manufacture devastating prototypes like experimental bombs.",al={"horde connection","why are goblins here"}}},ang={["profession:Engineering"]="The Skunkworks displays the peak of chaotic goblin ingenuity, crammed with volatile ordnance and mechanized shredder units that push prototype designs to their absolute limits.",["faction:Horde"]="Foreman Jinx coordinates operations here, securing dangerous technical payloads that help shift the brutal balance of power within the contested forests of Ashenvale."},kw={"ashenvale","bombgineer","foreman jinx","goblin","silverwind refuge","skunkworks","sploder","super reaper 6000"},rel={"subzone:silverwind-refuge","zone:ashenvale","topic:goblin","topic:horde","quest:1093"},src={"Skunkworks"}}
E["subzone:splintertree-post"] = {t="subzone",n="Splintertree Post",z="ashenvale",s="Splintertree Post is the primary Horde fortress in eastern Ashenvale, situated northwest of Felfire Hill. Established by Grommash Hellscream and the Warsong clan during the Third War, it serves as a heavily fortified bulwark against the night elves and a staging ground for territorial expansion.",h="Splintertree Post is the primary Horde fortress in eastern Ashenvale, situated northwest of Felfire Hill.",sec={{t="A Frontier Stronghold",b="Carved straight out of the ancient woodlands, Splintertree Post serves as the Horde's main military and logistical hub across eastern Ashenvale. Originally established by Grommash Hellscream and the Warsong clan when orcs first pressed into the forest during the Third War, it remains a heavily armed enclave defended primarily by orcish and tauren scouts and warriors. Armed with a flight master, an inn, and steady supply lines to Orgrimmar, it anchors the Horde's contested presence beneath the canopy.",sp=0},{t="The Constant Threat of Retaliation",b="Splintertree Post exists in a state of perpetual readiness. The night elves have neither forgotten nor forgiven Grommash's actions during the war, nor do they tolerate ongoing orcish logging and raids against Astranaar. As a result, the settlement faces constant retaliatory strikes and guerilla attacks from the Sentinels hiding in the surrounding timber, testing the garrison's watchmen at all hours.",sp=0}},faq={{q="Who founded Splintertree Post?",a="It was established by Grommash Hellscream and the Warsong clan when the orcs first pushed into Ashenvale during the Third War to gather timber and establish a foothold.",al={"who built splintertree","splintertree founder","grom splintertree"}},{q="Why do the night elves frequently attack this base?",a="The night elves view Splintertree as an illegal, desecrating intrusion on ancestral lands. Hostility lingers from Grommash's brutal campaigns in the Third War, fueled further by ongoing Horde logging and skirmishes against the nearby elven stronghold of Astranaar.",al={"why are elves attacking","splintertree sentinel attacks","night elf raids splintertree"}},{q="What amenities and travel options are available here?",a="Splintertree Post provides an inn, stable master, mailbox, armor repair, and a wind rider flight master with routes connecting to Orgrimmar, the Crossroads, Valormok, Zoram'gar Outpost, and the Emerald Sanctuary.",al={"splintertree flight path","splintertree services","splintertree inn"}},{q="Who currently makes up the garrison at Splintertree?",a="The settlement is populated primarily by orcs and tauren, functioning as seasoned scouts, sentries, and frontline officers tasked with holding the frontier.",al={"splintertree guards","who lives in splintertree","splintertree races"}}},ang={["faction:Horde"]="Splintertree Post is the essential central base camp for adventurers pressing through Ashenvale, offering repairs, respite, and crucial flight routes across Kalimdor.",["race:NightElf"]="To the night elves, this fortress is a bitter scar upon Ashenvale, founded by the very warlord who struck down Cenarius and perpetuated by invaders who butcher their ancient trees."},kw={"ashenvale","astranaar","felfire hill","grommash hellscream","splintertree post","vhulgra","warsong clan"},rel={"zone:ashenvale","topic:warsong-clan","topic:grommash-hellscream","subzone:astranaar","subzone:felfire-hill","zone:orgrimmar","subzone:zoram-gar-outpost","topic:third-war"},src={"Splintertree Post"}}
E["subzone:stardust-spire"] = {t="subzone",n="Stardust Spire",z="ashenvale",s="Stardust Spire is an ancient elven watchtower perched in the forested hills of southern Ashenvale, looking down toward Talondeep Pass. Standing atop the remnants of a far older structure, it sits adjacent to the haunted Ruins of Stardust, serving as an enduring sentinel over the mountain road.",h="Stardust Spire is an ancient elven watchtower perched in the forested hills of southern Ashenvale, looking...",sec={{t="A Sentry on the Mountain Pass",b="Stardust Spire consists of a reinforced night elf sentry tower constructed over the crumbling foundation of a much larger ancient elven ruin. Located just north of the crags of Talondeep Pass leading into the Stonetalon Mountains, its high vantage point provides a clear view over the southern woodlands of Ashenvale. The tower takes its name from the nearby Ruins of Stardust, where restless spirits linger among fallen colonnades and moonlit waters.",sp=0}},faq={{q="Where is Stardust Spire located?",a="It stands in southern Ashenvale, situated upon high ground just north of the trail leading into Talondeep Pass and the Stonetalon Mountains.",al={"stardust spire location","where is stardust spire"}},{q="Why is it called Stardust Spire?",a="The tower is named after the nearby Ruins of Stardust, an ancient elven site nestled among the nearby trees and waters.",al={"stardust spire name","why stardust spire"}},{q="What was the spire originally?",a="The present watchtower sits directly atop the stonework and foundations of a far larger structure built by the ancient night elves prior to the Sundering.",al={"stardust spire history","who built stardust spire"}}},ang={["race:NightElf"]="Stardust Spire represents the enduring vigil of your kin, guarding the southern approaches to Ashenvale from an ancient, shored-up watchtower.",["faction:Alliance"]="Positioned over the southern routes into Ashenvale, this vantage point watches over the winding passes that connect the forest to the Stonetalon Mountains."},kw={"ashenvale","night elf tower","ruins of stardust","stardust spire","stonetalon mountains","talondeep pass"},rel={"zone:ashenvale","subzone:ruins-of-stardust","subzone:talondeep-pass","zone:stonetalon","topic:sentinels","topic:night-elf","topic:alliance"},src={"Stardust Spire"}}
E["subzone:talondeep-vale"] = {t="subzone",n="Talondeep Vale",z="ashenvale",s="Talondeep Vale is a quiet, forested hollow nestled in south-central Ashenvale. Bordering Silverwind Refuge, the Ruins of Stardust, and the gateway to the Stonetalon Mountains, it acts as a peaceful canopy through which travelers navigate southern Kalimdor.",h="Talondeep Vale is a quiet, forested hollow nestled in south-central Ashenvale.",sec={{t="A Sheltered Valley",b="Tucked away beneath the dense canopy of south-central Ashenvale, Talondeep Vale serves as a crossroads between several landmark sites. It is framed by Silverwind Refuge to the east, the haunting Ruins of Stardust and Stardust Spire nearby, and the rugged rise leading up into the Stonetalon Mountains. Shaded by ancient trees, the valley remains an untamed tract of woodland through which night elf wardens, sentinels, and passing wanderers traverse as they move between the heart of the forest and the high crags beyond.",sp=0}},faq={{q="Where is Talondeep Vale located?",a="Talondeep Vale lies in south-central Ashenvale, nestled between Silverwind Refuge, the ancient Ruins of Stardust, and the southern mountain pass heading into the Stonetalon Mountains.",al={"where is talondeep vale","talondeep vale location","how to find talondeep vale"}},{q="Where does the path leading south through the vale go?",a="Following the trail through the vale leads travelers toward Talondeep Path, an ascent through the rugged heights connecting the woodlands of Ashenvale directly with the arid peaks of the Stonetalon Mountains.",al={"path south talondeep vale","where does talondeep pass lead","road to stonetalon"}},{q="What nearby landmarks should travelers watch for?",a="The vale sits adjacent to Silverwind Refuge to the east, as well as Stardust Spire and the waterlogged Ruins of Stardust, where ancient night elven remnants still stand beneath the tree boughs.",al={"landmarks near talondeep vale","what is near talondeep vale"}}},ang={["race:NightElf"]="Nestled near the sacred waters of Mystral Lake and the Ruins of Stardust, these valley paths are familiar ground to the sentinels and wardens patrolling southern Ashenvale."},kw={"ashenvale","ruins of stardust","silverwind refuge","stardust spire","talondeep pass","talondeep path","talondeep vale"},rel={"subzone:talondeep-path","subzone:silverwind-refuge","subzone:ruins-of-stardust","subzone:stardust-spire","zone:ashenvale","subzone:talondeep-pass","quest:1034"},src={"Talondeep Vale"}}
E["subzone:thistlefur-hold"] = {t="subzone",n="Thistlefur Hold",z="ashenvale",s="Thistlefur Hold is a cavernous den carved into northern Thistlefur Village in west-central Ashenvale. Once peaceful bears of the forest, the Thistlefur furbolgs residing here have succumbed to corruption and turn violent toward any outsider who draws near.",h="Thistlefur Hold is a cavernous den carved into northern Thistlefur Village in west-central Ashenvale.",sec={{t="A Corrupted Den",b="Tucked into the northern reaches of Thistlefur Village, Thistlefur Hold serves as the heart of the Thistlefur tribe's territory. The furbolgs here were driven mad after coming into possession of the Idol of Remulos, falling into a state of feral hostility that makes them dangerous to travelers and neighbors alike. Deep within the winding caverns, the tribe hordes scavenged relics—including troll charms of interest to the Darkspear—and keeps captives bound in wooden cages, such as the imprisoned tauren brave Ruul Snowhoof.",sp=0}},faq={{q="What is Thistlefur Hold?",a="Thistlefur Hold is the subterranean cavern complex at the northern end of Thistlefur Village in west-central Ashenvale. It houses the densest population of the hostile Thistlefur furbolg tribe.",al={"thistlefur hold info","what is this cave","thistlefur cave"}},{q="Why are the furbolgs in Thistlefur Hold hostile?",a="The Thistlefur furbolgs were corrupted by the Idol of Remulos, an artifact they kept within their possession. The malign influence twisted their minds and drove them to lash out against all outsiders.",al={"why are thistlefur mad","thistlefur corruption","why are furbolgs attacking"}},{q="Who is trapped inside the hold?",a="Ruul Snowhoof, a tauren brave, was captured by the Thistlefur tribe and sits locked in a wooden cage deep inside the caverns awaiting rescue by Horde champions.",al={"thistlefur captive","tauren in thistlefur hold","who is ruul snowhoof"}},{q="Why is the Horde interested in Thistlefur Hold?",a="The Horde seeks to free the captured tauren Ruul Snowhoof and recover valuable troll charms that the furbolgs have hoarded within the depths of the cave.",al={"horde quests thistlefur","troll charms thistlefur"}}},ang={["faction:Horde"]="The hold represents both a rescue mission and a salvage operation for the Horde, demanding warriors enter the den to liberate Ruul Snowhoof and retrieve stolen troll charms.",["class:Druid"]="Seeing the Thistlefur furbolgs fall to madness under the sway of the Idol of Remulos is a tragic reminder of how easily nature's guardians can be corrupted in Ashenvale."},kw={"ashenvale","furbolg","remulos","ruul snowhoof","thistlefur hold","thistlefur village","troll charms"},rel={"subzone:thistlefur-village","zone:ashenvale","npc:ruul-snowhoof","topic:furbolg","npc:remulos","quest:6462","topic:horde","topic:troll"},src={"Thistlefur Hold"}}
E["subzone:thistlefur-village"] = {t="subzone",n="Thistlefur Village",z="ashenvale",s="Thistlefur Village is a sprawling settlement tucked into the forest north of Astranaar in west-central Ashenvale. It serves as the primary home of the Thistlefur furbolg tribe, who have fallen prey to dark corruption and violently assault any outsiders venturing near their dens.",h="Thistlefur Village is a sprawling settlement tucked into the forest north of Astranaar in west-central...",sec={{t="A Corrupted Den",b="Situated just north of the night elf haven of Astranaar, Thistlefur Village was once part of the peaceful woodland communities native to Ashenvale. However, the malignant corruption that has seeped into the ancient forests has entirely claimed the Thistlefur tribe. Now thoroughly maddened and intensely hostile, the furbolgs fiercely guard the paths winding through their settlement. The clan answers to two exceptionally ferocious chieftains, Dal Bloodclaw and Rorgish Jowl, whose unyielding aggression poses a constant threat to travelers and nearby settlements.",sp=0}},faq={{q="Where is Thistlefur Village located?",a="Thistlefur Village is situated in the west-central reaches of Ashenvale, nestled deep in the woodland hills directly north of the night elf town of Astranaar.",al={"thistlefur village location","where is thistlefur","thistlefur map"}},{q="Why are the furbolgs here attacking travelers?",a="The Thistlefur furbolgs have been gripped by the dark corruption spreading across the forests of Ashenvale. Driven mad by these foul influences, they view all outsiders as immediate enemies and attack anyone who approaches their territory.",al={"why are thistlefur hostile","corrupted furbolgs thistlefur","why attack"}},{q="Who leads the Thistlefur furbolgs?",a="The tribe is led by two particularly fierce and brutal warrior chieftains named Dal Bloodclaw and Rorgish Jowl, who maintain vicious dominance over the village and its nearby dens.",al={"thistlefur boss","thistlefur leaders","who leads thistlefur"}},{q="Does Thistlefur Village pose a danger to Astranaar?",a="Yes. Because Thistlefur Village lies immediately north of Astranaar, the aggressive and unstable nature of the corrupted furbolgs makes them a persistent danger to night elf scouts, supply lines, and sentries stationed along the central roads.",al={"thistlefur threat to astranaar","danger to astranaar"}}},ang={["race:NightElf"]="For centuries, the night elves lived in harmony alongside the native furbolg tribes. Seeing the Thistlefur succumb to violent corruption so close to Astranaar is both a heartbreak and a dire security crisis for the Sentinels.",["class:Druid"]="The fallen state of the Thistlefur tribe serves as a grim reminder of the lingering taint afflicting the spirits and wildlife of Ashenvale, demanding vigilant cleansing from the Cenarion Circle."},kw={"ashenvale","astranaar","corruption","dal bloodclaw","furbolg","rorgish jowl","thistlefur","village"},rel={"zone:ashenvale","topic:furbolg","subzone:astranaar"},src={"Thistlefur Village"}}
E["subzone:warsong-labor-camp"] = {t="subzone",n="Warsong Labor Camp",z="ashenvale",s="The Warsong Labor Camp is an isolated Horde timber-harvesting outpost tucked away in southeastern Ashenvale. Operated by Warsong loggers and defended by orcish sentries, the work site cuts lumber to fuel the growth of Durotar while braving the hostility of the surrounding forest.",h="The Warsong Labor Camp is an isolated Horde timber-harvesting outpost tucked away in southeastern Ashenvale.",sec={{t="Timber for the Horde",b="Situated east of Fallen Sky Lake and southwest of the Dor'Danil Barrow Den, the Warsong Labor Camp exists for one vital purpose: harvesting the dense timber of Ashenvale. The dry plains of Durotar offer little usable lumber to build cities like Orgrimmar, forcing the Warsong clan to push deep into the contested woods. Staffed by hardy loggers and orcish guards, the site operates in relative isolation, grinding through ancient trees despite the ever-present threat of night elf scouts and passing Alliance warbands.",sp=0},{t="A Vulnerable Outpost",b="Because of its remote location far from the main road and fortified bases like Splintertree Post, the camp is exceptionally vulnerable. Alliance raiders often strike the working peons and watchmen, knowing reinforcements will not arrive swiftly. To the night elves, every felled tree is an act of sacrilege, turning this mundane logging camp into a perennial flashpoint in the regional war.",sp=0}},faq={{q="Where is the Warsong Labor Camp located?",a="The labor camp lies in southeastern Ashenvale, east of Fallen Sky Lake and southwest of the Dor'Danil Barrow Den.",al={"warsong labor camp location","where is warsong labor camp","finding labor camp"}},{q="What is the purpose of this camp?",a="The outpost serves as a timber harvesting operation. Orc loggers cut and process the ancient woods of Ashenvale to provide building materials for Orgrimmar and other settlements in Durotar.",al={"why are orcs here","what do they do here","warsong logging camp purpose"}},{q="Why is the camp frequently attacked?",a="The camp sits in isolation, far from major Horde fortifications. Night elves fiercely despise the harvesting of their sacred forests, and Alliance champions often raid the outpost because its remote position prevents nearby guards from offering swift backup.",al={"alliance attacks labor camp","why is it targeted","is the camp safe"}},{q="Did Grommash Hellscream found this camp?",a="Warchief Thrall originally sent Grommash Hellscream and the Warsong clan into Ashenvale during the Third War specifically to harvest lumber. The Labor Camp stands as an active continuation of those original logging efforts.",al={"did grom make this","grom hellscream labor camp","history of the camp"}}},ang={["faction:Horde"]="The lumber harvested by these loggers is crucial to building and maintaining Orgrimmar, making their remote work station a vital economic lifeline in contested territory.",["race:NightElf"]="The camp represents a continuous wound in the living woods of Ashenvale, deforesting ancestral groves to fuel the warmachine of Durotar."},kw={"ashenvale","dor'danil","fallen sky lake","labor camp","loggers","lumber","timber","warsong"},rel={"zone:ashenvale","quest:1035","subzone:dor-danil-barrow-den","topic:grommash-hellscream","npc:thrall","topic:alliance"},src={"Warsong Labor Camp"}}
E["subzone:warsong-lumber-camp"] = {t="subzone",n="Warsong Lumber Camp",z="ashenvale",s="The Warsong Lumber Camp is a fortified orc logging operation deep in Ashenvale, run by the Warsong clan to harvest timber for the Horde. Anchored by the fortified Kargathia Keep, it stands as both an economic lifeline for nearby Horde settlements and an unrelenting provocation to the night elves. The constant sound of goblin-built shredders chewing through ancient boughs makes this clearing a primary flashpoint of the forest war.",h="The Warsong Lumber Camp is a fortified orc logging operation deep in Ashenvale, run by the Warsong clan to...",sec={{t="Heart of the Harvest",b="Carved straight out of the dense canopy of eastern Ashenvale, the Warsong Lumber Camp is the industrial engine fueling the Horde's expansion across Kalimdor. Orc peons and hired goblin engineers strip the forest with whirring shredders, processing towering trunks into lumber to reinforce outpost walls like nearby Splintertree Post and build up the fledgling nation of Durotar. The camp is heavily fortified against constant night elf counterattacks, centering on the stockades of Kargathia Keep and an active kennel for the clan's fierce war wolves. For the Warsong, every felled tree is survival and strength; for the native Sentinels, every saw blade is an act of sacrilege.",sp=0},{t="A Legacy of War",b="The Warsong clan's presence in these woods dates back to the Third War, when Grom Hellscream first led his warriors into the sacred groves to claim wood for the Horde. That initial deforestation ignited the fury of the demigod Cenarius and brought down the ancient wrath of the night elves. Though the modern camp operates under the banners of Thrall's Horde, the old animosities burn just as fiercely. Surrounded by untamed timber, hostile elves, and the lingering demonic corruption around neighboring Felfire Hill, the camp's defenders remain armed around the clock, harvesting trees with axes in hand and ready to drop their timber to repel the next ambush.",sp=0}},faq={{q="Why is the Horde logging in Ashenvale?",a="The lands settled by the Horde—particularly Durotar and the Barrens—are arid and sparse, lacking the dense timber required to construct buildings, palisades, and war machinery. Ashenvale offers a massive, virtually endless supply of prime wood essential for the survival and expansion of orc outposts like Splintertree Post and the capital of Orgrimmar.",al={"why cut trees","warsong logging reasons","why does horde need wood"}},{q="What is Kargathia Keep?",a="Kargathia Keep is the fortified stronghold anchoring the Warsong Lumber Camp. It provides barracks, strategic command, and a reinforced bastion where peons and overseers can retreat and hold off night elf ambushes when Sentinels or local wildlife strike the logging perimeter.",al={"kargathia keep purpose","fort in lumber camp","warsong keep ashenvale"}},{q="Why are the night elves so hostile to this camp?",a="To the night elves, Ashenvale is a sacred ancestral homeland protected by nature spirits and ancients. Felling ancient trees with noisy, smoke-belching goblin machinery is considered wanton destruction and outright desecration, prompting constant guerrilla attacks to expel the Warsong orcs from the forest.",al={"night elf reaction","why elves attack lumber camp","sentinel attacks"}},{q="What role do goblins play in the camp?",a="Goblin mercenaries and technicians provide the specialized technology driving the lumber operation, most notably steam-powered shredders. These machines allow the Warsong clan to harvest and strip massive ancient trees at speeds conventional hand axes could never achieve.",al={"goblins at warsong camp","why are shredders here","goblin machinery ashenvale"}}},ang={["faction:Horde"]="The lumber harvested here supplies the building materials for Splintertree Post and the fortifications safeguarding the Horde's future across Kalimdor.",["race:NightElf"]="The camp's whining shredders and falling trees represent a direct, brutal assault on the sacred balance of Ashenvale that the Sentinels have vowed to extinguish."},kw={"ashenvale","kargathia keep","shredders","splintertree post","timber","warsong clan","warsong lumber camp"},rel={"topic:warsong-clan","zone:ashenvale","subzone:splintertree-post","subzone:kargathia-keep","subzone:felfire-hill","topic:goblin","topic:horde","topic:third-war"},src={"Warsong Lumber Camp"}}
E["subzone:xavian"] = {t="subzone",n="Xavian",z="ashenvale",s="Xavian is an ancient ruined night elf temple complex in northeastern Ashenvale, now overrun and claimed by the satyrs. Serving as the primary seat of satyr influence in the forest, the ruin is foul with demonic corruption and dark rites directed against the woodland.",h="Xavian is an ancient ruined night elf temple complex in northeastern Ashenvale, now overrun and claimed by...",sec={{t="A Seat of Shadow",b="Tucked away in the northeastern hills of Ashenvale, west of Forest Song and north of Satyrnaar, Xavian stands as the foremost bastion of satyr power in the region. Once a sacred elven temple, its stone arches and terraces have been desecrated by followers of the Burning Legion. Leaders among the satyrs, including Prince Raze and Geltharis, oversee their kin from these ruins. They perform defiling rituals across the grounds, even utilizing stolen Warsong oil to further blight the sacred woodland. The area takes its name from Xavius, the highborne councilor who became the first satyr during the War of the Ancients after failing Sargeras.",sp=0},{t="The Fallen Vanguard",b="The corruption radiating from Xavian has not gone unchallenged, but confronting the satyrs comes at a grim price. Sentinels and woodland guardians keep a watchful eye on the stronghold, knowing its strategic malice eclipses nearby enclaves like Night Run. Recently, dryad defenders attempted to infiltrate the ruins to recover the sacred Branch of Cenarius, only to suffer grievous losses. Adventurers who breach the outer terraces can find the dying dryad Anilia, struck down while attempting to halt the defilers from using holy relics in their dark incantations.",sp=1}},faq={{q="Why is this place named Xavian?",a="The stronghold is named in honor of Lord Xavius, the highborne courtier of Queen Azshara who helped usher the Burning Legion into Azeroth during the War of the Ancients. After displeasing Sargeras, Xavius was remade into the very first satyr, a demonic curse that spread to others of his kind.",al={"origin of xavian","who is xavian named after","xavius xavian"}},{q="What are the satyrs doing here?",a="The satyrs use Xavian as their primary command center in Ashenvale. They conduct dark rituals to spread demonic corruption throughout the ancient forest, utilizing defiled sacred relics like the stolen Branch of Cenarius as well as machinery oil pilfered from the Warsong orcs.",al={"what are they doing in xavian","xavian satyr rituals"}},{q="Who is the dying dryad lying on the ground?",a="Her name is Anilia. She was part of a dryad effort to recover the stolen Branch of Cenarius from the satyrs. She was mortally wounded during the skirmish and lies among the ruins, pleading for someone to reclaim the sacred branch before it is completely corrupted.",al={"injured dryad xavian","who is anilia","dryad in xavian"}},{q="How does Xavian differ from Satyrnaar or Night Run?",a="While Satyrnaar and Night Run are notable satyr camps within Ashenvale, Xavian acts as the political and ritual heart of their forces in the forest. High-ranking satyr leaders such as Geltharis and Prince Raze make their base here among the ruins.",al={"satyrnaar vs xavian","other satyr camps","why is xavian important"}}},ang={["race:NightElf"]="Seeing the desecrated halls of an ancient temple defiled by the twisted descendants of the Highborne is a bitter offense to any night elf, demanding swift retribution.",["class:Druid"]="The satyrs here have stolen the Branch of Cenarius and use fel rites to corrupt the land; druids are called upon to reclaim the artifact and heal the grove's spiritual wounds."},kw={"anilia","ashenvale","branch of cenarius","geltharis","raze","satyr","xavian","xavius"},rel={"zone:ashenvale","topic:satyr","subzone:satyrnaar","subzone:night-run","subzone:forest-song","topic:cenarius","topic:sargeras","topic:war-of-the-ancients"},src={"Xavian"}}
E["subzone:zoram-gar-outpost"] = {t="subzone",n="Zoram'gar Outpost",z="ashenvale",s="Zoram'gar Outpost is a fortified Horde beachhead nestled on the western edge of Ashenvale along the Zoram Strand. Serving as a crucial coastal encampment, it provides the Horde with access to the Veiled Sea and keeps watch over regional threats like the encroaching naga and the sinister depths nearby.",h="Zoram'gar Outpost is a fortified Horde beachhead nestled on the western edge of Ashenvale along the Zoram...",sec={{t="A Bastion on the Strand",b="Situated at the northwestern lip of Ashenvale where the primeval forest collapses into the sea, Zoram'gar Outpost serves as the Horde's isolated coastal footing on the Zoram Strand. Hemmed in by night elf territory inland and maritime hazards offshore, the encampment acts as a staging ground for scouts, hunters, and shaman tasked with tracking local dangers. Life at the outpost is an endless vigil: naga regularly prowl the shallows, while lurking cultists and primal horrors pulse from the subterranean cavern system known as Blackfathom Deeps just down the shore.",sp=0},{t="Strategic Importance",b="Because of its peripheral location, Zoram'gar maintains flight connections with other critical Horde holdings like Splintertree Post, the Crossroads, and Thunder Bluff. While small in footprint, the outpost anchors Horde supply lines on the western coast and prevents hostile forces from sailing unmolested into Kalimdor's northern waterways.",sp=0}},faq={{q="Why did the Horde establish Zoram'gar Outpost?",a="The Horde established the camp to secure a foothold on the western shoreline of Ashenvale. It provides maritime monitoring along the Zoram Strand and offers a defensible station to counter the aggressive naga infesting the coast.",al={"why is zoram'gar here","purpose of zoram gar","why did horde build zoram gar"}},{q="What threats does the outpost face?",a="The immediate threat comes from the Wrathscale naga slithering across the Zoram Strand. Additionally, the twilight cultists and beastly horrors residing within the nearby temple ruins of Blackfathom Deeps pose a constant lurking danger.",al={"threats to zoram gar","enemies at zoram gar"}},{q="Where does the outpost connect via flight master?",a="Zoram'gar Outpost connects aerial wind riders across central Kalimdor, linking travelers to Splintertree Post, Sun Rock Retreat, the Crossroads, and the tauren capital of Thunder Bluff.",al={"flight paths zoram gar","where can i fly from zoram gar"}},{q="What is the relation between the outpost and Blackfathom Deeps?",a="Blackfathom Deeps lies just north of the outpost along the shoreline ruins. Horde forces stationed at Zoram'gar monitor the corruption seeping out of the flooded temple and dispatch adventurers inside to counter the cultists and their beast, Aku'mai.",al={"blackfathom deeps near zoram","is bfd near zoram gar"}}},ang={["faction:Horde"]="The outpost serves as your primary haven in northwest Ashenvale, offering shelter, rest, and wind rider transport amidst dangerous wilderness.",["faction:Alliance"]="An entrenched Horde presence on the coast of Ashenvale, Zoram'gar represents a dangerous supply foothold close to night elf ancestral lands."},kw={"ashenvale","blackfathom deeps","horde","naga","outpost","zoram gar","zoram strand","zoram'gar"},rel={"subzone:zoram-strand","zone:blackfathom","zone:ashenvale","subzone:splintertree-post","quest:6442","quest:6563","npc:aku-mai","topic:horde"},src={"Zoram'gar Outpost"}}
E["subzone:zoram-strand"] = {t="subzone",n="Zoram Strand",z="ashenvale",s="The Zoram Strand is a windswept coastline lining the northwestern edge of Ashenvale along the Veiled Sea. Once the site of an ancient night elven city swallowed by the Great Sundering, the shore is now plagued by Wrathtail naga, shipwrecks, and beached leviathans. It also holds the entrance to the submerged temple complex of Blackfathom Deeps.",h="The Zoram Strand is a windswept coastline lining the northwestern edge of Ashenvale along the Veiled Sea.",sec={{t="Ruins of the Sundered Coast",b="Ten thousand years ago, the grand night elven city of Zoram graced these shores before the Great Sundering tore Kalimdor apart and cast the settlement into the ocean depths. Today, the tide continually washes up ancient relics, remnants of shattered vessels, and the carcasses of massive sea beasts. The Wrathtail naga have overrun the beaches and tidal pools, fiercely guarding the flooded ruins and ancient artifacts against anyone daring to approach.",sp=0},{t="A Contested Shoreline",b="Despite the naga menace, both mainland travelers and coastal wanderers find themselves drawn to the strand. To the south lies the fortified Horde encampment of Zoram'gar Outpost, whose warriors fight a continuous battle to secure the coast. Deep within the nearby caverns sits Blackfathom Deeps, an ancient temple of Elune that has fallen into dark hands, making the strand a gathering ground for scouts, scholars, and treasure seekers braving the surf.",sp=0}},faq={{q="What was Zoram before it was destroyed?",a="Prior to the Great Sundering ten thousand years ago, Zoram was a majestic night elven city. The cataclysm shattered the coast, plunging the city beneath the Veiled Sea and leaving only jagged ruins and washed-up statuettes along the shore.",al={"zoram history","ancient zoram","what was zoram"}},{q="Who controls the Zoram Strand today?",a="The shoreline itself is largely overrun by the Wrathtail naga, who fiercely defend the shallows and ancient ruins. The Horde maintains a fortified foothold at Zoram'gar Outpost along the southern cliffs, while dangerous wildlife such as hydras and crabs prowl the sand.",al={"who lives at zoram strand","zoram strand enemies","who controls zoram strand"}},{q="Where is the entrance to Blackfathom Deeps?",a="The entrance to Blackfathom Deeps is located in the submerged caverns along the Zoram Strand. Travelers venture into the coastal caves along the water's edge to reach the descent into the sunken temple.",al={"blackfathom deeps location","how to find bfd","bfd entrance zoram"}},{q="Why are there so many beached sea creatures here?",a="The tumultuous tides and dark currents of the Veiled Sea frequently wash massive marine creatures ashore. Researchers and naturalists from both factions often seek out these remains to investigate what drives ocean behemoths to perish along the rocks.",al={"beached sea creature quest","dead whales zoram strand","beached creatures"}}},ang={["race:NightElf"]="The strand is a sobering reminder of the ancient world lost to the Sundering, where sacred relics and submerged temples to Elune now suffer beneath the tread of the naga.",["faction:Horde"]="Defending the approaches to Zoram'gar Outpost is vital to maintaining a northern naval and coastal presence in Ashenvale against the relentless Wrathtail brood."},kw={"ashenvale","blackfathom deeps","naga","ruuzel","veiled sea","wrathtail","zoram","zoram strand"},rel={"subzone:zoram-gar-outpost","zone:blackfathom","zone:ashenvale","quest:1008","quest:6442","quest:1007","quest:1009","topic:naga"},src={"Zoram Strand"}}
E["zone:ashenvale"] = {t="zone",n="Ashenvale",z="ashenvale",s="Ashenvale is the ancient, rain-drenched ancestral forest of the night elves, held sacred under the protection of the Sentinels and the demigod Cenarius. Bordering the Barrens to the south and Darkshore to the north, it has erupted into a bitter war zone as the Horde harvests timber to build its young nation. Ancient trees and tranquil moonwells share canopy with demonic holdouts, hostile beastmen, and clash points along the contested frontier.",h="Ashenvale is the ancient, rain-drenched ancestral forest of the night elves, held sacred under the protection...",sec={{t="The Whispering Canopy",b="Stretching beneath Mount Hyjal, Ashenvale has stood for millennia under the stewardship of the kaldorei and the children of Cenarius. Immense trees knit together into a dense canopy that turns daily rain into a gentle mist and casts the forest floor in eternal twilight. Ancient ruins of elven civilization poke through the moss, guarded by walking ancients and dryads. For thousands of years, the night elves built no true cities here, preferring to hunt lightly and preserve the wild domain in pristine balance.",sp=0},{t="War for the Woods",b="The peace shattered during the Third War when Grommash Hellscream and the Warsong clan penetrated the forest for lumber, slaying Cenarius after falling to demonic bloodlust. Today in 25 ADP, the struggle has become a full-scale territorial war. From Splintertree Post and the southern Mor'shan Rampart, the Warsong Outriders drive axes and shredders into the eastern woods to supply Orgrimmar. The Silverwing Sentinels, based in the sanctuary town of Astranaar, have sworn to expel every last orcish logger from the sacred grove.",sp=0},{t="Lingering Shadows",b="The lumber war is far from Ashenvale's only peril. The Burning Legion left scarred blights at Felfire Hill and Demon Fall Canyon, where Mannoroth met his end. Cruel satyrs operate out of ruins like Satyrnaar and Xavian, corrupting waterways and wildlife. Furbolg tribes, once friends of the elves, have largely succumbed to dark madness. Meanwhile, mysterious worgen stalk the northern shrine near Felwood, and cursed dragonkin prowl Bough Shadow, guarding a portal into the troubled Emerald Dream.",sp=0}},faq={{q="Why are the Horde and Alliance fighting in Ashenvale?",a="The orcs of Durotar have virtually no timber in their dry homeland and desperately need Ashenvale's lumber to build Orgrimmar and fuel their young nation. To the night elves, Ashenvale is a sacred ancestral homeland protected by nature deities. The Silverwing Sentinels view the Warsong clan's clear-cutting operations as intolerable desecration, sparking constant skirmishes and the pitched struggle in Warsong Gulch.",al={"why horde cutting trees","ashenvale war reason","warsong vs silverwing"}},{q="What happened to Cenarius in this forest?",a="During the Third War, Grommash Hellscream led the Warsong clan into Ashenvale to gather timber. Cenarius attacked the orcs to defend the sacred grove. Desperate to defeat the demigod, Grommash and his clan drank from a fountain tainted by the pit lord Mannoroth, gaining demonic fury and slaying Cenarius. Although Grom later broke the curse by slaying Mannoroth at Demon Fall Canyon, the elves have not forgotten the murder of their patron demigod.",al={"how cenarius died","grom killed cenarius","cenarius fate"}},{q="What is Blackfathom Deeps?",a="Blackfathom Deeps is a sunken temple complex situated beneath the Zoram Strand along Ashenvale's northwestern coastline. Formerly an ancient kaldorei temple dedicated to Elune, it collapsed into the sea during the Great Sundering. It is now overrun by savage naga, Twilight's Hammer cultists, and aquatic beasts who revere the ancient hydra Aku'mai.",al={"where is bfd","bfd lore","blackfathom deeps history"}},{q="What is the Great Tree at Bough Shadow?",a="Bough Shadow is home to one of four Great Trees planted by the Cenarion Circle thousands of years ago to anchor conduits into the Emerald Dream and contain saronite corruption. It serves as an active gateway between Azeroth and the Dream. Green dragonspawn guard the area, though a sinister taint within the Dream occasionally drives monstrous Nightmare Dragons through the portal.",al={"bough shadow tree","portal bough shadow","green dragons ashenvale"}},{q="Why are the furbolgs in Ashenvale hostile?",a="While the night elves maintained peaceful alliances with the furbolgs for centuries, the demonic taint left by the Burning Legion's invasion shattered their minds. Residual fel magic radiating from places like Felwood, Satyrnaar, and Demon Fall Canyon drove tribes like the Thistlefur into violent insanity, turning them hostile to outsiders and kin alike.",al={"crazy furbolgs ashenvale","thistlefur corrupt","why furbolgs attack"}},{q="Who is buried at Demon Fall Canyon?",a="Demon Fall Canyon is the battlefield where Grommash Hellscream and Thrall confronted the pit lord Mannoroth. Grom struck down the demon lord with a fatal blow, freeing the orcish race from the demonic blood curse at the cost of his own life. Mannoroth's shattered armor remains mounted on a stone monument there in memorial to Hellscream's sacrifice.",al={"mannoroth canyon","grommash grave ashenvale","monument demon fall"}},{q="How do I travel through Ashenvale?",a="Alliance travelers generally enter through the northern mountain pass from Auberdine in Darkshore, following the highway east toward Astranaar. Horde adventurers march north out of the Barrens through the fortified Mor'shan Rampart toward Splintertree Post or west to Zoram'gar Outpost on the Zoram Strand. Both factions maintain flight masters at their major fortresses.",al={"how to get to ashenvale","ashenvale travel","ashenvale flight paths"}}},ang={["race:NightElf"]="Ashenvale is your spiritual backyard and the legacy of Cenarius. Defending its groves against Warsong axes and weeding out satyr corruption from its moonwells is a matter of primal kaldorei honor.",["race:Orc"]="This timber fuels the very walls and siege towers of Orgrimmar. It is also sacred ground where Grommash Hellscream shed blood to redeem the orcish race from demonic servitude.",["class:Druid"]="The balance of nature here is under siege on multiple fronts. Between the lumber operations, corrupted furbolg dens, and the nightmare-haunted portal at Bough Shadow, Ashenvale desperately needs Cenarion restoration.",["profession:Herbalism"]="Fed by ancient magical leyways and perpetual rainfall, Ashenvale is one of Kalimdor's richest foraging zones for Briarthorn, Stranglekelp, Kingsblood, and rare Gromsblood around demonic scars."},kw={"ashenvale","astranaar","bough shadow","cenarius","grommash","mannoroth","silverwing","splintertree","warsong","zoram"},rel={"zone:darkshore","zone:barrens","zone:blackfathom","subzone:astranaar","subzone:demon-fall-canyon","subzone:bough-shadow","subzone:mor-shan-rampart"},m={levels="18-30"},src={"Ashenvale (Classic)","Ashenvale"}}
